window.EXPL={"변리사2018_55-03-2":{"f":"관습법은 사회의 거듭된 관행과 법적 확신이 있어야 성립된다.","w":"관습법은 사회의 거듭된 관행이 있고 그것이 법적 확신으로 뒷받침될 때 성립한다. 법적 확신이 없는 단순한 관행은 사실인 관습일 뿐이다.","c":"상","v":1},"변리사2018_55-03-3":{"f":"관습법은 당사자의 주장입증을 기다림이 없이 법원이 직권으로 이를 확정하여야 한다.","w":"관습법은 법원이 직권으로 확정하지만, 사실인 관습은 그 존재를 당사자가 주장·입증해야 한다.","c":"상","v":1},"변리사2018_55-03-4":{"f":"공동선조와 성과 본을 같이하는 후손이면 성별의 구별 없이 성년이 되면 당연히 종중의 구성원이 된다.","w":"종중원은 공동선조와 성과 본을 같이하는 후손 중 성년이 된 사람이며, 성별은 따지지 않는다. 미성년자는 종중원이 아니다(대법원 2005.7.21. 선고 2002다1178 전원합의체 판결).","c":"상","v":1},"변리사2018_55-03-5":{"f":"관습법이 사회생활규범으로 승인되었더라도 사회를 지배하는 기본적 이념이나 사회질서의 변화로 인하여 그 관습법을 적용하여야 할 시점에 있어서의 전체 법질서에 부합하지 않게 되었다면 그 법규범으로서의 효력이 부정된다.","w":"관습법도 현재의 전체 법질서에 부합하지 않게 되면 효력이 부정된다(대법원 2005.7.21. 전원합의체 판결).","c":"상","v":1},"변리사2018_55-04-1":{"f":"미성년자도 임의대리인이 될 수 있다.","w":"대리인은 행위능력자임을 요하지 않으므로 미성년자도 임의대리인이 될 수 있다(민법 제117조).","c":"상","v":1},"변리사2018_55-04-3":{"f":"미성년자가 법정대리인의 동의 없이 법률행위를 한 경우에 법정대리인의 취소권이 기간경과로 소멸되지 않는 한, 미성년자는 성년이 된 후에도 취소할 수 있다.","w":"미성년자 본인도 취소할 수 있고, 성년이 된 뒤에도 취소권이 소멸하기 전이면 취소할 수 있다(민법 제5조, 제140조, 제146조).","c":"상","v":1},"변리사2018_55-04-4":{"f":"甲이 乙과 계약을 체결할 당시 乙이 미성년자임을 알고 계약했다면 甲은 철회권을 행사할 수 없다.","w":"상대방의 철회권은 계약 당시 미성년자임을 알지 못한 선의의 상대방에게만 있다(민법 제16조 제1항).","c":"상","v":1},"변리사2018_55-04-5":{"f":"미성년자가 법정대리인의 동의 없이 법률행위를 하면서 특약에 의하여 미성년을 이유로 한 취소를 하지 않기로 한 경우에도 미성년을 이유로 그 법률행위를 취소할 수 있다.","w":"제한능력자의 취소권을 미리 배제하는 특약은 제한능력자 보호 취지에 반하여 효력이 없다.","c":"중","v":1},"변리사2018_55-07-2":{"f":"권리능력 없는 사단의 사원이 집합체로서 물건을 소유한 경우에는 총유로 한다.","w":"법인 아닌 사단의 사원이 집합체로서 물건을 소유하는 형태는 총유이다(민법 제275조). 합유는 조합의 소유 형태이다.","c":"상","v":1},"변리사2018_55-07-3":{"f":"권리능력 없는 사단에 구성원이 없게 되더라도 그 사단은 바로 소멸하지 않고 소송상의 당사자능력도 바로 상실하지 않는다.","w":"구성원이 없게 되면 해산사유가 될 뿐이고, 청산이 끝날 때까지는 사단이 존속하여 당사자능력이 유지된다.","c":"중","v":1},"변리사2018_55-07-4":{"f":"권리능력 없는 사단의 대표자는 자신의 업무를 타인에게 포괄적으로 위임할 수 없다.","w":"민법 제62조를 유추하여, 비법인사단의 대표자는 특정한 행위만 타인에게 대리하게 할 수 있고 업무 전부를 포괄적으로 위임할 수는 없다(대법원 판례).","c":"상","v":1},"변리사2018_55-07-5":{"f":"권리능력 없는 사단의 사원의 지위는 규약에 의하여 양도나 상속될 수 있다.","w":"사원의 지위는 규약이나 관행에 따라 양도·상속할 수 있다. 법인 아닌 사단의 사원 지위는 기본적으로 규약이 정하는 대로 따른다.","c":"중","v":1},"변리사2018_55-09-1":{"f":"법인의 정관에 법인 대표권의 제한에 관한 규정이 있다면, 그러한 취지가 등기되어 있지 않은 경우에는 법인은 그 제한으로써 악의의 제3자에게도 대항할 수 없다.","w":"대표권 제한은 정관에 있어도 등기하지 않으면 제3자에게 대항하지 못하고, 제3자의 선의·악의를 묻지 않는다(민법 제60조).","c":"상","v":1},"변리사2018_55-09-2":{"f":"법인의 정관에 이사의 해임사유에 관한 규정이 있는 경우에도 이사의 중대한 의무 위반이 있으면 법인은 정관에서 정하지 아니한 사유로 이사를 해임할 수 있다.","w":"법인과 이사의 관계는 위임 유사의 관계이므로, 이사에게 중대한 의무 위반 등이 있으면 정관에 정하지 않은 사유로도 해임할 수 있다(대법원 2013.11.28. 선고 판결).","c":"중","v":1},"변리사2018_55-09-4":{"f":"이사의 임기가 만료되었더라도 아직 임기가 만료되지 아니한 다른 이사들로 법인이 정상적인 활동을 할 수 있는 경우에는 임기만료된 이사로 하여금 이사로서 직무를 행사하게 할 필요가 없고, 법인의 정상적인 활동이 가능한지 여부는 이사의 임기만료시를 기준으로 판단하여야 한다.","w":"다른 이사들로 법인이 정상적인 활동을 할 수 있는지는 이사의 임기만료 당시를 기준으로 판단하고, 그 뒤의 사정까지 고려하지는 않는다(대법원 판례).","c":"중","v":1},"변리사2018_55-09-5":{"f":"대표권 없는 이사의 행위로는 민법 제35조 소정의 법인의 불법행위가 성립하지 않는다.","w":"법인의 불법행위(민법 제35조)는 대표기관의 행위로 성립한다. 대표권 없는 이사는 법인의 기관이기는 하지만 대표기관이 아니므로 그의 행위로는 제35조의 책임이 생기지 않는다(대법원 2005.12.23. 선고 2003다30159 판결).","c":"상","v":1},"변리사2018_55-10-4":{"f":"어떤 법률행위에 그 일상적인 의미만을 이해하여서는 알기 어려운 특별한 법률적인 의미나 효과가 부여되어 있는 경우에는 의사능력이 인정되기 위하여 그 행위의 일상적인 의미에 대한 이해만으로는 부족하고 법률적인 의미나 효과에 대한 이해도 필요하다.","w":"이런 법률행위에서는 일상적 의미뿐 아니라 법률적 의미와 효과를 이해할 수 있어야 의사능력이 인정된다(대법원 2006.9.22. 선고 판결).","c":"상","v":1},"변리사2019_56-02-2":{"f":"甲은 법정대리인의 동의가 없었다는 이유로 자신이 체결한 매매계약을 원칙적으로 취소할 수 있다.","w":"17세의 미성년자가 법정대리인의 동의 없이 체결한 계약은 본인도 취소할 수 있다(민법 제5조 제2항).","c":"상","v":1},"변리사2019_56-03-2":{"f":"사원자격의 득실에 관한 규정은 사단법인 정관의 필요적 기재사항에 해당한다.","w":"사원이 있는 것은 사단법인이다. 재단법인은 사원이 없으므로 사원자격 득실에 관한 사항은 재단법인 정관의 기재사항이 아니다(민법 제40조, 제43조).","c":"상","v":1},"변리사2021_58-03-1":{"f":"비법인사단은 부동산소유권에 관하여 등기의무자가 될 수 있다.","w":"비법인사단은 사단 명의로 부동산등기를 할 수 있으므로 등기권리자·등기의무자가 될 수 있다(부동산등기법 제26조).","c":"상","v":1},"변리사2021_58-03-3":{"f":"비법인사단의 대표자가 행한 타인에 대한 업무의 포괄적 위임과 그에 따른 포괄적 수임인의 대행행위는 비법인사단에 대하여 그 효력이 없다.","w":"대표자의 직무를 포괄적으로 위임하는 것은 허용되지 않아 그 대행행위는 사단에 효력이 미치지 않는다.","c":"상","v":1},"변리사2021_58-03-4":{"f":"비법인사단의 채무는 사단에 귀속한다.","w":"비법인사단의 채무는 사단 자체에 귀속하고, 구성원이 지분비율에 따라 나누어 부담하지 않는다. 구성원은 사단의 채무에 개인 재산으로 책임지지 않는다.","c":"중","v":1},"변리사2021_58-03-5":{"f":"이사의 결원으로 인하여 손해가 생길 염려가 있으면 이해관계인은 법원에 임시이사의 선임을 청구할 수 있다.","w":"이사가 없거나 결원이 되어 손해가 생길 염려가 있으면 이해관계인이나 검사의 청구로 법원이 임시이사를 선임할 수 있다(민법 제63조).","c":"상","v":1},"변리사2023_60-02-1":{"f":"2023. 2. 18. 현재 甲이 이미 성년이 되었더라도, 그것만으로 매매계약을 취소할 수 없게 되는 것은 아니다.","w":"성년이 되었다고 취소권이 없어지지 않는다. 취소권은 추인할 수 있는 날부터 3년, 법률행위를 한 날부터 10년 안에 행사할 수 있고(민법 제146조), 성년이 된 뒤 추인하거나 법정추인 사유가 생겨야 취소할 수 없게 된다.","c":"중","v":1},"변리사2023_60-03-3":{"f":"이사의 대표권에 대한 제한은 이를 등기하지 아니하면 제3자에게 대항하지 못한다.","w":"등기하지 않아도 당사자 사이에서는 효력이 있고, 등기하지 않으면 제3자에게 대항하지 못한다(민법 제60조). 효력 자체가 없는 것은 아니다.","c":"상","v":1},"변리사2024_61-01-1":{"f":"채권자는 물상보증인이 되려는 자에게 주채무자의 신용상태를 조사해서 고지할 신의칙상 의무를 부담하지 않는다.","w":"채권자에게 물상보증인 될 사람에게 주채무자의 신용상태를 조사하여 알려줄 신의칙상 의무는 없다.","c":"상","v":1},"변리사2026_63-02-1":{"f":"부재자로부터 재산의 처분권한을 위임받은 자는 부재자의 생사불명을 이유로 법원에 의해 부재자의 재산관리인으로 선임된 이후에는 부재자의 재산처분에 법원의 허가를 받아야 한다.","w":"법원이 재산관리인을 선임하면 그 재산관리인이 법원의 감독을 받으므로, 처분행위에는 법원의 허가가 필요하다(민법 제25조).","c":"중","v":1},"변리사2026_63-02-3":{"f":"후순위상속인은 부재자에 대한 실종선고의 여부에 따라 상속지분의 차이가 생기더라도 부재자에 대한 실종선고를 청구할 수 있는 이해관계인에 해당하지 않는다.","w":"실종선고 청구권자인 이해관계인은 법률상 직접 이해관계를 가진 사람이다. 후순위상속인은 실종선고 여부에 따라 상속지분이 달라져도 이해관계인이 아니다.","c":"상","v":1},"변리사2026_63-02-4":{"f":"실종자를 당사자로 한 판결이 확정된 후에 실종선고가 확정되어 그 사망간주의 시점이 소제기 이전으로 소급하는 경우에도, 그 판결이 당사자능력이 없는 사망자를 상대로 한 판결로서 소급하여 무효가 되지는 않는다.","w":"실종선고가 확정되기 전에는 실종자도 당사자능력이 있으므로, 나중에 사망간주 시점이 소제기 전으로 소급하더라도 이미 확정된 판결이 무효가 되지 않는다(판례).","c":"상","v":1},"변리사2026_63-02-5":{"f":"실종선고가 이미 확정된 자에 대하여 그 실종선고가 취소됨이 없이 다시 실종선고가 내려진 경우, 최초의 실종선고를 기초로 상속관계를 판단하여야 한다.","w":"이미 확정된 실종선고가 취소되지 않았으면 그 선고가 기준이므로 상속관계는 처음의 실종선고에 따라 판단한다.","c":"중","v":1},"변리사2026_63-03-1":{"f":"재단법인의 정관변경은 그 변경방법을 정관에서 정한 때에도 주무관청의 허가를 얻어야 효력이 있다.","w":"정관에서 변경방법을 정한 때에는 그 방법에 따르되, 효력이 생기려면 주무관청의 허가가 필요하다(민법 제45조 제3항, 제42조 제2항).","c":"상","v":1},"변리사2026_63-03-3":{"f":"법인과 이사의 이익이 상반되는 사항에 관하여 이해관계인 또는 검사의 청구가 있는 경우, 법원은 특별대리인을 선임하여야 한다.","w":"이익이 상반되는 사항에는 임시이사(제63조)가 아니라 특별대리인을 선임한다(민법 제64조).","c":"상","v":1},"변리사2026_63-03-4":{"f":"사원총회의 결의로 정관의 규범적 의미와 다른 해석이 표명된 경우에도, 그 결의에 의한 해석은 법원을 구속하지 않는다.","w":"정관의 규범적 의미 내용은 법원이 객관적으로 해석하며, 사원총회의 결의로 다르게 해석해도 법원이 구속되지 않는다.","c":"상","v":1},"변리사2026_63-03-5":{"f":"청산 중인 법인의 청산인은 채권신고기간 내에는 채권자에 대한 변제를 할 수 없으나, 그 기간 동안에도 법인은 채권자에 대한 지연배상책임을 면하지 못한다.","w":"채권신고기간 중 변제를 못해도 법인은 채권자에 대한 지연배상책임을 면하지 못한다(민법 제90조 단서).","c":"상","v":1},"변리사2016_53-04-3":{"f":"물건이 주물의 소유자의 상용에 공여되고 있더라도, 주물 그 자체의 효용과 직접 관계가 없는 것은 종물이 아니다.","w":"종물은 주물 자체의 효용에 이바지하는 물건이어야 한다. 소유자가 쓰고 있다는 것만으로는 종물이 되지 않는다(대법원 판례).","c":"상","v":1},"변리사2017_54-04-2":{"f":"입목등기를 하지 않은 수목도 명인방법을 갖추면 독립된 물건이 될 수 있다.","w":"입목등기가 없는 수목은 명인방법을 갖추면 토지와 별개의 독립한 물건으로 거래할 수 있다.","c":"상","v":1},"변리사2017_54-04-3":{"f":"주물 소유자의 사용에 공여되고 있는 물건이라도 주물 자체의 효용과 관계없는 물건이면 종물이 되지 않는다.","w":"종물이 되려면 주물의 상용에 이바지해야 하고, 소유자의 일반적 사용만으로는 부족하다.","c":"상","v":1},"변리사2017_54-04-4":{"f":"성숙한 농작물은 명인방법을 갖추지 않아도 경작자의 소유가 된다.","w":"타인 토지에서 정당한 권원 없이 경작한 경우에도 농작물의 소유권은 경작자에게 있고, 명인방법은 필요 없다(대법원 판례).","c":"중","v":1},"변리사2017_54-04-5":{"f":"토지등기부에 분필등기가 되어도 「공간정보의 구축 및 관리 등에 관한 법률」이 정하는 바에 따른 분할절차를 밟지 않으면 분필의 효과가 발생하지 않는다.","w":"토지의 분할은 지적공부 정리 등 법정 분할절차를 거쳐야 효력이 생기고, 분필등기만으로는 효과가 없다.","c":"상","v":1},"변리사2018_55-12-2":{"f":"종물은 주물의 일부이거나 구성부분이 아니고 독립한 물건이어야 한다.","w":"주물의 구성부분은 종물이 아니다. 종물은 주물과 독립한 별개의 물건이다(민법 제100조 제1항).","c":"상","v":1},"변리사2019_56-04-1":{"f":"소유권이전의 대가, 노동의 대가는 법정과실이 아니다.","w":"법정과실은 물건의 사용대가로 받는 금전 기타의 물건(임료·이자 등)이다. 소유권이전의 대가나 노동의 대가는 포함되지 않는다(민법 제101조 제2항).","c":"상","v":1},"변리사2021_58-05-2":{"f":"집합물에 대한 양도담보권자가 점유개정의 방법으로 양도담보권설정계약 당시 존재하는 집합물의 점유를 취득한 후 양도담보권설정자가 자기 소유의 집합물을 이루는 물건을 반입한 경우, 나중에 반입된 물건에도 양도담보권의 효력이 미친다.","w":"집합물에 대한 양도담보권의 효력은 설정 뒤 설정자가 반입해 집합물의 구성부분이 된 물건에도 미친다(판례).","c":"상","v":1},"변리사2021_58-05-3":{"f":"적법한 경작권 없이 타인의 토지를 경작하였더라도 그 경작한 입도(立稻)가 성숙한 경우에는 경작자가 그 입도의 소유권을 가진다.","w":"성숙한 농작물은 토지와 별개의 물건이어서, 적법한 경작권 없이 남의 땅에 심었더라도 경작한 사람이 소유권을 가진다(판례).","c":"중","v":1},"변리사2021_58-05-4":{"f":"종물은 주물의 처분에 따르지만, 당사자의 특약으로 종물만을 별도로 처분할 수 있다.","w":"종물은 주물의 처분에 따르는 것이 원칙이나 강행규정이 아니다. 특약으로 종물을 제외하거나 종물만 따로 처분할 수 있다(민법 제100조 제2항).","c":"상","v":1},"변리사2021_58-05-5":{"f":"입목에 관한 법률에 의하여 소유권보존등기가 마쳐진 입목은 토지와 분리하여 양도될 수 있고, 저당권의 객체도 될 수 있다.","w":"등기된 입목은 부동산으로 보아 토지와 별개로 양도할 수 있고 저당권의 목적이 될 수 있다(입목에 관한 법률 제3조).","c":"상","v":1},"변리사2024_61-04-1":{"f":"독립한 물건이라면 부동산도 종물이 될 수 있다.","w":"종물은 독립한 물건이면 동산이든 부동산이든 될 수 있다.","c":"중","v":1},"변리사2024_61-04-2":{"f":"주물의 점유로 인한 시효취득의 효력은 점유하지 않은 종물에는 미치지 않는다.","w":"시효취득은 점유를 요건으로 하므로, 주물만 점유했다면 점유하지 않은 종물까지 시효취득하지는 못한다.","c":"중","v":1},"변리사2024_61-04-3":{"f":"주물에 대한 압류의 효력은 원칙적으로 종물에도 미친다.","w":"종물은 주물의 처분에 따르고(민법 제100조 제2항), 이 처분에는 압류 같은 공법상 처분도 포함되므로 주물 압류의 효력은 종물에도 미친다(판례).","c":"상","v":1},"변리사2024_61-04-4":{"f":"주물 그 자체의 효용과 직접 관계가 없는 한 주물의 소유자의 상용에 공여되고 있는 물건이라도 종물이 아니다.","w":"종물은 주물 자체의 효용에 이바지해야 하며, 소유자의 일반적인 사용에 쓰인다는 것만으로는 부족하다.","c":"상","v":1},"변리사2016_53-05-1":{"f":"계약체결 당시 불공정한 법률행위가 아니라면 사후에 외부 환경의 급격한 변화로 계약당사자 일방에게 큰 손실이, 상대방에게는 그에 상응하는 큰 이익이 발생하더라도 불공정한 계약에 해당하지 않는다.","w":"불공정한 법률행위(제104조)는 계약 성립 당시를 기준으로 판단하고, 사후 사정변경은 판단 대상이 아니다(대법원 판례).","c":"상","v":1},"변리사2016_53-06-5":{"f":"사기에 의한 의사표시의 취소로써 대항하지 못하는 선의의 제3자에는 취소 전부터 양립되지 않는 법률관계를 가졌던 제3자뿐 아니라 취소 후 그 말소등기 전에 이해관계를 맺은 제3자도 포함된다.","w":"판례는 취소 전에 이해관계를 맺은 자뿐 아니라 취소 후 말소등기가 되기 전에 새로 이해관계를 맺은 선의의 제3자도 제110조 제3항의 제3자로 보호한다(대법원 1975.12.23. 선고 75다533 판결).","c":"상","v":1},"변리사2016_53-08-1":{"f":"비법인사단인 교회의 대표자가 교인총회의 결의를 거치지 않고 총유물인 교회재산을 처분한 행위에 대하여는 민법 제126조(권한을 넘은 표현대리)를 준용할 수 없다.","w":"총유물 처분은 사원총회 결의가 필요하며, 이를 거치지 않은 대표자의 처분은 표현대리가 성립하지 않는다(대법원 2009.2.12. 선고 판결).","c":"상","v":1},"변리사2016_53-10-1":{"f":"복대리인은 대리인이 선임한 본인의 대리인이다.","w":"복대리인은 대리인의 대리인이 아니라 본인의 대리인이다. 대리인이 자기 이름으로 선임하되 본인을 대리한다(민법 제123조).","c":"상","v":1},"변리사2016_53-11-4":{"f":"조건을 붙이는 것이 허용되지 않는 법률행위에 조건을 붙인 경우 그 법률행위는 무효이다.","w":"조건과 친하지 않은 법률행위에 조건을 붙이면 조건만 무효가 되는 것이 아니라 그 법률행위 전체가 무효이다.","c":"상","v":1},"변리사2017_54-07-5":{"f":"乙이 丙으로부터 받은 매매대금을 유용할 배임적 의도를 갖고 있었고 丙이 이를 알았다면, 민법 제107조 제1항 단서의 유추적용으로 乙의 대리행위는 甲에게 효력이 없다.","w":"대리권 남용을 상대방이 알았거나 알 수 있었던 경우에는 무권대리가 되는 것이 아니라 비진의표시 단서를 유추하여 본인에게 효력이 없다.","c":"중","v":1},"변리사2017_54-08-3":{"f":"乙이 甲을 단독으로 상속하여 X토지의 소유자가 되면, 乙은 본인의 지위에서 매매계약의 추인을 거절할 수 없다.","w":"무권대리인이 본인을 상속한 경우 추인거절은 신의칙에 반하여 허용되지 않는다(대법원 1994.9.27. 선고 판결).","c":"상","v":1},"변리사2019_56-05-1":{"f":"착오가 의사표시자의 중대한 과실로 인한 경우에도 상대방이 그 착오를 알고 이를 이용하였다면 의사표시자는 착오를 이유로 의사표시를 취소할 수 있다.","w":"중과실이 있어도 상대방이 착오를 알고 이용한 경우에는 취소할 수 있다(대법원 판례).","c":"상","v":1},"변리사2019_56-05-3":{"f":"무효인 가등기를 유효한 등기로 전용할 것을 약정하였더라도 그 가등기가 소급하여 유효로 되는 것은 아니다.","w":"무효인 등기를 유효한 등기로 쓰기로 약정해도 그 등기는 약정한 때부터 유효하고, 처음 등기한 때로 소급하지 않는다(판례). 무효행위의 추인에는 소급효가 없다(민법 제139조).","c":"상","v":1},"변리사2019_56-05-4":{"f":"취소권을 행사할 수 있는 기간의 경과 여부는 제척기간이므로 법원이 직권으로 조사하여 고려해야 한다.","w":"취소권 행사기간은 제척기간이어서 당사자의 주장이 없어도 법원이 직권으로 조사한다.","c":"상","v":1},"변리사2019_56-05-5":{"f":"유동적 무효인 토지거래계약이 확정적으로 무효가 된 경우, 이에 대해 귀책사유가 있는 자도 계약의 무효를 주장할 수 있다.","w":"토지거래허가를 받지 않은 계약이 확정적으로 무효가 되면, 무효가 된 데 귀책사유가 있는 당사자도 그 무효를 주장할 수 있다(판례).","c":"상","v":1},"변리사2019_56-06-1":{"f":"공무원 甲이 사직의 의사표시를 하는 것과 같은 사인의 공법행위에는 진의 아닌 의사표시에 관한 민법 규정이 적용되지 않는다.","w":"사인의 공법행위에는 민법 제107조 단서가 적용되지 않는다. 사직서 제출 시 속마음이 달라도 효력이 있다.","c":"상","v":1},"변리사2019_56-09-1":{"f":"乙이 무권대리인임을 알았던 丙도 甲에게 乙의 대리행위에 대한 추인 여부의 확답을 최고할 수 있다.","w":"최고권은 상대방의 선의·악의와 관계없이 인정된다(민법 제131조). 철회권만 선의의 상대방에게 있다.","c":"상","v":1},"변리사2018_55-11-1":{"f":"복대리인은 본인의 대리인이다.","w":"복대리인은 대리인의 대리인이 아니라 본인의 대리인이다(민법 제123조 제1항).","c":"상","v":1},"변리사2018_55-11-2":{"f":"임의대리인은 본인의 승낙이 있거나 부득이한 사유가 있는 때가 아니면 복대리인을 선임하지 못한다.","w":"임의대리인은 원칙적으로 복임권이 없고, 본인의 승낙이나 부득이한 사유가 있을 때에만 복대리인을 선임할 수 있다(민법 제120조).","c":"상","v":1},"변리사2018_55-11-4":{"f":"법정대리인이 부득이한 사유로 복대리인을 선임한 경우에는 본인에 대하여 그 선임감독에 관한 책임만 있다.","w":"법정대리인이 부득이한 사유로 복대리인을 선임한 때에는 선임·감독에 관한 책임을 진다(민법 제122조 단서, 제121조 제1항). 부적임·불성실을 알고 통지나 해임을 게을리한 때에만 책임지는 것은 임의대리인이 본인의 지명으로 복대리인을 선임한 경우이다(제121조 제2항).","c":"상","v":1},"변리사2018_55-11-5":{"f":"대리인의 사망으로 대리권이 소멸한 경우에는 복대리권도 소멸한다.","w":"복대리권은 대리인의 대리권을 바탕으로 하므로 대리권이 소멸하면 복대리권도 소멸한다.","c":"상","v":1},"변리사2019_56-11-3":{"f":"매매계약의 체결에 관한 권한을 수여받은 乙이 甲을 대리하여 매매계약을 체결한 경우, 乙은 특별한 사정이 없는 한 甲을 대리하여 매매계약의 해제 등 처분권을 행사할 수 없다.","w":"매매계약 체결 권한에는 중도금·잔금을 받는 이행 권한은 포함되지만, 계약 해제 같은 처분권은 포함되지 않는다.","c":"중","v":1},"변리사2019_56-12-3":{"f":"조건이 법률행위 당시 이미 성취한 것인 경우에는 그 조건이 해제조건이면 그 법률행위는 무효로 한다.","w":"이미 성취한 조건이 정지조건이면 조건 없는 법률행위가 되고, 해제조건이면 그 법률행위는 무효이다(민법 제151조 제2항).","c":"상","v":1},"변리사2021_58-04-3":{"f":"무상임치의 경우에는 임치인(채권자)만이, 무이자 소비대차의 경우에는 채무자만이 기한이익을 갖는다.","w":"무상임치에서 기한은 임치인(채권자)을 위한 것이다. 임치인은 기간을 정했어도 언제든 계약을 해지하고 반환을 청구할 수 있고, 수치인은 부득이한 사유 없이 기간 전에 해지하지 못한다(민법 제698조). 무이자 소비대차에서는 채무자만 기한이익을 갖는다.","c":"중","v":1},"변리사2021_58-07-2":{"f":"불공정한 법률행위로서 무효인 경우에는 추인하여도 유효로 되지 않는다.","w":"불공정한 법률행위는 절대적 무효이므로 추인해도 유효가 되지 않는다.","c":"상","v":1},"변리사2021_58-07-3":{"f":"불공정한 법률행위에 관한 규정은 부담 없는 증여의 경우에는 적용되지 않는다.","w":"대가 없이 한쪽만 급부하는 부담 없는 증여에는 불공정한 법률행위에 관한 민법 제104조가 적용되지 않는다(판례).","c":"상","v":1},"변리사2021_58-07-4":{"f":"경매에서 경매부동산의 매각대금이 시가에 비하여 현저히 저렴한 경우에도, 불공정한 법률행위에 해당하지 않는다.","w":"경매는 당사자의 법률행위가 아니라 법원이 진행하는 절차여서, 매각대금이 시가보다 현저히 낮아도 민법 제104조가 적용되지 않는다(판례).","c":"상","v":1},"변리사2021_58-07-5":{"f":"법률행위가 현저하게 공정을 잃은 경우에도, 그 법률행위가 궁박·경솔·무경험으로 인해 이루어진 것으로 추정되지 않는다.","w":"급부와 반대급부 사이의 현저한 불균형이 있다고 해서 궁박·경솔·무경험이 추정되지 않는다. 이 요건은 주장하는 쪽이 증명해야 한다(대법원 판례).","c":"상","v":1},"변리사2021_58-08-1":{"f":"법률에 관한 착오도 그것이 법률행위 내용의 중요부분에 관한 것이라면 착오를 이유로 취소할 수 있다.","w":"법률의 부지·착오도 법률행위 내용의 중요부분에 관한 것이면 취소할 수 있다(대법원 판례).","c":"상","v":1},"변리사2021_58-08-2":{"f":"착오로 인한 의사표시의 취소에 관한 민법 제109조 제1항은 당사자의 합의로 그 적용을 배제할 수 있다.","w":"제109조 제1항은 임의규정이어서 당사자 합의로 배제할 수 있다.","c":"상","v":1},"변리사2021_58-08-3":{"f":"착오한 표의자의 중대한 과실 유무에 관한 증명책임은 의사표시의 효력을 부인하려는 상대방에게 있다.","w":"표의자의 중대한 과실은 취소를 막으려는 상대방이 증명한다.","c":"상","v":1},"변리사2021_58-08-5":{"f":"표의자가 착오를 이유로 의사표시를 취소한 경우, 취소로 인하여 손해를 입은 상대방은 표의자에게 불법행위로 인한 손해배상을 청구할 수 없다.","w":"착오가 경과실에 그치는 표의자가 취소권을 행사한 것은 위법하지 않으므로, 상대방은 취소로 입은 손해를 불법행위로 청구할 수 없다.","c":"중","v":1},"변리사2021_58-09-3":{"f":"丙과의 매매계약이 불공정한 법률행위에 해당하는지 여부가 문제된 경우, 매도인의 무경험은 대리인 乙을 기준으로 판단한다.","w":"대리인이 계약을 체결한 경우 경솔·무경험은 대리인을 기준으로, 궁박은 본인을 기준으로 판단한다(대법원 판례).","c":"중","v":1},"변리사2021_58-10-1":{"f":"제한능력자의 법률행위에 대한 법정대리인의 추인은 취소의 원인이 소멸되기 전에도 그 효력이 있다.","w":"취소의 원인이 소멸된 후에 추인해야 한다는 요건은 취소권자가 제한능력자 본인일 때의 것이고, 법정대리인의 추인에는 이 요건이 필요 없다(민법 제144조 제2항).","c":"상","v":1},"변리사2021_58-11-5":{"f":"X토지가 중간생략등기의 합의에 따라 乙로부터 丙에게 허가 없이 전매된 경우, 丙은 甲에 대하여 직접 허가신청절차의 협력의무 이행청구권을 가지지 못한다.","w":"허가구역 안의 토지를 허가 없이 전매하면서 중간생략등기를 합의했더라도, 최종 매수인 丙은 최초 매도인 甲에게 직접 허가신청절차 협력을 청구할 수 없다(판례).","c":"상","v":1},"변리사2021_58-12-1":{"f":"丙이 乙의 대리행위가 유권대리라고 주장하는 경우, 그 주장 속에는 표현대리의 주장이 포함된 것으로 볼 수 없다.","w":"유권대리와 표현대리는 별개의 요건사실이어서, 유권대리 주장에 표현대리 주장이 당연히 포함되지 않는다(대법원 1983.12.13. 전원합의체 판결).","c":"상","v":1},"변리사2021_58-12-3":{"f":"丙이 계약체결 당시에 乙에게 매매계약 체결의 대리권이 없음을 알았다면 계약을 철회할 수 없다.","w":"상대방의 철회권은 계약 당시 대리권 없음을 몰랐던 선의의 상대방에게만 있다(민법 제134조).","c":"상","v":1},"변리사2021_58-12-4":{"f":"乙의 행위가 권한을 넘은 표현대리로 인정되는 경우, 丙에게 과실(過失)이 있더라도 과실상계의 법리에 따라 甲의 책임이 경감될 수는 없다.","w":"표현대리가 성립하면 본인은 대리행위 전부에 대해 책임을 지고, 상대방에게 과실이 있어도 과실상계로 책임을 줄일 수 없다(판례).","c":"상","v":1},"변리사2021_58-12-5":{"f":"丙이 乙의 대리행위가 권한을 넘은 표현대리라고 주장하는 경우, 乙에게 매매계약체결의 대리권이 있다고 丙이 믿을 만한 정당한 이유가 있었는지의 여부는 계약성립 당시의 모든 사정을 고려하여 판단해야 한다.","w":"정당한 이유는 대리행위가 이루어진 당시를 기준으로 판단하고, 계약성립 이후의 사정은 고려하지 않는다.","c":"상","v":1},"변리사2023_60-08-4":{"f":"통정허위표시에 따른 선급금 반환채무 부담행위에 기하여 선의로 그 채무를 보증하고 보증채무를 이행하여 구상권을 취득한 자는 허위표시의 무효로부터 보호받는 제3자에 해당한다.","w":"판례는 허위의 주채무를 선의로 보증하고 보증채무를 이행해 구상권을 취득한 보증인을 민법 제108조 제2항의 제3자로 본다. 보증채무를 이행해 구상권을 얻은 것이 새로운 이해관계의 근거가 되었다.","c":"중","v":1},"변리사2023_60-09-5":{"f":"예술품의 위작(僞作)을 진품으로 착각한 매도인의 말을 믿고서 과실 없이 진품에 상응하는 가격으로 그 위작을 구입한 매수인이 매도인에게 하자담보책임을 물을 수 있더라도 착오취소를 주장할 수 있다.","w":"하자담보책임과 착오취소는 요건과 효과가 달라 함께 성립할 수 있다. 매수인은 하자담보책임을 물을 수 있더라도 착오를 이유로 매매계약을 취소할 수 있다(판례).","c":"상","v":1},"변리사2023_60-10-1":{"f":"대리권은 대리인의 권리도 의무도 아니다.","w":"대리권은 대리인이 본인을 위해 행위하여 그 효과를 본인에게 귀속시킬 수 있는 법률상의 지위(자격)이다. 권리나 의무가 아니다.","c":"상","v":1},"변리사2023_60-10-3":{"f":"복대리인은 본인의 대리인이지만 원대리인의 복임행위는 본인을 위한 대리행위가 아니다.","w":"복임행위는 대리인이 자기 권한으로 복대리인을 선임하는 행위이며 본인을 대리하는 행위가 아니다. 복대리인의 선임은 대리인 자신의 행위이다.","c":"상","v":1},"변리사2023_60-10-4":{"f":"대리권이 이미 소멸한 원대리인에 의해 선임된 복대리인의 대리행위에 대해서도 대리권 소멸 후의 표현대리(제129조)가 성립할 여지가 있다.","w":"대리권이 소멸한 원대리인이 선임한 복대리인의 대리행위에도 대리권 소멸 후의 표현대리(민법 제129조)가 성립할 수 있다(판례).","c":"상","v":1},"변리사2023_60-10-5":{"f":"자신에게 유효한 대리권이 있다고 과실 없이 믿었던, 행위능력 있는 선의의 무권대리인도 본인의 추인이 없다면 상대방에 대한 무권대리인의 책임에 관한 민법 제135조에 따른 책임을 진다.","w":"제135조의 무권대리인 책임은 무과실책임이다. 자신에게 대리권이 있다고 믿은 데 과실이 없어도 책임을 진다(대법원 판례). 행위능력이 없는 경우만 면책된다.","c":"상","v":1},"변리사2023_60-11-5":{"f":"乙은 특별한 사정이 없는 한 위 매매계약의 허가를 받기 전까지는 부당이득반환청구권을 행사하여 甲에게 이미 지급한 계약금의 반환을 청구할 수 없다.","w":"허가를 받기 전 유동적 무효 상태에서는 계약이 확정적으로 무효가 되기 전이므로, 이미 지급한 계약금을 부당이득으로 반환청구할 수 없다(판례).","c":"상","v":1},"변리사2023_60-12-1":{"f":"이행지체의 경우 채권자는 채무자를 상대로 상당한 기간을 정하여 이행을 청구하면서 그 기간 내에 이행이 없으면 계약은 당연히 해제된 것으로 한다는 취지의 정지조건부 해제권 행사를 할 수 있다.","w":"이행 최고와 함께 기간 내 이행하지 않으면 해제된 것으로 한다는 의사표시는 정지조건부 해제의 의사표시로서 유효하다. 해제조건부로 보지 않는다.","c":"중","v":1},"변리사2024_61-06-2":{"f":"매매목적물에 하자가 있는 사실을 착오로 알지 못하고 매매계약을 체결한 매수인은 착오로 인한 의사표시의 취소 요건을 갖춘 경우 매도인의 하자담보책임이 성립하더라도 착오를 이유로 그 계약을 취소할 수 있다.","w":"하자담보책임과 착오취소는 경합할 수 있어, 하자담보책임을 물을 수 있어도 착오취소가 가능하다(대법원 2018.9.13. 선고 판결).","c":"상","v":1},"변리사2024_61-07-3":{"f":"적법하게 성립된 매매에 관하여 해제사유가 발생한 경우, 해제의 의사가 상대방 당사자의 미성년 자(子)에게 도달하더라도 그 즉시 해제의 효력이 발생하지는 않는다.","w":"의사표시는 상대방이 그 내용을 알 수 있는 객관적 상태에 놓인 때 도달한다. 상대방의 미성년 자녀가 받았다는 사실만으로 곧바로 도달했다고 볼 수 없고, 그 자녀가 사리를 분별해 상대방에게 전할 수 있었는지에 따라 판단한다.","c":"중","v":1},"변리사2024_61-08-1":{"f":"법정대리인은 원칙적으로 부득이한 사유가 없어도 복임권이 있다.","w":"법정대리인은 부득이한 사유가 없어도 자기 책임으로 복대리인을 선임할 수 있다(민법 제122조).","c":"상","v":1},"변리사2024_61-09-5":{"f":"만일 丙이 丁에게 위 부동산을 매도한 경우, 乙이 丁에게만 추인의 의사를 표시하더라도 추인의 효력은 발생한다.","w":"추인은 무권대리인이나 상대방, 상대방의 승계인에게 할 수 있다(대법원 1981.4.14. 선고 판결).","c":"상","v":1},"변리사2024_61-10-1":{"f":"미성년자가 체결한 계약이 법정대리인의 동의없음을 이유로 취소할 수 있는 경우, 계약당사자인 미성년자는 단독으로 그 계약을 취소할 수 있다.","w":"제한능력자 본인도 취소권자이므로 법정대리인의 동의 없이 단독으로 취소할 수 있다(민법 제140조).","c":"상","v":1},"변리사2024_61-10-2":{"f":"계약을 체결할 수 있는 권한만을 가진 임의대리인이 상대방의 사기로 계약을 체결한 경우, 그 임의대리인은 별도의 수권 없이 그 계약을 취소할 수 없다.","w":"취소권은 계약 체결 대리권에 당연히 포함되지 않고, 취소 수권을 따로 받아야 한다. 취소권은 본인에게 속한다.","c":"중","v":1},"변리사2024_61-10-3":{"f":"미성년자인 임의대리인이 계약을 체결한 경우, 본인은 미성년자에 의한 대리행위라는 이유로 취소할 수 없다.","w":"대리인은 행위능력자일 필요가 없으므로 본인은 대리인이 제한능력자임을 이유로 대리행위를 취소할 수 없다(민법 제117조).","c":"상","v":1},"변리사2024_61-10-5":{"f":"미성년자가 단독으로 발급받은 신용카드를 이용하여 구입한 물품의 대금을 성년자가 되어 이의없이 결제한 후에는 그 물품구입계약을 미성년자의 행위임을 이유로 취소할 수 없다.","w":"성년이 된 뒤 이의 없이 대금을 이행하면 법정추인이 되어 취소할 수 없다(민법 제145조 제1호).","c":"상","v":1},"변리사2024_61-11-1":{"f":"乙은 甲을 상대로 허가가 나오는 것을 조건으로 하여 잔금과 상환으로 이전등기를 해 달라고 청구할 수 없다.","w":"토지거래허가를 받기 전에는 채권적 효력도 없으므로 이행청구가 허용되지 않는다. 허가를 조건으로 한 장래이행청구도 안 된다(대법원 1991.12.24. 전원합의체 판결).","c":"상","v":1},"변리사2024_61-11-2":{"f":"허가가 나오기 전에는 甲은 乙이 잔금기일에 잔금을 지급하지 않았다는 것을 이유로 위 계약을 해제할 수 없다.","w":"허가 전에는 유동적 무효 상태여서 채무불이행을 이유로 계약을 해제할 수 없다.","c":"상","v":1},"변리사2024_61-11-4":{"f":"거래허가를 신청하기 전이라도 乙의 기망행위로 위 계약을 체결하였다면 甲은 그 계약을 취소할 수 있다.","w":"유동적 무효 상태에서도 사기에 의한 취소는 가능하며, 허가 신청 전에 취소하여 협력의무를 면할 수 있다(대법원 1997.11.14. 선고 판결).","c":"상","v":1},"변리사2024_61-11-5":{"f":"만일 계약 당시 합의에 따라 계약금을 乙이 丙에게 지급하였는데 그 후 위 계약이 확정적으로 무효가 된 경우, 특별한 사정이 없는 한 乙은 甲을 상대로 지급한 계약금 상당액의 반환을 청구할 수 있다.","w":"乙이 甲과의 합의에 따라 丙에게 계약금을 지급한 것은 甲에 대한 급부이므로, 계약이 확정적으로 무효가 되면 乙은 甲에게 반환을 청구해야 하고 丙에게 직접 부당이득반환을 청구할 수 없다(판례).","c":"상","v":1},"변리사2026_63-05-3":{"f":"불공정한 법률행위로 무효인 경우, 당사자가 이를 추인하더라도 무효인 법률행위가 유효로 되지 않는다.","w":"불공정한 법률행위(민법 제104조)로 무효인 경우에는 당사자가 추인하더라도 유효가 되지 않는다(판례).","c":"상","v":1},"변리사2026_63-06-4":{"f":"매도인이 제3자의 기망행위에 의해 매수인과 매매계약을 체결한 경우, 매도인이 그 제3자에게 사기에 의한 불법행위를 이유로 손해배상을 청구하기 위해서는 그 매매계약을 취소할 필요가 없다.","w":"사기 취소와 불법행위 손해배상은 별개이므로 매매계약을 취소하지 않고도 제3자에게 손해배상을 청구할 수 있다(대법원 판례).","c":"중","v":1},"변리사2026_63-08-2":{"f":"권한을 넘은 표현대리는 특별한 사정이 없는 한, 대리인이 사술을 써서 대리행위의 표시없이 단지 본인의 성명을 모용하여 자기가 마치 본인인 것처럼 기망하여 본인 명의로 직접 법률행위를 한 경우에는 성립될 수 없다.","w":"대리행위의 표시 없이 본인 행세를 하며 본인 명의로 직접 법률행위를 한 경우, 상대방은 대리인과 거래한다고 인식하지 않았으므로 특별한 사정이 없으면 권한을 넘은 표현대리가 성립하지 않는다(판례).","c":"상","v":1},"변리사2026_63-08-3":{"f":"대리권 소멸 후의 표현대리에 관한 민법 제129조는 법정대리인의 대리권 소멸에 관하여서도 적용될 수 있다.","w":"제129조는 임의대리뿐 아니라 법정대리에도 적용된다(대법원 1975.1.28. 선고 판결).","c":"상","v":1},"변리사2026_63-08-4":{"f":"지방자치단체가 사경제주체로서 한 법률행위에 대해서는 표현대리에 관한 법리가 적용될 수 있다.","w":"사경제주체로서 하는 거래에서는 사인과 마찬가지로 표현대리 법리가 적용된다.","c":"중","v":1},"변리사2026_63-08-5":{"f":"학교법인을 대표하는 이사장이 사립학교법상 규정을 위반하여 이사회의 심의결정없이 학교법인의 기본재산을 처분하는 행위에 대해서는 권한을 넘은 표현대리에 관한 규정이 준용될 수 없다.","w":"법령상 이사회 심의결정이 필요한 행위를 거치지 않은 처분에는 표현대리 규정을 준용할 수 없다(대법원 판례).","c":"중","v":1},"변리사2026_63-09-2":{"f":"甲이 丙에게 계약을 이미 추인하였다면, 丙이 계약체결 당시 乙이 무권대리인임을 알지 못하였더라도 丙은 계약을 철회할 수 없다.","w":"상대방의 철회는 본인이 추인하기 전에만 가능하다(민법 제134조).","c":"상","v":1},"변리사2016_53-12-1":{"f":"형성권은 제척기간의 경과 자체만으로 곧 권리 소멸의 효과가 발생한다.","w":"제척기간은 기간 경과 자체로 권리가 소멸하고, 소멸시효와 달리 당사자의 원용이 필요 없다.","c":"상","v":1},"변리사2017_54-11-4":{"f":"A호텔의 청구에 대하여 기각판결이 확정된 후, A호텔이 재심을 청구하더라도 소멸시효의 진행이 중단되지 않는다.","w":"기각된 때에는 재판상 청구로 인한 시효중단의 효력이 없다(민법 제170조 제1항).","c":"중","v":1},"변리사2017_54-12-2":{"f":"채권자가 채무자를 상대로 법원에 신청한 화해가 불성립되어 채권자가 그로부터 1월내에 소를 제기한 경우, 채권의 소멸시효는 화해신청 시부터 중단된다.","w":"화해신청 시에 시효가 중단되며, 불성립 후 1월 내에 소를 제기하면 그 효력이 유지된다(민법 제173조).","c":"상","v":1},"변리사2017_54-12-3":{"f":"소멸시효의 기간만료 전 6월 내에 제한능력자에게 법정대리인이 없는 경우, 그가 능력자가 되거나 법정대리인이 취임한 때로부터 6월 내에는 소멸시효가 완성되지 아니한다.","w":"기간은 6개월이다(민법 제179조). 1년이 아니다.","c":"상","v":1},"변리사2017_54-12-4":{"f":"상속재산에 대한 권리는 상속인의 확정, 관리인의 선임 또는 파산선고가 있는 때로부터 6월 내에는 소멸시효가 완성되지 아니한다.","w":"기간은 6개월이다(민법 제181조).","c":"상","v":1},"변리사2017_54-12-5":{"f":"채무자가 시효중단의 효력이 있는 승인을 하는 데에는 채권자의 채권에 관한 처분의 능력이나 권한이 있을 것을 요하지 않는다.","w":"승인에는 상대방의 권리에 관한 처분의 능력이나 권한이 필요 없다(민법 제177조). 승인하는 채무자에게는 관리의 능력이나 권한만 있으면 된다.","c":"상","v":1},"변리사2018_55-01-1":{"f":"부작위채권도 소멸시효의 대상이 된다.","w":"부작위를 목적으로 하는 채권도 소멸시효에 걸리며, 위반행위를 한 때부터 시효가 진행한다(민법 제166조 제2항).","c":"상","v":1},"변리사2018_55-01-2":{"f":"주채무자가 시효완성의 이익을 포기한 경우에도 보증인은 주채무의 시효소멸을 원용할 수 있다.","w":"주채무자의 항변포기는 보증인에게 효력이 없으므로(민법 제433조 제2항), 주채무자가 시효이익을 포기해도 보증인은 주채무의 시효소멸을 원용할 수 있다.","c":"상","v":1},"변리사2018_55-01-3":{"f":"“시효의 중단은 당사자 및 그 승계인 간에만 효력이 있다”는 규정(민법 제169조)에서 ‘승계인’에는 특정승계인이 포함된다.","w":"제169조의 승계인에는 포괄승계인뿐 아니라 특정승계인도 포함된다.","c":"상","v":1},"변리사2018_55-01-4":{"f":"기한을 정하지 않은 채권의 소멸시효의 기산점은 이행청구를 받은 때가 아니라 채권이 발생된 때이다.","w":"기한 없는 채권은 성립한 때부터 언제든 청구할 수 있으므로 그때부터 소멸시효가 진행한다(민법 제166조 제1항).","c":"상","v":1},"변리사2019_56-08-1":{"f":"제척기간이 경과하면 그 기산일에 소급하여 권리소멸의 효과가 발생하지 않는다.","w":"소멸시효와 달리 제척기간은 기간이 지난 때에 권리가 소멸하고 기산일로 소급하지 않는다.","c":"중","v":1},"변리사2019_56-08-2":{"f":"제척기간은 권리자의 청구나 압류 등이 있어도 중단되지 않는다.","w":"제척기간에는 중단이 없다. 소멸시효에만 중단·정지 제도가 있다.","c":"상","v":1},"변리사2019_56-08-3":{"f":"점유보호청구권의 행사기간은 제척기간이기 때문에 반드시 그 기간 내에 소를 제기하여야 한다.","w":"점유보호청구권의 행사기간은 출소기간이어서 재판 외 행사로는 부족하고 기간 내에 소를 제기해야 한다.","c":"상","v":1},"변리사2019_56-08-5":{"f":"채권양도의 통지만으로는 제척기간의 준수에 필요한 권리의 재판 외 행사가 이루어졌다고 볼 수 없다.","w":"채권양도 통지는 양도 사실을 알리는 관념의 통지일 뿐, 채무자에게 채권의 이행을 청구하는 권리 행사가 아니다.","c":"중","v":1},"변리사2019_56-10-3":{"f":"甲이 乙을 상대로 대여금반환청구의 소를 제기하였다가 이후 그 소를 취하한 경우에는 甲의 대여금반환청구의 소제기로 인한 시효중단의 효력이 없다.","w":"재판상 청구는 소송이 각하·기각·취하되면 시효중단의 효력이 없다(민법 제170조 제1항). 다만 6개월 안에 재판상 청구, 파산절차참가, 압류·가압류·가처분을 하면 최초의 재판상 청구 때 중단된 것으로 본다(같은 조 제2항).","c":"상","v":1},"변리사2019_56-15-5":{"f":"소유권이전등기의 말소를 구하는 소를 제기하였다가 그 소를 취하한 후, 그로부터 6개월 내에 다시 취하된 소와 동일한 내용의 소를 제기한 경우, 최초의 소가 제기된 때로부터 취득시효의 진행이 중단된다.","w":"6개월 내에 다시 소를 제기하면 최초의 재판상 청구 때 중단된 것으로 본다(민법 제170조 제2항). 후소 제기 시가 아니다.","c":"상","v":1},"변리사2021_58-06-5":{"f":"원인채권의 지급을 확보하기 위하여 어음이 수수된 당사자 사이에 채권자가 어음채권에 관한 집행권원에 기하여 한 배당요구는 그 원인채권의 소멸시효를 중단시키는 효력이 있다.","w":"배당요구는 압류에 준하는 시효중단 사유이며, 어음채권에 의한 배당요구가 원인채권의 시효도 중단시킨다.","c":"중","v":1},"변리사2023_60-05-2":{"f":"2004년 1월 17일 오후 2시에 태어난 甲이 성년이 되는 시점은 2023년 1월 16일 24시이다.","w":"나이는 출생일을 산입하여 만 나이로 계산한다(민법 제158조). 2004. 1. 17.에 태어난 甲은 2023. 1. 16.이 끝나는 24시에 만 19세가 되어 성년이 된다.","c":"상","v":1},"변리사2024_61-12-3":{"f":"채무자가 채권자를 상대로 채무부존재확인소송을 제기하여 채권자가 이를 적극적으로 다툰 경우, 채권자가 응소하여 적극적으로 권리를 주장한 때부터 시효중단의 효력이 인정된다.","w":"채무자가 제기한 소 자체로는 시효가 중단되지 않는다. 채권자가 그 소송에 응소하여 적극적으로 권리를 주장하고 그것이 받아들여지면, 응소한 때에 재판상 청구로서 시효가 중단된다(대법원 1993. 12. 21. 선고 92다47861 전원합의체 판결).","c":"상","v":1},"변리사2018_55-19-2":{"f":"乙의 甲에 대한 본등기청구권은 乙의 가등기가 존속하는 동안에도 소멸시효에 걸린다.","w":"가등기가 있어도 본등기청구권은 채권적 청구권이므로 소멸시효에 걸린다(대법원 판례).","c":"상","v":1},"변리사2018_55-19-4":{"f":"乙이 가등기에 기한 본등기를 하면, 乙의 소유권취득의 효력은 본등기를 한 때부터 생긴다.","w":"본등기의 물권변동 효력은 본등기 시에 생기고 가등기 시로 소급하지 않는다. 가등기는 본등기의 순위만 보전한다.","c":"상","v":1},"변리사2018_55-19-5":{"f":"丙 명의의 소유권이전등기가 원인무효라도 가등기권리자인 乙은 직접 그 말소를 구할 수 없다.","w":"가등기권리자는 아직 소유권자가 아니어서 제3자의 등기에 대한 말소청구권이 없고, 소유자를 대위하여 청구하는 방법을 취해야 한다.","c":"중","v":1},"변리사2019_56-14-4":{"f":"후순위 저당권이 있는 부동산의 소유권을 선순위 저당권자가 아무런 조건 없이 증여 받아 취득한 경우에도 혼동에 의해 저당권은 소멸하지 않는다.","w":"다른 사람의 권리의 목적이 되어 있는 때에는 혼동으로 소멸하지 않는다(민법 제191조 제1항 단서). 후순위 저당권자의 이익이 있기 때문이다.","c":"상","v":1},"변리사2021_58-15-1":{"f":"본등기에 의한 물권변동의 효력은 본등기를 한 때부터 발생한다.","w":"가등기는 순위만 보전하고, 본등기를 한 때에 물권변동 효력이 생긴다.","c":"상","v":1},"변리사2021_58-15-3":{"f":"합유자가 그 지분을 포기하면 지분권 이전등기를 하여야 포기된 합유지분이 나머지 잔존 합유지분권자들에게 귀속된다.","w":"합유지분 포기에 의한 물권변동은 법률행위에 의한 변동이므로 등기가 있어야 효력이 생긴다(민법 제186조).","c":"상","v":1},"변리사2021_58-15-4":{"f":"매매로 인한 소유권이전등기에서 등기명의자가 등기원인을 증여로 주장하더라도 등기의 추정력은 깨어지지 않는다.","w":"등기원인이 다르다고 주장해도 추정력은 유지된다. 새 원인이 부적법함을 증명해야 추정이 깨진다.","c":"중","v":1},"변리사2021_58-15-5":{"f":"사망자 명의로 신청하여 이루어진 이전등기에는 등기의 추정력이 인정되지 않으므로, 그 등기의 유효를 주장하는 자가 실체관계에 부합함을 증명하여야 한다.","w":"사망자 명의 신청으로 이루어진 등기는 원인무효로서 추정력이 없다(대법원 판례).","c":"상","v":1},"변리사2021_58-16-4":{"f":"甲은 丙에 대하여 간접점유자로서 점유권에 기한 방해배제청구권을 행사할 수 있다.","w":"임대인 甲은 간접점유자이고, 간접점유자도 점유권에 기한 방해배제를 청구할 수 있다(민법 제207조 제1항). 甲은 소유권에 기한 방해배제도 청구할 수 있다.","c":"상","v":1},"변리사2023_60-14-1":{"f":"미등기건물에 대한 양도담보계약상의 채권자의 지위를 승계하여 건물을 관리하고 있는 자는 그 건물에 대한 철거처분권을 가진 자에 해당하지 않는다.","w":"미등기건물의 양도담보 채권자는 소유권을 취득하지 못하고 철거처분권도 없다.","c":"중","v":1},"변리사2026_63-14-3":{"f":"토지에 대한 점유취득시효가 완성된 후 점유자가 그 토지에 대한 점유를 상실하더라도 시효완성을 원인으로 한 소유권이전등기청구권이 즉시 소멸하는 것은 아니다.","w":"시효완성 후 점유를 상실해도 이전등기청구권은 곧바로 소멸하지 않고, 별도의 소멸시효(10년)에 걸린다.","c":"상","v":1},"변리사2026_63-17-4":{"f":"유치권자가 유치권을 포기하기로 한 경우, 유치물을 채무자에게 인도하지 않아도 포기의 의사표시로 그 유치권이 소멸한다.","w":"유치권은 포기의 의사표시만으로 소멸하고, 유치물을 반환하지 않아도 된다.","c":"상","v":1},"변리사2017_54-13-5":{"f":"미등기 부동산의 경우에도 점유자는 취득시효기간이 완성된 후 등기를 하여야 소유권을 취득한다.","w":"점유취득시효는 기간이 완성되어도 등기를 해야 소유권을 취득한다(민법 제245조 제1항).","c":"상","v":1},"변리사2018_55-14-1":{"f":"甲이 그 소유건물을 乙에게 임대하여 현실적으로 건물이나 그 부지를 점거하고 있지 않더라도, 甲은 그 부지를 점유한다고 볼 수 있다.","w":"건물의 부지는 건물 소유자가 점유하는 것으로 보므로, 건물을 임대하여 현실적으로 건물이나 부지를 점거하지 않아도 건물 소유자인 甲이 그 부지를 점유한다(대법원 판례).","c":"상","v":1},"변리사2018_55-17-1":{"f":"취득시효 완성 후 등기 경료 전에 그 부동산이 제3자에게 명의신탁된 경우, 점유자는 시효완성을 이유로 그 제3자의 소유권 행사를 저지할 수 있다.","w":"명의신탁약정과 그에 따른 등기는 부동산실명법에 따라 무효여서 소유권은 여전히 원래 소유자에게 있다. 점유자는 원래 소유자에 대한 시효취득 등기청구권을 보전하려고 그를 대위해 제3자 명의 등기의 말소를 구할 수 있으므로, 제3자의 소유권 행사를 저지할 수 있다(대법원 판례).","c":"중","v":1},"변리사2018_55-17-3":{"f":"甲의 취득시효 완성 당시 미등기로 남아 있던 토지의 소유자가 취득시효 완성 후에 그 명의로 소유권보존등기를 마쳤더라도, 甲은 토지소유자에 대하여 취득시효의 완성을 주장할 수 있다.","w":"보존등기는 소유자의 변경이 아니므로 취득시효 완성 당시의 소유자에게 계속 주장할 수 있다.","c":"상","v":1},"변리사2018_55-17-4":{"f":"국유재산이 일반재산이던 당시에 취득시효가 완성되었더라도 그 후 행정재산으로 되었다면 시효취득을 원인으로 하는 소유권이전등기를 청구할 수 없다.","w":"등기 전 행정재산이 되면 취득시효를 이유로 한 소유권이전이 허용되지 않는다(대법원 판례).","c":"중","v":1},"변리사2018_55-17-5":{"f":"점유자가 취득시효기간이 경과한 후 소유자와의 분쟁을 간편하게 해결하기 위하여 상대방에게 매수제의를 하였더라도, 점유자의 점유는 타주점유로 전환되지 않는다.","w":"매수제의는 자주점유를 포기한 것이 아니고, 취득시효 완성 후 점유 성질은 달라지지 않는다.","c":"상","v":1},"변리사2018_55-20-2":{"f":"반환청구권의 양도에 의한 소유권의 양도의 경우에는 대항요건을 갖추면 선의취득이 인정될 수 있다.","w":"반환청구권의 양도(지시인도)도 점유 취득의 한 방법으로 선의취득이 인정된다. 점유개정만 제외된다.","c":"상","v":1},"변리사2018_55-20-3":{"f":"甲이 자신의 소유 동산을 乙에게 매도하여 인도하고, 乙이 다시 丙에게 매도하여 인도한 경우, 甲과 乙의 매매가 사회질서에 반하여 무효라도 丙은 선의, 무과실이라면 선의취득할 수 있다.","w":"乙은 점유를 가진 무권리자이므로 乙에서 丙으로의 거래에서는 선의취득이 가능하다.","c":"상","v":1},"변리사2018_55-20-4":{"f":"점유보조자가 횡령한 물건은 민법 제250조(도품, 유실물에 대한 특례)의 도품에 해당하지 않는다.","w":"점유보조자의 횡령은 도품·유실물에 해당하지 않아 제250조가 적용되지 않는다.","c":"중","v":1},"변리사2018_55-20-5":{"f":"甲 소유 동산을 점유하는 乙이 丙에게 매도함과 동시에 丙으로부터 임차하기로 약정한 경우 丙은 현실인도를 받기 전에는 그 동산을 선의취득할 수 없다.","w":"점유개정으로는 선의취득에 필요한 점유취득이 이루어지지 않는다(대법원 판례).","c":"상","v":1},"변리사2018_55-22-5":{"f":"공유자 중 1인이 다른 공유자의 동의 없이 공유토지 전부를 매도하여 타인 명의로 소유권이전등기가 마쳐진 경우, 다른 공유자는 처분한 공유자의 지분을 제외한 나머지 부분에 관해서만 소유권이전등기의 말소를 청구할 수 있다.","w":"처분한 공유자의 지분 범위에서는 그 등기가 실체관계에 부합하므로, 다른 공유자는 보존행위로서 그 지분을 넘는 부분에 대해서만 말소를 청구할 수 있다(대법원 판례).","c":"상","v":1},"변리사2019_56-13-5":{"f":"","w":"丙은 소유권이전등기를 마치지 않아 X토지의 소유자가 아니다(제186조). 소유권에 기한 물권적 청구권은 소유자인 甲에게 있으므로 丙은 제3자에게 이를 직접 행사할 수 없고 점유권에 기한 청구나 乙·甲의 권리를 대위하는 방법을 써야 한다.","c":"상","v":1},"변리사2021_58-13-5":{"f":"점유보조자가 보관한 물건을 횡령하여 형사상 절도죄가 성립되는 경우에도, 그 물건은 민법 제250조(도품유실물에 대한 특례)의 도품에 해당하지 않는다.","w":"점유보조자의 횡령은 도품이 아니어서 피해자는 2년 내 반환청구권을 갖지 못한다.","c":"중","v":1},"변리사2023_60-15-2":{"f":"甲의 통상의 필요비 청구가 부정되는 민법 제203조(점유자의 상환청구권) 제1항 단서 규정은 과실수취권이 없는 악의의 점유자에 대해서는 적용되지 않는다.","w":"제203조 제1항 단서는 과실을 취득한 점유자에게 적용된다. 과실수취권이 없는 악의의 점유자는 통상의 필요비를 청구할 수 있다.","c":"상","v":1},"변리사2023_60-15-3":{"f":"민법 제203조(점유자의 상환청구권) 제2항에서 유익비의 상환범위는 지출금액이나 증가액 중 회복자의 선택에 따른다.","w":"유익비는 점유자가 지출한 금액이나 현존하는 증가액 중 회복자가 선택하는 것으로 상환한다(민법 제203조 제2항).","c":"상","v":1},"변리사2023_60-15-4":{"f":"점유물이 甲의 책임있는 사유로 인하여 멸실한 경우, 민법 제202조(점유자의 회복자에 대한 책임)에 따르면 甲이 악의의 점유자로서 부담하는 손해배상범위와 선의이면서 타주점유자로서 부담하는 손해배상범위는 다르지 않다.","w":"악의 점유자와 선의 타주점유자는 모두 손해 전부를 배상한다. 선의 자주점유자만 현존이익의 범위에서 배상한다(민법 제202조).","c":"상","v":1},"변리사2023_60-15-5":{"f":"점유를 침탈당한 甲이 본권인 유치권 소멸에 따른 손해배상청구권을 행사하는 때에는 점유를 침탈당한 날부터 1년 내에 행사해야 하는 것은 아니다.","w":"1년의 제척기간(민법 제204조 제3항)은 점유보호청구권에만 적용된다. 본권인 유치권이 소멸해 생긴 손해배상청구권에는 이 기간이 적용되지 않는다(판례).","c":"상","v":1},"변리사2024_61-14-3":{"f":"법정대리인의 동의를 받지 않은 미성년자로부터 타인 소유의 자전거를 선의로 매수한 자는 그 미성년자가 제한능력을 이유로 매매계약을 취소하면 선의취득에 기해 그 자전거의 소유권을 취득할 수 없다.","w":"선의취득은 유효한 거래행위를 전제로 한다. 거래행위 자체가 제한능력을 이유로 취소되면 선의취득이 성립하지 않는다.","c":"상","v":1},"변리사2024_61-15-1":{"f":"선의의 점유자라도 본권에 관한 소에 패소한 때에는 그 소가 제기된 때로부터 악의의 점유자로 본다.","w":"본권에 관한 소에 패소하면 소 제기 시부터 악의의 점유자로 본다(민법 제197조 제2항).","c":"상","v":1},"변리사2024_61-15-3":{"f":"직접점유자가 그의 점유를 침탈당하거나 방해당하고 있는 경우, 간접점유자도 점유보호청구권을 행사할 수 있다.","w":"점유보호청구권은 간접점유자도 가진다(민법 제207조).","c":"상","v":1},"변리사2024_61-15-4":{"f":"甲의 점유가 타주점유인 경우, 甲의 특정승계인 乙이 자기의 점유만을 주장하면 그 점유는 자주점유로 추정된다.","w":"점유자는 소유의 의사로 점유하는 것으로 추정되고(제197조 제1항), 승계인이 자기 점유만 주장하면 전 점유자의 하자를 지지 않는다.","c":"상","v":1},"변리사2024_61-15-5":{"f":"과실수취권이 있는 점유자는 점유물로부터 과실을 취득한 경우 회복자에 대하여 점유물을 보존하기 위하여 지출한 통상의 필요비의 상환을 청구할 수 없다.","w":"과실을 취득한 점유자는 통상의 필요비를 청구하지 못한다(민법 제203조 제1항 단서).","c":"상","v":1},"변리사2024_61-17-1":{"f":"공유자는 다른 공유자의 동의없이 자기의 지분을 담보로 제공할 수 있다.","w":"공유자는 자기 지분을 자유롭게 처분할 수 있으므로 담보로 제공하는 것도 다른 공유자의 동의가 필요 없다(민법 제263조).","c":"상","v":1},"변리사2024_61-17-2":{"f":"공유물의 변경은 공유자 전원의 동의로 결정한다.","w":"공유물의 처분·변경에는 전원의 동의가 필요하다(민법 제264조). 지분 과반수로 결정하는 것은 관리행위이다.","c":"상","v":1},"변리사2024_61-17-3":{"f":"공유물의 관리에 관한 사항은 공유자의 지분의 과반수로써 결정한다.","w":"관리는 공유자의 머릿수가 아니라 지분의 과반수로 결정한다(민법 제265조).","c":"상","v":1},"변리사2024_61-17-5":{"f":"총유물에 대한 보존행위는 달리 정함이 없는 한 비법인사단의 사원총회의 결의에 따라야 하고, 각 사원이 단독으로 할 수 없다.","w":"총유물의 보존행위도 사원총회의 결의를 거쳐야 하며 각 사원은 단독으로 할 수 없다(민법 제276조 제1항, 대법원 2005.9.15. 전원합의체 판결).","c":"상","v":1},"변리사2026_63-18-3":{"f":"악의 점유자는 수취한 과실을 반환함에 있어서 그 받은 이익에 이자를 붙여 반환하여야 한다.","w":"악의의 점유자는 받은 이익에 이자를 붙여 반환하고, 손해가 있으면 배상한다(민법 제201조 제2항, 제748조 제2항).","c":"상","v":1},"변리사2026_63-19-1":{"f":"부동산에 대한 점유취득시효가 완성된 경우, 소유명의자는 점유자가 시효가 완성되기까지 그 부동산으로부터 얻은 이익에 대하여 부당이득반환청구를 할 수 없다.","w":"점유취득시효로 소유권을 취득하면 그 효력이 점유를 시작한 때로 소급하므로(민법 제247조 제1항), 소유명의자는 시효기간 동안 점유자가 얻은 이익을 부당이득으로 반환 청구할 수 없다(판례).","c":"상","v":1},"변리사2026_63-19-2":{"f":"토지에 관하여 점유취득시효 완성에 따라 소유권이전등기가 마쳐진 경우, 제3자가 등기명의자의 취득시효 기간 중 일부 기간 동안 해당 토지 일부에 관하여 직접적·현실적인 점유를 한 사실이 있더라도 그 등기가 원인무효의 등기가 되는 것은 아니다.","w":"점유의 계속은 추정되므로, 일부 기간 제3자가 점유한 사실만으로 시효취득이 부정되지 않는다.","c":"중","v":1},"변리사2026_63-19-3":{"f":"취득시효완성 사실을 알면서 소유자로부터 그 부동산을 매수하여 소유권이전등기를 마친 자는 소유자의 등기의무를 승계하지 않는다.","w":"매수인이 취득시효 완성 사실을 알았다는 것만으로 등기의무를 승계하지는 않는다. 시효완성자는 소유자에 대한 이전등기청구권이 있고 제3자에게는 직접 청구하지 못한다.","c":"중","v":1},"변리사2026_63-19-4":{"f":"취득시효기간의 완성 전에 소유자의 채권자에 의하여 시효취득 목적물이 압류 또는 가압류가 된 경우에도 취득시효는 중단되지 않는다.","w":"압류·가압류는 소유자의 재산에 대한 처분 제한일 뿐이며 점유자의 점유를 방해하지 않으므로 취득시효의 중단사유가 되지 않는다.","c":"상","v":1},"변리사2016_53-18-1":{"f":"","w":"관습법상 법정지상권은 토지와 건물이 같은 사람 소유였다가 매매 등으로 소유자가 갈릴 때 생긴다. 판례는 미등기 건물을 대지와 함께 팔고 대지만 이전등기한 경우에는 매도인에게 관습법상 법정지상권을 인정하지 않는다. 매도인이 건물도 넘기기로 한 이상 건물 소유를 위해 토지를 쓸 권리를 남겨 둘 이유가 없기 때문이다. 따라서 甲은 C건물을 위한 법정지상권을 얻지 못한다.","c":"상","v":1},"변리사2016_53-18-2":{"f":"C가 무허가건물인 경우에도 C의 소유자는 그 건물의 소유를 위한 관습법상 법정지상권을 취득할 수 있다.","w":"무허가건물이어도 관습법상 법정지상권 성립에는 지장이 없다(대법원 판례).","c":"중","v":1},"변리사2016_53-18-4":{"f":"만일 乙이 근저당권 설정 당시 존재하던 B건물을 철거하고 D건물을 신축한 후에 A토지에 대한 저당권이 실행되었다면, B건물과 D건물의 동일성이 인정되지 않더라도 乙은 D건물을 위한 법정지상권을 취득할 수 있다.","w":"토지에 저당권을 설정할 당시 건물이 있었다면, 그 건물을 헐고 새로 지은 경우에도 법정지상권이 성립하고 두 건물의 동일성은 요구되지 않는다. 다만 법정지상권의 범위는 옛 건물을 기준으로 정한다(대법원 판례).","c":"중","v":1},"변리사2017_54-15-4":{"f":"지상권을 가진 건물소유자가 그 건물에 전세권을 설정하였으나 그가 2년 이상의 지료를 지급하지 아니한 경우, 토지소유자는 전세권자의 동의 없이 지상권 소멸 청구를 할 수 있다.","w":"민법 제304조 제2항은 건물소유자인 전세권설정자가 전세권자 동의 없이 지상권을 소멸시키는 행위를 막을 뿐이다. 지상권자가 2년 이상 지료를 내지 않으면 토지소유자는 전세권자의 동의 없이 지상권 소멸을 청구할 수 있다(민법 제287조, 대법원 판례).","c":"상","v":1},"변리사2017_54-21-1":{"f":"지역권은 다른 약정이 없는 한 요역지소유권에 부종하여 이전한다.","w":"지역권은 요역지 소유권에 부종하여 이전하고, 승역지 소유권에 부종하는 것이 아니다(민법 제292조 제1항).","c":"상","v":1},"변리사2017_54-21-3":{"f":"통행지역권을 시효취득하기 위해서는 요역지의 소유자가 타인의 토지를 20년간 통행하였다는 사실만으로 부족하고, 요역지의 소유자가 타인의 소유인 승역지 위에 통로를 개설하여야 한다.","w":"계속되고 표현된 지역권만 시효취득하므로, 통행지역권은 요역지 소유자가 통로를 개설하여 사용한 경우에 시효취득할 수 있다(민법 제294조).","c":"상","v":1},"변리사2017_54-21-4":{"f":"요역지의 공유자 중 1인이 지역권을 시효로 취득하면 다른 공유자도 지역권을 취득한다.","w":"요역지 공유자 1인이 시효취득하면 다른 공유자도 취득한다(민법 제295조 제1항).","c":"상","v":1},"변리사2017_54-21-5":{"f":"승역지는 반드시 1필의 토지일 필요가 없으며, 토지의 일부 위에도 지역권을 설정할 수 있다.","w":"지역권은 승역지의 일부에도 설정할 수 있다. 요역지는 1필의 토지여야 한다.","c":"상","v":1},"변리사2018_55-16-4":{"f":"지상건물이 없는 토지에 관하여 1번 저당권을 설정할 당시 저당권자가 그 토지에 건물을 축조하는 것에 동의하였더라도 법정지상권은 성립하지 않는다.","w":"법정지상권(민법 제366조)은 저당권 설정 당시 토지 위에 건물이 있어야 성립한다. 나대지에 저당권을 설정하면서 저당권자가 건물 축조에 동의했더라도 법정지상권은 생기지 않는다(대법원 판례).","c":"상","v":1},"변리사2018_55-21-3":{"f":"지역권자 甲이 그 소유 토지를 乙에게 매도하고 이전등기한 경우, 특별한 사정이 없는 한 乙은 지역권의 이전등기 없이도 지역권을 취득한다.","w":"지역권은 요역지 소유권에 부종하여 이전하므로 요역지 소유권 이전등기만으로 지역권이 함께 이전되고 별도 이전등기가 필요 없다(민법 제292조 제1항).","c":"상","v":1},"변리사2019_56-16-1":{"f":"지상권은 1필 토지의 일부에 대해서도 성립할 수 있다.","w":"지상권은 1필 토지의 일부에도 설정할 수 있다.","c":"중","v":1},"변리사2019_56-16-2":{"f":"지상권자는 존속기간이 만료한 때에 지상물이 현존하는 경우, 지상권설정자에 대해 먼저 지상권의 갱신을 청구할 수 있고, 설정자가 갱신을 원하지 않으면 지상물의 매수를 청구할 수 있다.","w":"갱신청구와 매수청구는 선택적이 아니라 순차적이다. 갱신청구를 거절당한 뒤에 매수를 청구한다(민법 제283조).","c":"상","v":1},"변리사2019_56-16-3":{"f":"지상권은 지상물의 소유를 목적으로 토지를 사용하는 권리이지만, 지상권자는 지상권을 유보한 채 지상물 소유권만을 양도할 수 있다.","w":"지상권과 지상물 소유권은 별개의 권리여서, 지상권자는 지상권을 유보한 채 지상물 소유권만 양도할 수도 있고 지상물을 남겨 두고 지상권만 양도할 수도 있다(판례).","c":"중","v":1},"변리사2019_56-16-5":{"f":"금융기관이 토지에 저당권과 함께 지료 없는 지상권을 설정받으면서 채무자의 사용수익권을 배제하지 않은 경우, 금융기관은 그 토지의 무단점유자에 대해 지상권침해를 근거로 임료 상당의 손해배상을 청구할 수 없다.","w":"저당권과 함께 담보 목적으로 지료 없는 지상권을 설정받고 토지 소유자의 사용수익권을 배제하지 않았다면, 무단점유가 있어도 지상권자에게 임료 상당의 손해가 생기지 않으므로 그 배상을 청구할 수 없다(판례).","c":"상","v":1},"변리사2021_58-18-1":{"f":"2020. 10. 1. 당시 丙은 X토지에 대하여 법정지상권 등기를 하지 않았더라도, 丙은 X토지에 대한 법정지상권을 취득한다.","w":"법정지상권은 등기 없이도 법률 규정에 의해 취득한다(민법 제187조). 다만 처분하려면 등기를 해야 한다.","c":"중","v":1},"변리사2021_58-18-2":{"f":"2020. 10. 1. 丙이 법정지상권을 취득하였더라도 지료를 지급하여야 한다.","w":"법정지상권도 유상이며 지료는 당사자 협의나 법원 결정으로 정한다(민법 제366조). 본인 의사와 무관하게 취득했다는 이유로 지료가 면제되지 않는다.","c":"상","v":1},"변리사2021_58-18-4":{"f":"2021. 2. 10. 戊는 법정지상권 등기를 하여야 X토지에 대하여 법정지상권을 취득한다.","w":"지상권을 건물과 함께 양수하는 것은 법률행위에 의한 물권변동이므로 이전등기를 해야 취득한다(민법 제186조).","c":"중","v":1},"변리사2021_58-20-4":{"f":"전세권에 저당권을 설정한 경우, 전세기간이 만료되면 전세권의 저당권자는 전세권 자체에 대하여 저당권을 실행할 수 없고 전세금반환채권에 대한 물상대위권을 행사하여야 한다.","w":"전세기간이 끝나면 전세권의 용익물권적 권능이 소멸하므로 전세권 자체를 경매할 수 없다. 전세금반환채권을 압류하는 물상대위로 변제받는다.","c":"상","v":1},"변리사2023_60-19-1":{"f":"甲이 보증금의 반환을 담보하기 위하여 전세권을 설정하면서 이와 동시에 목적물을 인도하지 않았더라도 전세권의 설정은 효력이 있다.","w":"목적물의 인도는 전세권의 성립요건이 아니므로, 인도하지 않았더라도 전세권설정등기를 마쳤다면 전세권은 유효하다(판례).","c":"상","v":1},"변리사2023_60-19-2":{"f":"전세금의 지급은 전세권 성립의 요소가 되지만 전세금을 현실적으로 지급하지 않고 기존의 채권으로 대신할 수 있다.","w":"전세금은 반드시 현실로 수수될 필요가 없고 기존 채권으로 갈음할 수 있다.","c":"상","v":1},"변리사2023_60-19-4":{"f":"임대차보증금의 반환을 담보하기 위하여 전세권설정등기가 경료되었음을 丙이 알지 못한 경우에는 甲은 연체차임의 공제를 가지고 丙에게 대항할 수 없다.","w":"전세권이 임대차보증금 반환을 담보할 목적으로 설정된 사실을 모르는 전세권저당권자에게는 연체차임 공제를 주장할 수 없다(판례).","c":"중","v":1},"변리사2023_60-19-5":{"f":"전세권의 존속기간이 만료되면 丙은 X상가에 대한 전세권저당권을 실행하는 방법이 아니라 전세금반환채권에 대한 물상대위의 방법으로 乙에 대한 대여금채권을 회수하여야 한다.","w":"전세권 존속기간이 끝나면 전세권저당권자는 전세권 자체를 경매할 수 없고 전세금반환채권에 물상대위권을 행사한다.","c":"상","v":1},"변리사2024_61-19-1":{"f":"甲이 丙에게 Y건물을 인도하지 않은 경우에도, 특별한 사정이 없는 한 丙의 전세권은 성립한다.","w":"전세권은 등기로 성립하며 목적물의 인도가 성립요건이 아니다.","c":"상","v":1},"변리사2024_61-19-2":{"f":"甲과 丙이 전세권의 존속기간을 약정하지 아니한 경우, 甲과 丙은 언제든지 상대방에 대하여 전세권의 소멸을 통고할 수 있고 상대방이 이 통고를 받은 날부터 6개월이 지나면 전세권은 소멸한다.","w":"존속기간 약정이 없을 때에는 통고 후 6개월이 지나야 소멸하며, 통고를 받은 때 곧바로 소멸하지 않는다(민법 제313조).","c":"상","v":1},"변리사2024_61-19-3":{"f":"전세금 3억 원은 현실적으로 수수되지 않아도 되며, 丙이 甲에 대하여 갖는 기존의 채권으로 전세금의 지급에 갈음할 수 있다.","w":"전세금은 기존 채권으로 갈음할 수 있다.","c":"상","v":1},"변리사2024_61-19-4":{"f":"특별한 사정이 없는 한, 전세기간 중 丙은 甲의 동의를 얻지 않고도 Y건물을 타인에게 임대할 수 있다.","w":"전세권자는 설정자의 동의 없이 전전세·임대를 할 수 있다(민법 제306조 본문). 설정행위로 금지한 경우에만 제한된다.","c":"상","v":1},"변리사2026_63-20-5":{"f":"지상물매수청구에 따른 지상물매매가격의 산출은 지상권 소멸 당시의 시가가 아니라 지상물 매수청구 당시의 시가에 의한다.","w":"매수청구권은 형성권이므로 행사한 때 매매계약이 성립하고, 가격은 매수청구 당시의 시가이다.","c":"중","v":1},"변리사2026_63-21-4":{"f":"전세권설정자는 전세권자에 대하여 전세권자에게 책임있는 사유로 인하여 전세목적물이 멸실됨에 따른 손해배상채권 이외의 다른 채권을 가지고 전세금반환채권에 대하여 물상대위권을 행사한 전세권저당권자에게 상계 등으로 대항할 수 없다.","w":"저당권자가 물상대위로 전세금반환채권을 압류한 경우에는 민법 제315조의 손해배상채권 이외의 채권으로 상계하여 대항할 수 없다.","c":"상","v":1},"변리사2016_53-20-2":{"f":"甲이 공장을 점유하는 과정에서 폭력을 사용하는 등의 불법행위가 있었다면 공장을 점유하였더라도 유치권은 성립하지 않는다.","w":"점유가 불법행위로 시작된 경우에는 유치권이 성립하지 않는다(민법 제320조 제2항).","c":"상","v":1},"변리사2016_53-20-3":{"f":"丙 은행에 근저당권이 설정된 후에 공장을 점유한 甲도 매수인 丁에 대해서는 유치권을 주장할 수 있다.","w":"저당권 설정 뒤에 유치권을 취득했더라도 경매개시결정 기입등기 전에 점유를 취득했다면 매수인에게 유치권으로 대항할 수 있다(대법원 2009.1.15. 선고 2008다70763 판결).","c":"상","v":1},"변리사2016_53-20-4":{"f":"甲이 丁에게 유치권을 행사할 수 있다는 것은 丁에게 직접 공사잔금 5억원을 청구할 수 있음을 뜻하지 않는다.","w":"유치권은 변제를 받을 때까지 유치물의 인도를 거절하는 권리이다. 매수인에게 채무자의 채무를 직접 청구할 수 있다는 뜻은 아니다.","c":"상","v":1},"변리사2016_53-21-2":{"f":"丙이 질권설정 사실을 승낙한 후 그 질권설정계약이 합의해지된 경우, 甲이 해지를 이유로 丙에게 원래의 채권으로 대항하려면 질권자 乙이 丙에게 해지 사실을 통지하여야 한다.","w":"질권설정계약이 합의해지된 경우 질권자가 제3채무자에게 해지 사실을 통지해야 질권설정자가 원래의 채권으로 대항할 수 있다.","c":"중","v":1},"변리사2016_53-21-4":{"f":"甲에게 이미 변제한 丙이 착오로 乙에게 이의를 보류하지 아니하고 승낙하였더라도, 乙에게 중과실이 있다면 丙은 변제로 乙에게 대항할 수 있다.","w":"이의를 보류하지 않은 승낙으로 항변이 끊기는 것은 질권자가 선의이고 중과실이 없을 때이다. 질권자에게 중과실이 있으면 제3채무자는 변제로 대항할 수 있다(민법 제349조 제2항, 제451조 제1항, 판례).","c":"상","v":1},"변리사2016_53-21-5":{"f":"乙이 丙에게 직접청구권을 행사하여 변제받은 경우, 입질채권의 발생원인인 계약관계가 무효였다면 丙은 乙을 상대로 부당이득반환을 청구할 수 없다.","w":"제3채무자가 질권자에게 한 변제는 질권설정자에게 한 변제로 취급되므로, 제3채무자는 질권자가 아니라 질권설정자에게 부당이득반환을 청구해야 한다.","c":"중","v":1},"변리사2016_53-22-4":{"f":"근저당권설정등기가 원인 없이 말소된 이후에, 근저당목적물인 부동산에 관하여 다른 근저당권자의 신청에 따라 경매절차가 진행되어 매각허가결정이 확정되고 매수인이 매각대금을 완납한 경우, 그 근저당권은 소멸한다.","w":"경매에서 매수인이 대금을 납부하면 부동산 위의 저당권은 소멸하고, 등기가 원인 없이 말소되었더라도 마찬가지이다.","c":"중","v":1},"변리사2017_54-19-5":{"f":"저당권의 효력은 저당부동산에 대한 압류가 있은 후에 저당권설정자가 그 부동산으로부터 수취한 과실 또는 수취할 수 있는 과실에 미친다.","w":"저당권은 압류 이후의 과실에만 미친다(민법 제359조).","c":"상","v":1},"변리사2017_54-20-1":{"f":"경매개시결정이 있은 후, 甲이 경매신청을 취하하더라도 채무확정의 효과는 번복되지 않는다.","w":"경매신청 시에 확정된 피담보채권은 그 뒤 경매신청을 취하해도 번복되지 않는다(대법원 판례).","c":"상","v":1},"변리사2017_54-22-4":{"f":"양도담보권자는 사용수익할 수 있는 정당한 권한이 있는 채무자나 그 채무자로부터 사용수익할 수 있는 권한을 승계한 자에 대하여 그 사용수익을 하지 못한 것을 이유로 임료 상당의 손해배상이나 부당이득반환을 청구할 수 없다.","w":"담보 목적의 양도에서는 설정자가 사용수익권을 가지므로, 담보권자는 설정자에게 임료 상당 손해배상이나 부당이득반환을 청구할 수 없다.","c":"상","v":1},"변리사2017_54-24-3":{"f":"유치권에 의한 경매절차가 정지된 상태에서 그 목적물에 대한 담보권실행을 위한 경매가 진행되어 매각이 이루어지더라도 그 유치권은 소멸하지 않는다.","w":"유치권에 의한 경매는 인수주의이므로, 유치권은 담보권 실행 경매의 매수인이 인수한다.","c":"중","v":1},"변리사2018_55-23-1":{"f":"세금체납을 이유로 한 체납처분압류가 되어 있는 부동산에 대한 경매절차가 개시되기 전에 유치권을 취득한 유치권자는 그 경매절차의 매수인에게 유치권을 주장할 수 있다.","w":"체납처분압류에는 처분금지효가 없어서, 체납처분압류 뒤라도 경매절차가 개시되기 전에 유치권을 취득했다면 경매절차의 매수인에게 유치권을 주장할 수 있다(대법원 2014.3.20. 선고 2009다60336 전원합의체 판결).","c":"상","v":1},"변리사2018_55-23-3":{"f":"매도인이 중도금만 받고서 매수인에게 부동산의 소유권을 이전한 경우, 매도인은 잔금채권을 피담보채권으로 하여 매수인에 대하여 유치권을 행사할 수 없다.","w":"매매대금채권은 목적물 자체에서 생긴 채권이 아니어서 유치권의 피담보채권이 되지 못한다. 소유권을 넘겨준 매도인이 목적물을 점유하고 있더라도 잔금채권으로 유치권을 행사할 수 없다는 것이 판례다(대법원 2012. 1. 12.자 2011마2380 결정).","c":"중","v":1},"변리사2018_55-23-4":{"f":"부동산 근저당권에 기한 압류의 효력이 발생한 후에 취득한 유치권으로는 그 근저당권에 기한 경매절차의 매수인에게 대항할 수 없다.","w":"경매개시결정 기입등기로 압류의 효력이 생긴 뒤에 점유를 취득해 유치권을 얻으면, 압류의 처분금지효에 반하므로 그 경매절차의 매수인에게 유치권으로 대항할 수 없다(대법원 판례).","c":"상","v":1},"변리사2018_55-23-5":{"f":"건물신축공사를 도급받은 수급인이 사회통념상 독립한 건물이 되지 못한 정착물을 토지에 설치한 상태에서 공사가 중단된 경우, 토지에 대하여 유치권을 행사할 수 없다.","w":"정착물이 독립한 건물이 아니면 토지에 부합하고, 공사대금채권이 토지에 관하여 생긴 채권이 아니므로 유치권이 성립하지 않는다.","c":"중","v":1},"변리사2019_56-18-2":{"f":"질권설정을 위한 인도는 현실의 인도에 한하지 않으나, 점유개정에 의해서는 할 수 없다.","w":"질권자는 설정자에게 질물을 점유하게 하지 못하므로(민법 제332조), 설정자가 계속 점유하는 점유개정으로는 동산질권을 설정할 수 없다. 간이인도나 목적물반환청구권 양도로는 할 수 있다.","c":"상","v":1},"변리사2019_56-19-2":{"f":"유치권자는 채권의 변제를 받기 위하여 유치물을 경매할 수 있지만 매각대금에서 후순위 권리자보다 우선변제를 받을 수는 없다.","w":"유치권자는 경매를 청구할 수 있지만(민법 제322조 제1항) 이 경매는 현금화를 위한 것이고, 유치권에는 매각대금에서 우선변제를 받을 권리가 없다.","c":"상","v":1},"변리사2019_56-19-3":{"f":"수급인이 자신의 노력과 재료를 들여 신축한 건물에 대한 소유권을 원시취득한 경우, 수급인은 공사대금을 지급받을 때까지 유치권을 행사할 수 없다.","w":"유치권은 타인의 물건에 대해서만 성립하므로 수급인 자기 소유의 건물에는 성립하지 않는다.","c":"상","v":1},"변리사2019_56-19-4":{"f":"유치권의 피담보채권의 소멸시효기간이 확정판결 등에 의하여 10년으로 연장된 경우, 유치권이 성립된 부동산의 매수인은 종전의 단기소멸시효를 원용할 수 없다.","w":"시효기간 연장은 채권자·채무자 사이에서 생긴 것이어서 매수인은 연장 전의 단기시효를 원용하지 못한다.","c":"중","v":1},"변리사2019_56-19-5":{"f":"공사대금채권에 기하여 유치권을 행사하는 자가 스스로 보존에 필요한 범위 내에서 유치물인 주택에 거주하며 사용하는 경우에는 소유자가 유치권의 소멸을 청구할 수 없다.","w":"보존에 필요한 사용은 소유자의 승낙 없이도 할 수 있다(민법 제324조 제2항 단서).","c":"상","v":1},"변리사2019_56-21-4":{"f":"","w":"丙은 2017. 10. 1. 인도와 전입신고를 마쳐 다음 날 0시에 대항력을 얻었고 확정일자를 받으면 우선변제권이 생긴다. 그러나 甲의 저당권은 그보다 먼저 등기되었으므로 丙은 甲보다 후순위로 배당받는다. 甲보다 앞서 보증금 전액을 우선변제받을 수는 없다.","c":"상","v":1},"변리사2019_56-21-5":{"f":"丙이 적법하게 배당요구를 하였다면 배당받을 수 있었던 금액이 丙의 적법한 배당요구가 없어서 丁과 戊에게 배당된 경우, 丙은 丁과 戊에게 부당이득반환을 청구할 수 없다.","w":"적법하게 배당요구를 하지 않은 사람은 배당받을 지위에 있지 않으므로, 배당받은 다른 채권자를 상대로 부당이득반환을 청구할 수 없다(대법원 판례).","c":"중","v":1},"변리사2019_56-22-2":{"f":"甲이 담보권실행을 통하여 우선변제 받게 되는 이자나 지연배상금 등 피담보채권의 범위는 담보권 실행 통지 당시를 기준으로 확정된다.","w":"청산금을 계산할 때 피담보채권의 범위는 담보권 실행 통지 당시를 기준으로 확정된다. 통지에는 그 당시의 부동산 평가액과 채권액을 밝혀야 한다(가등기담보 등에 관한 법률 제3조 제2항).","c":"중","v":1},"변리사2019_56-22-3":{"f":"甲이 담보권실행을 통지하고 2개월의 청산기간이 지난 경우, 청산금의 지급이 없다면 乙은 대여금을 변제하고 가등기말소를 청구할 수 있다.","w":"채무자는 청산금 지급 전까지 채무를 변제하고 가등기 말소를 청구할 수 있다(가등기담보 등에 관한 법률 제11조).","c":"중","v":1},"변리사2019_56-22-4":{"f":"甲이 주관적으로 평가한 청산금의 액수가 정당하게 평가된 청산금의 액수에 미치지 못하더라도 담보권실행 통지의 효력은 인정된다.","w":"통지한 청산금이 정당한 평가액에 미달해도 통지는 유효하며, 채권자는 정당한 청산금을 지급해야 소유권을 취득한다(대법원 판례).","c":"중","v":1},"변리사2019_56-22-5":{"f":"甲이 담보권실행을 위해 통지하여야 할 청산금의 평가액은 통지 당시의 목적부동산 가액에서 甲의 채권액과 선순위담보 등에 의하여 담보된 채권액을 공제한 차액이다.","w":"청산금은 통지 당시 부동산 가액에서 채권자 자신의 채권액과 선순위 담보권으로 담보된 채권액을 뺀 금액이다. 후순위 권리자의 채권액은 빼지 않는다(가등기담보 등에 관한 법률 제4조 제1항).","c":"중","v":1},"변리사2019_56-24-1":{"f":"질권의 목적인 채권의 양도행위에는 질권자의 동의가 필요하지 않다.","w":"질권설정자가 입질채권을 양도하는 것은 질권의 소멸·변경이 아니므로 질권자의 동의가 필요하지 않다. 질권자의 동의가 필요한 것은 질권의 목적권리를 소멸·변경하는 행위이다(민법 제352조).","c":"상","v":1},"변리사2021_58-19-3":{"f":"저당권부 채권을 양수한 채권자가 채권양도의 대항요건을 갖추지 않았더라도 그보다 후순위 저당권자에 대하여 채권양도로써 대항할 수 있다.","w":"후순위 저당권자는 채권양도의 대항요건 흠결을 주장할 정당한 이익이 있는 제3자가 아니다(대법원 판례).","c":"중","v":1},"변리사2021_58-21-2":{"f":"유치권자가 유치물의 보존에 필요한 사용을 한 경우에도 특별한 사정이 없는 한, 차임 상당의 이득을 소유자에게 반환할 의무가 있다.","w":"유치권자가 보존에 필요한 사용을 하는 것은 적법하지만, 그 사용으로 얻은 차임 상당의 이익은 부당이득으로 소유자에게 반환해야 한다(판례).","c":"중","v":1},"변리사2021_58-21-3":{"f":"건물공사대금의 채권자가 그 건물에 대하여 유치권을 행사하는 동안에도 그 공사대금채권의 소멸시효는 진행한다.","w":"유치권을 행사하더라도 피담보채권의 소멸시효는 진행한다(민법 제326조).","c":"상","v":1},"변리사2021_58-21-4":{"f":"임대인과 임차인 사이에 임대차 종료에 따른 건물명도 시에 권리금을 반환하기로 약정한 경우, 임차인은 권리금반환청구권을 가지고 건물에 대한 유치권을 행사할 수 없다.","w":"권리금반환청구권은 건물에 관하여 생긴 채권이 아니므로 유치권의 피담보채권이 될 수 없다(판례).","c":"상","v":1},"변리사2021_58-21-5":{"f":"유치권자가 경매개시결정등기 전에 부동산에 관하여 유치권을 취득하였다면, 그 취득에 앞서 저당권설정등기가 먼저 되어 있었더라도 경매절차의 매수인에게 자기의 유치권으로 대항할 수 있다.","w":"저당권설정등기가 먼저 되어 있었더라도 경매개시결정 기입등기 전에 유치권을 취득했다면 경매절차의 매수인에게 유치권으로 대항할 수 있다(판례).","c":"상","v":1},"변리사2021_58-23-5":{"f":"저당권부 채권에 질권을 설정하면서 그 저당권의 피담보채권만을 질권의 목적으로 하고 저당권은 질권의 목적으로 하지 않는 것도 허용된다.","w":"저당권부 채권에 질권을 설정할 때 피담보채권만 질권의 목적으로 하고 저당권은 제외하는 것도 가능하며, 저당권의 부종성에 반하지 않는다(판례).","c":"상","v":1},"변리사2023_60-20-1":{"f":"채무자는 상당한 담보를 제공하고 유치권의 소멸을 청구할 수 있는데, 유치물 가액이 피담보채권액보다 적을 경우에는 유치물 가액에 해당하는 담보를 제공하면 된다.","w":"유치권 소멸청구의 담보는 유치물의 가액을 기준으로 한다(민법 제327조).","c":"중","v":1},"변리사2023_60-20-2":{"f":"유치권자가 유치물에 대한 점유를 빼앗긴 경우에는 점유를 회복하기 전에는 유치권이 인정되지 않는다.","w":"유치권은 점유를 상실하면 소멸하고(민법 제328조), 점유회수의 소로 점유를 되찾아야 유치권이 되살아난다.","c":"중","v":1},"변리사2023_60-20-3":{"f":"유치권의 존속 중에 유치물의 소유권이 제3자에게 양도된 경우에도 유치권자는 그 제3자에 대하여 유치권을 행사할 수 있다.","w":"유치권은 물권이므로 누구에게나 주장할 수 있다. 소유자가 바뀌어도 유치권자는 새 소유자에게 유치권을 행사한다.","c":"상","v":1},"변리사2023_60-20-5":{"f":"수급인은 도급계약에 따라 자신의 재료와 노력으로 건축된 자기 소유의 건물에 대해서는 도급인으로부터 공사대금을 지급받을 때까지 유치권을 가지지 못한다.","w":"유치권은 타인의 물건에 대하여 성립하므로 수급인 자신이 소유권을 원시취득한 건물에는 유치권이 성립하지 않는다.","c":"상","v":1},"변리사2023_60-22-1":{"f":"경매절차의 매수인이 증축부분의 소유권을 취득하기 위해서는 부합된 증축부분이 기존건물에 대한 경매절차에서 경매목적물로 평가되었을 것을 요하지 않는다.","w":"저당권의 효력은 부합물에 미치므로, 증축부분이 경매목적물로 평가되지 않았더라도 매수인이 소유권을 취득한다(대법원 판례).","c":"상","v":1},"변리사2023_60-23-2":{"f":"공동근저당권자가 X건물과 Y건물에 대하여 공동저당을 설정한 후, 제3자가 신청한 X건물에 대한 경매절차에 참가하여 배당을 받더라도 Y건물에 대한 피담보채권은 확정되지 않는다.","w":"공동근저당권자 자신이 경매를 신청한 경우와 달리, 타인이 신청한 경매에서 배당받은 것만으로 다른 부동산의 피담보채권이 확정되지는 않는다.","c":"중","v":1},"변리사2023_60-24-1":{"f":"가등기담보권자가 목적물의 소유권을 취득하려면 청산금 통지 당시 목적물의 평가액과 피담보채권액의 범위를 밝혀야 한다.","w":"평가액과 채권액은 담보권 실행 통지 당시를 기준으로 밝히며, 담보설정 당시가 기준이 아니다(가등기담보 등에 관한 법률 제3조).","c":"상","v":1},"변리사2023_60-24-3":{"f":"목적부동산의 평가액이 채권액에 미달하여 청산금이 없다고 인정되는 때에도 그 뜻을 채무자에게 통지하여야 한다.","w":"청산금이 없다고 평가되는 때에도 그 뜻을 통지해야 한다(가등기담보 등에 관한 법률 제3조 제1항).","c":"상","v":1},"변리사2023_60-24-4":{"f":"채권자가 담보목적부동산에 관하여 이미 소유권이전등기를 마친 경우에도 청산금을 채무자에게 지급하지 않으면 담보목적부동산의 소유권을 취득하지 못한다.","w":"청산금을 지급하지 않은 채 이전등기를 마쳤다 해도 소유권을 취득하지 못한다(가등기담보 등에 관한 법률 제4조 제2항).","c":"상","v":1},"변리사2023_60-24-5":{"f":"채권자가 평가한 청산금의 액수가 정당하게 평가된 청산금의 액수에 미치지 못하는 경우에도 담보권 실행통지로서의 효력이 있다.","w":"통지한 금액이 정당한 평가액에 미달해도 통지의 효력은 인정되고, 정당한 청산금을 지급해야 소유권을 취득한다(대법원 판례).","c":"중","v":1},"변리사2024_61-20-5":{"f":"유치권자가 소유자의 승낙 없이 유치목적물을 임대한 경우, 임차인의 점유는 소유자에게 대항할 수 있는 적법한 권원에 기한 것이 아니다.","w":"유치권자는 소유자의 승낙 없이 유치물을 임대할 수 없고, 임대하면 소유자가 유치권의 소멸을 청구할 수 있다(민법 제324조 제2항, 제3항).","c":"상","v":1},"변리사2024_61-21-4":{"f":"채무자의 부탁으로 그의 채무를 담보하기 위하여 자기 소유의 동산에 질권을 설정한 자는 그 채무의 이행기가 도래하더라도 채무자에게 미리 구상권을 행사할 수 없다.","w":"물상보증인은 수탁보증인과 달리 사전구상권(민법 제442조)을 갖지 않으므로, 채무를 대신 변제하거나 질권 실행으로 소유권을 잃은 뒤에야 구상할 수 있다(판례).","c":"상","v":1},"변리사2024_61-22-2":{"f":"저당권 등기가 위법하게 말소된 후 그 저당부동산이 경매절차에서 매각된 경우, 저당권자는 매수인을 상대로 말소된 저당권 등기의 회복을 청구할 수 없다.","w":"저당권 등기가 위법하게 말소되었더라도 경매로 매각되면 그 저당권은 소멸하므로 매수인에게 회복등기를 청구할 수 없다. 저당권자는 배당받은 자에게 부당이득반환을 청구할 수 있다(판례).","c":"상","v":1},"변리사2024_61-24-2":{"f":"가등기담보권이 설정되기 위해서 피담보채권이 등기되어야 하는 것은 아니다.","w":"가등기담보권은 담보가등기를 하면 성립하고, 피담보채권 자체는 등기사항이 아니다.","c":"중","v":1},"변리사2026_63-16-1":{"f":"매매대금 채무를 담보하기 위하여 가등기를 한 경우에는 「가등기담보 등에 관한 법률」이 적용되지 않는다.","w":"이 법은 소비대차나 준소비대차에 기한 채권의 담보에 적용된다. 매매대금 채권 담보에는 적용되지 않는다(가등기담보 등에 관한 법률 제1조).","c":"상","v":1},"변리사2026_63-16-2":{"f":"공동명의로 담보가등기를 마친 수인(數人)의 채권자가 각자의 지분별로 별개의 독립적인 매매예약완결권을 가지는 경우, 채권자 중 1인은 단독으로 자신의 지분에 관하여 소유권이전의 본등기절차 이행청구를 할 수 있다.","w":"각자가 독립적인 예약완결권을 가진다면 각 채권자는 자기 지분에 관하여 단독으로 본등기를 청구할 수 있다.","c":"상","v":1},"변리사2026_63-16-4":{"f":"채권자가 평가한 청산금의 액수가 정당하게 평가된 청산금의 액수에 미치지 못하는 경우에도 담보권 실행통지로서의 효력이 있다.","w":"통지한 금액이 정당한 평가액에 미달해도 통지는 유효하고, 채권자는 정당한 청산금을 지급해야 소유권을 취득한다.","c":"중","v":1},"변리사2026_63-16-5":{"f":"채무담보를 위하여 가등기가 경료되어 있는 경우, 특별한 사정이 없는 한 피담보채무의 변제가 가등기말소절차의 이행보다 먼저 이행되어야 하고 둘은 동시이행관계에 있지 않다.","w":"채무자의 변제가 선이행이며, 변제와 가등기 말소는 동시이행 관계가 아니다.","c":"상","v":1},"변리사2026_63-22-2":{"f":"상가임대인이 임차건물의 객관적 가치상승과 무관하게 임차인이 지출한 비용에 대해서도 임차인에게 상환하기로 약정한 경우, 임차인은 그 채권을 피담보채권으로 하여 유치권을 행사할 수 없다.","w":"건물에 관하여 생긴 채권이 아니라 약정에 따른 채권이어서 유치권의 피담보채권이 될 수 없다.","c":"중","v":1},"변리사2026_63-22-3":{"f":"유치권자가 선관주의의무를 위반하여 유치물을 타인에게 임대한 경우, 그 후 유치물을 양수한 자도 유치권자에 대하여 선관주의의무 위반을 이유로 유치권소멸을 청구할 수 있다.","w":"유치권 소멸청구권은 소유자에게 있고 소유권을 양수한 자도 행사할 수 있다.","c":"중","v":1},"변리사2026_63-22-4":{"f":"甲이 하나의 채권을 피담보채권으로 하여 乙 소유 여러 필지의 토지에 대하여 유치권을 취득하고, 일부 필지의 토지에 대하여 乙의 승낙없이 무단으로 사무실을 설치한 경우, 乙은 甲에게 그 일부 필지에 대한 유치권의 소멸만을 청구할 수 있다.","w":"의무위반이 있는 필지에 한하여 소멸을 청구할 수 있고, 유치목적물 전부에 대한 소멸을 청구할 수는 없다.","c":"상","v":1},"변리사2026_63-22-5":{"f":"저당목적물에 유익비를 지출한 저당목적물의 제3취득자는 저당권실행에 따른 경매절차의 매수인에 대하여 민법 제367조의 제3취득자의 비용상환청구권을 피담보채권으로 하는 유치권을 행사할 수 없다.","w":"제367조의 비용상환청구권은 경매대가에서 우선 상환받는 권리일 뿐, 이를 피담보채권으로 한 유치권을 매수인에게 행사할 수는 없다.","c":"상","v":1},"변리사2026_63-23-1":{"f":"임대차보증금반환채권에 대하여 질권을 설정하는 경우, 그 채권증서인 임대차계약서를 질권자에게 교부하지 않아도 질권의 효력이 생긴다.","w":"임대차계약서는 질권 설정 때 교부해야 하는 채권증서(민법 제347조)에 해당하지 않으므로, 교부하지 않아도 질권 설정의 효력이 생긴다(판례).","c":"상","v":1},"변리사2016_53-25-2":{"f":"특정물채권에서 채무자의 목적물에 대한 선관주의의무의 존속기간은 특정물채무의 성립시부터 인도할 때까지이다.","w":"선관주의의무는 목적물을 인도할 때까지 계속된다(민법 제374조). 이행기까지가 아니다.","c":"상","v":1},"변리사2016_53-26-4":{"f":"손해발생으로 인하여 피해자에게 이득이 생겼다면 손해액을 산정할 때 먼저 과실상계를 한 후에 손익상계를 하여야 한다.","w":"과실상계를 먼저 하고 그 결과에서 손익상계를 한다(대법원 판례).","c":"상","v":1},"변리사2016_53-27-1":{"f":"임차건물이 화재로 소실된 경우 그 화재의 발생 원인이 불명이면, 임차인은 임차 건물의 보존에 관한 선관주의의무를 다하지 않은 경우 그 책임을 면하지 못한다.","w":"원인 불명의 화재라도 임차인이 자신에게 귀책사유가 없음을 증명하지 못하면 책임을 진다(대법원 판례).","c":"중","v":1},"변리사2016_53-27-2":{"f":"이행보조자의 불법행위로 인하여 채무자가 채무불이행책임을 부담하는 경우 이행보조자의 손해배상책임과 채무자의 채무불이행책임은 부진정연대채무관계에 있다.","w":"두 책임은 발생 근거가 서로 다른 별개 채무여서 부진정연대채무이다.","c":"상","v":1},"변리사2016_53-27-3":{"f":"채무자의 제3채무자에 대한 채권의 가압류가 있는 경우에도 그 채권의 이행기가 도래하였다면 제3채무자는 그 지체책임을 부담한다.","w":"채권이 가압류되어도 제3채무자는 채무자에게 지급하지 못할 뿐 채무의 이행기가 미뤄지지는 않으므로, 이행기가 지나면 지체책임을 진다. 지체책임을 피하려면 공탁해야 한다(대법원 판례).","c":"상","v":1},"변리사2016_53-27-4":{"f":"채무불이행으로 인하여 계약이 합의해제 되었더라도 손해배상을 청구하려면 합의해제 시 손해배상 청구권을 유보하는 특약이 필요하다.","w":"합의해제를 하면서 손해배상에 관해 아무 약정이 없으면 채무불이행으로 인한 손해배상을 청구할 수 없다(대법원 판례).","c":"상","v":1},"변리사2016_53-29-4":{"f":"원인채무의 이행확보를 위해 발행한 어음의 반환과 원인채무의 이행이 동시이행관계에 있는 경우에도 원인채무의 이행기가 지나면 채무자는 이행지체책임을 진다.","w":"어음 반환과 원인채무 이행이 동시이행관계라는 것은 채무자가 어음과 상환으로 지급하겠다고 항변할 수 있다는 뜻일 뿐이다. 원인채무의 이행기가 지나면 채무자는 이행지체책임을 진다(대법원 판례).","c":"중","v":1},"변리사2017_54-25-1":{"f":"매매계약 당시 매매목적 토지의 소유권이 매도인에게 속하지 아니함을 알고 있던 매수인도 소유권이전의무의 이행불능에 매도인의 귀책사유가 있다면 채무불이행을 이유로 계약을 해제하고 손해배상을 청구할 수 있다.","w":"타인 권리를 매매한 경우 매수인이 악의여도 채무불이행 요건을 갖추면 해제와 손해배상이 가능하다.","c":"중","v":1},"변리사2017_54-26-3":{"f":"숙박업자가 숙박계약상의 고객보호의무를 다하지 못하여 투숙객이 사망한 경우, 그 투숙객의 근친자는 숙박계약의 당사자가 아니므로 숙박업자의 숙박계약상의 채무불이행을 이유로 위자료를 청구할 수 없다.","w":"근친자는 계약 당사자가 아니므로 채무불이행을 근거로 위자료를 청구할 수 없고 불법행위를 근거로 청구해야 한다.","c":"중","v":1},"변리사2018_55-25-2":{"f":"채권자지체 중에 이행불능이 된 경우, 채권자지체가 발생한 사실에 대한 증명책임은 채무자에게 있다.","w":"채권자지체를 주장하는 쪽, 즉 채무자가 증명해야 한다.","c":"중","v":1},"변리사2018_55-25-3":{"f":"채권자지체로 인하여 채권의 목적물을 보관 또는 변제하기 위한 비용이 증가된 때에 그 증가액은 채권자가 부담한다.","w":"채권자지체로 증가한 보관·변제 비용은 채권자의 부담이다(민법 제403조).","c":"상","v":1},"변리사2018_55-25-4":{"f":"이자 있는 채권의 경우에 채권자지체 중에는 채무자가 이자를 지급할 의무가 없다.","w":"채권자지체 중에는 채무자가 이자를 지급할 필요가 없다(민법 제402조).","c":"상","v":1},"변리사2018_55-25-5":{"f":"민법 제538조 제1항의 ‘채권자의 수령지체 중에 당사자 쌍방의 책임 없는 사유로 채무를 이행할 수 없게 된 때’에 해당하기 위해서는 채무자의 현실 제공 또는 구두 제공이 필요하다.","w":"제538조 제1항 제2문의 수령지체가 성립하려면 채무자가 현실 제공이나 구두 제공을 했어야 한다(판례). 제공의 정도는 그 시기와 구체적 상황에 따라 신의칙에 맞게 정한다.","c":"상","v":1},"변리사2019_56-31-3":{"f":"부동산의 소유권이전등기의무자가 그 부동산에 제3자 명의로 가등기를 마쳐주더라도 그것만으로 소유권이전등기의무가 이행불능이 되지는 않는다.","w":"가등기를 마쳐도 소유권은 여전히 의무자에게 있고 본등기 전까지는 이전할 수 있어 이행불능이 아니다.","c":"중","v":1},"변리사2021_58-25-5":{"f":"甲은 乙로부터 1억 원을 빌리면서 5회에 걸쳐 매회 2천만 원씩 분할상환하되, 분할변제기한을 1회라도 지체하였을 때는 기한의 이익을 잃는 것으로 특약한 경우, 특별한 사정이 없는 한 채권자의 청구가 있어야 미상환금액 전부에 대하여 기한이익이 상실되어 지체책임을 진다.","w":"이런 특약은 특별한 사정이 없으면 채권자의 청구 등이 있어야 기한이익이 상실되는 형성권적 특약으로 추정된다.","c":"상","v":1},"변리사2021_58-26-4":{"f":"채권액이 외국통화로 지정된 금액채권인 외화채권의 경우, 채권자는 대용급부권을 행사하여 우리나라 통화로 환산하여 청구할 수 있다.","w":"민법 제378조는 채무자가 우리나라 통화로 변제할 수 있다고 정한다. 판례는 채권자도 외화채권을 우리나라 통화로 환산하여 청구할 수 있다고 본다.","c":"상","v":1},"변리사2021_58-27-3":{"f":"민법상 임대차에서 목적물을 사용수익하게 할 임대인의 의무는 임대인이 임대차목적물의 소유권을 상실한 것만으로는 이행불능이 되지 않는다.","w":"소유권 상실만으로는 이행불능이 아니고, 임차인이 소유자로부터 반환청구를 받는 등 실제로 사용수익할 수 없게 되어야 이행불능이다.","c":"상","v":1},"변리사2023_60-25-1":{"f":"계약당사자 일방이 자신의 계약상 채무 이행에 장애가 될 수 있는 사유를 계약체결 시에 예견할 수 있었음에도 상대방에게 고지하지 않은 경우, 그 사유로 인해 채무불이행이 되는 것에 대해 귀책사유가 인정될 수 있다.","w":"예견할 수 있었던 장애를 고지하지 않았다면 그것 자체가 귀책사유가 된다.","c":"중","v":1},"변리사2023_60-28-4":{"f":"채무자가 금전채무를 이행하지 않아 발생한 확정된 지연손해금에 대하여 채권자가 이행청구를 하는 경우 그 지연손해금에 대하여 다시 지연손해금의 지급을 구할 수 있다.","w":"확정된 지연손해금은 이행청구를 받은 때부터 다시 지체책임이 생겨 그에 대한 지연손해금을 청구할 수 있다.","c":"상","v":1},"변리사2024_61-25-2":{"f":"특정물매매의 경우, 매수인이 매매대금을 지급하지 않더라도 인도받지 않은 목적물로부터 생긴 과실에 대한 수취권은 특별한 사정이 없는 한 매도인에게 귀속된다.","w":"인도 전 목적물에서 생긴 과실은 매도인의 것이다. 대금을 완납하지 않은 매수인에게 귀속되지 않는다(민법 제587조).","c":"상","v":1},"변리사2024_61-26-2":{"f":"이행기의 정함이 없는 지명채권을 양수한 채권양수인이 채무자를 상대로 그 이행을 구하는 소를 제기하고, 그 소송 계속 중 채무자에 대한 채권양도통지가 이루어진 경우에는 특별한 사정이 없는 한 채무자는 채권양도통지가 도달된 날의 다음 날부터 채권양수인에 대해 이행지체의 책임을 진다.","w":"소 제기 시가 아니라 양도통지가 도달한 다음 날부터 이행지체이다.","c":"상","v":1},"변리사2026_63-26-5":{"f":"토지소유자가 수필의 토지 중 일정 면적을 상대방에게 매도한 경우, 양도할 토지의 위치가 확정되지 않았다면 특별한 사정이 없는 한 상대방의 채권은 선택채권에 해당한다.","w":"여러 필지 중 일정 면적을 매도하고 위치를 정하지 않았다면 매수인의 채권은 종류채권이 아니라 선택채권이다(판례).","c":"상","v":1},"변리사2026_63-27-4":{"f":"이행불능으로 인한 손해배상청구권은 본래의 채권과 동일성을 가지므로 본래의 채권이 시효로 소멸하면 본래의 채권과 함께 소멸한다.","w":"이행불능으로 인한 손해배상청구권은 본래 채권의 내용이 바뀐 것이어서 본래 채권의 소멸시효 기간이 지나면 함께 소멸한다.","c":"상","v":1},"변리사2016_53-28-4":{"f":"丁의 甲에 대한 채권이 시효완성으로 인하여 소멸하였다면 乙과 丙은 甲의 부담부분 한도에서 채무를 면하게 된다.","w":"어느 연대채무자에 대하여 소멸시효가 완성하면 그 부담부분에 한하여 다른 연대채무자도 의무를 면한다(민법 제421조). 乙과 丙이 채무 전부를 면하는 것은 아니다.","c":"상","v":1},"변리사2016_53-30-1":{"f":"丙이 乙에게 자신의 명의로 된 확정일자 있는 채권양도통지서를 발송하여 도달되었더라도, 丙은 乙에게 위 채권양도로 대항할 수 없다.","w":"채권양도의 통지는 양도인이 해야 한다. 양수인이 한 통지는 효력이 없다(민법 제450조 제1항).","c":"상","v":1},"변리사2016_53-30-2":{"f":"매매대금채권에 관하여 甲과 乙 사이에 양도금지 특약이 있더라도, 乙은 경과실로 이를 알지 못한 丙에게 위 특약으로써 대항할 수 없다.","w":"양도금지 특약은 선의의 제3자에게 대항하지 못하고, 중과실이 있어야 악의와 같이 취급한다(민법 제449조 제2항, 대법원 판례).","c":"상","v":1},"변리사2016_53-30-4":{"f":"甲이 乙에 대한 위 채권을 丁에게도 양도하였고 丙과 丁에 대한 양도에 대하여 확정일자 있는 증서에 의한 통지가 이루어졌다면 丙과 丁 간의 우열은 통지가 도달한 일시의 선후에 의한다.","w":"확정일자 있는 통지끼리의 우열은 확정일자의 선후가 아니라 통지가 채무자에게 도달한 일시의 선후로 정한다(대법원 1994.4.26. 선고 93다24223 전원합의체 판결).","c":"상","v":1},"변리사2016_53-30-5":{"f":"丙이 乙에 대하여 매매대금의 지급을 소구(訴求)하였다면 丙이 아직 대항요건을 갖추지 못하였더라도 丙의 재판상 청구는 소멸시효 중단사유로 인정된다.","w":"양수인이 대항요건을 갖추지 못했어도 채권자로서 소를 제기하면 시효중단의 효력이 생긴다.","c":"중","v":1},"변리사2016_53-31-4":{"f":"토지매수인이 그 토지에 관한 임대차보증금 반환채무 등을 인수하면서 채무액을 매매대금에서 공제하기로 약정한 경우, 그 인수는 특별한 사정이 없는 한 이행인수로 보아야 한다.","w":"매매대금에서 공제하기로 한 경우에는 채권자를 면책시키는 것이 아니라 이행인수로 해석한다(대법원 판례).","c":"중","v":1},"변리사2017_54-29-1":{"f":"甲이 1천만원의 채무에 대한 소멸시효 기간이 경과한 후 시효의 이익을 포기한 경우에도, 丙은 소멸시효를 원용하여 연대보증채무의 소멸을 주장할 수 있다.","w":"주채무자의 항변포기는 보증인에게 효력이 없으므로(민법 제433조 제2항), 주채무자가 시효이익을 포기해도 보증인은 주채무의 소멸시효 완성을 원용할 수 있다.","c":"상","v":1},"변리사2017_54-29-2":{"f":"甲이 乙에게 8백만원의 채권을 가지고 있는 경우, 丙은 8백만원의 한도 내에서 상계로 채권자에게 대항할 수 있다.","w":"보증인은 주채무자가 채권자에게 가진 채권으로 상계할 수 있는 한도에서 채권자에게 대항할 수 있다(민법 제434조).","c":"중","v":1},"변리사2017_54-29-3":{"f":"乙이 甲에 대한 채권을 丁에게 양도하고 확정일자 있는 증서로 甲에게 통지한 경우, 乙이 丙에게 보증채권 양도의 통지를 하지 않아도 丙에 대한 채권이 丁에게 이전된다.","w":"보증채권은 주채권에 수반하여 이전되므로 보증인에게 따로 통지할 필요가 없다.","c":"상","v":1},"변리사2017_54-29-5":{"f":"甲의 채무가 본래 단기소멸시효에 걸리는 것이었지만 확정판결에 의해 소멸시효 기간이 10년으로 연장된 경우라도, 丙의 보증채무에는 10년의 소멸시효기간이 적용되지 않는다.","w":"주채무자에 대한 확정판결로 주채무의 시효기간이 10년으로 늘어나도 보증채무의 시효기간은 늘어나지 않고 보증채무 자체의 성질에 따라 정해진다(대법원 판례).","c":"상","v":1},"변리사2017_54-31-1":{"f":"이행인수인은 법정대위를 할 수 있는 변제할 정당한 이익이 있는 자에 해당한다.","w":"이행인수인은 채무자에 대해 채무를 변제할 의무를 지므로 변제할 정당한 이익이 있는 자에 해당하고, 변제하면 법정대위를 할 수 있다(민법 제481조, 대법원 판례).","c":"상","v":1},"변리사2017_54-31-3":{"f":"부동산 매수인이 매매목적물에 설정된 근저당권의 피담보채무를 이행인수한 뒤 그 변제를 게을리 하여 근저당권이 실행됨으로써 매도인이 매매목적물에 대한 소유권을 상실한 경우, 이는 매수인의 책임 있는 사유로 소유권이전등기의무가 이행불능으로 된 경우에 해당하고 그에 대하여 매도인의 과실은 인정되지 않는다.","w":"이행인수를 한 매수인이 변제를 게을리했으므로 불능의 책임은 매수인에게 있고, 매도인에게는 과실이 없다.","c":"중","v":1},"변리사2017_54-31-4":{"f":"계약당사자로서의 지위가 제3자에게 이전되는 경우, 계약상 지위를 전제로 한 권리관계는 이전되지만 불법행위에 기한 손해배상청구권은 별도의 채권양도절차를 밟아야 제3자에게 이전된다.","w":"계약상 지위 이전이 불법행위에 기한 손해배상청구권까지 당연히 이전시키지는 않는다.","c":"중","v":1},"변리사2017_54-31-5":{"f":"채무자와 인수인의 합의에 의한 중첩적 채무인수의 경우, 채권자의 수익의 의사표시는 계약의 성립요건이나 효력발생요건이 아니라 채권자가 인수인에 대한 권리를 취득하기 위한 요건이다.","w":"채무자와 인수인의 합의에 의한 중첩적 채무인수는 제3자를 위한 계약이고, 채권자의 수익의 의사표시는 채권자가 인수인에게 직접 청구할 권리를 취득하기 위한 요건이다(대법원 판례).","c":"상","v":1},"변리사2018_55-28-1":{"f":"甲이 丁에 대한 4천만원의 반대채권을 가지고 유효하게 상계한 경우, 丙의 채무도 4천만원이 소멸하여 2천만원의 채무만 남는다.","w":"연대채무자 1인의 상계는 채무자 전원의 이익을 위해 절대적 효력이 있다. 상계된 4천만원 한도에서 모든 채무자의 채무가 소멸한다(민법 제418조 제1항).","c":"중","v":1},"변리사2018_55-29-1":{"f":"丙이 보증계약 후 乙의 변제기를 연장해 준 경우, 특별한 사정이 없는 한 甲은 주채무의 보증계약 당시의 이행기가 되면 乙에게 미리 구상권을 행사할 수 있다.","w":"채권자가 주채무자에게 변제기를 연장해 준 것은 보증인이 주채무자에게 대항할 수 없으므로 보증계약 당시의 이행기가 도래하면 사전구상이 가능하다(민법 제442조 제2항).","c":"상","v":1},"변리사2018_55-29-2":{"f":"甲이 丙에게 변제한 이후 乙과 丙의 계약이 해제되어 소급적으로 소멸한 경우, 甲은 丙을 상대로 이미 이행한 급부를 부당이득으로 반환청구할 수 있다.","w":"해제로 주채무가 소급해서 소멸하므로 보증채무도 없어지고, 보증인이 한 변제는 법률상 원인이 없는 이행이 되어 부당이득으로 반환청구할 수 있다.","c":"중","v":1},"변리사2018_55-29-4":{"f":"丙이 乙에 대한 대금채권을 실행하기 위해 乙의 재산을 압류하면 甲의 보증채무의 소멸시효도 중단된다.","w":"주채무에 대한 시효중단은 보증인에게도 효력이 있다(민법 제440조).","c":"상","v":1},"변리사2018_55-29-5":{"f":"甲이 변제로 乙의 채무를 소멸시킨 경우, 甲은 변제액과 면책된 날 이후의 법정이자 및 피할 수 없는 비용 기타 손해배상을 구상할 수 있다.","w":"주채무자의 부탁으로 보증한 보증인은 변제액에 면책일 이후의 법정이자, 비용, 손해배상까지 구상한다(민법 제441조 제2항, 제425조 제2항). 그 당시 이익을 받은 한도로 줄어드는 것은 부탁 없이 보증한 경우다(제444조 제1항).","c":"중","v":1},"변리사2018_55-30-4":{"f":"채권양도에 대한 乙의 승낙이 있은 후에 채권양도계약이 해제되어 甲이 乙에게 양도철회통지를 한 경우, 乙은 이로써 丙의 채무이행청구에 대하여 대항할 수 없다.","w":"채무자가 승낙한 뒤 양도계약이 해제되었다면, 채무자에게 해제 사실을 통지해야 하는 쪽은 양수인이다(판례, 민법 제452조 제2항 취지). 양도인 甲의 철회통지만으로는 乙이 丙에게 대항하지 못한다.","c":"중","v":1},"변리사2018_55-31-1":{"f":"채무인수인은 특별한 의사표시가 없으면 자신의 구(舊)채무자에 대한 항변사유를 가지고 채권자에게 대항할 수 없다.","w":"인수인 자신이 구채무자에 대해 가진 항변은 채권자에게 대항하는 데 쓸 수 없다. 인수인은 구채무자가 채권자에 대해 갖는 항변으로만 대항한다(민법 제458조).","c":"중","v":1},"변리사2018_55-31-3":{"f":"토지매수인이 토지에 관한 매도인의 채무를 인수하면서 그 채무액을 매매대금에서 공제하기로 약정한 경우, 특별한 사정이 없는 한 이행인수에 해당한다.","w":"대금에서 채무액을 공제하기로 한 약정은 채권자를 면책시키려는 것이 아니므로 이행인수로 본다.","c":"중","v":1},"변리사2018_55-31-4":{"f":"채무자 아닌 제3자가 설정한 근저당권에 관하여 그 제3자의 동의를 얻어 채무인수를 원인으로 채무자를 교체하는 변경등기가 마쳐졌더라도, 특별한 사정이 없는 한 그 근저당권은 그 후 채무인수인이 다른 원인으로 부담하는 채무까지 담보하지는 않는다.","w":"인수한 채무만 담보하고, 이후 별개 원인으로 생긴 채무까지 담보하는 것은 아니다.","c":"상","v":1},"변리사2018_55-31-5":{"f":"채무자와 인수인 간의 중첩적 채무인수계약의 경우에 채권자는 인수인에 대하여 수익의 의사표시를 하여야 직접 청구할 권리를 갖는다.","w":"채무자와 인수인 사이의 계약으로 하는 중첩적 채무인수는 제3자를 위한 계약이어서, 채권자가 수익의 의사표시를 해야 인수인에게 직접 청구할 권리가 생긴다(민법 제539조 제2항, 판례). 인수인에게 이행을 청구하는 것도 수익의 의사표시가 된다.","c":"상","v":1},"변리사2019_56-26-4":{"f":"채권자가 연대보증인에게 채무이행을 청구한 경우, 연대보증인은 최고·검색의 항변을 할 수 없다.","w":"연대보증인에게는 최고·검색의 항변권이 없다(민법 제437조 단서).","c":"상","v":1},"변리사2019_56-32-5":{"f":"매수인이 매매목적물에 관한 임대차보증금반환채무를 인수하면서 그 채무액을 매매대금에서 공제하기로 약정한 경우, 임차인의 승낙이 없으면 이행인수로 본다.","w":"병존적 채무인수가 아니라 이행인수로 본다. 임차인의 승낙이 있어야 면책적 인수가 된다.","c":"중","v":1},"변리사2021_58-28-1":{"f":"채무자와 채무인수인 사이의 면책적 채무인수에서 채권자가 승낙을 거절하였다면 다시 승낙하더라도 채무인수의 효력이 생기지 않는다.","w":"채권자가 한 번 거절하면 확정되어 이후의 승낙은 효력이 없다.","c":"상","v":1},"변리사2021_58-28-2":{"f":"채무자와 채무인수인 사이의 면책적 채무인수에서 채권자가 채무인수인에게 인수금의 지급을 청구하는 것은 채무인수의 승낙으로 볼 수 있다.","w":"채권자가 인수인에게 직접 이행을 청구했다면 묵시적 승낙으로 인정될 수 있다.","c":"상","v":1},"변리사2021_58-28-3":{"f":"채무자와 채무인수인 사이의 면책적 채무인수에서 채권자의 승낙이 없는 경우에도, 채무자와 인수인 사이에는 이행인수로서의 효력이 인정될 수 있다.","w":"채권자의 승낙이 없어 면책적 인수가 되지 않더라도 당사자 사이에서는 이행인수로 해석된다.","c":"중","v":1},"변리사2021_58-28-5":{"f":"면책적 채무인수의 경우, 채무인수인은 채무자에 대한 항변사유로 채권자에게 대항할 수 없다.","w":"인수인이 채무자에게 가진 항변은 채권자에게 대항하는 데 쓸 수 없다. 전(前) 채무자가 채권자에 대해 가진 항변만 쓴다(민법 제458조).","c":"상","v":1},"변리사2023_60-31-2":{"f":"저당권이 설정된 부동산의 매수인이 피담보채무를 인수하면서 그 채무액을 매매대금에서 공제하기로 하고 잔액만을 지급한 경우, 특별한 사정이 없는 한 매수인은 잔금 지급의무를 다한 것으로 본다.","w":"채무 인수액을 대금에서 공제하기로 했다면 잔액을 지급하면 대금 지급의무를 다한 것이다.","c":"중","v":1},"변리사2023_60-31-3":{"f":"주택의 임차인이 대항력을 갖추었더라도 그가 그 주택의 소유권을 취득하면 특별한 사정이 없는 한 임대인에 대한 보증금반환청구권은 혼동으로 소멸한다.","w":"대항력을 갖춘 임차인이 그 주택의 소유권을 취득하면 임대인의 지위를 승계해 보증금반환채무를 인수하므로, 보증금반환채권은 혼동으로 소멸한다(판례).","c":"상","v":1},"변리사2023_60-31-4":{"f":"중첩적 채무인수에서 채무자와 인수인은 채권자에 대하여 원칙적으로 연대채무 관계에 있다.","w":"채무자의 부탁으로 인수한 중첩적 채무인수에서는 채무자와 인수인이 연대채무를 진다. 채무자의 부탁 없이 채권자와 인수인의 계약만으로 인수한 경우에 부진정연대채무가 된다(판례).","c":"중","v":1},"변리사2023_60-31-5":{"f":"채무가 인수된 경우 특별한 사정이 없는 한 제3자가 제공한 담보물권은 소멸한다.","w":"제3자가 제공한 담보는 그 제3자의 동의가 없으면 채무인수 때 소멸한다(민법 제459조 단서).","c":"상","v":1},"변리사2024_61-30-1":{"f":"부동산매매로 인한 소유권이전등기청구권이 양도된 경우, 양도인의 채무자에 대한 통지만으로는 채무자에 대한 대항력이 발생하지 않고 채무자의 동의나 승낙이 있어야 한다.","w":"부동산 이전등기청구권 양도는 채무자의 동의나 승낙이 있어야 채무자에게 대항할 수 있다(대법원 판례).","c":"상","v":1},"변리사2024_61-30-2":{"f":"소송행위를 하게 하는 것을 주목적으로 지명채권의 양도가 이루어진 경우, 그 채권양도가 신탁법상의 신탁에 해당하지 않는 경우에도 무효이다.","w":"소송행위를 주된 목적으로 한 채권양도는 신탁법상 신탁에 해당하지 않더라도 신탁법 제6조(소송을 목적으로 하는 신탁의 금지)가 유추적용되어 무효이다(판례).","c":"상","v":1},"변리사2024_61-30-3":{"f":"주채무자에 대한 지명채권이 양도된 후 양수인이 보증인에게 보증채권을 행사하기 위해서는 주채권의 양도에 대한 대항요건과 별도로 보증채권의 양도에 대한 대항요건을 갖출 필요가 없다.","w":"보증채권은 주채권에 수반하여 함께 이전하므로 주채권 양도의 대항요건으로 족하다.","c":"상","v":1},"변리사2024_61-30-5":{"f":"채권자와 양수인 사이의 계약에 의해 지명채권이 양도된 경우, 양수인은 제3자에 대한 대항요건을 구비하기 위하여 채권자에게 채권양도통지절차의 이행을 청구할 수 있다.","w":"양수인은 양도인에게 통지의 이행을 청구할 수 있다. 양도 통지는 양도인이 해야 하기 때문이다.","c":"상","v":1},"변리사2026_63-30-1":{"f":"전세권 존속 중에는 장래에 그 전세권이 소멸하는 경우에 전세금반환채권이 발생하는 것을 조건으로 그 장래의 조건부 채권을 양도할 수 있다.","w":"전세권 존속 중에도 장래 발생할 전세금반환채권을 조건부로 양도할 수 있다(대법원 판례).","c":"중","v":1},"변리사2026_63-31-1":{"f":"면책적 채무인수가 있으면 종전채무자의 채무에 대한 보증은 보증인의 동의 없이는 소멸한다.","w":"종전 채무자의 채무에 대한 보증은 보증인이 채무인수에 동의하지 않으면 채무인수로 소멸한다(민법 제459조).","c":"상","v":1},"변리사2026_63-31-3":{"f":"면책적 채무인수에서 채권자는 승낙 또는 거절의 의사표시를 채무자나 인수인 중 어느 한쪽에 하면 된다.","w":"채권자의 승낙 또는 거절은 채무자와 인수인 중 어느 쪽에 해도 된다(민법 제454조 제2항).","c":"상","v":1},"변리사2026_63-31-4":{"f":"채무자와 인수인의 합의에 의한 중첩적 채무인수에서 채권자의 수익의 의사표시는 그 채무인수 계약의 효력발생을 위한 요건이 아니다.","w":"수익의 의사표시는 성립요건도 효력발생요건도 아니다.","c":"상","v":1},"변리사2026_63-31-5":{"f":"채무자와 인수인이 면책적 채무인수의 약정을 한 경우, 채권자의 승낙이 있어야 채무자는 채무를 면한다.","w":"면책적 채무인수는 채권자의 승낙이 있어야 효력이 생기므로 승낙 없이는 채무자가 면책되지 않는다(민법 제454조).","c":"상","v":1},"변리사2026_63-32-1":{"f":"채권자가 주채무자에 대하여 상계적상이 있는 자동채권을 상계하지 않는 경우에도, 보증인은 이를 이유로 보증채무의 이행을 거절할 수 없다.","w":"채권자에게 주채무자와 상계할 의무가 없으므로, 상계하지 않았다는 이유로 보증인이 이행을 거절할 수는 없다. 이행거절권은 주채무자에게 취소권·해제권·해지권이 있는 경우에 인정된다(민법 제435조).","c":"중","v":1},"변리사2026_63-32-2":{"f":"채권자의 연대보증인 중 1인에 대한 채무면제는 연대보증인 사이에 연대특약이 없으면 다른 연대보증인에 대하여 그 효력이 미치지 않는다.","w":"연대보증인 사이에 연대특약이 없으면 그 1인에 대한 면제는 다른 보증인에게 영향을 주지 않는다.","c":"중","v":1},"변리사2026_63-32-3":{"f":"부진정연대채무자 상호간에 구상권을 행사하기 위해서는 사전 또는 사후에 통지를 할 필요가 없다.","w":"통지 의무는 연대채무에 관한 규정(민법 제426조)이고 부진정연대채무에는 적용되지 않는다.","c":"중","v":1},"변리사2026_63-32-4":{"f":"사용대차에서 공동차주의 목적물 반환의무는 원칙적으로 연대채무이다.","w":"수인이 공동하여 물건을 차용한 때에는 연대하여 의무를 부담한다(민법 제616조).","c":"상","v":1},"변리사2016_53-33-3":{"f":"공사도급계약의 도급인이 자기 소유의 토지에 근저당권을 설정하여 수급인으로 하여금 공사에 필요한 자금을 대출받도록 한 경우, 수급인의 근저당권말소의무와 도급인의 공사대금채무는 동시이행관계에 있다.","w":"대출 목적으로 설정한 근저당권의 말소의무와 공사대금 지급의무는 서로 대가관계에 있어 동시이행이다.","c":"중","v":1},"변리사2016_53-35-2":{"f":"매도인이 계약금의 배액을 상환하고 계약을 해제하려면 계약해제의 의사표시를 하고 계약금 배액을 제공하면 되고, 상대방이 수령하지 않는 경우에도 공탁까지 할 필요는 없다.","w":"배액을 제공하면 충분하고 공탁은 요구되지 않는다(대법원 판례).","c":"상","v":1},"변리사2016_53-35-3":{"f":"계약당사자가 위 민법규정에 따라 매매계약을 해제하는 경우, 상대방에 대하여 원상회복은 청구할 수 없고 채무불이행을 이유로 한 손해배상도 청구할 수 없다.","w":"해약금에 의한 해제는 채무불이행에 의한 해제가 아니므로 손해배상을 청구할 수 없다(민법 제565조 제2항).","c":"상","v":1},"변리사2016_53-35-4":{"f":"매도인이 매수인에게 매매계약의 이행을 최고하고 매매잔대금의 지급을 구하는 소송을 제기한 것만으로는 이행에 착수한 것이 아니다.","w":"매도인이 이행을 최고하고 잔대금 지급을 구하는 소를 제기한 것만으로는 이행에 착수했다고 볼 수 없어 매수인은 여전히 해약금 해제를 할 수 있다(대법원 판례).","c":"상","v":1},"변리사2016_53-35-5":{"f":"토지거래허가구역 내 토지에 관하여 매매계약을 체결하고 계약금만 주고받은 상태에서 토지거래허가를 받았더라도, 매도인은 해약금규정에 따른 계약해제를 할 수 있다.","w":"허가를 받은 것만으로는 이행 착수가 아니므로 해약금에 의한 해제가 가능하다.","c":"중","v":1},"변리사2016_53-36-2":{"f":"채권자대위권행사의 통지를 받은 후 채무자의 채무불이행을 이유로 제3채무자가 매매계약을 해제한 경우, 그 제3채무자는 계약해제로써 대위권을 행사하는 채권자에게 대항할 수 있다.","w":"법정해제는 채무자의 권리를 처분하는 행위가 아니어서 대위권 행사 통지 후에도 대항할 수 있다.","c":"중","v":1},"변리사2017_54-34-4":{"f":"만약 丙이 甲의 대리인으로서 乙을 기망하여 乙이 위 매매계약을 체결한 경우, 乙은 丙의 대금지급청구를 거절할 수 있을 뿐 아니라 위 매매계약을 취소할 수도 있다.","w":"대리인의 기망은 상대방의 사기와 같이 다루어 취소할 수 있다.","c":"상","v":1},"변리사2017_54-35-1":{"f":"만약 계약 당시 乙이 계약금 5백만원을 지급하였다면 계약의 이행 착수 전이라도, 甲은 1천만원을 상환하고 위 매매계약을 해제할 수 없다.","w":"계약금 일부만 지급된 경우 해약금의 기준은 실제로 받은 금액이 아니라 약정 계약금이다. 받은 5백만원의 배액만 상환해서는 해제할 수 없다(대법원 판례).","c":"중","v":1},"변리사2017_54-35-2":{"f":"甲의 채권자 丙이 2015. 2. 15. 甲의 잔대금 채권을 가압류한 경우라면, 丙은 민법 제548조 제1항 단서에 의해 보호받을 수 있는 제3자에 해당하지 않는다.","w":"해제된 계약상의 채권을 압류한 자는 해제된 계약의 효과를 기초로 새 권리를 취득한 제3자가 아니다.","c":"중","v":1},"변리사2017_54-35-4":{"f":"乙 명의의 등기말소 전인 2015. 4. 20. 乙로부터 X주택의 일부를 임차하여 주택 임대차보호법상 대항력을 갖춘 임차인이라도 위 매매계약이 해제된 사실을 알고 있었다면 X주택에 대한 甲의 명도청구에 대항할 수 없다.","w":"계약 해제 뒤 말소등기 전에 이해관계를 맺은 제3자는 해제 사실을 몰랐던 경우에만 민법 제548조 제1항 단서로 보호된다. 해제를 알고 임차한 임차인은 甲에게 대항할 수 없다(대법원 판례).","c":"상","v":1},"변리사2017_54-35-5":{"f":"X주택을 사용한 乙이 계약의 해제로 이를 甲에게 반환하는 경우, X주택이 乙의 사용으로 인해 훼손되었다고 볼 수 없는 경우에는 그 사용이익 외에 감가상각비를 별도로 산정하여 반환할 필요가 없다.","w":"사용으로 훼손되지 않았다면 사용이익을 반환하면 족하고, 감가상각비를 따로 가산하지 않는다.","c":"중","v":1},"변리사2017_54-40-1":{"f":"사업자와 고객 사이에 교섭이 이루어진 약관 조항은 「약관의 규제에 관한 법률」에 정한 약관에 해당하지 않는다.","w":"개별적으로 교섭한 합의사항은 약관이 아니다(약관의 규제에 관한 법률 제2조, 제4조).","c":"상","v":1},"변리사2017_54-40-2":{"f":"약관조항이 무효로 되면, 민법상 일부무효의 법리와 달리 나머지 부분은 유효함이 원칙이다.","w":"약관법은 약관의 일부가 무효여도 나머지 부분은 유효하다고 정한다(약관의 규제에 관한 법률 제16조).","c":"상","v":1},"변리사2017_54-40-3":{"f":"약관에 정하여진 사항이 거래상 일반적이고 공통된 것이어서 고객이 별도의 설명 없이도 충분히 예상할 수 있었던 사항이라면, 사업자에게 명시설명 의무가 없다.","w":"설명의무는 고객이 예상하기 어려운 중요 내용에 한해 인정된다.","c":"상","v":1},"변리사2017_54-40-5":{"f":"동일한 약관집 내의 대다수의 조항들이 교섭되고 변경된 사정이 있다면, 변경되지 아니한 나머지 소수의 조항들에 대해서도 교섭이 이루어진 것으로 추정할 수 있다.","w":"대다수 조항이 교섭되었다면 변경되지 않은 조항에도 교섭이 있었다고 추정할 수 있다.","c":"중","v":1},"변리사2018_55-33-1":{"f":"乙은 상당한 기간을 정해 이행을 최고하지 않고도 甲과의 계약을 해제할 수 있다.","w":"이행불능이면 최고 없이 곧바로 해제할 수 있다(민법 제546조).","c":"상","v":1},"변리사2018_55-33-2":{"f":"乙이 甲과의 계약을 해제하면 乙은 甲에 대해 원상회복청구권을 갖는데, 그 권리의 소멸시효는 해제권이 발생한 때가 아니라 해제를 한 때로부터 진행한다.","w":"원상회복청구권은 해제의 의사표시를 한 때 발생하므로 그때부터 시효가 진행한다.","c":"중","v":1},"변리사2018_55-33-3":{"f":"乙은 甲의 소유권이전등기의무와 동시이행관계에 있는 잔대금지급의무의 이행제공을 하지 않고도 甲과의 계약을 해제할 수 있다.","w":"이행불능을 이유로 해제할 때에는 해제하는 쪽이 자기의 반대채무(잔대금 지급)를 이행제공할 필요가 없다(판례).","c":"상","v":1},"변리사2018_55-33-4":{"f":"만약 丙이 아직 甲에게 매매대금을 지급하지 않았다면, 乙은 甲에게 丙에 대한 매매대금채권을 자신에게 양도하라고 청구할 수 있을 뿐, 丙을 상대로 직접 매매대금을 자신에게 지급하라고 청구할 수는 없다.","w":"대상청구권은 채무자에게 그가 얻은 대상(여기서는 丙에 대한 대금채권)을 넘겨 달라고 청구하는 권리다. 제3자인 丙에게 직접 지급을 청구할 수는 없다(판례).","c":"중","v":1},"변리사2019_56-33-4":{"f":"계약금을 수령한 매도인이 매수인에 대하여 해제권을 행사하기 위해서는 수령한 계약금의 배액의 이행제공을 하면 되고, 매수인이 수령을 거부하더라도 공탁할 필요는 없다.","w":"배액을 제공하면 해제권을 행사할 수 있고 공탁까지 필요하지는 않다.","c":"중","v":1},"변리사2019_56-34-1":{"f":"甲은 乙이 발송한 편지를 2018. 9. 19. 받았는데, 甲이 2018. 9. 24. 개봉하여 읽었다면 매매계약은 乙이 승낙의 편지를 발송한 때 성립한다.","w":"격지자 사이의 계약은 승낙의 통지를 발송한 때 성립한다(민법 제531조). 청약자가 편지를 읽은 때가 아니다.","c":"상","v":1},"변리사2019_56-34-2":{"f":"乙이 승낙의 의사표시를 하였더라도, 乙이 발송한 편지를 甲이 승낙기간인 2018. 9. 25.까지 받지 못하면 매매계약은 성립하지 않는다.","w":"승낙의 통지가 승낙기간 내에 도달해야 하고 도달하지 않으면 청약이 효력을 잃는다(민법 제528조).","c":"상","v":1},"변리사2019_56-34-3":{"f":"甲은 乙이 발송한 편지를 2018. 9. 20. 받았다면, 매매계약은 乙이 승낙을 발송한 때에 성립하고 효력이 발생한다.","w":"격지자 사이의 계약은 승낙의 통지를 발송한 때 성립한다(민법 제531조). 편지가 도달한 날이 성립 시기가 아니다.","c":"상","v":1},"변리사2019_56-34-5":{"f":"乙이 2018. 9. 17. 매수하겠다는 편지를 발송하기 전이라도 甲은 乙에 대하여 매각의 의사표시를 철회할 수 없다.","w":"청약은 상대방에게 도달해 효력이 생긴 뒤에는 철회하지 못한다(민법 제527조). 상대방이 아직 승낙을 발송하지 않았어도 마찬가지다.","c":"상","v":1},"변리사2019_56-35-1":{"f":"근저당권 실행을 위한 경매가 무효로 된 경우, 매수인의 채무자에 대한 소유권이전등기 말소의무와 근저당권자의 매수인에 대한 배당금반환의무는 동시이행관계에 있지 않다.","w":"매수인의 등기말소의무는 채무자에게 지는 것이고 배당금반환의무는 근저당권자가 매수인에게 지는 것이어서, 두 의무는 동시이행관계에 있지 않다(판례).","c":"중","v":1},"변리사2019_56-35-2":{"f":"동시이행관계에 있는 쌍방의 채무 중 어느 한 채무가 이행불능이 됨으로 인하여 발생한 손해배상채무도 다른 채무와 동시이행관계에 있다.","w":"손해배상채무는 본래 채무의 변형이므로 동일성이 유지되어 동시이행 관계가 유지된다.","c":"상","v":1},"변리사2019_56-35-3":{"f":"가압류등기가 있는 부동산 매매계약의 경우, 특별한 사정이 없는 한 매도인의 가압류 등기의 말소의무는 매수인의 대금지급의무와 동시이행관계에 있다.","w":"가압류 등기 말소는 매도인이 소유권이전과 함께 이행해야 하는 의무이므로 대금지급과 동시이행 관계에 있다.","c":"중","v":1},"변리사2019_56-35-4":{"f":"쌍방의 채무가 동시이행관계에 있는 경우, 상대방 채무의 이행제공이 없으면 채무자가 이행기에 채무를 이행하지 않더라도 이행지체의 책임을 지지 않는다.","w":"동시이행항변권이 있는 동안에는 이행기를 넘겨도 지체책임이 없다.","c":"상","v":1},"변리사2021_58-34-3":{"f":"계약이 의사의 불합치로 성립하지 아니한 경우, 그로 인하여 손해를 입은 당사자는 상대방에 대하여 민법 제535조(계약체결상의 과실)를 유추적용하여 손해배상을 청구할 수 없다.","w":"제535조는 원시적 불능으로 계약이 무효인 경우에 적용되며, 의사 불합치로 계약이 성립하지 않은 경우에는 유추적용되지 않는다.","c":"중","v":1},"변리사2021_58-35-4":{"f":"원인채무의 지급을 담보하기 위하여 어음이 교부된 경우, 채무자는 어음반환과 동시이행을 주장하여 원인채무의 지급을 거절할 수 있다.","w":"원인채무의 지급을 담보하려고 어음을 교부한 경우, 채무자는 어음을 돌려받는 것과 동시이행을 주장하며 원인채무의 지급을 거절할 수 있다(판례).","c":"중","v":1},"변리사2021_58-36-1":{"f":"甲과 乙이 계약해제로 인한 원상회복의무로 반환할 매매대금에 가산할 이자를 4%로 약정한 경우, 동 약정이율은 매매대금 반환의무의 이행지체로 인한 지연손해금률에는 적용되지 않는다.","w":"해제로 반환할 금전에 붙일 이자의 약정이율은 이행지체 전까지의 이자에 적용된다. 이행지체 뒤에는 지연손해금률이 적용되고, 지연손해금률을 따로 정하지 않았다면 법정이율에 따른다(판례).","c":"중","v":1},"변리사2023_60-34-3":{"f":"요약자와 수익자 사이의 법률관계(대가관계)의 효력 상실을 이유로 요약자는 낙약자와 요약자 사이의 법률관계(기본관계)상 낙약자에게 부담하는 채무의 이행을 거절할 수 없다.","w":"대가관계의 하자는 기본관계에 영향을 주지 않는다.","c":"상","v":1},"변리사2023_60-35-2":{"f":"사정변경을 이유로 한 계약의 해제나 해지에서 사정변경에 대한 예견가능성이 있었는지는 개별적 사정을 고려하여 구체적·개별적으로 판단하여야 한다.","w":"추상적·일반적으로 판단하지 않고, 당사자의 개별 사정을 고려해 구체적으로 판단한다.","c":"중","v":1},"변리사2024_61-33-1":{"f":"의사표시의 불일치로 인해 계약이 성립하지 않는 경우, 그로 인해 손해를 입은 당사자는 상대방이 계약의 불성립을 알았거나 알 수 있었음을 이유로 계약체결상의 과실로 인한 손해배상을 청구할 수 없다.","w":"의사의 불합치로 계약이 성립하지 않은 경우에는 민법 제535조를 유추적용하여 계약체결상의 과실 책임을 물을 수 없다(판례). 제535조는 목적이 불능인 계약을 체결한 경우에 관한 규정이다.","c":"상","v":1},"변리사2024_61-34-1":{"f":"乙의 과실로 도자기가 멸실된 경우, 甲은 도자기 이전의무를 면하면서 얻은 이익이 있다면 이를 乙에게 상환하여야 한다.","w":"채권자의 책임 있는 사유로 이행불능이 되어 채무자가 이익을 얻은 때에는 이를 채권자에게 상환해야 한다(민법 제538조 제2항).","c":"상","v":1},"변리사2026_63-25-1":{"f":"甲에게 乙과의 위 매매계약에 관한 적법한 해제권이 발생하였다면 이후 甲의 과실로 X토지가 현저히 훼손되었을 때에는 甲의 해제권은 소멸한다.","w":"해제권자의 고의나 과실로 목적물이 현저히 훼손되면 해제권이 소멸한다(민법 제553조).","c":"상","v":1},"변리사2026_63-25-2":{"f":"X토지가 토지거래허가구역내의 토지이고 甲과 乙의 매매계약이 주무관청의 허가를 받지 않아 유동적 무효의 상태에 있는 경우, 甲은 乙의 채무불이행을 이유로 위 매매계약을 해제할 수 없다.","w":"유동적 무효 상태의 계약은 아직 효력이 없어 채무불이행을 이유로 해제할 수 없다.","c":"상","v":1},"변리사2026_63-25-3":{"f":"甲의 해제권 행사가 있기 이전에 乙이 丙에게 X토지를 처분함으로써 이후 甲의 해제권 행사에 따른 乙의 원물반환이 불가능하게 된 경우, 乙이 甲에게 원상회복의무로써 반환하여야 할 금액은 처분 당시의 목적물의 대가이다.","w":"반환이 불가능해진 경우의 가액 반환은 처분 당시의 가액을 기준으로 한다.","c":"중","v":1},"변리사2026_63-25-5":{"f":"乙이 甲에 대한 X토지의 소유권이전등기청구권을 丁에게 양도하고 이를 甲에게 통지한 후 甲과 乙의 매매계약이 해제된 경우, 특별한 사정이 없는 한 丁은 민법 제548조 제1항 단서에 의해 보호되는 제3자에 해당하지 않는다.","w":"계약상 채권의 양수인은 해제된 계약의 효과를 기초로 새 권리를 취득한 자가 아니므로 제3자로 보호받지 못한다.","c":"중","v":1},"변리사2026_63-35-4":{"f":"丙의 甲에 대한 대여금채권이 소멸한 경우에도, 乙은 이를 이유로 丙에게 매매대금의 지급을 거절할 수 없다.","w":"수익자와 요약자 사이의 대가관계 소멸은 낙약자가 수익자에게 대항할 수 있는 사유가 아니다.","c":"상","v":1},"변리사2016_53-34-1":{"f":"乙이 丙에 대하여 채무의 이행을 청구하는 소를 제기하였다가 패소한 경우에는 甲은 丙에 대하여 채권자대위권을 행사할 수 없다.","w":"채무자가 스스로 제3채무자에게 권리를 행사했다면 그 결과가 패소이더라도 채권자는 같은 권리를 대위로 행사할 수 없다(대법원 판례).","c":"상","v":1},"변리사2016_53-34-2":{"f":"甲이 丙에 대하여 채권자대위권을 행사한 경우 丙은 甲의 乙에 대한 채권이 시효로 소멸하였음을 주장할 수 없다.","w":"제3채무자는 채권자의 채무자에 대한 채권이 시효로 소멸하여 직접 이익을 받는 자가 아니므로 그 소멸시효 완성을 원용할 수 없다(대법원 판례).","c":"상","v":1},"변리사2016_53-34-3":{"f":"甲이 乙에 대하여 이행청구의 소를 제기하여 승소한 경우에는, 丙은 甲의 채권자 대위권 행사에 대항하여 乙에 대한 甲의 채권이 무효임을 주장할 수 없다.","w":"채권자가 채무자를 상대로 승소 확정판결을 받았다면 제3채무자는 대위소송에서 피보전채권의 존재를 다툴 수 없다(대법원 판례).","c":"상","v":1},"변리사2016_53-32-2":{"f":"채무자가 채권자에게 채무변제에 갈음하여 다른 채권을 양도하기로 한 경우, 양도인은 양도된 채권의 채무자의 변제자력까지 담보하는 것으로 볼 수 없다.","w":"대물변제로 채권을 양도한 경우 특별한 약정이 없으면 양도인은 채권의 존재만 책임지고 채무자의 변제자력은 담보하지 않는다.","c":"중","v":1},"변리사2017_54-32-3":{"f":"가압류의 효력발생 당시 乙의 채권이 변제기에 도달하지 않은 경우, 甲의 채권의 변제기 후에 乙의 채권이 변제기에 도달한다면 乙은 상계로써 丙에게 대항할 수 없다.","w":"압류·가압류 당시 자동채권의 변제기가 오지 않았다면, 그 변제기가 피압류채권의 변제기와 같거나 먼저 와야 제3채무자가 상계로 대항할 수 있다(대법원 2012.2.16. 선고 2011다45521 전원합의체 판결).","c":"상","v":1},"변리사2023_60-32-4":{"f":"피용자의 고의의 불법행위로 인하여 사용자책임이 성립하는 경우, 사용자는 자신의 고의가 없음을 주장하더라도 피해자의 손해배상채권을 수동채권으로 하는 상계권을 행사할 수 없다.","w":"고의의 불법행위로 인한 손해배상채권을 수동채권으로 한 상계는 금지되며(민법 제496조), 사용자책임의 경우에도 사용자가 상계할 수 없다.","c":"중","v":1},"변리사2026_63-33-4":{"f":"채무자로부터 담보부동산을 취득한 후에 채무를 변제한 제3자는 물상보증인에 대하여 채권자를 대위할 수 없다.","w":"채무자로부터 담보부동산을 취득한 제3자는 보증인에 대하여 대위하지 못하는 것(민법 제482조 제2항 제2호)과 마찬가지로 물상보증인에 대하여도 채권자를 대위할 수 없다(판례).","c":"상","v":1},"변리사2016_53-34-5":{"f":"甲이 채권자대위권을 행사하는 과정에서 비용을 지출한 경우 甲은 乙에게 그 비용의 상환을 청구할 수 있다.","w":"채권자가 대위권을 행사하는 데 쓴 비용은 위임의 비용상환(민법 제688조)을 준용하여 채무자에게 청구할 수 있다.","c":"상","v":1},"변리사2017_54-27-2":{"f":"채권자대위소송에서 제3채무자는 채권자의 채무자에 대한 권리의 발생원인이 된 법률행위가 무효라거나 변제 등으로 소멸하였다는 등의 사실을 주장하여 채권자의 채무자에 대한 권리가 인정되는지를 다툴 수 있다.","w":"제3채무자는 피보전채권의 발생원인이 무효라거나 변제로 소멸했다는 사실을 주장해 피보전채권의 존부를 다툴 수 있다(대법원 판례). 다만 피보전채권의 소멸시효 완성은 원용하지 못한다.","c":"상","v":1},"변리사2017_54-27-3":{"f":"토지거래허가구역에 있는 토지의 매수인은 채권보전의 필요성이 인정되는 경우에 한하여 토지거래허가 신청절차의 협력의무 이행청구권을 보전하기 위하여 매도인의 권리를 대위하여 행사할 수 있다.","w":"채권자대위권은 채권보전의 필요성이 있어야 행사할 수 있다.","c":"중","v":1},"변리사2017_54-27-4":{"f":"이행인수 약정이 체결된 경우, 채무자는 인수인이 그 채무를 이행하지 아니하면 인수인에 대하여 채권자에게 이행할 것을 청구할 수 있고, 채무자의 인수인에 대한 위 청구권을 채권자가 대위행사할 수 있다.","w":"채권자는 자기 채권 보전을 위해 채무자의 이행청구권을 대위하여 행사할 수 있다.","c":"중","v":1},"변리사2017_54-27-5":{"f":"지하도상가 내 점포의 사용청구권을 가지는 자는 상가의 소유자인 시(市)가 불법점유자들에 대하여 가지는 점포의 인도청구권을 대위행사할 수 있다.","w":"특정 점포의 사용청구권을 가진 사람은 소유자의 인도청구권을 대위 행사할 수 있다.","c":"중","v":1},"변리사2017_54-28-4":{"f":"채무자의 수익자에 대한 채권양도가 사해행위로 취소되고, 그에 따른 원상회복으로서 제3채무자에게 채권양도가 취소되었다는 취지의 통지가 이루어진 경우에도, 채권자는 채무자를 대위하여 제3채무자에게 채권에 관한 지급을 청구할 수 없다.","w":"사해행위 취소의 효력은 채권자와 수익자 사이에서만 생기므로 채권은 채무자의 책임재산으로 취급될 뿐 채무자에게 돌아가지 않는다. 그래서 채권자가 채무자를 대위해 제3채무자에게 지급을 청구할 수 없다(대법원 판례).","c":"상","v":1},"변리사2018_55-26-1":{"f":"채무자의 법률행위가 통정허위표시로 무효인 경우에도 채권자취소권의 대상이 될 수 있다.","w":"허위표시로 무효여도 채권자취소권의 요건을 갖추면 사해행위로 취소할 수 있다.","c":"상","v":1},"변리사2018_55-26-2":{"f":"매매계약을 원인으로 하는 가등기에 기하여 본등기가 경료된 경우, 사해행위 요건의 구비 여부는 특별한 사정이 없는 한 가등기를 한 시점을 기준으로 판단하여야 한다.","w":"본등기는 가등기 순위를 확정하는 것이어서 사해행위는 가등기를 한 시점의 원인행위를 기준으로 판단한다(대법원 판례).","c":"중","v":1},"변리사2018_55-26-4":{"f":"채무자가 저당권이 설정되어 있는 자신의 유일한 재산을 양도한 경우, 저당권의 피담보채권액이 그 재산의 가액을 초과하면 당해 재산의 양도는 사해행위에 해당하지 않는다.","w":"피담보채권액이 가액을 넘으면 일반채권자의 공동담보에 남는 책임재산이 없어 사해행위가 되지 않는다.","c":"상","v":1},"변리사2018_55-26-5":{"f":"채권자가 채무자와 수익자 사이의 부동산매매계약을 사해행위로 취소함에 따라 수익자 명의의 소유권이전등기가 말소되어 채무자의 등기명의가 회복된 경우, 채무자가 그 부동산을 제3자에게 처분하더라도 이는 무권리자의 처분으로서 효력이 없다.","w":"취소의 효력은 상대적이어서 채무자는 소유권을 취득하지 못하고, 처분해도 무권리자의 처분이다.","c":"중","v":1},"변리사2021_58-32-5":{"f":"乙의 채권자 戊가 2020. 12. 3. 乙 소유의 X부동산을 가압류한 상태에서, 2021. 1. 15. 乙로부터 X부동산을 양도받은 丙이 乙의 戊에 대한 가압류채무를 변제한 경우, X부동산의 양도계약이 사해행위로 취소되면 丙은 특별한 사정이 없는 한 甲에게 가액반환을 하여야 하고, 위 변제액은 공제하지 않는다.","w":"가압류채권자에게는 우선변제권이 없어 가압류된 부동산도 전부가 일반채권자의 공동담보가 된다. 수익자가 가압류채무를 변제했더라도 반환할 가액에서 그 변제액을 빼지 않는다(판례).","c":"중","v":1},"변리사2023_60-26-1":{"f":"채권자는 피보전채권의 변제기 전이라도 채권자대위권을 행사해서 피대위채권의 시효중단을 위한 이행청구를 할 수 있다.","w":"시효중단은 보존행위이므로 변제기 전에도 대위로 이행청구할 수 있다(민법 제404조 제2항 단서).","c":"상","v":1},"변리사2023_60-26-2":{"f":"임대인의 동의없는 임차권의 양도는 당사자 사이에서는 유효하더라도 임차권의 양수인은 임대인의 권한을 대위 행사할 수 없다.","w":"동의 없는 임차권 양도는 임대인에게 대항할 수 없으므로, 양수인은 임대인의 권한(제3자에 대한 방해배제청구 등)을 대위행사할 수 없다(판례).","c":"상","v":1},"변리사2023_60-26-4":{"f":"채권자가 채무자의 토지 소유권이전등기청구권을 대위행사한 후 이를 채무자에게 통지한 경우, 채무자가 그 토지 소유권을 이전받는 것은 처분권제한에 위배되지 않아 유효하다.","w":"채무자가 등기를 이전받는 행위는 권리의 처분이 아니므로 대위 행사 통지 후에도 유효하다.","c":"중","v":1},"변리사2023_60-26-5":{"f":"제3채무자가 직접 대위채권자에게 금전을 지급하도록 하는 채권자대위소송의 판결이 확정된 경우, 대위채권자의 채권자는 대위채권자가 제3채무자로부터 지급받을 권리를 압류할 수 없다.","w":"판결이 확정되어도 피대위채권은 여전히 채무자에게 속하고, 대위채권자가 지급받을 권리는 독립한 재산이 아니어서 대위채권자의 채권자가 압류할 수 없다(판례).","c":"상","v":1},"변리사2023_60-27-5":{"f":"취소채권자는 수익자가 사해행위로 취득한 근저당권에 배당된 배당금을 가압류한 수익자의 채권자에 대하여 우선하여 배당을 받을 수 없다.","w":"사해행위취소로 취소채권자에게 우선변제권이 생기지 않으므로, 배당금을 가압류한 수익자의 채권자보다 우선하여 배당받을 수 없다(판례).","c":"중","v":1},"변리사2024_61-28-3":{"f":"취득시효의 대상인 부동산의 소유자가 취득시효 완성 후에 그 부동산을 처분하여 점유자의 시효취득을 원인으로 한 소유권이전등기청구권이 침해된 경우, 그 점유자는 소유권이전등기청구권의 보전을 위해 채권자취소권을 행사할 수 없다.","w":"채권자취소권은 금전채권을 보전하는 제도이고 특정물에 대한 이전등기청구권을 보전하기 위해서는 행사할 수 없다.","c":"상","v":1},"변리사2026_63-28-5":{"f":"비법인사단이 총유재산에 관한 권리를 행사하지 않고 있어 비법인사단의 채권자가 그 권리를 대위행사하는 경우에는 사원총회의 결의를 거칠 필요가 없다.","w":"채권자가 대위로 행사하는 것이어서 사원총회 결의가 필요하지 않다.","c":"상","v":1},"변리사2026_63-29-3":{"f":"사해행위 이전에 성립한 채권이 사해행위 이후에 양도되었더라도 그 채권양수인은 채권자취소권을 행사할 수 있다.","w":"피보전채권이 사해행위 전에 성립했다면 이후에 양도되어도 양수인이 행사할 수 있다.","c":"상","v":1},"변리사2016_53-37-5":{"f":"건축주 사정으로 공사가 중단된 미완성의 건물을 인도받아 완공하였더라도, 그 건물이 공사 중단 시점에서 사회통념상 독립한 건물이라고 볼 수 있는 형태와 구조를 갖추고 있었다면 완공자가 그 건물의 소유권을 원시취득하지 못한다.","w":"이미 독립한 건물로서 형태를 갖춘 상태에서 인도받았다면 최초 건축주가 소유권을 취득한 것이고 완공자는 원시취득하지 못한다(대법원 판례).","c":"중","v":1},"변리사2016_53-38-1":{"f":"조합원 중에 변제할 자력이 없는 자가 있는 때에는 그 변제할 수 없는 부분은 다른 조합원이 균분하여 변제할 책임이 있다.","w":"조합원 중 무자력자의 부담 부분은 다른 조합원이 균분하여 변제한다(민법 제713조). 출자가액 비례가 아니다.","c":"상","v":1},"변리사2017_54-33-1":{"f":"乙의 차임채무불이행으로 임대차가 종료된 경우에는 乙은 甲에게 Y건물의 매수를 청구할 수 없다.","w":"임차인의 채무불이행으로 임대차가 해지된 경우에는 지상물매수청구권이 생기지 않는다.","c":"상","v":1},"변리사2017_54-33-2":{"f":"乙이 적법하게 Y건물의 매수를 청구한 경우, 甲의 대금지급의무는 乙의 Y건물 명도 및 소유권이전의무와 동시이행관계에 있다.","w":"매수청구 후 대금 지급과 건물 명도·이전등기는 동시에 이행한다.","c":"상","v":1},"변리사2017_54-33-3":{"f":"乙이 Y건물에 대한 보존등기를 마친 후 甲이 丙에게 X토지를 매도하고 소유권이전등기를 마쳐 준 경우, 乙의 임차권이 기간만료로 소멸하면 乙은 丙을 상대로 Y건물의 매수를 청구할 수 있다.","w":"乙이 지상건물을 등기했으므로 토지임대차는 제3자에 대하여 효력이 있고(민법 제622조), 임차권이 기간만료로 소멸하면 乙은 새 토지소유자 丙에게 건물 매수를 청구할 수 있다.","c":"상","v":1},"변리사2017_54-33-4":{"f":"만약 乙의 채권자 명의로 근저당권이 설정된 Y건물에 대하여 乙이 적법하게 매수청구권을 행사한 경우, 甲은 근저당권이 말소되지 않았음을 이유로 채권최고액에 상당한 대금의 지급을 거절할 수 있다.","w":"건물에 설정된 근저당권의 말소와 대금 지급은 동시이행 관계에 있어 근저당이 말소되지 않았다면 일부 지급을 거절할 수 있다.","c":"중","v":1},"변리사2018_55-34-2":{"f":"임차인의 차임연체를 이유로 임대차계약이 해지되어, 임대인이 임차목적물의 인도와 연체차임의 지급을 구하는 소송을 제기한 경우 그 소송비용은 특별한 합의가 없더라도 보증금에서 당연히 공제될 수 있다.","w":"보증금은 임대차 종료 후 목적물 인도 때까지 생긴 임차인의 채무를 모두 담보한다. 차임연체로 해지된 뒤 임대인이 인도와 연체차임을 구하는 소송을 낸 경우 그 소송비용도 보증금에서 당연히 공제된다(판례).","c":"중","v":1},"변리사2018_55-39-1":{"f":"매도인이 계약과 동시에 환매할 권리를 보류한 때에는 환매대금은 매도인이 영수한 대금 및 매수인이 부담한 매매비용으로 하되, 당사자가 특약으로 환매대금을 다르게 정할 수 있다.","w":"환매대금에 관한 특약은 허용된다(민법 제590조 제2항 단서).","c":"상","v":1},"변리사2019_56-37-3":{"f":"甲과 乙 사이의 임대차계약은 무단전대를 이유로 甲이 해지의 의사표시를 하여야 해지의 효력이 발생한다.","w":"무단전대를 이유로 한 해지는 임대인의 의사표시가 있어야 하고 당연히 해지되는 것은 아니다(민법 제629조 제2항).","c":"상","v":1},"변리사2019_56-37-5":{"f":"甲과 乙 사이의 임대차계약이 존속하는 한 甲은 X토지의 불법점유를 이유로 丙에게 차임상당의 부당이득반환을 청구할 수 없다.","w":"임대차가 존속하는 동안 임대인은 임차인에게서 차임을 받을 수 있어 전차인에게 부당이득반환을 청구할 수 없다.","c":"중","v":1},"변리사2019_56-39-1":{"f":"조합원은 언제든지 조합의 업무 및 재산상태를 검사할 수 있다.","w":"조합원은 정당한 사유가 없어도 업무와 재산 상태를 검사할 수 있다(민법 제710조).","c":"상","v":1},"변리사2019_56-39-3":{"f":"조합원의 제명은 정당한 사유가 있는 때에 한하여 다른 조합원의 일치로 결정된다.","w":"제명은 정당한 사유가 있고 다른 조합원의 일치가 있어야 한다(민법 제718조 제1항).","c":"상","v":1},"변리사2019_56-39-4":{"f":"조합의 채무자는 그 채무와 조합원에 대하여 개인적으로 가지는 채권과 상계할 수 없다.","w":"조합의 채권과 조합원 개인에 대한 채권은 당사자가 다르므로 상계할 수 없다(민법 제715조).","c":"상","v":1},"변리사2019_56-39-5":{"f":"조합원의 제명 결정은 제명된 조합원에게 통지하지 아니하면 그 조합원에게 대항하지 못한다.","w":"제명 결정은 제명된 조합원에게 통지해야 그에게 대항할 수 있다(민법 제718조 제2항).","c":"상","v":1},"변리사2021_58-39-1":{"f":"어느 조합원이 출자의무를 이행하지 않은 경우, 다른 조합원은 이를 이유로 조합계약을 해제할 수 없다.","w":"조합계약에는 해제가 적용되지 않고 탈퇴·제명·해산청구로 해결한다.","c":"상","v":1},"변리사2021_58-39-3":{"f":"부동산의 공동매수인들이 전매차익을 얻으려는 목적으로만 상호 협력하는 경우에는 민법상 조합관계에 있다고 볼 수 없다.","w":"공동사업 경영이 없이 각자 이익을 얻을 목적으로 협력하는 관계는 조합이 아니다.","c":"중","v":1},"변리사2021_58-39-4":{"f":"조합원의 채권자는 조합재산을 구성하는 개개의 재산에 대한 조합원의 합유지분에 대하여 강제집행을 할 수 없다.","w":"합유지분은 처분이 제한되므로 개별 재산에 대한 합유지분을 압류할 수 없다.","c":"상","v":1},"변리사2021_58-39-5":{"f":"조합원이 조합을 탈퇴할 권리는 그 성질상 채권자대위가 허용되지 않는 일신전속적 권리에 해당하지 않는다.","w":"조합 탈퇴권은 재산적 성질이 있어 채권자대위의 대상이 될 수 있다.","c":"상","v":1},"변리사2021_58-40-1":{"f":"수량지정매매에 해당하는 부동산매매계약에서 실제면적이 계약면적에 미달하는 경우, 매수인은 대금감액청구권의 행사와 별도로 부당이득반환청구를 할 수 없다.","w":"면적 부족은 담보책임으로 대금감액을 청구하는 것이어서 부당이득반환을 따로 청구할 수 없다.","c":"중","v":1},"변리사2023_60-38-1":{"f":"조합재산을 구성하는 개개의 재산에 대한 합유지분을 압류 기타 강제집행의 대상으로 삼을 수 없다.","w":"합유지분은 조합 전체의 동의 없이 처분할 수 없어 강제집행의 대상이 되지 않는다.","c":"상","v":1},"변리사2023_60-38-2":{"f":"2인으로 구성된 조합에서 1인이 탈퇴하여 조합관계가 종료되는 경우, 특별한 사정이 없는 한 해산이나 청산을 거치지 않고 조합재산은 남은 조합원의 단독소유에 속하게 된다.","w":"2인 조합에서 1인이 탈퇴하면 조합관계가 소멸하고, 재산은 남은 조합원의 단독소유가 된다.","c":"상","v":1},"변리사2023_60-38-3":{"f":"2인으로 구성된 조합에서 1인이 존속기한을 정하지 않고 부동산 사용권을 출자하였다가 탈퇴한 경우, 특별한 사정이 없는 한 탈퇴 시 남은 조합원의 부동산 사용권은 소멸하지 않는다.","w":"출자한 부동산 사용권은 탈퇴로 소멸하지 않고 남은 조합원이 계속 사용할 수 있다.","c":"중","v":1},"변리사2023_60-38-4":{"f":"공동이행방식의 건설공동수급체의 구성원인 조합원이 그 출자의무를 불이행하더라도, 특별한 사정이 없는 한 출자의무의 불이행을 이유로 이익분배 자체를 거부할 수 없다.","w":"출자의무를 이행하지 않은 구성원에게도 이익분배 자체를 거부할 수는 없고, 분배할 이익금에서 미출자금이나 그 손해배상액을 공제할 수 있을 뿐이다(판례).","c":"상","v":1},"변리사2024_61-35-1":{"f":"부담부 증여에서 상대방의 부담의무 불이행을 이유로 한 증여자의 계약해제는 이미 이행한 부분에 대하여도 효력이 미친다.","w":"부담 불이행을 이유로 부담부 증여를 해제하는 경우에는 이미 이행한 부분에 영향이 없다는 민법 제558조가 적용되지 않으므로, 이행한 부분까지 원상회복을 청구할 수 있다(판례).","c":"상","v":1},"변리사2024_61-37-5":{"f":"수임인이 위임인의 지명에 의하여 복수임인을 선임한 경우, 수임인은 부적임 또는 불성실함을 알고 위임인에 대한 통지나 그 해임을 게을리한 때에 한하여 책임을 진다.","w":"위임인이 지명한 복수임인에 관해서는 선임·감독 책임이 없고, 부적임·불성실을 알고도 통지나 해임을 게을리한 경우에만 책임이 있다(민법 제682조 제2항, 제121조 제2항).","c":"상","v":1},"변리사2026_63-37-2":{"f":"甲이 乙의 사용수익권을 보장하기 위하여 X건물을 수선한 경우, 그 수선기간 동안 乙의 사용수익에 지장이 생겼다면 乙은 그 지장의 한도에서 차임의 지급을 거절할 수 있다.","w":"임대인의 수선 때문에 사용수익이 방해된 범위에서는 차임 지급을 거절할 수 있다.","c":"중","v":1},"변리사2026_63-37-3":{"f":"임대차계약의 체결 당시에 乙이 필요비상환청구권을 미리 포기하기로 약정한 경우, 특별한 사정이 없는 한 이러한 약정은 유효하다.","w":"필요비상환청구권을 정한 민법 제626조는 강행규정(제652조)에 들어 있지 않으므로 이를 미리 포기하는 약정은 유효하다.","c":"상","v":1},"변리사2026_63-37-5":{"f":"甲이 丁에게 X건물을 양도하고 소유권등기를 이전한 후 X건물의 임대차가 종료되어 丁이 乙에게 임대차보증금을 반환하여야 하는 경우, 丁이 甲의 지위를 승계하기 전까지 발생한 연체차임은 채권양도의 요건을 갖추지 않아도 임대차보증금에서 당연히 공제된다.","w":"양수인이 임대인 지위를 승계하면 양도 전 연체차임도 보증금에서 공제된다. 임차인의 차임 연체는 임대차 종료 때 보증금에서 당연히 공제되기 때문이다.","c":"상","v":1},"변리사2026_63-38-1":{"f":"乙이 직접 X건물을 건축하지 않고 이행대행자로서 丙을 사용하였더라도 특별한 사정이 없는 한 乙은 도급계약을 불이행한 것으로 볼 수 없다.","w":"수급인은 일의 완성에 책임을 지고, 특별한 사정이 없으면 이행보조자를 쓸 수 있다.","c":"상","v":1},"변리사2016_53-39-1":{"f":"사무관리의 성립요건인 ‘타인을 위하여 사무를 처리하려는 의사’는 관리자 자신의 이익을 도모하려는 의사와 병존할 수 있다.","w":"타인을 위한 의사가 인정되면 자신을 위한 의사와 함께 있어도 사무관리가 성립한다.","c":"상","v":1},"변리사2016_53-39-3":{"f":"사무관리자가 본인의 의사에 반하여 사무를 관리한 때에는 본인의 현존이익의 한도에서 비용의 상환을 청구할 수 있다.","w":"본인의 의사에 반한 사무관리는 본인의 현존이익 한도에서 비용상환을 청구할 수 있다(민법 제739조 제3항).","c":"상","v":1},"변리사2016_53-39-4":{"f":"사무관리자는 본인에 대하여 비용의 상환을 청구할 수 있을 뿐, 사무관리에 의하여 결과적으로 사실상 이익을 얻은 다른 제3자에 대하여 직접 부당이득반환을 청구할 수는 없다.","w":"상환 청구는 본인에게만 할 수 있고, 제3자에게 직접 부당이득반환을 청구할 수 없다.","c":"중","v":1},"변리사2016_53-39-5":{"f":"사무관리 관계의 종료를 위해 본인이 명시적으로 관리자에게 그 목적인 사무를 스스로 직접 관리하겠다는 의사표시를 하여야 하는 것은 아니다.","w":"관리자는 본인이 그 사무를 관리하는 때까지 관리를 계속해야 하고(민법 제737조), 본인의 명시적 의사표시가 사무관리 종료의 요건은 아니다(대법원 판례).","c":"중","v":1},"변리사2016_53-40-2":{"f":"고의의 불법행위를 원인으로 한 부당이득반환채권을 수동채권으로 하는 상계는 허용되지 않는다.","w":"고의 불법행위로 인한 채권을 수동채권으로 하는 상계는 금지된다(민법 제496조).","c":"중","v":1},"변리사2017_54-37-1":{"f":"사무처리의 긴급성 등으로 국가의 사무에 대하여 사인의 개입이 정당화되는 경우, 사인은 국가의 사무를 처리하면서 지출한 필요비뿐 아니라 유익비의 상환도 청구할 수 있다.","w":"사무관리의 비용상환 대상에는 유익비도 포함된다.","c":"중","v":1},"변리사2018_55-35-4":{"f":"甲이 乙에게 부동산을 매도하고 목적물을 인도하지 않은 상태에서 乙로부터 중도금까지 받았으나 매매계약이 처음부터 무효였다면, 甲이 선의라면 받은 날로부터 이자를 가산하지 않고 받은 금전을 반환하면 된다.","w":"받은 이익에 이자를 붙여 반환하는 것은 악의의 수익자다(민법 제748조 제2항). 선의의 수익자는 받은 이익이 현존하는 한도에서 반환하고(같은 조 제1항) 받은 날부터의 이자를 붙일 의무가 없다.","c":"중","v":1},"변리사2023_60-39-3":{"f":"과세관청이 3자간 등기명의신탁에 따라 해당 부동산의 공부상 소유자가 된 명의수탁자에게 재산세 부과처분을 하여 명의수탁자가 재산세를 납부한 경우, 그는 명의신탁자나 그 상속인을 상대로 재산세 상당액에 대한 부당이득반환청구를 할 수 없다.","w":"명의수탁자에게 재산세가 부과·납부되었다고 해서 명의신탁자가 재산세 납부의무를 면하는 이익을 얻은 것이 아니므로 부당이득반환을 청구할 수 없다(판례).","c":"상","v":1},"변리사2024_61-38-1":{"f":"관리자가 사무의 적절한 관리를 함에 있어 과실없이 손해를 받은 때에는 본인의 현존이익의 한도에서 그 손해의 보상을 청구할 수 있다.","w":"손해 전액이 아니라 본인의 현존이익 한도이다(민법 제740조).","c":"상","v":1},"변리사2024_61-38-2":{"f":"관리자가 본인을 위하여 본인의 의사에 부합하게 사무를 관리하면서 유익비를 지출한 경우, 지출한 유익비 전부의 상환을 청구할 수 있다.","w":"본인의 의사에 반하지 않는 관리라면 지출한 유익비 전부의 상환을 청구할 수 있다(민법 제739조 제1항). 현존이익 한도로 줄어드는 것은 본인의 의사에 반하여 관리한 경우이다(같은 조 제3항).","c":"상","v":1},"변리사2024_61-38-3":{"f":"상대방과의 약정에 따라 제3자의 사무를 관리한 경우, 그 관리자와 제3자 사이에서는 원칙적으로 사무관리가 성립하지 않는다.","w":"계약상 의무에 따른 관리는 사무관리가 아니라 그 계약 관계로 처리한다.","c":"상","v":1},"변리사2024_61-38-4":{"f":"관리자에게 타인을 위해 사무를 처리하는 의사와 관리자 자신의 이익을 위한 의사가 모두 있는 경우에도 사무관리가 성립할 수 있다.","w":"두 의사가 병존해도 사무관리가 성립한다.","c":"상","v":1},"변리사2026_63-39-3":{"f":"채권자가 채무자에게 지급되어야 할 대상(代償)청구의 대상이 되는 보상금을 어떤 사유로 직접 자신의 명의로 지급받았더라도 채무자에 대한 관계에서 바로 부당이득이 되는 것은 아니다.","w":"채권자는 대상청구권에 따라 그 보상금을 넘겨받을 권리가 있으므로, 직접 자기 명의로 받았다는 사정만으로 채무자에 대한 부당이득이 되지 않는다(판례).","c":"중","v":1},"변리사2017_54-38-2":{"f":"","w":"과실상계 후 손해액은 5천만원 × 70% = 3천 5백만원이고 甲과 乙은 이를 부진정연대로 부담한다. 판례는 부진정연대채무자 1인이 한 상계도 채권자가 만족을 얻은 것이므로 다른 채무자에게 효력이 있다고 본다. 甲이 2천만원을 상계하면 乙의 채무도 그만큼 줄어 1천 5백만원이 남는다. 4백 5십만원이 아니다.","c":"상","v":1},"변리사2018_55-36-5":{"f":"피용자와 제3자와의 공동불법행위로 인해 손해를 입은 피해자에게 사용자가 채권을 가지고 있으나 사용자가 상계할 수 있음에도 상계하지 않는 경우, 제3자는 사용자의 채권을 가지고 피해자에게 상계할 수 없다.","w":"사용자와 제3자가 피해자에게 지는 채무는 부진정연대채무여서, 다른 채무자의 반대채권으로 그 부담부분만큼 상계할 수 있다는 민법 제418조 제2항이 적용되지 않는다(판례).","c":"중","v":1},"변리사2019_56-40-5":{"f":"공동불법행위자 중 1인인 甲의 손해배상채무가 시효로 소멸한 후에도, 다른 공동불법행위자 乙이 피해자에게 자기의 부담부분을 넘는 손해를 배상하였다면 乙은 甲에게 구상권을 행사할 수 있다.","w":"구상권은 변제로 새로 생기는 별개의 채권이어서 피해자에 대한 채무가 시효로 소멸했더라도 구상할 수 있다.","c":"중","v":1},"변리사2023_60-40-1":{"f":"공동불법행위자들 중에 고의로 불법행위를 행한 자가 있는 경우에도, 과실에 그친 공동불법행위자는 과실상계를 주장할 수 있다.","w":"과실상계는 각 공동불법행위자에 대해 따로 판단한다. 고의의 불법행위자는 과실상계를 주장할 수 없다.","c":"중","v":1},"변리사2024_61-39-1":{"f":"공동불법행위자 甲과 乙중 甲의 손해배상채무가 시효로 소멸한 후에 乙이 피해자에게 자기의 부담 부분을 넘는 손해를 배상한 경우, 乙은 甲을 상대로 구상권을 행사할 수 있다.","w":"구상권은 변제 시 새로 발생하는 권리로, 甲의 채무가 소멸시효로 소멸했어도 행사할 수 있다.","c":"중","v":1},"변리사2024_61-39-2":{"f":"자신의 과실에 의해 초래된 급박한 위난을 피하기 위해 부득이 타인에게 손해를 가한 자는 그 손해에 대한 배상책임을 진다.","w":"위난이 가해자 자신의 과실로 생긴 경우에는 긴급피난(민법 제761조 제2항)으로 책임을 면하지 못하고 손해를 배상해야 한다.","c":"상","v":1},"변리사2024_61-39-4":{"f":"피용자와 제3자가 공동불법행위에 따른 손해배상채무를 부담하는 경우, 사용자가 피용자와 제3자의 책임비율에 의해 정해진 부담부분을 초과하여 피해자에게 배상하면 제3자에 대하여 구상권을 행사할 수 있다.","w":"사용자도 피용자의 부담부분을 넘어 배상한 경우 제3자에게 구상할 수 있다.","c":"상","v":1},"변리사2024_61-39-5":{"f":"불법행위로 인하여 건물이 훼손되어 사용 및 수리가 불가능한 경우, 손해배상액의 기준이 되는 건물의 시가에는 원칙적으로 건물의 철거비용이 포함되지 않는다.","w":"사용·수리가 불가능할 정도로 훼손된 건물의 손해액은 그 건물의 시가 상당액이고, 이 시가에 철거비용은 원칙적으로 포함되지 않는다(판례).","c":"중","v":1},"변리사2026_63-40-1":{"f":"피용자의 고의에 의한 불법행위로 인하여 사용자가 사용자책임을 부담하는 경우, 사용자책임의 범위를 정함에 있어서 피해자의 과실을 고려하여 그 책임을 제한할 수 있다.","w":"피용자가 고의로 불법행위를 해도 사용자책임에서는 피해자의 과실을 참작할 수 있다.","c":"상","v":1},"변리사2016_53-18-5":{"f":"","w":"丙이 경매로 A토지 소유권을 취득할 때 B건물 소유자 乙이 법정지상권을 얻는다(제366조). 법률 규정에 따른 취득이라 등기가 없어도 되지만 이를 처분하려면 등기를 해야 한다(제187조 단서). 판례는 법정지상권이 있는 건물을 매수한 사람은 건물 이전등기만으로 법정지상권을 취득하지 못하고 지상권 이전등기를 마쳐야 한다고 본다. 丁은 乙에게 지상권 이전등기를 청구할 수 있을 뿐이다.","c":"상","v":1},"변리사2016_53-20-1":{"f":"채권발생 후에 공장을 점유한 甲도 공장에 대한 유치권을 주장할 수 있다.","w":"유치권은 채권이 그 물건에 관하여 생긴 것이면 되고, 채권이 생길 때부터 물건을 점유하고 있어야 하는 것은 아니다. 채권이 생긴 뒤에 점유를 얻어도 유치권이 성립한다(판례).","c":"상","v":1},"변리사2016_53-21-1":{"f":"甲은 乙의 동의 없이도 질권의 목적인 채권을 양도할 수 있다.","w":"질권설정자에게 금지되는 것은 질권의 목적된 권리를 소멸하게 하거나 질권자의 이익을 해하는 변경이다(민법 제352조). 입질채권은 질권자 동의 없이 양도할 수 있고, 질권은 양도된 채권 위에 그대로 남는다.","c":"중","v":1},"변리사2018_55-19-1":{"f":"甲이 丙에게 한 처분행위는 가등기가 있더라도 유효하다.","w":"가등기에는 처분을 막는 효력이 없어 가등기 뒤에 소유자가 한 처분행위도 유효하다. 乙이 본등기를 하면 순위가 가등기 때로 올라가 그 뒤의 丙 명의 등기가 직권말소될 뿐이다(부동산등기법 제91조, 제92조).","c":"상","v":1},"변리사2019_56-21-1":{"f":"","w":"丙의 임차권은 경매로 소멸하는 선순위 권리보다 늦게 대항력을 갖춰 매각으로 소멸한다. 그래서 매수인 A는 임대인의 지위를 승계하지 않는다. 임대인 지위 승계(주택임대차보호법 제3조 제4항)는 매수인에게 대항할 수 있는 임차인에게만 적용된다.","c":"중","v":1},"변리사2019_56-21-2":{"f":"","w":"가압류등기 뒤에 저당권이 설정되었다면 저당권자는 가압류채권자보다 먼저 배당받지 못하고, 두 사람은 채권액에 비례해 평등하게 배당받는다(판례). 사례의 등기 순서는 데이터에 없어 丁의 가압류가 먼저인 것으로 보았다.","c":"중","v":1},"변리사2019_56-29-1":{"f":"","w":"피보전채권은 그 발생원인을 가리지 않으므로, 채권자 甲이 증명할 것은 A채권의 존재이고 발생원인을 따로 증명할 책임까지 지는 것은 아니라는 취지로 보인다. 이 결론을 뒷받침하는 판례는 확인하지 못했다.","c":"하","v":1},"변리사2019_56-37-1":{"f":"甲은 丙에게 X토지의 반환을 청구할 수 있다.","w":"무단전차인 丙은 임대인 甲에게 대항할 점유권원이 없으므로, 甲은 소유권에 기해 丙에게 토지 반환을 청구할 수 있다. 임대차가 존속하는 동안에는 임차인 乙에게 반환하라고 청구하는 형태가 된다.","c":"중","v":1},"변리사2019_56-37-2":{"f":"甲은 乙에 대한 임대차계약상의 차임청구권을 상실하지 않는다.","w":"무단전대가 있어도 甲이 해지하기 전까지 甲과 乙의 임대차는 유지되므로, 甲은 乙에게 계속 차임을 청구할 수 있다(민법 제629조 제2항은 해지권을 줄 뿐이다).","c":"상","v":1},"변리사2021_58-18-5":{"f":"2021. 2. 27. 현재 丁은 戊에 대하여 Y건물의 철거를 청구할 수 없다.","w":"법정지상권이 붙은 건물을 산 戊는 지상권 등기가 없어도 丙을 대위해 지상권설정등기를 청구할 수 있는 지위에 있다. 그래서 토지소유자 丁이 戊에게 건물 철거를 청구하는 것은 신의칙에 반해 허용되지 않는다(대법원 1985. 4. 9. 선고 84다카1131 전원합의체 판결).","c":"상","v":1},"변리사2026_63-37-1":{"f":"甲은 특별한 사정이 없는 한, 乙의 안전을 배려할 보호의무를 부담하지 않는다.","w":"통상의 임대차에서 임대인은 목적물을 사용·수익하게 할 의무를 질 뿐, 임차인의 안전을 배려하거나 도난을 막아 줄 보호의무까지 지지 않는다(판례). 숙박계약처럼 일시 사용을 위한 임대차와는 다르다.","c":"상","v":1},"변리사2016_53-02-5":{"f":"한정후견인의 동의가 있어야 하는 법률행위에 있어서 동의가 없으면 피한정후견인의 이익이 침해될 염려가 있음에도 동의하지 않는 경우, 피한정후견인이 동의 없이 법률행위를 하였다면 한정후견인은 이를 취소할 수 있다.","w":"한정후견인이 부당하게 동의하지 않을 때 피한정후견인은 가정법원에 동의를 갈음하는 허가를 청구할 수 있을 뿐이다(민법 제13조 제3항). 동의도 허가도 없이 한 행위는 한정후견인이 취소할 수 있다(제13조 제4항).","c":"상","v":1},"변리사2016_53-03-1":{"f":"법인의 불법행위는 대표권이 없는 이사가 제3자에 대하여 행한 불법행위에 의해서는 성립하지 않는다.","w":"제35조의 「이사 기타 대표자」는 법인의 대표기관이다. 대표권 없는 이사는 여기에 들지 않아 그 행위로는 법인의 불법행위책임이 생기지 않는다(판례).","c":"상","v":1},"변리사2016_53-03-2":{"f":"법인의 불법행위는 법인을 실질적으로 운영하면서 법인을 사실상 대표하여 법인의 사무를 집행하는 자가 법인사무에 관하여 제3자에 대하여 행한 불법행위에 대해서도 성립한다.","w":"판례는 법인을 실질적으로 운영하며 사실상 대표하여 사무를 집행하는 사람도 제35조의 「이사 기타 대표자」에 포함시킨다. 그가 법인 사무에 관해 한 불법행위로도 법인이 배상책임을 진다.","c":"상","v":1},"변리사2016_53-03-3":{"f":"법인의 불법행위는 감사의 행위에 의해서는 성립하지 않는다.","w":"감사는 이사의 업무를 감독하는 내부 기관이고 법인을 대표하지 않는다. 제35조 책임은 대표기관의 행위에 대해서만 생긴다.","c":"중","v":1},"변리사2016_53-03-4":{"f":"법인의 불법행위는 대표기관이 법인의 목적범위 외의 행위로 인하여 타인에게 손해를 가한 때에는 인정되지 않는다.","w":"목적범위 밖의 행위로 손해를 입힌 경우 법인은 제35조 제1항의 책임을 지지 않는다. 대신 그 사항의 의결에 찬성하거나 의결을 집행한 사원·이사 기타 대표자가 연대하여 배상한다(민법 제35조 제2항).","c":"상","v":1},"변리사2016_53-07-4":{"f":"보통우편의 방법으로 의사표시를 통지한 경우에는 발송되었다는 사실만으로는 상당한 기간 내에 도달한 것으로 추정되지 않는다.","w":"판례는 내용증명우편이나 등기우편은 반송되지 않는 한 상당한 기간 내 도달을 추정하지만, 보통우편은 발송 사실만으로 도달을 추정하지 않는다. 도달 사실은 이를 주장하는 쪽이 증명해야 한다.","c":"상","v":1},"변리사2016_53-09-4":{"f":"무효인 계약의 성립에 기초하여 외견상 있는 것처럼 보이는 의무를 위반한 계약 당사자를 상대로 하여 채무불이행을 이유로 하는 손해배상을 청구할 수 없다.","w":"계약이 무효이면 처음부터 이행할 채무가 없으므로, 겉으로 의무를 어긴 것처럼 보여도 채무불이행이 되지 않는다. 판례도 이를 이유로 한 손해배상청구를 받아들이지 않는다.","c":"중","v":1},"변리사2016_53-13-5":{"f":"미성년자인 甲이 자신의 X건물을 친권자 乙에게 증여하고 소유권이전등기를 하여 준 경우, 그 증여행위가 이해상반행위라 하더라도 특별한 사정이 없는 한 乙의 이전등기는 적법한 것으로 추정된다.","w":"판례는 미성년자가 친권자에게 부동산을 증여한 이해상반행위라도 일단 친권자 앞으로 이전등기가 되었으면 특별대리인 선임 등 필요한 절차를 적법하게 거친 것으로 추정한다. 그 절차를 거치지 않았다는 사실은 등기의 무효를 주장하는 쪽이 증명해야 한다.","c":"상","v":1},"변리사2017_54-01-2":{"f":"미등기 무허가건물의 매수인은 그 소유권이전등기를 경료하지 않으면 건물의 소유권을 취득할 수 없고, 소유권에 준하는 관습상의 물권도 인정되지 않는다.","w":"판례는 미등기 무허가건물의 매수인에게 등기 없이 소유권에 준하는 관습상 물권이 생긴다고 보지 않는다. 그런 물권을 인정할 관습법이 없기 때문이다.","c":"상","v":1},"변리사2017_54-06-3":{"f":"상대방의 사기에 속아 신원보증서류에 서명날인한다는 착각에 빠진 상태로 연대 보증서면에 서명날인한 경우, 이러한 표시상의 착오에서는 착오를 이유로 연대보증계약을 취소할 수 있을 뿐 사기를 이유로 취소할 수는 없다.","w":"판례는 이 사안을 의사와 표시가 어긋난 표시상의 착오로 본다. 사기에 의한 의사표시는 의사와 표시가 일치하되 의사를 정하는 과정에 기망이 끼어든 경우이므로, 여기에는 착오 규정(민법 제109조)만 적용된다.","c":"상","v":1},"변리사2017_54-09-3":{"f":"무경험은 생활체험의 부족을 의미하는 것으로, 특정영역에 있어서의 경험부족이 아니라 거래일반에 대한 경험부족을 의미한다.","w":"제104조의 무경험은 거래 일반에 관한 생활체험의 부족을 말하고, 어느 특정 영역의 경험 부족을 뜻하지 않는다(판례).","c":"상","v":1},"변리사2017_54-10-1":{"f":"정지조건부 채권양도에 있어서 정지조건이 성취되었다는 사실은 채권양도의 효력을 주장하는 자가 증명해야 한다.","w":"정지조건부 법률행위는 조건이 성취되어야 효력이 생기므로(민법 제147조 제1항), 조건이 성취된 사실은 그 효력을 주장하는 쪽이 증명한다는 것이 판례다.","c":"상","v":1},"변리사2017_54-17-5":{"f":"공유물분할의 소에서 공유부동산의 특정한 일부씩을 각각의 공유자에게 귀속시 키는 것으로 현물분할하는 내용의 조정이 성립하였더라도, 그 조정이 성립한 때 물권변동의 효력이 발생하지 않는다.","w":"판례(대법원 2013. 11. 21. 선고 2011두1917 전원합의체 판결)는 현물분할 조정이 성립해도 곧바로 물권변동이 생기지 않고, 조정에 따라 지분이전등기를 마쳐야 분할된 부분의 소유권을 취득한다고 본다. 조정조서는 공유물분할 판결 같은 형성판결이 아니어서 제187조가 적용되지 않는다.","c":"상","v":1},"변리사2017_54-18-3":{"f":"소유권이전등기의 원인으로 주장된 계약서가 진정하지 않은 것으로 증명된 경우에는 등기가 적법한 것으로 추정되지 않는다.","w":"등기의 추정력은 반대 사실이 증명되면 깨진다. 판례는 등기원인으로 내세운 계약서가 위조되는 등 진정하지 않음이 증명되면 그 등기가 적법하다는 추정도 깨진다고 본다.","c":"상","v":1},"변리사2017_54-36-1":{"f":"乙이 출자를 지연한 때에는 연체이자를 지급하는 외에 손해도 배상하여야 한다.","w":"금전 출자를 지체한 조합원은 연체이자를 지급하는 외에 손해를 배상하여야 한다(민법 제705조). 乙은 1억원을 금전으로 출자하기로 했으므로 이 규정이 적용된다.","c":"상","v":1},"변리사2017_54-36-2":{"f":"乙의 채권자는 乙을 집행채무자로 하여 A식당의 채권에 대하여 강제집행을 할 수 없다.","w":"조합재산은 조합원 전원의 합유이므로 조합원 개인의 채권자는 그 조합원을 집행채무자로 하여 조합의 채권에 강제집행할 수 없다. 乙의 채권자는 乙의 지분을 압류해 장래의 이익배당과 지분반환청구권에 효력을 미치게 할 수 있을 뿐이다(민법 제714조).","c":"상","v":1},"변리사2017_54-36-3":{"f":"현물을 출자한 甲이 동업에서 탈퇴하게 되면, 甲의 지분은 금전으로 반환할 수 있다.","w":"탈퇴한 조합원의 지분은 출자의 종류와 상관없이 금전으로 반환할 수 있다(민법 제719조 제2항). 현물을 출자했다고 그 현물로만 돌려받는 것은 아니다.","c":"상","v":1},"변리사2017_54-36-4":{"f":"甲은 동업자로서의 지위를 유지한 채 전체 지분을 제3자에게 처분할 수 없다.","w":"합유자는 전원의 동의 없이 합유물에 대한 지분을 처분하지 못한다(민법 제273조 제1항). 판례도 조합원의 지분은 조합원 지위와 떼어 처분할 수 없다고 보므로, 조합원 지위를 그대로 가진 채 지분 전부만 넘길 수는 없다.","c":"중","v":1},"변리사2018_55-02-1":{"f":"법률행위가 무효임을 알고 당사자가 추인한 때에는 새로운 법률행위로 본다.","w":"무효임을 알고 추인하면 새로운 법률행위로 「본다」(민법 제139조 단서). 반대 증거로 뒤집을 수 있는 추정이 아니라 간주다.","c":"상","v":1},"변리사2018_55-02-3":{"f":"취소권은 법률행위를 추인할 수 있는 날로부터 3년 내에 행사하지 않으면 소멸한다.","w":"취소권은 추인할 수 있는 날부터 3년, 법률행위를 한 날부터 10년 안에 행사해야 하고(민법 제146조), 어느 한 기간이라도 지나면 소멸한다. 추인할 수 있는 날부터 5년이 지났다면 3년 기간이 이미 끝났다.","c":"상","v":1},"변리사2018_55-02-4":{"f":"폭리행위는 그 무효원인이 해소되지 않았다면 당사자의 추인이 있어도 유효로 될 수 없다.","w":"불공정한 법률행위(민법 제104조)는 절대적 무효다. 무효원인이 그대로 있는 한 당사자가 추인해도 유효가 되지 않는다(판례).","c":"상","v":1},"변리사2018_55-02-5":{"f":"미성년을 이유로 취소할 수 있다는 사실을 알고 법정대리인의 동의 없이 법률행위를 한 미성년자가 그 법률행위를 적법하게 취소한 경우, 미성년자는 그 행위로 받은 이익이 현존하는 한도에서 반환하면 된다.","w":"제한능력자는 취소된 행위로 받은 이익이 현존하는 한도에서만 상환한다(민법 제141조 단서). 이 특칙은 선의·악의를 묻지 않으므로 취소할 수 있음을 알았던 미성년자도 이자를 붙여 반환할 필요가 없다.","c":"상","v":1},"변리사2018_55-05-5":{"f":"법률행위가 반사회질서행위로 무효인지 여부는 그 법률행위가 이루어진 때를 기준으로 판단하여야 한다.","w":"반사회질서 여부는 법률행위가 이루어진 때를 기준으로 판단한다(판례). 효력이 발생한 때나 이행할 때가 기준이 아니다.","c":"상","v":1},"변리사2018_55-13-5":{"f":"민사집행법에 따른 경매를 통하여 부동산을 매수한 경우, 매수인은 매각대금을 다 낸 때에 소유권을 취득한다.","w":"경매의 매수인은 매각대금을 다 낸 때에 소유권을 취득한다(민사집행법 제135조). 법률 규정에 따른 물권변동이라 등기가 없어도 효력이 생기며(민법 제187조), 촉탁에 의한 이전등기는 그 뒤에 이루어진다.","c":"상","v":1},"변리사2018_55-18-1":{"f":"乙이 무자력이 아닌 경우에도 丙은 乙의 甲에 대한 이전등기청구권을 대위행사할 수 있다.","w":"丙이 보전하려는 권리는 乙에 대한 소유권이전등기청구권이라는 특정채권이다. 특정채권을 보전하기 위한 채권자대위권은 채무자의 무자력을 요건으로 하지 않는다.","c":"상","v":1},"변리사2018_55-18-2":{"f":"甲, 乙, 丙 전원의 합의가 없다면, 丙은 甲에게 직접 이전등기를 청구할 수 없다.","w":"판례는 최종 양수인이 최초 양도인에게 직접 이전등기를 청구하려면 관계 당사자 전원의 중간생략등기 합의가 있어야 한다고 본다. 합의가 없으면 丙은 乙의 이전등기청구권을 대위행사해야 한다.","c":"상","v":1},"변리사2018_55-18-3":{"f":"甲에서 직접 丙에게 이전등기하는 것에 관해 甲, 乙, 丙 전원의 합의가 있었으나, 甲과 乙 사이의 매매가 적법하게 합의해제된 경우, 甲은 丙의 이전등기청구를 거절할 수 있다.","w":"중간생략등기 합의가 있어도 甲·乙 사이와 乙·丙 사이의 매매계약은 각각 그대로 효력을 가진다. 판례는 甲과 乙의 매매가 적법하게 합의해제되면 甲이 그 해제를 들어 丙의 이전등기청구를 거절할 수 있다고 본다.","c":"중","v":1},"변리사2018_55-18-4":{"f":"甲에서 丙으로 직접 이전등기가 된 경우, 乙과 丙이 대금을 완제했다면 甲은 중간생략등기의 합의가 없다는 이유로 丙 명의의 등기의 말소를 청구할 수 없다.","w":"중간생략등기가 이미 마쳐졌고 그 등기가 실체관계에 부합하면 합의가 없었다는 이유만으로 무효를 주장할 수 없다는 것이 판례다. 乙과 丙이 대금을 모두 치렀다면 丙 명의 등기는 실체관계에 부합한다.","c":"상","v":1},"변리사2018_55-27-1":{"f":"乙이 Y노트북을 선택하고 그 의사를 甲에게 전달한 경우, 乙은 특별한 사정이 없는 한 甲의 동의 없이는 이를 철회할 수 없다.","w":"선택의 의사표시는 상대방의 동의가 없으면 철회하지 못한다(민법 제382조 제2항).","c":"상","v":1},"변리사2018_55-27-2":{"f":"乙은 Y노트북을 선택하면서 조건을 붙일 수 없다.","w":"선택은 상대방에 대한 일방적 의사표시로 채권의 목적을 확정하는 단독행위다. 조건을 붙이면 목적이 확정되지 않아 상대방의 지위가 불안해지므로 선택에는 조건을 붙이지 못한다고 본다.","c":"중","v":1},"변리사2018_55-27-3":{"f":"乙이 X노트북을 선택하면 채권의 목적물은 X노트북으로 확정된다.","w":"X의 이행불능은 선택권 없는 甲의 과실로 생겼으므로 채권의 목적이 남은 Y로 특정되지 않는다(민법 제385조 제2항). 선택권자 乙은 X를 고를 수 있고, 고르면 목적물은 X로 확정된다.","c":"상","v":1},"변리사2018_55-27-4":{"f":"乙은 X노트북을 선택하더라도 丙에게 X노트북의 반환을 청구할 수 없다.","w":"乙이 X를 선택해도 甲에 대한 채권을 가질 뿐이고, X의 소유권은 매매와 인도로 이미 丙에게 넘어갔다. 乙은 丙에게 반환을 청구할 권리가 없고, 甲에게 이행불능을 이유로 손해배상을 청구할 수 있다.","c":"상","v":1},"변리사2018_55-38-2":{"f":"甲의 채권자 丙이 甲 소유의 물건에 흠결이 있다는 것을 안 상태에서 담보권 실행을 위한 경매를 신청하였고 乙이 그 물건을 경락받은 경우, 乙은 그 물건에 흠결이 있음을 이유로 丙에게 손해배상을 청구할 수 있다.","w":"채권자가 물건이나 권리의 흠결을 알고 경매를 청구한 경우 경락인은 그 채권자에게 손해배상을 청구할 수 있다(민법 제578조 제3항). 이 규정은 담보권 실행을 위한 경매에도 적용된다.","c":"중","v":1},"변리사2019_56-07-1":{"f":"동기의 착오가 상대방에 의하여 제공되거나 유발된 경우에는 착오를 이유로 취소할 수 있다.","w":"판례는 동기의 착오가 상대방이 준 부정확한 정보 등으로 유발된 경우, 동기가 표시되지 않았더라도 그 착오가 중요부분에 관한 것이면 취소를 인정한다.","c":"상","v":1},"변리사2019_56-07-2":{"f":"법률행위 내용의 중요부분에 대한 착오를 판단할 때, 의사표시자의 경제적인 불이익 여부도 고려된다.","w":"판례는 착오로 표의자가 아무런 경제적 불이익을 입지 않았다면 법률행위 내용의 중요부분 착오가 아니라고 본다. 경제적 불이익이 있었는지는 중요부분을 판단하는 요소의 하나다.","c":"상","v":1},"변리사2019_56-07-4":{"f":"법률행위가 사기에 의한 것으로서 취소되는 경우, 그 법률행위가 동시에 불법행위를 구성하는 때에는 취소의 효과로 생기는 부당이득반환청구권과 불법행위로 인한 손해배상청구권은 경합하지만 중첩적으로 행사할 수는 없다.","w":"두 청구권은 경합하므로 어느 것이든 골라 행사할 수 있다. 다만 같은 손해를 두 번 메울 수는 없어 중첩적으로 행사하지 못한다(판례).","c":"상","v":1},"변리사2019_56-07-5":{"f":"제3자의 사기로 인하여 계약을 체결한 경우, 그 제3자에 대하여 불법행위로 인한 손해배상을 청구하기 위하여 먼저 그 계약을 취소할 필요는 없다.","w":"제3자의 사기는 계약과 별개로 불법행위가 된다. 판례는 피해자가 계약을 취소하지 않은 채 그 제3자에게 손해배상을 청구할 수 있다고 본다.","c":"상","v":1},"변리사2019_56-20-1":{"f":"甲은 전세권 존속 중에도 장래에 그 전세권이 소멸하는 경우에 전세금반환채권이 발생하는 것을 조건으로 그 장래의 조건부 채권을 양도할 수 있다.","w":"전세권과 떼어 전세금반환채권만 양도하는 것은 원칙적으로 허용되지 않는다. 다만 전세권이 존속하는 동안 장래 전세권이 소멸하면 생길 전세금반환채권을 조건부 채권으로 양도하는 것은 유효하다(판례).","c":"상","v":1},"변리사2019_56-20-2":{"f":"乙이 甲에게 전세금의 반환을 지체한 경우, 甲은 X주택의 전부가 아니라 A부분에 대하여만 경매를 청구할 수 있다.","w":"건물 일부에 대한 전세권자는 전세권의 목적이 된 부분만 경매를 청구할 수 있다. 그 부분이 구분·분할되지 않는 경우라도 나머지 부분까지 경매를 청구할 수는 없다는 것이 판례다.","c":"상","v":1},"변리사2019_56-20-3":{"f":"경매절차에서 X주택이 매각된 경우, 甲은 X주택의 전부에 대하여 후순위권리자보다 전세금을 우선 변제받을 수 있다.","w":"전세권자는 그 부동산 전부에 대하여 후순위권리자 기타 채권자보다 전세금을 우선변제받을 권리가 있다(민법 제303조 제1항). 건물 일부의 전세권자도 건물 전부의 매각대금에서 우선변제를 받는다.","c":"상","v":1},"변리사2019_56-20-4":{"f":"甲의 채권자 丙이 甲의 전세권에 저당권을 취득한 경우, 전세권의 존속기간이 만료되면 丙은 전세권 자체에 대하여 저당권을 실행할 수 없다.","w":"존속기간이 끝나면 전세권의 용익권능이 소멸하므로 전세권 자체에 저당권을 실행할 수 없다. 판례는 이때 저당권자가 전세금반환채권을 압류·추심하거나 전부명령을 받는 방법으로 물상대위를 해야 한다고 본다.","c":"상","v":1},"변리사2019_56-25-5":{"f":"A가 甲과의 매매계약을 원인으로 X토지의 소유권이전등기를 마친 후 甲의 대여금채무를 모두 변제한 경우, A는 丙에 대하여 乙을 대위할 수 없다.","w":"A는 채무자 甲의 X토지를 사들인 제3취득자이고, 제3취득자는 보증인에 대하여 채권자를 대위하지 못한다(민법 제482조 제2항 제2호).","c":"상","v":1},"변리사2019_56-27-4":{"f":"특별손해의 배상에서 채무자가 그 사정을 알았거나 알 수 있었는지의 여부는 계약체결 당시가 아니라 채무의 이행기를 기준으로 판단하여야 한다.","w":"채무자가 특별한 사정을 알았거나 알 수 있었는지(민법 제393조 제2항)는 계약 체결 때가 아니라 채무의 이행기를 기준으로 판단한다(판례).","c":"상","v":1},"변리사2019_56-28-3":{"f":"丙이 甲의 대여금채권에 양도금지특약이 있다는 사실을 알았더라도 그 후 乙이 승낙 하였다면, 채권양도는 다른 약정이 없는 한 승낙한 때부터 유효하게 된다.","w":"양도금지특약을 알고 한 채권양도는 무효지만 채무자가 나중에 승낙하면 유효로 된다. 판례는 이 경우 다른 약정이 없는 한 소급효가 없어 양도의 효력은 승낙한 때부터 생긴다고 본다.","c":"상","v":1},"변리사2019_56-36-3":{"f":"계약이 일부이행된 경우, 그 원상회복에 관하여도 의사가 일치되어야 계약의 묵시적 합의해제가 인정될 수 있다.","w":"판례는 계약이 일부 이행된 뒤 묵시적 합의해제를 인정하려면 이미 이행된 부분의 원상회복에 관하여도 당사자의 의사가 일치되어야 한다고 본다. 원상회복에 관한 의사가 맞지 않으면 합의해제가 성립하지 않는다.","c":"상","v":1},"변리사2021_58-14-1":{"f":"악의의 점유자가 점유물의 사용에 따른 이익을 반환하여야 하는 경우, 자신의 노력으로 점유물을 활용하여 얻은 초과이익은 반환하지 않아도 된다.","w":"판례는 반환할 사용이익을 손실자가 통상 얻었을 범위로 한정하고, 점유자가 자기 노력과 수완으로 올린 초과이익(운용이익)은 반환 대상에서 뺀다.","c":"중","v":1},"변리사2021_58-14-3":{"f":"악의의 점유자가 과실(果實)을 수취하지 못한 경우, 이에 대한 과실(過失)이 없다면 그 과실(果實)의 대가를 보상할 필요가 없다.","w":"악의의 점유자는 과실(過失)로 과실(果實)을 수취하지 못한 경우에 그 대가를 보상한다(민법 제201조 제2항). 과실(過失) 없이 수취하지 못한 과실(果實)은 보상하지 않는다.","c":"상","v":1},"변리사2021_58-14-4":{"f":"점유자가 점유물을 개량하기 위하여 유익비를 지출한 경우뿐 아니라 필요비를 지출한 경우에도 점유물을 반환할 때에 그 상환을 청구할 수 있다.","w":"점유자는 필요비든 유익비든 점유물을 반환할 때에 상환을 청구한다(민법 제203조 제1항·제2항). 필요비를 즉시 청구할 수 있는 것은 임차인이다(제626조 제1항).","c":"상","v":1},"변리사2021_58-14-5":{"f":"점유물이 점유자의 책임 있는 사유로 멸실된 때, 악의의 점유자라면 자주점유이든 타주점유이든 손해의 전부를 배상하여야 한다.","w":"악의의 점유자는 자주점유든 타주점유든 손해 전부를 배상한다(민법 제202조). 현존이익 한도로 책임이 줄어드는 것은 선의의 자주점유자뿐이다.","c":"상","v":1},"변리사2021_58-17-5":{"f":"취득시효완성 후 등기명의인이 바뀐 경우, 등기명의가 바뀐 시점으로부터 다시 취득시효기간이 경과하면 취득시효완성을 주장할 수 있다.","w":"판례(대법원 1994. 3. 22. 선고 93다46360 전원합의체 판결)는 시효완성 뒤 등기명의인이 바뀐 경우 바뀐 시점을 새 기산점으로 삼아 다시 시효기간이 지나면 새 명의인에게 취득시효완성을 주장할 수 있다고 본다.","c":"상","v":1},"변리사2021_58-29-1":{"f":"甲과 乙이 공유하는 부동산을 丙에게 공동으로 임대한 경우, 임대차 종료 시 甲과 乙은 丙에게 임대차보증금 전액을 반환할 불가분채무를 부담한다.","w":"공유자가 공유물을 공동으로 임대한 경우 보증금반환채무는 성질상 불가분채무다(판례). 甲과 乙은 지분비율로 나누지 않고 각자 보증금 전액을 반환할 의무를 진다.","c":"상","v":1},"변리사2021_58-30-4":{"f":"甲이 丙에게 공사대금채권 중 5,000만 원만 양도하고 乙에게 채권양도통지 후 乙이 甲에 대한 2,000만 원의 하자보수에 갈음하는 손해배상채권을 취득한 경우, 乙의 위 채권에 의한 상계는 각 분할된 채권액의 채권 총액에 대한 비율에 따를 필요가 없다.","w":"채권 일부가 양도되면 분할된 부분마다 독립한 채권이 된다. 판례는 채무자가 양도인과 양수인 중 누구의 채권이든 골라 상계할 수 있고, 분할된 채권액의 비율대로 나누어 상계해야 하는 것은 아니라고 본다.","c":"중","v":1},"변리사2021_58-33-2":{"f":"甲은 丙의 동의가 없더라도 乙의 채무불이행을 이유로 계약을 해제할 수 있다.","w":"요약자는 계약 당사자로서 해제권을 가지므로, 수익자의 동의 없이도 낙약자의 채무불이행을 이유로 계약을 해제할 수 있다는 것이 판례다. 제541조는 당사자가 합의로 수익자의 권리를 바꾸거나 없애는 것을 막을 뿐이다.","c":"상","v":1},"변리사2021_58-37-5":{"f":"丙이 甲에게 손해 전부를 배상하고 乙에 대한 구상권을 취득한 후 甲의 乙에 대한 손해배상채권이 시효로 소멸한 경우에도, 丙은 乙에게 구상권을 행사할 수 있다.","w":"공동불법행위자 사이의 구상권은 피해자의 손해배상채권과 다른 별개의 권리다. 판례는 피해자의 乙에 대한 손해배상채권이 시효로 소멸한 뒤에도 丙이 이미 취득한 구상권은 행사할 수 있다고 본다.","c":"상","v":1},"변리사2023_60-07-1":{"f":"행정기관에 진정서를 제출하여 상대방을 궁지에 빠뜨린 다음 이를 취하하는 조건으로 거액의 급부를 제공받기로 약정한 것은 반사회질서의 법률행위에 해당한다.","w":"판례는 진정서 취하를 조건으로 거액을 받기로 한 약정을 민법 제103조의 반사회질서 법률행위로 보아 무효라고 했다. 궁박·경솔·무경험을 요건으로 하는 제104조로 판단한 사안이 아니다.","c":"중","v":1},"변리사2023_60-07-2":{"f":"법률행위의 성립시에는 존재하지 않았던 급부간의 현저한 불균형이 그 이후 외부적 사정의 급격한 변화로 인하여 발생하였더라도 불공정한 법률행위는 인정되지 않는다.","w":"불공정한 법률행위인지는 법률행위가 성립한 때를 기준으로 판단한다. 성립 뒤 외부 사정이 바뀌어 생긴 불균형에는 제104조가 적용되지 않는다(판례).","c":"상","v":1},"변리사2023_60-07-3":{"f":"불공정한 법률행위의 성립요건으로 요구되는 무경험이란 해당 법률행위가 행해진 바로 그 영역에서의 경험 부족이 아니라 일반적인 생활체험의 부족을 의미한다.","w":"무경험은 특정 영역의 경험 부족이 아니라 거래 일반에 관한 생활체험의 부족이다(판례).","c":"상","v":1},"변리사2023_60-07-5":{"f":"불공정한 법률행위를 할 때 당사자간에 그 법률행위의 불공정성을 이유로 하여 법률행위의 효력을 다툴 수 없다는 합의가 함께 행해졌다면 그러한 합의도 무효이다.","w":"불공정한 법률행위의 효력을 다투지 않기로 한 부제소 합의도 그 법률행위와 마찬가지로 무효다(판례).","c":"상","v":1},"변리사2023_60-16-5":{"f":"「임야소유권 이전등기에 관한 특별조치법」 에 의한 소유권보존등기가 경료된 임야에 관하여 그 임야를 사정받은 사람이 따로 있는 것이 사후에 밝혀졌더라도, 그 등기는 실체적 권리관계에 부합하는 등기로 추정된다.","w":"특별조치법에 따른 소유권보존등기는 그 법이 정한 절차를 거친 등기이므로 실체관계에 부합하는 것으로 추정된다. 판례는 임야를 사정받은 사람이 따로 있다는 사실만으로는 이 추정이 깨지지 않고, 등기 말소를 구하는 쪽이 보증서·확인서가 허위라는 등의 사정을 증명해야 한다고 본다.","c":"중","v":1},"변리사2023_60-36-5":{"f":"매수인이 매매목적물을 대금지급 전에 인도받았더라도 대금지급의무와 소유권이전등기의무가 동시이행관계에 있다면 민법 제587조(과실의 귀속, 대금의 이자)에 의한 매매대금이자를 지급할 의무가 없다.","w":"판례는 매수인이 목적물을 먼저 인도받았더라도 대금지급의무와 매도인의 소유권이전등기의무가 동시이행관계에 있으면 제587조의 대금 이자를 지급할 의무가 없다고 본다.","c":"상","v":1},"변리사2024_61-18-1":{"f":"토지에 관하여 근저당권을 설정함과 아울러 그 토지의 담보가치가 저감하는 것을 막기 위해 채권자 앞으로 건물의 소유를 목적으로 하는 지상권이 설정된 경우, 피담보채권의 변제로 근저당권이 소멸하면 그 지상권도 소멸한다.","w":"이런 담보지상권은 근저당권에 딸린 권리여서, 피담보채권이 변제되어 근저당권이 소멸하면 지상권도 함께 소멸한다(판례).","c":"상","v":1},"변리사2024_61-27-1":{"f":"숙박업자가 숙박계약에 따른 의무를 다하지 못하여 투숙객이 사망한 경우, 숙박계약의 당사자가 아니면서 그 사고로 인하여 정신적 고통을 받은 그 투숙객의 근친자는 그 투숙객에 대한 숙박계약상의 채무불이행을 이유로 숙박업자에게 위자료를 청구할 수 없다.","w":"숙박업자의 보호의무는 계약 당사자인 투숙객에 대한 의무다. 판례는 계약 당사자가 아닌 근친자가 숙박계약상 채무불이행을 이유로 위자료를 청구할 수는 없다고 본다(불법행위를 이유로 한 청구는 별개다).","c":"상","v":1},"변리사2024_61-27-2":{"f":"채무불이행을 이유로 계약이 해제된 경우에 채권자는 이행이익의 배상 대신에 계약이 이행되리라고 믿고 지출한 비용을 채무불이행으로 인한 손해로 배상을 청구할 수 있으나, 그 지출비용은 이행이익의 범위를 초과하여 청구할 수 없다.","w":"이행이익 대신 지출비용의 배상을 청구할 수는 있지만, 그 배상액은 이행이익의 범위를 넘지 못한다(판례).","c":"상","v":1},"변리사2024_61-27-4":{"f":"채무자의 채무불이행으로 인한 손해배상액이 예정되어 있는 경우에 채무불이행으로 인한 손해의 발생 및 확대에 채권자에게도 과실이 있더라도 과실상계를 할 수 없다.","w":"손해배상액이 예정되어 있으면 채권자의 과실을 이유로 과실상계를 하지 않는다. 판례는 채권자의 과실을 예정액이 부당히 과다한지 판단해 감액할 때(민법 제398조 제2항) 참작할 뿐이라고 본다.","c":"상","v":1},"변리사2024_61-27-5":{"f":"위약금이 위약벌로 해석되기 위해서는 특별한 사정이 주장입증되어야 하며, 도급계약서에 계약보증금 외에 지체상금도 규정되어 있다는 사정만으로 계약보증금이 위약벌이 되지는 않는다.","w":"위약금은 손해배상액의 예정으로 추정되므로(민법 제398조 제4항) 위약벌로 보려면 특별한 사정을 주장·증명해야 한다. 판례는 계약보증금 외에 지체상금 규정이 따로 있다는 것만으로 계약보증금을 위약벌로 볼 수 없다고 한다.","c":"상","v":1},"변리사2026_63-04-1":{"f":"甲이 乙에게 대표자로서의 모든 권한을 포괄적으로 위임하여 乙이 포괄적 수임인으로서 A를 대표하여 행한 대행행위는 원칙적으로 A에 대하여 효력이 없다.","w":"비법인사단에는 법인격을 전제로 하지 않는 법인 규정이 유추된다. 이사는 특정한 행위만 남에게 대리시킬 수 있으므로(민법 제62조), 대표자가 모든 권한을 포괄적으로 위임해 수임인이 한 대행행위는 비법인사단에 효력이 없다는 것이 판례다.","c":"상","v":1},"변리사2026_63-04-2":{"f":"甲이 정관에 기재된 대표권에 관한 제한을 위반하여 거래행위를 한 경우, 그와 같은 대표권 제한 사실을 거래 상대방이 알았거나 알 수 있었다는 점에 관한 증명책임은 A에게 있다.","w":"판례는 비법인사단 대표자가 대표권 제한을 어기고 한 거래도 상대방이 그 제한을 알았거나 과실로 몰랐을 때에만 무효로 본다. 상대방의 악의·과실은 거래의 무효를 주장하는 비법인사단이 증명해야 한다.","c":"상","v":1},"변리사2026_63-04-3":{"f":"甲이 A의 대표자로서 타인 간의 금전채무를 보증하는 계약을 체결하면서 사원총회의 결의를 거치지 않았더라도 특별한 사정이 없는 한 그 보증계약은 무효가 아니다.","w":"판례(대법원 2007. 4. 19. 선고 2004다60072 전원합의체 판결)는 비법인사단이 타인의 채무를 보증하는 것은 총유물의 관리·처분이 아니라 단순한 채무 부담이라고 본다. 사원총회 결의를 거치지 않았어도 그 보증계약은 유효하다.","c":"상","v":1},"변리사2026_63-04-5":{"f":"A가 甲의 고의의 불법행위로 인해 손해를 입은 丁에 대해 민법 제35조의 손해배상책임을 지는 경우, 丁에게 과실이 있었다면 과실상계의 법리를 적용할 수 있다.","w":"대표자의 고의 불법행위로 비법인사단이 제35조 책임을 지는 경우에도 피해자 丁의 과실은 과실상계로 참작된다. 피해자의 부주의를 이용해 고의로 불법행위를 한 사람 본인은 과실상계를 주장하지 못하지만, 그 행위로 책임을 지는 단체는 주장할 수 있다는 것이 판례다.","c":"중","v":1},"변리사2016_53-01":{"w":"ㄱ O. 계약 성립의 기초가 되지 않은 사정이 후에 변경되어 일방이 계약 목적을 달성하지 못해 손해를 입어도, 특별한 사정이 없으면 사정변경을 이유로 한 해제는 인정되지 않는다.\nㄴ X. 채무액과 변제기가 특정된 회사 채무를 보증한 이사는 이사직 사임을 이유로 보증계약을 일방적으로 해지할 수 없다.\nㄷ O. 신의칙 위반과 권리남용은 강행규정 위반이므로 당사자의 주장이 없어도 법원이 직권으로 판단한다.\nㄹ X. 강행법규를 위반한 자가 스스로 그 약정의 무효를 주장해도 특별한 사정이 없으면 신의칙에 반하지 않는다.\n따라서 ㄱ, ㄷ인 ②.","c":"상","v":1},"변리사2017_54-02":{"w":"옳지 않은 것은 ㄱ, ㄴ이다.\nㄱ X. 실종선고를 청구할 수 있는 이해관계인은 실종선고로 직접 신분상·재산상 권리를 얻거나 의무를 면하는 사람이다. 배우자 乙과 아들 丁은 제1순위 상속인이라 해당하지만 제2순위 상속인인 어머니 丙은 이해관계인이 아니라는 것이 판례다.\nㄴ X. 실종자를 당사자로 한 판결이 확정된 뒤 실종선고로 사망간주 시점이 그 이전으로 소급하더라도 그 판결이 사망자를 상대로 한 무효의 판결이 되지는 않는다(대법원 1992. 7. 14. 선고 92다2455).\nㄷ O. 실종선고가 취소되기 전에는 생존 사실이 밝혀져도 실종선고의 효력이 그대로 있으므로 그에 따른 상속은 유효하다.\n정답 ③.","c":"중","v":1},"변리사2017_54-03":{"w":"ㄱ X. 비법인사단 대표자는 정관이나 총회 결의로 허용되지 않는 한 업무 전반을 포괄적으로 위임할 수 없고, 이 경우 수임인의 대행행위는 비법인사단에 효력이 없다.\nㄴ X. 비법인사단도 명예권의 주체가 되어 명예훼손에 대한 손해배상을 청구할 수 있다.\nㄷ O. 대표자의 행위가 직무에 관한 것이 아님을 피해자가 알았거나 중대한 과실로 알지 못한 때에는 제35조 책임을 물을 수 없다.\nㄹ O. 법령에 위배되는 행위여도 외관상 객관적으로 직무에 관한 행위이면 제35조 제1항 책임이 인정된다.\n정답 ④.","c":"중","v":1},"변리사2018_55-08":{"w":"ㄱ O. 채무액과 변제기가 특정된 회사 채무의 보증은 이사직 사임을 이유로 일방 해지할 수 없다.\nㄴ X. 소멸시효 완성 주장이 권리남용이어서 국가가 배상한 경우에도, 사건 은폐조작 등 원인행위를 적극 주도한 공무원에 대한 국가의 구상권 행사는 신의칙상 허용된다.\nㄷ O. 대표권 남용에서 상대방이 그 사정을 알았거나 알 수 있었던 경우 회사는 상대방의 악의 등을 증명해 효과를 부인할 수 있다(제107조 제1항 단서 유추).\nㄹ X. 상대방이 고지 대상 사실을 이미 알고 있으면 고지의무는 없다.\nㅁ O. 경험칙상 고지받았다면 거래하지 않았을 것이 명백한 사정은 신의칙상 고지할 의무가 있다.\n정답 ③.","c":"중","v":1},"변리사2019_56-01":{"w":"ㄱ O. 사정변경에 따른 해제는 계약준수 원칙의 예외이다.\nㄴ O. 사용자는 신의칙상 부수의무로 근로자의 건강을 해치지 않도록 필요한 조치를 해야 한다.\nㄷ O. 채권자가 제3자 부동산을 채무자에게 명의신탁하게 한 뒤 강제집행하는 것은 신의칙상 허용되지 않는다.\nㄹ O. 분양자는 인근 쓰레기 매립장 건설 예정 사실을 분양계약자에게 고지할 신의칙상 의무가 있다.\n모두 옳아 ⑤.","c":"상","v":1},"변리사2021_58-01":{"w":"ㄱ O. 채무자가 시효완성 전에 채권자의 권리행사를 현저히 곤란하게 하여 시효가 완성되었다면 시효 완성 주장은 권리남용이다.\nㄴ O. 권리남용은 당사자 주장이 없어도 법원이 직권으로 판단할 수 있다.\nㄷ O. 유치권을 고의로 작출해 최우선순위 담보권의 지위를 부당하게 이용하는 것은 신의칙에 반하는 유치권의 남용이다.\nㄹ X. 권리남용의 효과는 권리의 종류와 남용의 결과에 따라 달라서 모두 권리 박탈로 귀결되지는 않는다(행사 불허, 손해배상 등).\n정답 ④.","c":"상","v":1},"변리사2021_58-02":{"w":"ㄱ O. 정관에 이사 해임사유가 규정되어 있으면 중대한 의무위반 등 특별한 사정이 없는 한 그 밖의 사유로 해임할 수 없다(판례).\nㄴ X. 이사의 성명·주소는 등기사항이지만(제49조 제2항) 감사는 등기사항이 아니다.\nㄷ O. 법인과 이사의 이익이 상반되는 사항은 특별대리인이 법인을 대표한다(제64조).\nㄹ X. 이사의 대표권 제한은 정관에 기재해야 하고(제41조) 등기하지 않으면 선의·악의를 가리지 않고 제3자에게 대항하지 못한다(제60조).\n정답 ①.","c":"중","v":1},"변리사2023_60-01":{"w":"③이 옳다. 실종선고가 취소되면 실종선고를 직접 원인으로 재산을 취득한 자가 선의인 경우 받은 이익이 현존하는 한도에서 반환하면 된다(제29조 제2항).\n①은 사망 간주 시점이 실종기간 5년이 끝난 때(2020. 9. 15. 무렵)이지 선고 시점이 아니다(제28조). ②는 실종선고가 취소되기 전에는 생존이 증명되어도 선고의 효력이 그대로라 반환을 구할 수 없다. ④는 실종선고의 사망 간주는 실종자의 종래 주소를 중심으로 한 사법상 법률관계에만 미치고 선거권 같은 공법상 권리에는 영향이 없다. ⑤는 취소의 효력이 소급한다(다만 선고 후 취소 전에 선의로 한 행위는 효력이 있다).","c":"중","v":1},"변리사2024_61-02":{"w":"ㄱ X. 비법인사단 대표자가 대표자로서의 모든 권한을 포괄적으로 위임한 것은 허용되지 않고, 그 수임인의 대행행위는 원칙적으로 비법인사단에 효력이 없다.\nㄴ O. 실질적으로 대표자로 행위한 乙의 사무집행 중 불법행위에 대해 비법인사단은 제35조 책임을 진다.\nㄷ X. 사익을 도모한 행위여도 외관상 객관적으로 직무에 관한 행위이면 직무관련성이 인정된다(상대방이 악의 또는 중과실이면 예외).\nㄹ O. 대표 권한을 전부 위임하고 직무를 전혀 집행하지 않은 것은 그 자체로 이사의 선관주의의무 위반이다.\n정답 ③.","c":"중","v":1},"변리사2024_61-03":{"w":"ㄱ X. 의사무능력자의 법률행위는 무효이고, 무능력을 이유로 한 무효 주장이 신의칙에 반하지는 않는다.\nㄴ O. 의사무능력자는 선의·악의를 가리지 않고 받은 이익이 현존하는 한도에서 반환한다(제141조 단서 유추, 판례).\nㄷ O. 甲의 丙에 대한 부당이득반환채권 양도의무와 乙의 저당권등기 말소의무는 동시이행관계에 있다(판례).\n정답 ④.","c":"중","v":1},"변리사2026_63-01":{"w":"ㄱ O. 차임불증액 특약이 있어도 특약을 유지하는 것이 신의칙에 반할 정도의 사정변경이 있으면 임대인의 차임증액청구가 인정된다.\nㄴ O. 채무액과 변제기가 특정된 회사채무의 보증은 이사직 사임을 이유로 일방 해지할 수 없다.\nㄷ X. 임대차 체결 시 지상물 포기 약정은 지상물매수청구권(제643조, 제652조)에 반하는 약정으로 무효이므로, 임차인의 매수청구권 행사가 신의칙에 반하지 않는다.\n정답 ③.","c":"상","v":1},"변리사2023_60-04":{"w":"⑤가 종물 관계가 아니다. 주유소 부지 지하에 매설된 유류저장탱크는 토지에 부합된 것이지 독립한 물건인 종물이 아니다(판례).\n배와 노, 자물쇠와 열쇠, 주유소건물과 주유기, 횟집과 수족관은 종물이다(제100조).","c":"중","v":1},"변리사2017_54-05":{"w":"제103조에 해당하지 않는 것은 ㄱ, ㄷ, ㄹ이다.\nㄱ 강제집행 면탈 목적의 허위 근저당권은 통정허위표시(제108조)로 무효이고 제103조 위반은 아니다.\nㄴ 과도하게 무거운 위약벌은 제103조에 반해 무효이다(해당).\nㄷ 뇌물을 소극적으로 은닉하기 위한 임치 약정은 반사회적이지 않다.\nㄹ 해외연수 후 일정 기간 근무 약정은 유효하다.\nㅁ 공무원의 직무에 관한 청탁의 대가로 금전을 지급하는 약정은 반사회적이다(해당).\n정답 ②.","c":"중","v":1},"변리사2018_55-06":{"w":"ㄱ O. 대리인 乙이 상대방 丙을 기망하면 丙은 사기를 이유로 취소할 수 있다.\nㄴ O. 의사표시의 하자 유무는 대리인을 기준으로 정하지만(제116조 제1항), 취소권은 법률행위의 효과가 귀속되는 본인 甲에게 있다.\nㄷ O. 대리인에게 취소권을 포함한 포괄적 대리권이 수여되어 있으므로 乙도 취소할 수 있다(제140조).\n정답 ⑤.","c":"중","v":1},"변리사2024_61-05":{"w":"ㄱ O. 이중매매에서 배임행위에 적극 가담한 제2매수인과의 매매는 제103조 위반으로 절대적 무효이다.\nㄴ X. 제1매수인 乙은 매도인 甲을 대위하여 말소를 청구할 수 있을 뿐, 직접 丙에게 말소를 청구할 수 없다.\nㄷ X. 특정물 인도·이전등기청구권 보전을 위한 채권자취소권은 인정되지 않는다.\nㄹ X. 제103조 위반 무효는 선의의 제3자에게도 주장할 수 있어 丁은 매매계약의 유효를 주장할 수 없다.\n정답 ①.","c":"상","v":1},"변리사2026_63-07":{"w":"ㄱ O. 복대리인은 대리인이 자기 이름으로 선임한 본인의 대리인이다.\nㄴ O. 법정대리인이 부득이한 사유로 복대리인을 선임하면 본인에 대해 선임감독 책임만 진다(제122조).\nㄷ O. 임의대리인이 복대리인을 선임하면 본인에 대해 선임감독 책임이 있다(제121조 제1항).\nㄹ O. 복임권 없는 대리인이 선임한 복대리인의 권한도 권한을 넘은 표현대리(제126조)의 기본대리권이 될 수 있다는 판례이다.\n모두 옳아 ⑤.","c":"중","v":1},"변리사2026_63-10":{"w":"②가 해당하지 않는다. 법정추인(제145조)은 취소권자가 이행하거나 이행을 청구하는 등 취소권자 쪽의 행위이며, 취소권자에 대한 상대방의 이행 청구는 사유가 아니다.\n①은 전부나 일부의 이행, ③은 경개, ④는 담보의 제공(취소권자가 채무자로서 제공하는 경우 포함), ⑤는 취득한 권리의 전부나 일부의 양도로서 제145조 사유이다.","c":"상","v":1},"변리사2026_63-11":{"w":"ㄱ X. 이미 성취한 조건이 해제조건이면 법률행위는 무효이다(제151조 제2항). 정지조건이면 조건 없는 법률행위가 된다.\nㄴ O. 이미 성취할 수 없는 조건이 정지조건이면 법률행위는 무효이다(제151조 제3항).\nㄷ O. 불확정한 사실의 발생 시를 이행기한으로 정한 경우, 사실이 발생한 때뿐 아니라 발생이 불가능하게 된 때에도 기한이 도래한 것으로 본다(판례).\nㄹ X. 기한이익 상실의 특약은 특별한 사정이 없는 한 형성권적 기한이익 상실 특약으로 추정된다(정지조건부가 아님).\n정답 ②.","c":"중","v":1},"변리사2023_60-06":{"w":"옳지 않은 것은 ㄱ, ㄹ이다.\nㄱ X. 보험금청구권의 소멸시효는 보험사고가 발생한 때부터 진행하며 청구한 때부터가 아니다.\nㄴ O. 변제 충당을 지정하지 않고 일부 변제하면 특별한 사정이 없는 한 모든 채무에 대한 승인으로서 시효가 중단된다(진행 사유 부인).\nㄷ O. 중첩적 채무인수의 인수채무에는 기존채무와 같은 소멸시효기간이 적용된다.\nㄹ X. 보험금 부정 취득 목적의 다수 보험계약이 제103조로 무효가 된 경우 보험자의 부당이득반환청구권은 상행위에서 생긴 채권으로 상법 제64조의 5년 시효가 적용된다.\n정답 ②.","c":"중","v":1},"변리사2026_63-12":{"w":"①이 중단되지 않는 경우다. 판례는 물상보증인이 제기한 저당권설정등기 말소 소송에 채권자가 응소해 피담보채권의 존재를 주장해도 이는 채무자에 대한 재판상 청구가 아니므로 채무자에 대한 소멸시효가 중단되지 않는다고 본다.\n②는 대항요건을 갖추지 못한 양수인의 재판상 청구도 중단 효력이 있다는 판례, ③은 금전채권을 피담보채권으로 한 근저당권설정등기청구의 소도 그 채권의 재판상 청구로 본다는 판례에 따른다. ④는 최고 후 6개월 안에 승인(제168조 제3호)이 있었고 ⑤는 재판상 청구에 해당하는 지급명령 신청이 각하된 뒤 6개월 안에 소를 제기했다(제170조 제2항). 모두 중단된다.","c":"상","v":1},"변리사2024_61-13":{"w":"ㄱ O. 사인증여로 인한 소유권 취득은 법률행위에 의한 물권변동이므로 등기가 필요하다.\nㄴ O. 합유지분 포기로 지분이 다른 합유자에게 귀속되는 경우에도 등기를 해야 한다(판례).\nㄷ O. 이전등기절차 이행을 명한 판결은 이행판결이므로 등기해야 소유권을 취득한다.\nㄹ O. 점유취득시효 완성만으로 소유권을 취득하지 않고 등기를 해야 한다(제245조 제1항).\n모두 등기를 요해 ⑤.","c":"중","v":1},"변리사2026_63-13":{"w":"②가 등기를 해야 효력이 생기는 경우이다. 소유권확인 승소판결은 확인판결이어서 그 자체로 물권변동을 일으키지 않는다. 제187조의 판결은 공유물분할판결 같은 형성판결을 가리킨다.\n①은 상속, ③은 재결수용(수용 개시일에 원시취득), ④는 공매 대금 완납, ⑤는 담보물권의 부종성에 의한 소멸로 모두 등기 없이 효력이 생긴다(제187조).","c":"중","v":1},"변리사2016_53-14":{"w":"ㄱ O. 소유자 丙의 보존등기 말소청구는 소유권에 기한 방해배제청구권이다.\nㄴ O. 승소판결이 확정되어도 청구권의 성격은 물권적 청구권 그대로이다.\nㄷ O. 甲의 처분으로 乙이 등기부취득시효를 완성해 丙이 소유권을 잃었으므로 불법행위 손해배상을 청구할 수 있다.\nㄹ X. 물권적 청구권은 이행불능이 되어도 채무불이행에 의한 전보배상으로 바뀌지 않는다.\n정답 ③.","c":"중","v":1},"변리사2016_53-15":{"w":"⑤가 틀리다. 甲은 丙에게 맡긴 매수자금 5억 원을 부당이득으로 반환청구할 수 있다(불법원인급여에 해당하지 않는다는 판례).\n①은 부동산실명법 제4조 제1항으로 명의신탁약정이 무효이고, ②는 매도인 乙이 명의신탁 사실을 몰랐으므로 같은 조 제2항 단서에 따라 丙이 소유권을 유효하게 취득하며, ③은 같은 조 제3항으로 제3자 丁은 악의여도 소유권을 취득한다. ④는 부당이득반환은 매수자금 반환으로 구하는 것이지 소유권 이전을 청구하는 것이 아니다.","c":"상","v":1},"변리사2016_53-16":{"w":"(2020 판례 변경 전 기준) 판례 변경 전 기준으로 정답은 ①(ㄱ)이다.\nㄱ 출제 당시 판례는 소수지분권자도 보존행위로 협의 없이 공유물을 독점하는 다른 공유자에게 건물 철거와 토지 인도를 청구할 수 있다고 보았다. 대법원 2020. 5. 21. 선고 2018다287522 전원합의체 판결로 판례가 바뀌어 지금은 소수지분권자가 다른 소수지분권자에게 토지 인도를 청구할 수 없고 건물 철거 같은 방해배제만 청구할 수 있다. 지금 기준으로는 ㄱ도 옳지 않아 맞는 선지가 없다.\nㄴ X. 공유물 임대는 관리행위라 지분의 과반수로 정한다(제265조). 乙·丙의 지분 합계 3/7은 과반수가 아니어서 甲에게 임대차의 효력을 주장할 수 없다.\nㄷ X. 甲이 단독으로 공사계약을 맺고 비용 전액을 부담하기로 했으면 乙·丙은 丁에게 공사대금을 지급할 의무가 없다. 제266조의 관리비용 분담은 공유자 내부 관계다.\nㄹ X. 구분소유적 공유관계에서 甲의 지분에 설정된 근저당권은 공유관계가 해소되어 분할되더라도 甲의 단독소유 토지에 집중되지 않고 분할된 각 토지에 종전 지분 비율대로 남는다는 것이 판례다.","c":"중","v":1,"old":1,"ow":"(2020 판례 변경 전 기준) 판례 변경 전 기준으로 정답은 ①(ㄱ)이다.\nㄱ 출제 당시 판례는 소수지분권자도 보존행위로 협의 없이 공유물을 독점하는 다른 공유자에게 건물 철거와 토지 인도를 청구할 수 있다고 보았다. 대법원 2020. 5. 21. 선고 2018다287522 전원합의체 판결로 판례가 바뀌어 지금은 소수지분권자가 다른 소수지분권자에게 토지 인도를 청구할 수 없고 건물 철거 같은 방해배제만 청구할 수 있다. 지금 기준으로는 ㄱ도 옳지 않아 맞는 선지가 없다.\nㄴ X. 공유물 임대는 관리행위라 지분의 과반수로 정한다(제265조). 乙·丙의 지분 합계 3/7은 과반수가 아니어서 甲에게 임대차의 효력을 주장할 수 없다.\nㄷ X. 甲이 단독으로 공사계약을 맺고 비용 전액을 부담하기로 했으면 乙·丙은 丁에게 공사대금을 지급할 의무가 없다. 제266조의 관리비용 분담은 공유자 내부 관계다.\nㄹ X. 구분소유적 공유관계에서 甲의 지분에 설정된 근저당권은 공유관계가 해소되어 분할되더라도 甲의 단독소유 토지에 집중되지 않고 분할된 각 토지에 종전 지분 비율대로 남는다는 것이 판례다."},"변리사2016_53-17":{"w":"ㄱ X. 임차인 乙은 수리 중에도 X건물의 점유자이므로 무단 침입한 丁에게 점유권에 기한 방해배제를 청구할 수 있다(제205조).\nㄴ O. 乙과 도급계약을 맺은 수급인 丙은 계약 상대방인 乙에게 공사대금을 청구해야 하고 소유자 甲에게 수리비 상당의 부당이득반환을 직접 청구할 수 없다(판례).\nㄷ X. 제203조의 비용상환청구는 점유자의 권리인데 수리를 의뢰받은 丙은 점유자가 아니다. 점유자는 도급인 乙이다.\nㄹ X. 乙은 임대차계약에 따른 적법한 점유자이므로 비용상환은 임대차 규정(제626조)에 따라 계약 상대방에게 청구한다. 점유자와 회복자 사이의 제203조는 적용되지 않는다는 것이 판례다.\n정답 ②.","c":"중","v":1},"변리사2017_54-14":{"w":"ㄱ O. 총유물에 관한 사원의 권리·의무는 사원 지위의 득실에 따라 취득·상실된다(제277조).\nㄴ O. 총유물의 관리·처분은 정관 기타 규약에 정함이 없으면 사원총회 결의에 의한다(제276조 제1항).\nㄷ X. 총유재산에 관한 소송은 보존행위라도 총회 결의를 거쳐야 하지만, 결의 요건은 정관이나 규약에 따르며 전체 종원 과반수로 정해지는 것이 아니다.\nㄹ O. 총회 결의 없이 총유재산 처분에 관해 제기한 소송은 소송요건 흠결로 부적법하다.\n정답 ②.","c":"중","v":1},"변리사2017_54-16":{"w":"ㄱ O. 선의 점유자도 본권 소에 패소하면 소가 제기된 때부터 악의 점유자로 본다(제197조 제2항).\nㄴ X. 전후 양 시점의 점유자가 다르더라도 점유 승계가 입증되면 점유계속이 추정된다(제199조, 제198조).\nㄷ O. 점유 승계인이 자기 점유만 주장하는 경우 전 점유자가 타주점유였어도 현 점유는 자주점유로 추정된다.\nㄹ X. 제197조 제1항은 소유의 의사, 선의, 평온·공연한 점유를 추정할 뿐 무과실은 추정하지 않는다.\n정답 ②.","c":"상","v":1},"변리사2018_55-15":{"w":"ㄱ X. 건물 소유자인 丙에게는 대지 소유자가 건물 철거를 청구하고, 건물에서 퇴거하라는 청구는 하지 못한다.\nㄴ O. 위조 서류로 한 乙 명의 이전등기는 무효이므로 甲은 진정명의 회복을 위한 이전등기를 청구할 수 있다.\nㄷ O. 乙은 처분권이 없으므로 丙은 대지 사용권이 없고, 甲은 건물 철거를 청구할 수 있다.\nㄹ O. 철거 대상 건물의 임차인 丁은 대지 소유자에 대한 점유권원이 없어 甲이 퇴거를 청구할 수 있다.\n정답 ④.","c":"중","v":1},"변리사2019_56-17":{"w":"ㄱ O. 甲은 며칠 뒤에 자력으로 탈환했으므로 제209조 제2항의 자력탈환(즉시 또는 가해자를 추적하여) 요건을 갖추지 못했다. 점유를 침탈당한 丙은 점유회수의 소로 반환을 청구할 수 있다(제204조 제1항).\nㄴ X. 丙은 과실이 있어 선의취득 요건(선의·무과실, 제249조)을 갖추지 못했다.\nㄷ X. 점유의 소에서는 본권(소유권)에 관한 이유로 재판하지 못한다(제208조 제2항).\nㄹ X. 점유물반환청구권은 침탈자의 특별승계인에게는 행사하지 못하고 승계인이 악의인 때만 예외다(제204조 제2항). 丙은 선의의 특정승계인이므로 甲은 丙에게 점유물반환청구권을 행사할 수 없다.\n정답 ①.","c":"상","v":1},"변리사2023_60-13":{"w":"ㄱ X. 지방자치단체도 등기부취득시효(제245조 제2항)를 주장할 수 있다.\nㄴ O. 무과실은 점유 개시 시점에 있으면 족하고 시효기간 전체에 걸쳐 요구되지 않는다.\nㄷ O. 무효인 중복 소유권보존등기는 등기부취득시효의 기초가 될 수 없다.\n정답 ④.","c":"중","v":1},"변리사2023_60-17":{"w":"ㄱ O. 구분소유적 공유는 이미 대내적으로 특정 부분을 단독 소유하는 관계이므로 공유물분할청구가 허용되지 않는다.\nㄴ O. 공유자의 지분권자로서의 사용권을 사실상 포기하는 특약은 이를 모르고 지분을 취득한 특정승계인에게 승계되지 않는다(판례).\nㄷ X. 채권자가 대위권으로 총유재산에 관한 권리를 행사할 때는 비법인사단의 내부 의사결정을 거칠 필요가 없다.\nㄹ O. 합유자 일부가 사망하면 잔존 합유자가 2인 이상일 때 잔존 합유자의 합유가 된다.\n정답 ③.","c":"중","v":1},"변리사2024_61-16":{"w":"④가 틀리다. 소유자 乙의 채권자가 한 가압류는 점유자 甲의 취득시효를 중단시키지 못한다(점유의 중단이나 소유자 변경과 무관).\n①은 간접점유도 시효취득의 점유에 해당하고, ②는 시효 완성 전에 소유권을 취득한 丙에게 주장할 수 있으며, ③은 시효취득자가 소유자를 대위하여 말소를 청구할 수 있고, ⑤는 시효완성자에게 점유 기간의 부당이득반환을 청구할 수 없다.","c":"중","v":1},"변리사2016_53-19":{"w":"ㄱ X. 전세권설정계약이 합의로 해지되어 전세권이 소멸하면 전세금반환채권은 전세권과 분리하여 양도할 수 있다.\nㄴ X. 소유권이 丙에게 양도되면 丙이 전세권설정자의 지위를 승계하고 甲은 전세금반환의무를 면한다.\nㄷ O. 전세권저당권자 丁은 전세권 소멸 후 전세금반환채권을 압류하여(물상대위) 전세금을 청구할 수 있다.\n정답 ③.","c":"중","v":1},"변리사2021_58-24":{"w":"모두 성립하지 않는다.\nㄱ 환지처분은 매매 등 처분이 아니어서 성립하지 않는다.\nㄴ 건물 소유권을 취득하지 못한 매수인은 건물 소유자가 아니므로 성립하지 않는다.\nㄷ 공유토지에서 지분만 양도하면 다른 공유자 지분에 불리하므로 성립하지 않는다.\nㄹ 소유권이전등기가 원인무효로 말소되면 처음부터 토지 소유자가 아니었으므로 성립하지 않는다.\n정답 ⑤.","c":"중","v":1},"변리사2023_60-18":{"w":"옳지 않은 것은 ㄱ, ㄷ, ㄹ이다.\nㄱ X. 양도형 분묘기지권의 지료지급의무는 분묘기지권이 성립한 때부터 발생한다(판례 변경, 대법원 2021.4.29. 선고).\nㄴ O. 지료 연체가 토지 양도 전후에 걸쳐 있어도 양수인에 대한 연체기간이 2년이 안 되면 지상권소멸청구를 할 수 없다.\nㄷ X. 대지만 이전등기를 받고 건물 등기를 받지 못한 매수인에게는 관습법상 법정지상권이 성립하지 않는다.\nㄹ X. 토지 임대차를 맺었으면 법정지상권을 인정할 필요가 없어 성립하지 않는다.","c":"중","v":1},"변리사2016_53-23":{"w":"채권 5억 원, X토지(채무자 甲 소유)와 Y건물(물상보증인 乙 소유)이 각각 4억 원이다.\nㄱ O. X가 먼저 배당되면 丙이 X에서 4억 원을 모두 받는다. 채무자 소유 부동산의 후순위저당권자 丁은 물상보증인 소유 Y에 대위하지 못한다.\nㄴ O. Y가 먼저 배당되면 丙이 Y에서 4억 원을 받고 물상보증인 乙은 변제자대위로 X의 1번 저당권을 행사한다. X 4억 원에서 丙의 남은 채권 1억 원이 먼저이고 乙은 3억 원을 받는다.\nㄷ X. 채무자 소유 부동산과 물상보증인 소유 부동산이 동시에 배당되면 제368조 제1항의 안분을 하지 않고 채무자 소유 X에서 먼저 배당한다(대법원 2010. 4. 15. 선고 2008다41475). 丙은 X에서 4억 원, Y에서 1억 원을 받는다. 丁은 X에서 남는 것이 없고 Y에서도 배당받지 못한다.\n정답 ②.","c":"상","v":1},"변리사2016_53-24":{"w":"ㄱ X. 양도담보에서 대내적 소유권은 설정자 甲에게 있다.\nㄴ X. 설정자가 점유를 상실해도 乙은 양도담보권을 잃지 않는다.\nㄷ X. 점유개정으로는 선의취득을 할 수 없다.\nㄹ O. 丙이 乙의 담보권을 알면서 처분해 담보권 실행을 방해했다면 불법행위가 된다.\n정답 ①.","c":"중","v":1},"변리사2017_54-23":{"w":"ㄱ O: 질권설정에서 금지되는 것은 점유개정뿐이다(제332조). 제3자에 대한 목적물반환청구권을 양도하는 방법으로는 질권을 설정할 수 있다.\nㄴ X: 처분권 없는 자가 설정한 질권도 선의취득 요건을 갖추면 취득한다(제343조, 제249조).\nㄷ O: 물상보증인 乙은 채무자 丙에게 구상권이 있고(제355조, 제341조) 구상 범위에서 甲의 권리를 대위한다(제482조).\nㄹ O: 물상대위는 보상금이 지급되기 전에 압류해야 한다(제342조 후문). 乙이 보상금을 이미 받았으면 甲은 물상대위권을 행사할 수 없다.\n정답 ④.","c":"상","v":1},"변리사2019_56-23":{"w":"4,000만 원이다.\nX(가액 1.2억)를 먼저 경매하여 甲 1억, A 2천만 원이 배당된다. 물상보증인 간에는 부동산 가액 비율(X 1.2억 : Y 0.8억 = 3:2)로 채무 1억 원을 분담하므로 X 분담분 6천만 원, Y 분담분 4천만 원이다. 丙은 Y에 대해 4천만 원 한도에서 甲의 저당권을 대위하고, X의 후순위 A가 이 대위권에 물상대위를 해서 Y 매각대금 8천만 원에서 4천만 원을 우선 배당받는다.\n정답 ③.","c":"중","v":1},"변리사2023_60-21":{"w":"ㄱ X. 보증금반환채권에 질권을 설정할 때 임대차계약서의 교부는 필요하지 않다.\nㄴ O. 질권 목적 채권의 채무자와 질권설정자가 상계하는 것은 질권의 목적인 채권을 소멸시키는 행위여서 질권자에게 대항하지 못한다.\nㄷ X. 보증금반환채권에 대한 질권의 효력이 별도의 합의 없이 근저당권에 당연히 미치지는 않는다.\nㄹ O. 임차인이 임차목적물을 매수해도 질권자 丙은 임대인 乙에게 직접 변제를 청구할 수 있다.\n정답 ⑤.","c":"중","v":1},"변리사2023_60-29":{"w":"정답 ②. 주채무 5억 원은 X부동산(3억 원)과 Y부동산(4억 원)의 공동저당으로 전액 우선변제가 확보되어 있다(3억+4억=7억 원). 물적 담보로 채권 전액이 보전되어 있으면 연대보증인이 유일한 재산을 처분해도 채권자에 대한 사해행위가 되지 않는다는 것이 판례이므로, 乙은 丁의 처분행위를 취소할 수 없다.\n① O. 채무자 소유 부동산과 물상보증인 소유 부동산이 함께 공동저당된 경우 채무자 소유 부동산이 피담보채권 전액을 먼저 부담한다(대법원 2013. 7. 18. 선고 2012다5643 전원합의체 판결). X의 가액 3억 원은 피담보채권 5억 원에 못 미쳐 일반채권자에게 남는 가치가 없으므로 X의 매도는 사해행위가 아니다.\n③ O. 보증인 丁과 물상보증인 丙은 인원수에 비례하여 대위하므로(민법 제482조 제2항 제5호) 丁의 부담부분은 5억÷2=2.5억 원이다. 2억 원 변제는 자기 부담부분을 넘지 않아 丙에 대하여 대위할 수 없다.\n④ O. 물상보증인도 대위변제 후 저당권 등기에 대위의 부기등기를 하기 전에 저당물을 취득한 제3자 B에 대해서는 대위하지 못한다(제482조 제2항 제1호의 취지, 판례).\n⑤ O. 채무자 甲으로부터 X를 취득한 제3취득자 B는 보증인 丁에게 대위하지 못하고(제482조 제2항 제2호), 판례상 물상보증인 丙에게도 대위하지 못한다.","c":"상","v":1},"변리사2024_61-23":{"w":"ㄱ O. 동시배당이면 채권 3억 원을 매각대금 비율(X 4억 : Y 2억)로 안분하여 X에서 2억, Y에서 1억을 배당받는다.\nㄴ O. 이시배당으로 X에서 甲이 3억을 받으면, 동시배당이었다면 X에서 받았을 2억을 초과한 1억 원 범위에서 후순위 丙이 Y의 1번 저당권을 대위한다(제368조 제2항).\nㄷ X. 대위등기 전에 甲이 Y의 저당권을 말소하고 丁이 Y를 매수해 등기했다면 丙은 丁에게 저당권을 주장하지 못한다.\nㄹ X. 甲이 저당권을 포기했다면 포기하지 않았을 때 Y에서 받을 수 있었던 1억 원 몫은 丙에게 우선하지 못하므로 甲은 X에서 2억 원만 배당받는다.\n정답 ①.","c":"중","v":1},"변리사2026_63-15":{"w":"ㄱ O. 저당권자가 압류하면 압류 이후 저당권설정자의 차임채권에도 저당권의 효력이 미친다(제359조).\nㄴ O. 불법 말소된 저당권의 목적 부동산이 경매로 매각되면 저당권자는 매수인에게 말소된 등기의 회복을 청구할 수 없다.\nㄷ X. 제360조의 1년분 제한은 후순위권리자 등 제3자에 대해서만 의미가 있고, 채무자는 이를 이유로 피담보채권의 제한을 주장할 수 없다.\n정답 ③.","c":"중","v":1},"변리사2026_63-24":{"w":"옳지 않은 것은 ㄱ, ㄴ이다.\nㄱ X. 수탁보증인의 사전구상권(제442조)은 물상보증인에게 적용되지 않으므로 물상보증인은 사전구상권을 행사할 수 없다(판례).\nㄴ X. 물상보증인이 담보권 실행으로 소유권을 잃은 경우 구상 범위는 특별한 사정이 없으면 매수인이 매각대금을 다 낸 때의 부동산 시가를 기준으로 하고 매각대금을 기준으로 하지 않는다(대법원 2018. 4. 10. 선고 2017다283028).\nㄷ O. 근저당권의 물상보증인은 채권최고액만 변제하면 근저당권설정등기의 말소를 청구할 수 있다.\n정답 ②.","c":"상","v":1},"변리사2017_54-30":{"w":"ㄱ O. 양수인 A가 양도인 甲의 대리인으로서 한 통지도 효력이 있다.\nㄴ O. 통지는 방식에 제한이 없어 문자로도 가능하고, 먼저 도달한 통지를 기준으로 한 乙의 A에 대한 변제는 유효하다.\nㄷ O. 확정일자 없는 통지는 제3자 B에 대항하지 못하므로, 확정일자 있는 B의 통지가 있으면 A에게 한 변제로 B에게 대항하지 못한다.\nㄹ O. 확정일자의 선후가 아니라 확정일자 있는 통지가 채무자에게 도달한 선후로 우열을 정하므로, 먼저 도달한 B가 우선한다.\n모두 옳아 ⑤.","c":"중","v":1},"변리사2023_60-30":{"w":"옳은 것은 ㄱ, ㄴ, ㄹ이다(2번).\nㄱ 임차권 양도를 금지하는 특약이 임대차보증금반환채권의 양도까지 금지하는 것은 아니다.\nㄴ 이의를 보류하지 않은 승낙 당시 상계할 원인이 있었음을 양수인이 알았다면, 승낙 뒤에 상계적상이 생겨도 채무자는 양수인에게 상계로 대항할 수 있다.\nㄷ X: 명의신탁 해지를 원인으로 한 소유권이전등기청구권은 매매로 인한 이전등기청구권처럼 양도가 제한된다. 명의수탁자가 양도에 동의하거나 승낙하지 않으면 양수인은 명의수탁자에게 직접 이전등기를 청구할 수 없다(대법원 2021. 6. 3. 선고 2018다280316 판결).\nㄹ 임대인 지위는 임차인의 동의 없이 임대인과 목적물 양수인의 계약만으로 넘길 수 있다.","c":"중","v":1},"변리사2024_61-29":{"w":"④가 틀리다. 연대채무자 한 사람에 대한 면제는 그 부담부분(1억 원)에 한하여 다른 채무자의 이익을 위해 효력이 있고(제419조), 乙·丙의 채무가 전부 소멸하지 않는다.\n①은 이행청구·판결의 절대적 효력(제416조), ②는 부담부분 한도의 상계(제418조 제2항), ③은 경개의 절대적 효력(제417조), ⑤는 혼동으로 甲·乙이 부담부분 1억 원씩 변제하는 것이다.","c":"중","v":1},"변리사2024_61-31":{"w":"ㄱ O. 중첩적 채무인수는 채권자와 인수인의 합의로 채무자의 의사에 반해서도 할 수 있다.\nㄴ O. 면책적 채무인수와 동시에 인수인이 채무를 승인하면 인수채무의 시효는 인수일부터 새로 진행한다.\nㄷ X. 채무자와 인수인의 합의에 의한 중첩적 채무인수는 제3자를 위한 계약이어서 채권자가 인수인에게 수익의 의사표시를 해야 직접 청구할 수 있다.\n정답 ②.","c":"중","v":1},"변리사2018_55-32":{"w":"④가 틀리다. 압류 후에 취득한 채권을 자동채권으로 하는 상계로는 압류채권자에게 대항할 수 없다(제498조).\n①은 상계의 소급효(제493조 제2항), ②는 보증인이 주채무자의 채권으로 상계로 대항하는 제434조, ③은 상계금지 특약을 모르는 선의 양수인에게 대항하지 못하고(제492조 제2항), ⑤는 고의의 불법행위 채권은 수동채권으로 할 수 없을 뿐 자동채권으로는 상계할 수 있다(제496조).","c":"중","v":1},"변리사2021_58-31":{"w":"ㄱ O. 丙이 자기 채무로 오해해 지급한 것은 타인의 채무를 변제할 의사가 없어 제3자 변제가 아니다.\nㄴ X. 유치권 있는 건물의 매수인 丙은 정당한 이익이 있는 제3자라서 채무자의 의사에 반해서도 변제할 수 있다.\nㄷ X. 통장과 인감을 가지고 대리인을 사칭한 자도 채권의 준점유자에 해당한다.\nㄹ O. 지시채권 증서 소지인에 대한 변제는 변제자가 악의 또는 중과실이 아닌 한 유효하다(제518조).\n정답 ③.","c":"중","v":1},"변리사2024_61-32":{"w":"옳지 않은 것은 ㄴ, ㄷ, ㄹ이다.\nㄱ O. 변제의 유예가 있는 채무는 유예기까지 변제기가 도래하지 않은 것으로 보고 법정충당 순위를 정한다.\nㄴ X. 채권자가 미리 수령을 거절하고 있어 이행제공을 해도 받지 않을 것이 명백하면 채무자는 이행제공 없이 바로 변제공탁할 수 있다(제487조, 판례).\nㄷ X. 적법한 변제공탁은 공탁한 때에 변제의 효력이 생기고 그 뒤 공탁물 출급청구권이 가압류되어도 이미 생긴 변제의 효력은 그대로다.\nㄹ X. 제척기간이 지나기 전에 상계할 수 있었던 담보책임 손해배상채권은 제척기간이 지난 뒤에도 제495조를 유추해 자동채권으로 상계할 수 있다(판례).","c":"상","v":1},"변리사2018_55-37":{"w":"ㄱ O. 선이행 약정이 있어도 상대방의 이행이 곤란할 현저한 사유가 생기면 선이행의무를 거절할 수 있다.\nㄴ O. 임대차 종료 후 임차물 반환의무와 보증금 반환의무는 동시이행관계이다.\nㄷ X. 임차물 반환의무와 약정 지연손해배상의무는 동시이행관계가 아니다.\nㄹ X. 변제와 채권증서 반환은 동시이행이 아니다(제475조, 영수증 교부만 제474조에 따라 동시이행).\nㅁ O. 가압류등기의 말소의무도 대금지급과 동시이행이다.\nㅂ O. 이전등기의무와 인도의무 모두 대금지급과 동시이행이다.\n정답 ③.","c":"중","v":1},"변리사2018_55-40":{"w":"⑤가 틀리다. 해제의 의사표시가 상대방에게 도달하면 소를 취하하더라도 해제는 철회되지 않으므로, 이후 이행을 구하는 소를 제기해도 매도인이 매매계약상 의무를 이행해야 하는 것은 아니다.\n①은 제553조, ②는 제547조 규정의 임의규정성, ③은 제552조, ④는 약정해제권 유보가 법정해제권에 영향을 주지 않는다는 내용이다.","c":"중","v":1},"변리사2023_60-33":{"w":"ㄱ O. 매도인의 이행불능으로 생긴 손해배상채무는 본래 급부와 동일성이 있어 매수인의 대금지급채무와 동시이행관계이다.\nㄴ O. 한쪽이 선이행의무를 약정했더라도 쌍방 이행기가 모두 지난 뒤에는 동시이행관계가 된다.\nㄷ X. 근저당권자의 배당금 반환의무와 낙찰자의 이전등기 말소의무는 동시이행관계가 아니다.\n정답 ③.","c":"중","v":1},"변리사2026_63-34":{"w":"ㄱ O. 피담보채무 이행인수 불이행으로 인한 매수인의 손해배상채무와 매도인의 소유권이전등기의무는 동시이행관계이다.\nㄴ O. 임대차보증금 반환의무와 전세권설정등기 말소의무는 동시이행관계이다.\nㄷ O. 가압류등기가 있는 부동산 매매에서 소유권이전등기의무와 가압류등기 말소의무는 매수인의 대금지급의무와 동시이행관계이다.\n모두 옳아 ⑤.","c":"중","v":1},"변리사2019_56-30":{"w":"ㄱ X. 사해행위취소의 효력은 채권자와 수익자 사이에만 미치므로 丙 명의 등기가 말소되어 乙 명의가 회복되어도 乙이 소유권을 다시 취득하는 것은 아니다. 회복된 부동산은 채권자들을 위한 책임재산으로 취급될 뿐이다.\nㄴ O. 피보전채권은 사해행위 전에 성립했으면 액수나 범위가 구체적으로 확정되지 않아도 된다.\nㄷ O. 사해행위취소를 먼저 구하고 원상회복을 나중에 청구하는 경우 취소청구가 제척기간 안에 제기되었다면 원상회복청구는 그 기간이 지난 뒤에도 할 수 있다.\nㄹ X. 乙이 회복된 등기명의를 이용해 丁에게 처분한 것은 무권리자의 처분이라 丁 명의 등기는 원인무효다. 사해행위취소와 원상회복의 효력을 받는 다른 일반채권자 戊도 책임재산을 보전하기 위해 丁 명의 등기의 말소를 청구할 수 있다(대법원 2017. 3. 9. 선고 2015다217980).\n정답 ②.","c":"중","v":1},"변리사2017_54-39":{"w":"②가 임차인에게 불리한 약정도 유효한 경우이다. 임차인의 비용상환청구권(제626조)은 임의규정이다.\n①은 제643조·제652조, ③은 제628조·제652조, ④는 제635조·제652조, ⑤는 제640조·제652조로 임차인에게 불리한 약정이 효력이 없는 편면적 강행규정이다.","c":"상","v":1},"변리사2021_58-38":{"w":"ㄱ O: 건물 기타 토지의 공작물은 하자로 계약 목적을 달성할 수 없어도 도급인이 해제할 수 없다(제668조 단서).\nㄴ X: 하자가 중요하지 않은데 보수에 과다한 비용이 들면 보수를 청구할 수 없고(제667조 제1항 단서), 판례는 보수비용 상당의 손해배상도 청구할 수 없으며 하자로 줄어든 교환가치만 배상받는다고 본다.\nㄷ X: 판례상 지체상금의 종기는 甲이 실제로 해제한 때가 아니라 해제할 수 있었던 때부터 다른 업자에게 맡겨 완공할 수 있었던 시점까지다.\nㄹ O: 준공기한 전에 계약이 해제되어 공사가 끝나지 않았으면 지체상금약정은 적용되지 않는다.\n정답 ②.","c":"중","v":1},"변리사2023_60-37":{"w":"ㄱ O. 임대차 종료 후에는 임대목적물이 타인 소유라도 임차인은 임대인에게 인도완료일까지 차임 상당 부당이득을 반환해야 한다.\nㄴ O. 임대인이 필요비를 상환하지 않으면 임차인은 그 한도에서 차임 지급을 거절할 수 있다.\nㄷ X. 임대차가 존속하는 동안은 무단 전대의 전차인이 임대인에게 불법점유로 인한 차임 상당 손해배상 책임을 지지 않는다.\nㄹ O. 동의를 얻은 전대에서 전대차 차임을 감액한 경우 전차인은 변경된 내용을 임대인에게 주장할 수 있다.\n정답 ④.","c":"중","v":1},"변리사2024_61-36":{"w":"옳지 않은 것은 ㄱ, ㄷ, ㄹ이다.\nㄱ X. 일 완성 전 도급인이 제673조에 따라 손해를 배상하고 해제하는 경우 그 손해배상에서 도급인은 과실상계를 주장할 수 없다는 것이 판례다.\nㄴ O. 공사대금채권 양수인의 저당권설정청구(제666조)에 응해 도급인이 신축건물에 저당권을 설정하는 행위는 특별한 사정이 없으면 사해행위가 아니다.\nㄷ X. 하자보수에 갈음하는 손해배상을 청구할 때 도급인은 손해배상액에 상응하는 보수에 대해서만 지급을 거절할 수 있다(제667조 제3항, 판례). 보수 전액을 거절할 수는 없다.\nㄹ X. 하자보수에 갈음하는 손해배상액은 건물 완성 시를 기준으로 산정하지 않는다. 판례는 원칙적으로 하자보수를 청구한 때를 기준으로 본다.","c":"중","v":1},"변리사2024_61-40":{"w":"ㄱ O. 타인 권리 매매에서 이전불능으로 인한 손해배상액은 이행불능 당시 목적물의 시가를 기준으로 한다.\nㄴ O. 일부가 계약 당시 이미 멸실된 경우 악의의 매수인은 대금감액을 청구할 수 없다(제574조, 제572조 제3항).\nㄷ X. 유치권이 있는 목적물에 대한 선의 매수인은 계약의 목적을 달성할 수 없을 때에만 해제할 수 있다(제575조).\nㄹ O. 건축이 불가능한 토지는 물건의 하자에 해당하고, 하자 유무는 매매계약 성립 시를 기준으로 한다.\n정답 ④.","c":"중","v":1},"변리사2026_63-36":{"w":"ㄱ O. 타인 권리의 매매에서 매수인은 선의·악의 불문하고 해제할 수 있고, 선의 매수인은 제570조에 따라 손해배상도 청구할 수 있다.\nㄴ O. 수량을 지정한 매매일 때에 한하여 제574조의 대금감액청구가 인정된다.\nㄷ X. 매수인이 출재로 저당권을 소멸시켜 소유권을 보존한 경우 계약 당시 알았더라도 제576조 제2항에 따라 매도인에게 상환을 청구할 수 있다.\n정답 ③.","c":"중","v":1},"변리사2018_55-24":{"w":"ㄱ O. 부첩관계를 대가로 한 증여는 제103조에 반해 무효이다.\nㄴ X. 이미 이전등기를 마친 급여는 불법원인급여(제746조)여서 말소를 청구할 수 없다.\nㄷ O. 주택의 소유권이 乙에게 귀속되므로 甲은 명도를 청구할 수 없다.\nㄹ O. 乙이 丙에게 양도한 경우에도 甲은 丙 명의 등기의 말소를 청구할 수 없다.\n정답 ④.","c":"중","v":1},"변리사2019_56-38":{"w":"ㄱ X. 관리자가 사무관리를 하면서 과실 없이 손해를 입은 경우 본인의 현존이익 한도에서만 보상을 청구할 수 있다(제740조). 손해 전부가 아니다.\nㄴ O. 위임의 보고의무(제683조)가 사무관리에 준용되므로(제738조) 본인이 청구하면 사무처리 상황을 보고하고 종료하면 지체 없이 전말을 보고해야 한다.\nㄷ O. 타인을 위한 의사는 관리자 자신의 이익을 위한 의사와 병존할 수 있고 외부에 표시되거나 관리 당시에 확정되어 있을 필요가 없다(판례).\nㄹ X. 제3자와의 약정에 따라 타인의 사무를 처리한 경우 그 타인과의 관계에서는 원칙적으로 사무관리가 성립하지 않는다(판례).\n정답 ②.","c":"상","v":1},"변리사2018_55-04-2":{"w":"제8조 제1항에 따라 영업을 허락받은 미성년자는 그 영업에 관하여 성년자와 같은 행위능력이 있다. 허락의 취소(제8조 제2항)는 장래에 향하여만 효력이 있으므로 취소 전에 영업을 위해 한 상품주문은 유효하다.","c":"상","v":1},"변리사2018_55-07-1":{"w":"판례(전원합의체)는 총유재산에 관한 소송을 비법인사단 명의(민사소송법 제52조)로 하거나 구성원 전원이 당사자가 되는 필수적 공동소송으로만 할 수 있다고 본다. 구성원 개인은 대표자이거나 사원총회 결의를 거쳤어도 당사자적격이 없다.","c":"중","v":1},"변리사2018_55-10-1":{"w":"민법에는 의사능력의 정의 규정이 없고 판례가 이렇게 정의한다. 의사능력이 없는 상태에서 한 법률행위는 무효다.","c":"중","v":1},"변리사2018_55-10-2":{"w":"판례는 의사능력을 행위마다 따지며 특히 법률행위가 특별한 법률적 의미나 효과를 갖는 경우에는 그 의미·효과까지 이해할 수 있어야 의사능력이 있다고 본다.","c":"중","v":1},"변리사2018_55-10-5":{"w":"판례상 의사무능력을 이유로 무효를 주장하는 사람이 행위 당시 의사능력이 없었다는 사실의 증명책임을 진다.","c":"중","v":1},"변리사2019_56-02-1":{"w":"미성년자가 법정대리인의 동의 없이 한 법률행위는 취소할 수 있고(제5조 제2항) 법정대리인도 취소권자다(제140조). 100만원짜리 자전거 구입은 처분을 허락받은 재산이나 단순히 권리만 얻는 행위가 아니다.","c":"상","v":1},"변리사2019_56-02-3":{"w":"제15조의 확답촉구권은 상대방의 선의·악의를 따지지 않는다(악의면 배제되는 것은 제16조의 철회권). 甲이 아직 미성년자이므로 법정대리인에게 촉구한다(제15조 제2항).","c":"상","v":1},"변리사2019_56-02-4":{"w":"제17조 제2항에 따라 미성년자가 속임수로 법정대리인의 동의가 있는 것으로 믿게 한 경우 그 행위를 취소할 수 없다. 취소권 자체가 없어지므로 법정대리인도 취소하지 못한다.","c":"상","v":1},"변리사2019_56-02-5":{"w":"제16조 제1항 단서에 따라 상대방이 계약 당시 제한능력자임을 알았으면 의사표시를 철회할 수 없다.","c":"상","v":1},"변리사2021_58-03-2":{"w":"판례는 법인격을 전제로 하지 않는 사단법인 규정을 비법인사단에 유추적용하며 비법인사단이 해산한 경우의 청산절차에도 청산인에 관한 민법 규정(제82조 이하)을 유추적용한다.","c":"중","v":1},"변리사2023_60-02-2":{"w":"2022. 2. 17. 甲은 미성년자이고 혼인 전이어서 취소의 원인이 소멸하지 않았다. 추인은 취소의 원인이 소멸된 후에 해야 효력이 있으므로(제144조 제1항) 이 추인은 효력이 없고 취소권이 남는다.","c":"상","v":1},"변리사2023_60-02-3":{"w":"甲은 2022. 3. 12. 혼인으로 성년자로 의제되어(제826조의2) 취소의 원인이 소멸했다. 그 뒤인 5. 15.의 추인은 제144조 제1항의 요건을 갖추어 법정대리인 동의 없이도 유효하다.","c":"상","v":1},"변리사2023_60-02-4":{"w":"혼인으로 인한 성년의제는 이혼 후에도 유지된다는 것이 통설이다. 추인할 수 있게 된 뒤 이의를 보류하지 않고 상대방의 이행(매매대금)을 수령하면 제145조 제1호의 법정추인이 되어 취소권이 소멸한다.","c":"중","v":1},"변리사2023_60-02-5":{"w":"2023. 2. 18. 甲은 성년의제 상태이고 만 19세에도 이르러 취소의 원인이 소멸했으므로 단독으로 추인할 수 있다(제144조 제1항). 추인할 수 있는 날부터 3년의 제척기간(제146조)도 지나지 않았다.","c":"상","v":1},"변리사2026_63-04-4":{"w":"판례는 비법인사단이 총유물 매매로 부담하는 채무에 대해 소멸시효 중단 사유인 승인을 하는 것은 채무의 존재를 인정하는 데 그쳐 총유물의 관리·처분행위가 아니라고 본다. 따라서 사원총회 결의(제276조 제1항)가 없어도 승인은 유효하다.","c":"중","v":1},"변리사2018_55-03-1":{"w":"판례는 온천에 관한 권리를 관습법상 물권이나 준물권으로 인정하지 않는다. 온천수는 지하수의 일종으로 토지소유권의 범위에 속한다.","c":"중","v":1},"변리사2017_54-01-1":{"w":"제1조는 민사에 관하여 법률에 규정이 없으면 관습법에 의한다고 정한다. 판례는 관습법이 법령에 저촉되지 않는 한 보충적 효력을 가진다고 본다.","c":"상","v":1},"변리사2017_54-01-3":{"w":"판례는 종중이 공동선조의 후손으로 자연발생하는 단체라는 점에서 그 명칭 사용이 관습에 맞지 않는다는 사정만으로 종중의 실체를 부인하지 않는다.","c":"중","v":1},"변리사2017_54-01-4":{"w":"제106조에 따라 선량한 풍속 기타 사회질서와 관계없는 임의규정과 다른 관습이 있고 당사자 의사가 명확하지 않으면 그 관습에 의한다. 판례는 이러한 사실인 관습을 법률행위 해석의 기준으로 삼는다.","c":"상","v":1},"변리사2017_54-01-5":{"w":"판례상 사실인 관습은 법원(法源)이 아니어서 그 존재를 당사자가 주장·증명해야 한다. 관습이 강행규정과 다르면 효력이 없으므로 임의규정에 관한 것인지도 심리해야 한다.","c":"중","v":1},"변리사2019_56-03-1":{"w":"영리법인은 사원에게 이익을 분배하는 사단만 될 수 있고(제39조) 재단법인은 사원이 없으므로 제32조의 비영리법인으로만 설립된다.","c":"상","v":1},"변리사2019_56-03-3":{"w":"제81조는 해산한 법인이 청산의 목적범위 내에서만 권리가 있고 의무를 부담한다고 정한다.","c":"상","v":1},"변리사2019_56-03-4":{"w":"제60조는 이사의 대표권 제한을 등기하지 않으면 제3자에게 대항하지 못한다고 정하며 판례는 여기의 제3자에 악의의 제3자도 포함된다고 본다.","c":"중","v":1},"변리사2019_56-03-5":{"w":"판례는 청산종결등기가 되었더라도 청산사무가 실제로 끝나지 않았다면 그 범위 안에서 법인이 청산법인으로 존속한다고 본다. 등기는 청산 종결을 공시할 뿐 법인을 소멸시키지 않는다.","c":"중","v":1},"변리사2023_60-03-1":{"w":"제47조 제1항은 생전처분으로 재단법인을 설립하는 때에는 증여에 관한 규정을 준용한다고 정한다. 출연행위가 무상의 재산 출연이라는 점이 증여와 같기 때문이다.","c":"상","v":1},"변리사2023_60-03-2":{"w":"제48조 제2항은 유언으로 재단법인을 설립하는 때에는 출연재산이 유언의 효력이 발생한 때부터 법인에 귀속한 것으로 본다고 정한다.","c":"상","v":1},"변리사2023_60-03-4":{"w":"제46조는 재단법인의 목적을 달성할 수 없는 때 설립자나 이사가 주무관청의 허가를 얻어 설립의 취지를 참작해 목적 기타 정관 규정을 변경할 수 있다고 정한다.","c":"상","v":1},"변리사2023_60-03-5":{"w":"제44조는 재단법인 설립자가 명칭, 사무소소재지 또는 이사임면의 방법을 정하지 않고 사망한 때 이해관계인 또는 검사의 청구로 법원이 정한다고 정한다. 목적과 자산은 법원이 보충할 수 없다.","c":"상","v":1},"변리사2026_63-03-2":{"w":"판례는 기본재산의 처분은 정관 변경을 수반하므로 주무관청 허가가 필요하지만 기본재산에 근저당권을 설정하는 것은 처분이 아니어서 허가를 요하지 않는다고 본다.","c":"중","v":1},"변리사2016_53-03-5":{"w":"판례는 제35조 제1항의 「직무에 관하여」를 행위의 외형상 대표자의 직무행위로 보이면 족하다고 보며 대표자 개인의 이익을 위한 행위여도 직무관련성이 인정된다. 다만 상대방이 직무행위가 아님을 알았거나 중대한 과실로 몰랐으면 법인은 책임을 지지 않는다.","c":"중","v":1},"변리사2018_55-09-3":{"w":"판례는 법인과 이사의 관계를 위임과 유사하게 보아 제689조 제1항의 해지 자유를 적용하고 불리한 시기의 부득이한 사유 없는 해지에 한해 손해배상책임(제689조 제2항)을 인정한다. 정관에 해임사유를 정해 둔 경우에는 그 사유가 있어야 해임할 수 있다.","c":"중","v":1},"변리사2026_63-02-2":{"w":"법원 허가를 받은 재산관리인의 처분행위(제25조)는 선임결정이 취소되기 전에 한 것이면 실종기간이 지난 뒤여도 유효하다는 것이 판례다. 실종선고로 사망이 의제되면 그 효과는 부재자의 재산상속인에게 미친다.","c":"중","v":1},"변리사2024_61-01-2":{"w":"판례는 입원계약상 병원이 진료뿐 아니라 입원환자의 휴대품 등이 도난되지 않도록 적절한 조치를 할 신의칙상 보호의무를 진다고 보며 이를 어기면 채무불이행책임을 진다.","c":"중","v":1},"변리사2024_61-01-3":{"w":"판례는 숙박계약을 일시사용을 위한 임대차와 유사한 계약으로 보아 숙박업자에게 고객의 안전을 배려할 신의칙상 보호의무를 인정하고 이를 위반하면 채무불이행책임을 진다고 본다.","c":"중","v":1},"변리사2024_61-01-4":{"w":"판례는 강행법규 위반 행위의 효력을 다투는 주장을 신의칙 위반이라고 배척하면 강행법규의 취지가 몰각되므로 합법성의 원칙을 희생하고도 구체적 신뢰를 보호할 필요가 있는 예외적인 경우에만 신의칙을 적용한다.","c":"중","v":1},"변리사2024_61-01-5":{"w":"판례는 신의칙 위반 여부를 당사자 주장이 없더라도 법원이 직권으로 판단할 수 있는 사항으로 본다.","c":"중","v":1},"변리사2018_55-10-3":{"w":"의사무능력에 따른 무효와 미성년에 따른 취소(제5조 제2항)는 요건이 달라 함께 성립할 수 있다(이중효). 취소권자는 어느 쪽이든 선택해 주장할 수 있다.","c":"중","v":1},"변리사2016_53-02-1":{"w":"미성년자가 법정대리인의 동의 없이 한 법률행위는 취소할 수 있고(제5조 제2항) 제140조에 따라 제한능력자 본인도 취소권자다.","c":"상","v":1},"변리사2016_53-02-2":{"w":"민법은 동의의 방식을 정하지 않았다. 판례는 법정대리인의 동의를 묵시적으로도 할 수 있다고 보고 미성년자의 신용구매계약에서 묵시적 동의나 처분허락이 있는지를 따진다.","c":"중","v":1},"변리사2016_53-02-3":{"w":"제10조 제4항은 일용품의 구입 등 일상생활에 필요하고 그 대가가 과도하지 않은 법률행위는 성년후견인이 취소할 수 없다고 정한다.","c":"상","v":1},"변리사2016_53-02-4":{"w":"가정법원은 취소할 수 없는 피성년후견인의 법률행위 범위를 정할 수 있고(제10조 제2항) 그 범위의 행위는 성년후견인의 동의가 없어도 취소할 수 없다.","c":"상","v":1},"변리사2016_53-04-2":{"w":"판례는 제100조 제2항의 종물 법리를 물건과 권리 사이, 권리 상호 간에도 유추적용한다. 건물에 저당권이 설정되면 그 건물 소유를 위한 대지 임차권에도 효력이 미치는 것이 예다.","c":"중","v":1},"변리사2017_54-04-1":{"w":"판례는 지적공부에 1필지로 등록된 토지의 경계는 지적도상 경계로 특정된다고 보며 지적도 작성 과정의 기술적 착오 같은 특별한 사정이 있을 때만 실제 경계를 기준으로 한다.","c":"중","v":1},"변리사2018_55-12-1":{"w":"특정물과 불특정물은 구체적 거래에서 당사자가 물건의 개성을 중시했는지에 따라 나뉜다(주관적 구별). 거래관념상 객관적으로 나뉘는 것은 대체물과 부대체물이다.","c":"중","v":1},"변리사2018_55-12-3":{"w":"제98조는 물건을 유체물 및 전기 기타 관리할 수 있는 자연력으로 정하고 제99조 제2항은 부동산 이외의 물건을 동산으로 정한다.","c":"상","v":1},"변리사2018_55-12-4":{"w":"판례는 건물을 사용해 얻는 이익을 과실에 준하는 것으로 보아 선의 점유자의 과실취득(제201조 제1항)을 적용한다.","c":"중","v":1},"변리사2018_55-12-5":{"w":"미분리 농작물은 토지의 구성부분이지만 명인방법을 갖추면 독립한 거래 객체가 된다. 판례는 수확되지 않은 쪽파를 산 매수인이 명인방법을 갖추어야 소유권을 취득한다고 본다.","c":"중","v":1},"변리사2021_58-05-1":{"w":"제256조 단서는 타인이 권원에 의해 부속시킨 것은 그 타인의 권리로 남는다고 정하지만 판례는 분리하면 경제적 가치가 없을 정도로 부합한 경우(강한 부합)에는 권원이 있어도 부동산 소유자에게 귀속한다고 본다.","c":"중","v":1},"변리사2019_56-04-2":{"w":"제101조 제1항은 물건의 용법에 의하여 수취하는 산출물을 천연과실로 정한다. 물건의 사용대가로 받는 금전 기타의 물건은 법정과실이다(같은 조 제2항).","c":"상","v":1},"변리사2019_56-04-3":{"w":"제102조 제1항은 천연과실이 그 원물로부터 분리하는 때에 이를 수취할 권리자에게 속한다고 정한다.","c":"상","v":1},"변리사2019_56-04-4":{"w":"미분리 과실은 원물의 일부이지만 판례·통설은 명인방법을 갖추면 원물과 별개로 소유권의 객체가 된다고 본다.","c":"중","v":1},"변리사2019_56-04-5":{"w":"제102조 제2항은 법정과실을 수취할 권리의 존속기간 일수의 비율로 취득한다고 정하는데 이는 임의규정이어서 당사자가 다르게 약정할 수 있다.","c":"상","v":1},"변리사2016_53-04-1":{"w":"판례는 주택에서 떨어져 지어졌더라도 주택 사용에 계속 이바지하는 연탄창고·공동변소를 주택의 종물로 본다(제100조 제1항).","c":"중","v":1},"변리사2016_53-04-4":{"w":"제100조 제2항(종물은 주물의 처분에 따른다)은 임의규정이어서 특약으로 종물을 제외할 수 있고 종물도 독립한 물건이므로 따로 처분할 수 있다.","c":"상","v":1},"변리사2016_53-04-5":{"w":"제358조 본문은 저당권의 효력이 저당부동산에 부합된 물건과 종물에 미친다고 정한다. 법률에 특별한 규정이 있거나 설정행위에 다른 약정이 있으면 예외다.","c":"상","v":1},"변리사2024_61-04-5":{"w":"판례상 이미 변제기에 이른 이자채권은 원본채권과 별개로 독립한 채권이므로 원본채권을 양도해도 특별한 의사표시가 없으면 함께 양도되지 않는다.","c":"중","v":1},"변리사2016_53-05-2":{"w":"판례는 제104조의 불공정한 법률행위가 되려면 객관적으로 급부와 반대급부 사이에 현저한 불균형이 있고 주관적으로 상대방이 피해자의 궁박·경솔·무경험을 알고 이용하려는 폭리행위의 악의가 있어야 한다고 본다. 둘 중 하나라도 없으면 성립하지 않는다.","c":"중","v":1},"변리사2016_53-05-4":{"w":"판례는 매매대금이 과다해 불공정한 법률행위로 무효인 경우에도 당사자가 무효임을 알았다면 다른 대금으로 매매를 합의했을 가정적 의사가 인정되면 제138조에 따라 그 대금으로 계약이 유효하게 성립한다고 본다.","c":"중","v":1},"변리사2016_53-05-5":{"w":"제104조는 급부와 반대급부의 현저한 불균형을 전제하므로 판례는 증여처럼 대가관계 없는 일방적 급부 행위는 불공정한 법률행위가 될 수 없다고 본다.","c":"중","v":1},"변리사2016_53-06-1":{"w":"사기에 의한 의사표시는 기망으로 동기가 잘못 형성되었을 뿐 표의자가 내심으로 원한 것과 표시는 일치한다. 이 점에서 의사와 표시가 어긋나는 착오(제109조)와 구별되며 취소 근거는 제110조다.","c":"중","v":1},"변리사2016_53-08-2":{"w":"판례는 대리권이 소멸한 뒤 제129조로 표현대리가 성립하는 범위를 넘어 대리행위를 한 경우에도 그 소멸한 대리권을 기본대리권으로 보아 제126조의 표현대리가 성립할 수 있다고 본다.","c":"중","v":1},"변리사2016_53-08-3":{"w":"제125조 단서는 제3자가 대리권 없음을 알았거나 알 수 있었을 때에는 표현대리 책임이 없다고 정한다. 따라서 상대방은 선의·무과실이어야 한다.","c":"상","v":1},"변리사2016_53-08-4":{"w":"제126조는 대리인이 권한 외의 법률행위를 한 경우 제3자가 그 권한이 있다고 믿을 만한 정당한 이유가 있는 때 본인이 책임을 진다고 정한다.","c":"상","v":1},"변리사2016_53-08-5":{"w":"제125조 본문은 제3자에 대하여 타인에게 대리권을 수여함을 표시한 자는 그 대리권 범위 내에서 한 그 타인과 제3자 간의 법률행위에 대하여 책임이 있다고 정한다.","c":"상","v":1},"변리사2016_53-10-4":{"w":"복대리인도 본인의 대리인이므로 대리인의 행위능력에 관한 제117조가 그대로 적용된다. 대리행위의 효과는 본인에게 귀속하므로 복대리인에게 불이익이 없다.","c":"상","v":1},"변리사2016_53-10-5":{"w":"판례는 채권자를 특정하지 않고 부동산을 담보로 금전 차용을 위임한 경우 누구에게서 빌리든 상관없다는 뜻이므로 본인의 의사에 복대리인 선임에 대한 승낙(제120조)이 포함되어 있다고 본다.","c":"중","v":1},"변리사2017_54-08-1":{"w":"판례는 무권대리행위의 추인을 무권대리인, 상대방, 그 승계인 누구에게나 할 수 있다고 본다. 다만 무권대리인에게 한 추인은 상대방이 알 때까지 상대방에게 대항하지 못한다(제132조).","c":"상","v":1},"변리사2017_54-08-2":{"w":"추인은 방식의 제한이 없어 묵시적으로도 할 수 있다. 판례는 본인이 무권대리인의 처분행위와 문서위조를 불문에 붙이기로 한 경우처럼 무권대리행위를 인정하는 사정이 있으면 묵시적 추인을 인정한다.","c":"중","v":1},"변리사2017_54-08-4":{"w":"제134조는 대리권 없는 자가 한 계약은 본인의 추인이 있을 때까지 상대방이 본인이나 그 대리인에게 철회할 수 있되 계약 당시 대리권 없음을 안 때에는 철회할 수 없다고 정한다.","c":"상","v":1},"변리사2017_54-08-5":{"w":"제131조 후단은 본인이 최고 기간 내에 확답을 발하지 않으면 추인을 거절한 것으로 본다고 정한다.","c":"상","v":1},"변리사2018_55-11-3":{"w":"복대리인의 대리권은 대리인의 대리권을 전제로 하므로 대리권 소멸 후 선임된 복대리인은 무권대리인이다. 판례는 이 경우에도 상대방이 대리권 소멸을 과실 없이 몰랐다면 제129조의 표현대리가 성립할 수 있다고 본다.","c":"중","v":1},"변리사2019_56-06-2":{"w":"제107조 제1항 단서에 따라 비진의표시는 상대방이 진의 아님을 알았거나 알 수 있었을 경우에만 무효다. 판례는 무효를 주장하는 표의자가 상대방의 악의·과실을 증명해야 한다고 본다.","c":"중","v":1},"변리사2019_56-06-5":{"w":"제112조 본문은 의사표시의 상대방이 의사표시를 받은 때에 제한능력자이면 의사표시자가 그 의사표시로 대항할 수 없다고 정한다. 다만 상대방의 법정대리인이 도달 사실을 안 후에는 대항할 수 있다(같은 조 단서).","c":"상","v":1},"변리사2021_58-07-1":{"w":"판례는 대금 과다로 불공정한 법률행위가 되어 무효인 매매계약에도 제138조를 적용할 수 있다고 보며 당사자의 가정적 의사로 정해지는 대금으로 계약이 유효하게 성립한다고 한다.","c":"중","v":1},"변리사2021_58-09-1":{"w":"판례는 매매계약 체결의 대리권에 계약을 해제할 권한까지 포함되지는 않는다고 본다.","c":"중","v":1},"변리사2021_58-09-2":{"w":"제117조는 대리인이 행위능력자임을 요하지 않는다고 정한다. 대리행위의 효과는 본인에게 귀속하므로 본인은 대리인의 제한능력을 이유로 취소하지 못한다.","c":"상","v":1},"변리사2021_58-09-4":{"w":"판례는 매매계약 체결의 대리권에 상대방으로부터 대금을 수령할 권한이 포함된다고 본다. 대리인의 수령은 본인의 수령과 같아 본인에게 전달하지 않았어도 매수인의 대금채무는 소멸한다.","c":"중","v":1},"변리사2021_58-09-5":{"w":"판례는 매매계약의 체결과 이행에 관한 포괄적 대리권을 받은 대리인은 특별한 사정이 없으면 약정된 매매대금 지급기일을 연기해 줄 권한도 가진다고 본다.","c":"중","v":1},"변리사2021_58-10-3":{"w":"취소의 의사표시는 특별한 방식이 없다. 판례는 법률행위가 취소되었음을 전제로 한 이행청구나 이행거절에도 취소의 의사표시가 포함되어 있다고 본다.","c":"중","v":1},"변리사2021_58-11-1":{"w":"판례는 토지거래허가 전의 매매계약을 유동적 무효로 보면서도 당사자 사이에 허가신청절차에 협력할 의무가 있어 상대방이 협력하지 않으면 그 이행을 소구할 수 있다고 본다.","c":"중","v":1},"변리사2021_58-11-2":{"w":"판례상 허가 전에는 계약의 채권적 효력이 없으므로 협력의무를 이행하지 않았다고 매매계약 자체를 해제할 수는 없다. 협력의무 불이행에 따른 손해배상은 청구할 수 있다.","c":"중","v":1},"변리사2021_58-11-3":{"w":"판례는 허가를 받기 전의 유동적 무효 상태라도 당사자 쌍방이 허가신청 협력의무의 이행거절 의사를 명백히 표시하면 계약이 확정적으로 무효가 된다고 본다.","c":"중","v":1},"변리사2021_58-11-4":{"w":"판례는 유동적 무효 상태의 계약도 사기·착오를 이유로 취소할 수 있으며 취소하면 계약이 확정적으로 무효가 되어 허가신청 협력의무를 면한다고 본다.","c":"중","v":1},"변리사2021_58-12-2":{"w":"제131조의 최고권은 상대방의 선의·악의를 묻지 않는다. 선의 상대방에게만 인정되는 것은 제134조의 철회권이다.","c":"상","v":1},"변리사2023_60-08-1":{"w":"통정허위표시는 무효이지만 판례는 채무자의 책임재산을 감소시키는 행위인 이상 채권자취소권(제406조)의 대상이 될 수 있다고 본다.","c":"중","v":1},"변리사2023_60-08-2":{"w":"판례는 임대차보증금반환채권을 담보할 목적의 전세권설정계약을 유효하다고 보면서 임대차계약과 양립할 수 없는 범위(예: 전세권 존속 중 차임 지급 약정 부분)에서만 통정허위표시로 무효라고 본다.","c":"중","v":1},"변리사2023_60-08-3":{"w":"판례는 대출기관과 실제 차주 사이에 명의대여자에게는 법률효과를 귀속시키지 않기로 하는 의사의 합치가 있으면 명의대여자 명의의 대출계약을 제108조의 통정허위표시로 본다.","c":"중","v":1},"변리사2023_60-08-5":{"w":"판례는 파산관재인을 제108조 제2항의 제3자로 보고 선의 여부는 총파산채권자를 기준으로 판단하므로 파산채권자 모두가 악의가 아닌 한 파산관재인 개인이 악의여도 선의로 다룬다.","c":"중","v":1},"변리사2024_61-06-1":{"w":"제110조 제2항은 상대방 있는 의사표시에 관하여 제3자가 사기나 강박을 한 경우 상대방이 그 사실을 알았거나 알 수 있었을 경우에 한하여 취소할 수 있다고 정한다.","c":"상","v":1},"변리사2024_61-06-4":{"w":"판례는 경과실로 착오를 일으킨 표의자가 제109조에 따라 취소하는 것은 법이 허용한 행위로서 위법성이 없으므로 상대방에 대해 불법행위책임을 지지 않는다고 본다.","c":"중","v":1},"변리사2024_61-06-5":{"w":"제109조 제1항 단서가 중대한 과실 있는 표의자의 취소를 막는 것은 상대방 보호를 위한 것이므로 판례는 상대방이 착오를 알고 이용한 경우에는 중과실이 있어도 취소할 수 있다고 본다.","c":"중","v":1},"변리사2024_61-08-2":{"w":"제122조 단서는 법정대리인이 부득이한 사유로 복대리인을 선임한 때에는 제121조 제1항의 선임감독에 관한 책임만 있다고 정한다.","c":"상","v":1},"변리사2024_61-08-3":{"w":"제120조는 대리권이 법률행위로 부여된 경우 대리인은 본인의 승낙이 있거나 부득이한 사유가 있는 때가 아니면 복대리인을 선임하지 못한다고 정한다.","c":"상","v":1},"변리사2024_61-08-4":{"w":"제121조 제1항은 임의대리인이 제120조에 따라 복대리인을 선임한 때 본인에게 그 선임감독에 관한 책임이 있다고 정한다.","c":"상","v":1},"변리사2024_61-08-5":{"w":"판례는 대리의 목적인 법률행위의 성질상 대리인 자신이 처리할 필요가 없는 경우에는 본인이 복대리 금지를 명시하지 않는 한 복대리인 선임에 관한 묵시적 승낙이 있다고 본다. 반대로 아파트 분양처럼 대리인의 능력이 중요한 사무는 묵시적 승낙을 쉽게 인정하지 않는다.","c":"중","v":1},"변리사2024_61-09-1":{"w":"본인이 추인하면 계약은 계약 시에 소급해 본인에게 효력이 생기므로(제133조) 丙은 乙에게 계약상 책임을 묻는다. 제135조의 무권대리인 책임은 본인의 추인을 얻지 못한 경우에만 성립한다.","c":"상","v":1},"변리사2024_61-09-2":{"w":"무권대리인에게 한 추인은 상대방이 그 사실을 알 때까지 상대방에게 대항하지 못하므로(제132조) 丙은 여전히 철회할 수 있다. 철회는 계약 당시 대리권 없음을 몰랐던 상대방만 할 수 있다(제134조 단서).","c":"상","v":1},"변리사2024_61-09-3":{"w":"제135조 제1항의 무권대리인 책임은 판례상 무과실책임이어서 무권대리인에게 과실이 없어도 성립한다. 상대방이 대리권 없음을 알았거나 알 수 있었으면 책임이 없다(같은 조 제2항).","c":"상","v":1},"변리사2024_61-09-4":{"w":"제135조 제1항에 따라 상대방은 무권대리인에게 계약의 이행 또는 손해배상을 청구할 수 있다. 판례는 계약에 위약금 약정이 있으면 무권대리인이 손해배상으로 그 위약금 약정의 효력을 그대로 부담한다고 본다.","c":"중","v":1},"변리사2024_61-10-4":{"w":"제140조는 하자 있는 의사표시를 한 자의 승계인도 취소권자로 정한다. 건물양수인은 전세권설정자의 지위를 승계했으므로 사기를 이유로 전세권설정계약을 취소할 수 있다.","c":"중","v":1},"변리사2026_63-05-1":{"w":"판례는 불공정한 법률행위에 해당하는지를 법률행위가 이루어진 시점을 기준으로 판단하며 그 후 사정 변화로 불균형이 생겨도 불공정한 법률행위가 되지 않는다고 본다.","c":"중","v":1},"변리사2026_63-05-2":{"w":"판례는 매매계약이 제104조로 무효이면 그 계약에 관한 부제소합의 역시 같은 이유로 무효라고 본다.","c":"중","v":1},"변리사2026_63-05-4":{"w":"판례는 불공정한 법률행위로 무효인 매매계약에도 제138조를 적용해 당사자가 무효를 알았다면 의욕했을 가정적 의사가 있으면 그 내용으로 계약이 유효하게 된다고 본다.","c":"중","v":1},"변리사2026_63-06-3":{"w":"동기의 착오는 원칙적으로 동기가 표시되어 법률행위 내용이 되어야 취소할 수 있지만 판례는 상대방이 부정한 방법으로 유발한 동기의 착오는 표시되지 않았어도 제109조로 취소할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-06-5":{"w":"판례는 재단법인 설립을 위한 서면 출연행위도 상대방 없는 단독행위로서 착오 취소의 대상이 되며 법인이 성립하고 출연재산이 기본재산이 되었더라도 제109조 요건을 갖추면 취소할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-08-1":{"w":"제125조의 대리권 수여 표시는 반드시 대리권이라는 말을 쓸 필요가 없다. 판례는 사회통념상 대리권을 추단할 수 있는 직함이나 명칭의 사용을 본인이 승낙·묵인한 경우에도 대리권 수여의 표시가 있다고 본다.","c":"중","v":1},"변리사2026_63-09-1":{"w":"제131조의 최고권은 상대방의 선의·악의를 묻지 않는다. 계약 당시 무권대리임을 안 상대방이 할 수 없는 것은 제134조의 철회다.","c":"상","v":1},"변리사2026_63-09-3":{"w":"판례는 무권대리행위의 일부만 추인하거나 내용을 변경해 추인하면 상대방의 동의를 얻지 못하는 한 무효라고 본다.","c":"중","v":1},"변리사2026_63-09-4":{"w":"제132조는 추인 또는 거절의 의사표시를 상대방에게 하지 않으면 그 상대방에게 대항하지 못하되 상대방이 그 사실을 안 때에는 그렇지 않다고 정한다.","c":"상","v":1},"변리사2026_63-09-5":{"w":"판례는 무권대리인이 본인을 단독상속한 뒤 본인의 지위에서 추인을 거절하고 무효를 주장하는 것은 금반언·신의칙에 반해 허용되지 않는다고 본다.","c":"중","v":1},"변리사2019_56-11-1":{"w":"제117조는 대리인이 행위능력자임을 요하지 않는다고 정한다. 대리행위의 효과는 본인에게 귀속하고 대리인에게는 미치지 않으므로 제한능력자를 보호할 필요가 없다.","c":"상","v":1},"변리사2019_56-11-2":{"w":"판례(전원합의체)는 유권대리 주장에 표현대리 주장이 포함되지 않는다고 보므로 표현대리의 성립은 이를 주장하는 상대방 丙이 주장·증명해야 한다.","c":"중","v":1},"변리사2019_56-11-4":{"w":"판례는 대리인이 본인을 가장해 본인 명의로 직접 법률행위를 한 경우에도 상대방이 그를 본인으로 믿을 정당한 이유가 있으면 제126조를 유추적용한다고 본다.","c":"중","v":1},"변리사2019_56-11-5":{"w":"수권행위는 불요식이어서 묵시적으로도 할 수 있다. 판례는 본인이 타인의 대리인 행세를 알면서 이의 없이 방임한 경우처럼 사실상의 용태로 대리권 수여를 추단한다.","c":"중","v":1},"변리사2017_54-07-1":{"w":"판례는 매매계약 체결의 대리권을 받은 대리인에게 특별한 사정이 없으면 그 계약에 따른 중도금·잔금을 수령할 권한도 있다고 본다.","c":"중","v":1},"변리사2017_54-07-2":{"w":"판례상 매매계약 체결의 대리권만 받은 대리인은 특별한 사정이 없으면 약정된 대금 지급기일을 연기해 줄 권한이 없다. 체결과 이행에 관한 포괄적 대리권을 받은 경우와 구별된다.","c":"중","v":1},"변리사2017_54-07-3":{"w":"계약의 효력이 본인에게 미친다고 주장하는 쪽이 대리권의 존재를 증명해야 한다. 丙이 甲에게 이전등기를 청구하므로 乙의 대리권 존재에 대한 증명책임은 丙에게 있다.","c":"중","v":1},"변리사2017_54-07-4":{"w":"제115조 단서는 대리인이 본인을 위한 것임을 표시하지 않았어도 상대방이 대리인으로서 한 것임을 알았거나 알 수 있었을 때에는 본인에게 효력이 있다고 정한다.","c":"상","v":1},"변리사2019_56-09-2":{"w":"상대방이 제134조에 따라 철회하면 무권대리 계약은 확정적으로 무효가 되므로 본인은 그 뒤에 추인할 수 없다.","c":"중","v":1},"변리사2019_56-09-3":{"w":"제132조에 따라 무권대리인에게 한 추인은 상대방이 알 때까지 대항하지 못한다. 그 사이 상대방은 제134조로 철회할 수 있다.","c":"상","v":1},"변리사2019_56-09-4":{"w":"판례는 상대방의 철회가 제134조 단서로 효력이 없다고 다투는 본인이 상대방이 계약 당시 대리권 없음을 알았다는 사실을 증명해야 한다고 본다.","c":"중","v":1},"변리사2019_56-09-5":{"w":"판례는 무권대리인이 본인을 단독상속한 경우 본인의 지위에서 무권대리행위의 무효를 주장하는 것은 금반언·신의칙에 반해 허용되지 않는다고 본다.","c":"중","v":1},"변리사2023_60-07-4":{"w":"판례는 제104조의 불공정한 법률행위가 되려면 상대방이 피해자의 궁박 등을 알고 이를 이용하려는 폭리행위의 악의가 있어야 한다고 본다.","c":"중","v":1},"변리사2023_60-10-2":{"w":"판례는 대리권 남용에 제107조 제1항 단서를 유추적용해 무효로 보면서 그 무효를 선의의 제3자에게 대항하지 못하도록 같은 조 제2항도 유추적용한다.","c":"중","v":1},"변리사2017_54-10-2":{"w":"조건은 법률행위의 부관이어서 법률효과의 발생을 막는 사유가 되므로 판례는 정지조건이 붙었다는 사실을 그 존재를 주장하는 쪽이 증명해야 한다고 본다.","c":"중","v":1},"변리사2017_54-10-3":{"w":"제151조 제3항은 조건이 법률행위 당시 이미 성취할 수 없는 것인 경우 해제조건이면 조건 없는 법률행위로 하고 정지조건이면 그 법률행위를 무효로 한다고 정한다.","c":"상","v":1},"변리사2017_54-10-4":{"w":"제147조 제3항은 당사자가 조건성취의 효력을 성취 전에 소급하게 할 의사를 표시한 때에는 그 의사에 의한다고 정한다.","c":"상","v":1},"변리사2017_54-10-5":{"w":"제151조 제1항은 조건이 선량한 풍속 기타 사회질서에 위반한 것이면 그 법률행위는 무효라고 정한다. 판례도 불법조건이 붙은 법률행위는 조건만 무효가 아니라 법률행위 전부가 무효라고 본다.","c":"상","v":1},"변리사2017_54-09-1":{"w":"제104조는 「궁박, 경솔 또는 무경험」으로 정해 셋 중 하나만 있어도 된다는 것이 판례다.","c":"중","v":1},"변리사2017_54-09-2":{"w":"판례는 궁박을 급박한 곤궁으로 보고 경제적 원인뿐 아니라 정신적·심리적 원인에 기인한 것도 포함한다고 본다.","c":"중","v":1},"변리사2017_54-09-4":{"w":"판례는 제104조의 주관적 요건으로 피해자에게 궁박·경솔·무경험이 있는 것만으로는 부족하고 폭리자가 그 사정을 알면서 이용하려는 의사(폭리행위의 악의)가 있어야 한다고 본다.","c":"중","v":1},"변리사2017_54-09-5":{"w":"판례는 불공정한 법률행위의 무효는 절대적 무효여서 추인으로 유효가 될 수 없다고 보면서도 제138조의 무효행위 전환은 적용할 수 있다고 본다.","c":"중","v":1},"변리사2018_55-05-1":{"w":"도박자금 대여는 제103조 위반으로 무효이고 이미 준 금전은 불법원인급여(제746조)여서 반환을 청구할 수 없다.","c":"상","v":1},"변리사2018_55-05-2":{"w":"제103조 위반의 무효는 절대적 무효여서 선의의 제3자에게도 대항할 수 있고 무효를 주장할 이익이 있는 사람은 누구나 주장할 수 있다.","c":"중","v":1},"변리사2018_55-05-3":{"w":"판례는 강박이라는 불법적 방법이 법률행위 성립 과정에 쓰인 데 불과한 경우는 의사표시의 하자 문제로서 제110조로 취소할 수 있을 뿐 제103조의 반사회질서행위로 무효가 되지는 않는다고 본다.","c":"중","v":1},"변리사2018_55-05-4":{"w":"판례는 본처가 남편의 과거 부첩관계를 용서한 것이 손해배상청구권의 포기로 해석되면 그 효력을 인정한다. 장래의 부첩관계를 사전에 승인하는 약정과 달리 제103조에 반하지 않는다.","c":"중","v":1},"변리사2016_53-09-1":{"w":"취소는 상대방에 대한 의사표시로 하며(제142조) 특별한 방식이 없다. 판례는 법률행위의 효력을 처음부터 배제하려는 의사가 드러나면 취소의 의사표시가 있다고 본다.","c":"중","v":1},"변리사2016_53-09-2":{"w":"판례는 토지거래허가를 일정 기간 안에 받기로 약정했더라도 그 기간이 지났다는 사정만으로 곧바로 계약이 확정적으로 무효가 되지 않는다고 본다. 그 기간을 넘기면 계약을 무효로 하기로 하는 취지의 약정으로 볼 특별한 사정이 있어야 한다.","c":"중","v":1},"변리사2016_53-09-3":{"w":"판례는 법률행위의 취소를 당연한 전제로 한 소송상의 이행청구나 이행거절에 취소의 의사표시가 포함되어 있다고 본다.","c":"중","v":1},"변리사2016_53-09-5":{"w":"판례는 징계해임과 직권해임은 사유와 절차가 다른 별개 처분이므로 무효인 징계해임을 직권해임으로 전환해 효력을 인정할 수 없다고 본다.","c":"중","v":1},"변리사2018_55-02-2":{"w":"제142조는 취소할 수 있는 법률행위의 상대방이 확정된 경우 그 취소는 그 상대방에 대한 의사표시로 하도록 정한다.","c":"상","v":1},"변리사2019_56-05-2":{"w":"제108조 제2항은 선의의 제3자라고만 정한다. 판례는 제3자는 선의이면 족하고 무과실은 요건이 아니라고 보며 제3자의 선의는 추정된다.","c":"중","v":1},"변리사2021_58-04-1":{"w":"제493조 제1항 후단은 상계의 의사표시에 조건 또는 기한을 붙이지 못한다고 정한다. 상계는 소급효가 있어(제493조 제2항) 기한을 붙이는 것이 무의미하다.","c":"상","v":1},"변리사2021_58-04-2":{"w":"현상광고(제675조)는 광고자가 지정행위를 완료한 자에게 보수를 주기로 하는 계약으로, 지정행위의 완료에 조건이나 기한을 붙이지 못하게 하는 규정이 없다. 우수현상광고는 오히려 응모기간을 정해야 효력이 있다(제678조 제1항).","c":"중","v":1},"변리사2021_58-04-4":{"w":"제150조 제2항은 조건의 성취로 이익을 받을 당사자가 신의성실에 반하여 조건을 성취시킨 때에는 상대방이 그 조건이 성취하지 아니한 것으로 주장할 수 있다고 정한다.","c":"상","v":1},"변리사2021_58-04-5":{"w":"판례는 부관에 표시된 사실이 발생하지 않는 것으로 확정된 때에도 채무를 이행해야 한다고 보는 것이 상당하면 그 부관은 조건이 아니라 불확정기한으로 본다.","c":"중","v":1},"변리사2021_58-10-2":{"w":"제145조 제5호의 법정추인 사유는 「취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도」이며 판례·통설상 취소권자가 양도한 경우에만 해당한다. 상대방이 양도한 것은 법정추인이 아니다.","c":"상","v":1},"변리사2021_58-10-4":{"w":"제145조 제2호는 추인할 수 있는 후에 이의를 보류하지 않고 이행청구를 하면 추인한 것으로 본다고 정한다. 판례·통설은 취소권자가 이행을 청구한 경우만 여기에 해당한다고 본다.","c":"상","v":1},"변리사2021_58-10-5":{"w":"제143조 제1항은 취소권자가 추인할 수 있고 추인 후에는 취소하지 못한다고 정한다. 추인은 취소권의 포기여서 그 뒤로는 법률행위가 확정적으로 유효하다.","c":"상","v":1},"변리사2016_53-10-2":{"w":"제120조에 따라 임의대리인은 본인의 승낙이 있거나 부득이한 사유가 있는 때가 아니면 복대리인을 선임하지 못한다.","c":"상","v":1},"변리사2016_53-10-3":{"w":"제122조 본문은 법정대리인이 그 책임으로 복대리인을 선임할 수 있다고 정한다. 법정대리인은 본인의 신임으로 선임된 것이 아니고 사임도 쉽지 않아 임의대리인과 달리 복임권이 제한 없이 인정된다.","c":"상","v":1},"변리사2023_60-11-1":{"w":"판례는 토지거래허가를 받기 전의 매매계약은 채권적 효력도 없는 유동적 무효이고 허가를 받으면 계약 시로 소급해 유효가 된다고 본다.","c":"중","v":1},"변리사2023_60-11-2":{"w":"판례는 허가구역 내 토지의 매수인 지위를 제3자에게 이전하는 3자 합의는 최초 매매계약에 대한 관할관청의 허가가 있어야 효력이 생긴다고 본다. 최초 매도인과 최종 매수인 사이의 매매로 보아 허가를 받는 것은 허용되지 않는다.","c":"중","v":1},"변리사2023_60-11-3":{"w":"판례는 매수인이 매도인에 대해 가지는 토지거래허가 신청절차 협력의무 이행청구권을 피보전권리로 하여 매도인의 권리를 대위행사(제404조)할 수 있다고 본다.","c":"중","v":1},"변리사2023_60-11-4":{"w":"판례는 토지거래허가를 받은 것만으로는 이행에 착수한 것이 아니므로 허가 후에도 당사자가 이행에 착수하기 전이면 매수인은 계약금을 포기하고 제565조에 따라 해제할 수 있다고 본다.","c":"중","v":1},"변리사2024_61-11-3":{"w":"판례는 토지거래허가를 받지 못한 계약이 확정적으로 무효가 되면 무효가 된 데 책임 있는 당사자도 무효를 주장할 수 있고 이를 신의칙 위반으로 보지 않는다.","c":"중","v":1},"변리사2016_53-05-3":{"w":"판례는 대리인이 법률행위를 한 경우 경솔·무경험은 대리인을 기준으로, 궁박은 본인의 입장에서 판단한다.","c":"중","v":1},"변리사2026_63-05-5":{"w":"판례는 대리인이 법률행위를 한 경우 경솔과 무경험은 대리인을 기준으로 판단하고 궁박은 본인을 기준으로 판단한다.","c":"중","v":1},"변리사2017_54-06-1":{"w":"판례는 소송행위에 민법의 의사표시 하자 규정이 적용되지 않는다고 보아 강박으로 소를 취하했더라도 제110조로 취소할 수 없다고 본다. 다만 형사처벌될 행위로 소송행위를 하게 된 경우에는 재심사유(민사소송법 제451조 제1항 제5호)에 준해 무효가 될 수 있다.","c":"중","v":1},"변리사2017_54-06-2":{"w":"타인 물건 매매도 유효(제569조)하지만 판례는 매도인의 기망으로 타인 물건을 매도인 것으로 알고 산 매수인은 그 사실을 알았으면 사지 않았을 경우 제110조로 취소할 수 있고 담보책임 규정이 이를 배제하지 않는다고 본다.","c":"중","v":1},"변리사2017_54-06-4":{"w":"판례는 은행 출장소장처럼 상대방과 동일시할 수 있는 자의 사기는 제110조 제2항의 제3자의 사기가 아니라고 본다. 따라서 은행의 악의·과실과 관계없이 제110조 제1항으로 취소할 수 있다.","c":"중","v":1},"변리사2017_54-06-5":{"w":"판례는 강박이 불법행위도 되는 경우 취소에 따른 부당이득반환청구권과 불법행위 손해배상청구권이 경합해 선택적으로 행사할 수 있지만 이중으로 만족을 얻을 수는 없다고 본다.","c":"중","v":1},"변리사2016_53-06-2":{"w":"판례는 상대방의 대리인처럼 상대방과 동일시할 수 있는 자의 사기는 제110조 제2항의 제3자의 사기에 해당하지 않는다고 본다.","c":"중","v":1},"변리사2016_53-06-3":{"w":"판례는 광고에 다소 과장이 있어도 일반 상거래 관행상 용인될 정도면 기망이 아니지만 중요한 사항에 관하여 구체적 사실을 신의칙상 비난받을 방법으로 허위 고지하면 기망행위가 된다고 본다.","c":"중","v":1},"변리사2016_53-06-4":{"w":"판례는 사기에 의한 법률행위가 불법행위도 되는 경우 취소에 따른 부당이득반환청구권과 불법행위 손해배상청구권이 경합하여 병존하고 채권자는 어느 쪽이든 선택해 행사할 수 있다고 본다.","c":"중","v":1},"변리사2019_56-06-3":{"w":"판례는 통정허위표시로 무효인 법률행위도 채무자의 책임재산을 감소시키면 사해행위가 될 수 있어 채권자는 제406조의 채권자취소권을 행사할 수 있다고 본다.","c":"중","v":1},"변리사2019_56-06-4":{"w":"판례는 허위표시 외형을 기초로 새로 이해관계를 맺은 전득자도 제108조 제2항의 제3자에 포함된다고 본다. 직전 제3자가 악의여도 전득자가 선의이면 전득자에게 무효를 주장하지 못한다.","c":"중","v":1},"변리사2024_61-06-3":{"w":"통정허위표시는 당사자 사이에서 무효이므로(제108조 제1항) 이행할 채무 자체가 생기지 않고 채무불이행에 따른 손해배상(제390조)도 청구할 수 없다.","c":"상","v":1},"변리사2026_63-06-1":{"w":"판례는 통정허위표시로 무효인 법률행위도 채권자를 해하는 것이면 채권자취소권(제406조)의 대상이 된다고 본다.","c":"중","v":1},"변리사2026_63-06-2":{"w":"판례는 매도인이 채무불이행으로 계약을 해제한 뒤에도 매수인이 해제에 따른 손해배상책임 등을 피하기 위해 착오를 이유로 계약을 취소할 수 있다고 본다.","c":"중","v":1},"변리사2016_53-07-1":{"w":"판례는 준법률행위인 통지도 의사표시와 마찬가지로 상대방이 사회통념상 그 내용을 알 수 있는 객관적 상태에 놓였을 때 도달한 것으로 보며 상대방이 실제로 알았는지는 묻지 않는다.","c":"중","v":1},"변리사2016_53-07-2":{"w":"제111조 제1항은 상대방 있는 의사표시가 상대방에게 도달한 때 효력이 생긴다고 정한다. 판례는 상대방이 정당한 사유 없이 수령을 거절해도 그 내용을 알 수 있는 객관적 상태에 놓인 때 의사표시의 효력이 생긴다고 본다.","c":"상","v":1},"변리사2016_53-07-3":{"w":"판례는 채권양도 통지가 채무자의 주소·거소·영업소가 아닌 곳에서 이루어졌더라도 채무자가 사회통념상 그 통지의 내용을 알 수 있는 객관적 상태에 놓였으면 효력이 생긴다고 본다.","c":"중","v":1},"변리사2016_53-07-5":{"w":"제111조 제2항에 따라 표의자가 발송 후 사망해도 의사표시의 효력에 영향이 없으므로 의사표시는 그대로 도달할 수 있다. 상속인은 표의자의 지위를 승계하므로 도달 전이면 철회할 수 있다.","c":"상","v":1},"변리사2024_61-07-1":{"w":"제111조 제1항은 상대방이 있는 의사표시는 상대방에게 도달한 때에 그 효력이 생긴다고 정한다.","c":"상","v":1},"변리사2024_61-07-2":{"w":"제111조 제2항은 의사표시자가 그 통지를 발송한 후 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향을 미치지 않는다고 정한다.","c":"상","v":1},"변리사2024_61-07-4":{"w":"판례는 상대방이 정당한 사유 없이 등기우편 수취를 거부해 객관적 상태의 형성을 방해한 것이 신의칙에 반하면 수취 거부 시에 의사표시의 효력이 생긴 것으로 본다.","c":"중","v":1},"변리사2024_61-07-5":{"w":"도달은 상대방이 그 내용을 알 수 있는 객관적 상태에 놓이는 것이다. 판례는 가사도우미가 받은 미개봉 우편물을 표의자가 곧바로 회수해 간 경우에는 그런 상태가 형성되지 않아 도달로 볼 수 없다고 본다.","c":"중","v":1},"변리사2016_53-11-1":{"w":"불확정기한은 발생이 확실한 사실에 이행기를 맡긴 것이어서 채무는 이미 발생해 있고 이행기만 유예된다. 조건과 달리 법률효과의 발생 자체가 불확실하지 않다.","c":"하","v":1},"변리사2016_53-11-2":{"w":"제151조 제2항은 조건이 법률행위 당시 이미 성취한 것인 경우 정지조건이면 조건 없는 법률행위로 하고 해제조건이면 그 법률행위를 무효로 한다고 정한다.","c":"상","v":1},"변리사2016_53-11-3":{"w":"판례는 조건은 법률행위 내용의 일부로서 의사표시로 외부에 표시되어야 하고 표시되지 않은 내심의 조건은 법률행위의 동기에 불과하다고 본다.","c":"중","v":1},"변리사2016_53-11-5":{"w":"판례는 부관에 표시된 사실이 발생하지 않으면 채무를 이행하지 않아도 된다고 보는 것이 상당하면 조건으로, 발생하지 않는 것으로 확정되어도 이행해야 한다고 보는 것이 상당하면 불확정기한으로 본다.","c":"중","v":1},"변리사2019_56-12-1":{"w":"제152조 제2항은 종기 있는 법률행위가 기한이 도래한 때부터 그 효력을 잃는다고 정한다.","c":"상","v":1},"변리사2019_56-12-2":{"w":"제153조 제2항은 기한의 이익을 포기할 수 있으나 상대방의 이익을 해하지 못한다고 정한다.","c":"상","v":1},"변리사2019_56-12-4":{"w":"제148조는 조건 있는 법률행위의 당사자가 조건의 성부가 미정한 동안 조건의 성취로 생길 상대방의 이익을 해하지 못한다고 정한다.","c":"상","v":1},"변리사2019_56-12-5":{"w":"제150조 제1항은 조건의 성취로 불이익을 받을 당사자가 신의성실에 반하여 조건의 성취를 방해한 때 상대방이 그 조건이 성취한 것으로 주장할 수 있다고 정한다.","c":"상","v":1},"변리사2023_60-12-2":{"w":"판례는 동산 소유권유보부 매매에서 목적물을 인도하더라도 소유권이전의 물권적 합의는 대금 완납을 정지조건으로 성립하며 대금이 모두 지급될 때까지 매도인이 소유권을 가진다고 본다.","c":"중","v":1},"변리사2023_60-12-3":{"w":"부첩관계는 제103조에 반하므로 그 종료를 해제조건으로 하는 증여는 부첩관계의 유지를 강제하는 불법조건이 붙은 것이다. 제151조 제1항에 따라 증여계약 전체가 무효다.","c":"중","v":1},"변리사2023_60-12-4":{"w":"판례는 불확정기한의 경우 기한으로 정한 사실이 발생한 때뿐 아니라 그 사실의 발생이 불가능한 것으로 확정된 때에도 기한이 도래한 것으로 본다.","c":"중","v":1},"변리사2023_60-12-5":{"w":"판례는 기한이익 상실 특약을 정지조건부 특약(사유 발생 즉시 이행기 도래)과 형성권적 특약(채권자의 의사표시로 이행기 도래)으로 나누고 명백히 정지조건부로 볼 사정이 없으면 채권자에게 유리한 형성권적 기한이익 상실 특약으로 추정한다.","c":"중","v":1},"변리사2019_56-07-3":{"w":"제146조는 취소권을 추인할 수 있는 날부터 3년 내에, 법률행위를 한 날부터 10년 내에 행사하도록 정한다. 착오 취소도 같다.","c":"상","v":1},"변리사2021_58-08-4":{"w":"판례는 제109조 제1항 단서가 상대방을 보호하려는 규정이므로 상대방이 표의자의 착오를 알고 이용한 경우에는 표의자에게 중과실이 있어도 취소할 수 있다고 본다.","c":"중","v":1},"변리사2023_60-09-1":{"w":"자연적 해석은 표의자의 실제 의사대로 법률행위를 확정하므로 당사자가 같은 뜻으로 이해했다면 잘못 표시해도(오표시무해) 의사와 표시의 불일치가 생기지 않는다. 그래서 표시상의 착오가 문제되지 않는다.","c":"중","v":1},"변리사2023_60-09-2":{"w":"화해계약은 착오를 이유로 취소하지 못하지만 화해 당사자의 자격 또는 화해 목적인 분쟁 이외의 사항에 착오가 있으면 예외다(제733조). 수술과 증세의 인과관계는 화해의 목적인 분쟁 그 자체이므로 취소할 수 없다는 것이 판례다.","c":"중","v":1},"변리사2023_60-09-3":{"w":"판례는 계약이 해제되어 실효된 뒤에도 해제에 따른 불이익(손해배상 등)을 면하려고 착오를 이유로 취소할 수 있다고 본다.","c":"중","v":1},"변리사2023_60-09-4":{"w":"판례는 하나의 법률행위 일부에만 착오가 있고 나머지 부분만으로도 법률행위를 했을 것이라는 가정적 의사가 인정되면 일부무효(제137조)의 법리를 유추해 일부취소를 인정한다.","c":"중","v":1},"변리사2016_53-12-2":{"w":"판례는 수급인의 하자담보책임 존속기간(제670조, 제671조)을 재판상 또는 재판 외 권리행사기간인 제척기간으로 본다.","c":"중","v":1},"변리사2016_53-12-3":{"w":"판례는 제146조의 취소권 행사기간을 제척기간으로 보며 제척기간 경과 여부는 당사자 주장이 없어도 법원이 직권으로 조사해야 한다고 본다.","c":"중","v":1},"변리사2016_53-12-4":{"w":"판례는 매매예약완결권을 형성권으로 보아 그 행사기간(약정이 없으면 예약 성립 시부터 10년)을 제척기간으로 보며 제척기간에는 시효와 같은 중단이 없다.","c":"중","v":1},"변리사2016_53-12-5":{"w":"판례는 점유보호청구권의 1년 기간(제204조 제3항, 제205조 제2항)을 반드시 그 기간 내에 소를 제기해야 하는 출소기간으로 본다.","c":"중","v":1},"변리사2017_54-11-1":{"w":"제164조 제1호는 여관·음식점·대석·오락장의 숙박료, 음식료 등의 채권을 1년의 단기소멸시효에 걸리게 한다.","c":"상","v":1},"변리사2017_54-11-2":{"w":"음식료 채권의 변제기는 2015. 12. 5.이므로 1년 시효는 2016. 12. 5. 완성된다. 그 전인 2016. 11. 21.의 소 제기는 제168조 제1호의 청구로 시효를 중단시킨다.","c":"상","v":1},"변리사2017_54-11-3":{"w":"제170조 제1항에 따라 소가 취하되면 재판상 청구는 시효중단 효력이 없지만 같은 조 제2항에 따라 6개월 내에 재판상 청구, 파산절차참가, 압류 또는 가압류, 가처분을 하면 최초의 재판상 청구로 시효가 중단된 것으로 본다.","c":"상","v":1},"변리사2017_54-11-5":{"w":"甲과 乙은 연대채무자다. 제416조는 어느 연대채무자에 대한 이행청구가 다른 연대채무자에게도 효력이 있다고 정하므로 재판상 청구에 따른 시효중단의 효력이 乙에게도 미친다.","c":"상","v":1},"변리사2017_54-12-1":{"w":"제180조 제1항은 재산을 관리하는 아버지, 어머니 또는 후견인에 대한 제한능력자의 권리는 그가 능력자가 되거나 후임 법정대리인이 취임한 때부터 6개월 내에는 소멸시효가 완성되지 않는다고 정한다.","c":"상","v":1},"변리사2018_55-01-5":{"w":"제165조 제1항은 판결로 확정된 채권은 단기 소멸시효에 해당하는 것이라도 그 소멸시효를 10년으로 한다고 정한다.","c":"상","v":1},"변리사2019_56-08-4":{"w":"제척기간은 권리관계를 빨리 확정하려는 기간이어서 중단·정지가 없고 판례·통설은 당사자가 책임질 수 없는 사유로 기간을 지키지 못했어도 추후보완을 인정하지 않는다.","c":"중","v":1},"변리사2019_56-10-1":{"w":"개인 사이의 금전 대여로 상행위가 아니므로 원금반환채권은 일반 채권으로서 제162조 제1항의 10년 소멸시효에 걸린다.","c":"상","v":1},"변리사2019_56-10-2":{"w":"판례는 형사고소는 재판상 청구가 아니어서 시효중단 사유가 아니라고 본다. 반면 소송촉진 등에 관한 특례법의 배상명령 신청은 재판상 청구에 해당한다.","c":"중","v":1},"변리사2019_56-10-4":{"w":"가압류는 제168조 제2호의 시효중단 사유다. 판례는 이미 사망한 사람을 상대로 한 가압류처럼 당연무효인 가압류는 시효중단 효력이 없다고 본다.","c":"중","v":1},"변리사2019_56-10-5":{"w":"제174조는 최고 후 6개월 내에 재판상 청구, 파산절차참가, 화해를 위한 소환, 임의출석, 압류 또는 가압류, 가처분을 하지 않으면 시효중단의 효력이 없다고 정한다. 6개월 내에 소를 제기하면 최고한 때 중단된다.","c":"상","v":1},"변리사2021_58-06-1":{"w":"제184조 제2항은 소멸시효를 법률행위로 배제·연장·가중할 수 없으나 단축·경감할 수 있다고 정한다.","c":"상","v":1},"변리사2021_58-06-2":{"w":"판례는 공유물분할청구권이 공유관계에서 수반되는 형성권이므로 공유관계가 존속하는 한 따로 소멸시효에 걸리지 않는다고 본다.","c":"중","v":1},"변리사2021_58-06-3":{"w":"소멸시효는 권리를 행사할 수 있는 때부터 진행한다(제166조 제1항). 판례상 여기서 말하는 장애는 법률상 장애이고 권리의 존재나 발생을 몰랐다는 사실상 장애는 시효 진행을 막지 않는다.","c":"중","v":1},"변리사2021_58-06-4":{"w":"판례(전원합의체)는 부동산을 인도받아 사용·수익하던 매수인이 그 부동산을 처분하고 점유를 승계해 준 경우도 적극적 권리행사로 보아 이전등기청구권의 소멸시효가 진행하지 않는다고 본다.","c":"중","v":1},"변리사2023_60-05-1":{"w":"시·분으로 정한 기간은 즉시 기산한다(제156조). 오후 10시 30분부터 12시간이면 다음 날 오전 10시 30분에 만료하며 말일이 토요일이면 다음 날 만료한다는 제161조는 일 이상 단위의 기간에 적용된다.","c":"중","v":1},"변리사2023_60-05-3":{"w":"오전 0시에 시작하지 않으므로 초일을 산입하지 않아 12. 1.부터 기산한다(제157조). 월로 정한 기간은 역에 의해 계산해 최후의 월에서 기산일에 해당하는 날의 전일, 즉 2023. 2. 28.에 만료한다(제160조).","c":"상","v":1},"변리사2023_60-05-4":{"w":"「5월 1일부터」는 5월 1일 오전 0시부터 시작하는 기간이므로 초일을 산입한다(제157조 단서). 5월 1일부터 10일째인 5월 10일 24시에 만료한다(제159조).","c":"중","v":1},"변리사2023_60-05-5":{"w":"기간의 역산에도 제157조의 초일불산입을 유추한다. 소집일 3. 10. 전날인 3. 9.부터 거꾸로 7일을 세면 3. 3.이 말일이 되어 그 전날인 3. 2. 24시까지는 발송해야 한다(제71조 사원총회 소집통지 1주간 전 발송 참조).","c":"중","v":1},"변리사2024_61-12-1":{"w":"등기우편 이행청구는 최고에 해당한다. 제174조에 따라 최고 후 6개월 내에 재판상 청구, 압류 또는 가압류 등을 하지 않으면 시효중단의 효력이 없다.","c":"상","v":1},"변리사2024_61-12-2":{"w":"재판상 청구로 인한 시효중단은 소를 제기한 때 생긴다(민사소송법 제265조). 판례는 피고에게 소송서류가 송달되지 않은 채 판결이 선고되었더라도 소 제기로 생긴 시효중단 효력은 있다고 본다.","c":"중","v":1},"변리사2024_61-12-4":{"w":"판례는 대항요건을 갖추지 못한 채권양수인이 낸 소도 소멸시효 중단 사유인 재판상 청구에 해당한다고 본다. 그 소가 양도통지가 없다는 이유로 기각되더라도 확정 후 6개월 내에 다시 소를 내면 제170조 제2항에 따라 시효는 전소 제기 시에 중단된 것으로 본다.","c":"중","v":1},"변리사2024_61-12-5":{"w":"제416조가 다른 연대채무자에게 효력을 미치게 하는 것은 이행청구뿐이다. 압류·가압류에 의한 시효중단은 당사자 및 그 승계인 사이에만 효력이 있으므로(제169조) 다른 연대채무자의 채무 시효는 중단되지 않는다.","c":"상","v":1},"변리사2018_55-18-5":{"w":"판례는 중간생략등기의 합의가 있다고 해서 중간자의 최초 매도인에 대한 이전등기청구권이 소멸하지는 않는다고 본다.","c":"중","v":1},"변리사2018_55-19-3":{"w":"가등기에 의한 본등기가 마쳐지면 순위가 가등기 시로 소급하므로 등기관은 가등기 후 본등기 전에 마쳐진 등기로서 가등기에 의해 보전되는 권리를 침해하는 丙의 이전등기를 직권으로 말소한다(부동산등기법 제92조 제1항).","c":"상","v":1},"변리사2021_58-15-2":{"w":"판례는 등기가 원인 없이 말소되어도 그 물권의 효력에 영향이 없으므로 회복등기 전이라도 말소된 등기의 명의인이 적법한 권리자로 추정된다고 본다.","c":"중","v":1},"변리사2021_58-16-1":{"w":"제214조는 소유자가 소유권을 방해하는 자에게 방해의 제거를 청구할 수 있다고 정한다. 丙의 무단 적치는 소유권 방해다.","c":"상","v":1},"변리사2021_58-16-2":{"w":"임차인 乙은 소유자가 아니므로 소유권에 기한 방해배제청구권(제214조)을 직접 행사하지 못한다. 판례는 임차인이 임대인인 소유자의 방해배제청구권을 제404조로 대위행사할 수 있다고 본다.","c":"중","v":1},"변리사2021_58-16-3":{"w":"제205조 제1항의 점유방해배제청구권은 방해자의 고의·과실을 요건으로 하지 않는다. 丙이 자기 땅으로 오신했어도 점유자 乙은 방해의 제거를 청구할 수 있다.","c":"상","v":1},"변리사2021_58-16-5":{"w":"판례·통설은 임대차 종료에 따른 임대인의 목적물 반환청구권(채권적 청구권)과 소유권에 기한 반환청구권(제213조)이 경합해 어느 것이든 행사할 수 있다고 본다.","c":"중","v":1},"변리사2023_60-16-3":{"w":"판례는 3자간 등기명의신탁에서 명의신탁자가 매도인에 대해 가지는 소유권이전등기청구권도 부동산을 인도받아 점유하는 동안에는 소멸시효가 진행하지 않는다고 본다.","c":"중","v":1},"변리사2026_63-14-1":{"w":"판례(전원합의체)는 부동산 매수인이 목적물을 인도받아 사용·수익하는 동안에는 그 소유권이전등기청구권의 소멸시효가 진행하지 않는다고 본다.","c":"중","v":1},"변리사2026_63-14-2":{"w":"소멸시효는 권리를 행사할 수 있는 때부터 진행한다(제166조 제1항). 판례는 건물이 완공되기 전에는 이전등기를 할 수 없으므로 신축 중인 건물의 이전등기청구권은 건물 완공 시부터 시효가 진행한다고 본다.","c":"중","v":1},"변리사2026_63-14-4":{"w":"판례는 피담보채무가 변제되면 양도담보권설정자가 소유권에 기해 등기 회복을 청구하는 것으로서 물권적 청구권이므로 시효로 소멸하지 않는다고 본다.","c":"중","v":1},"변리사2026_63-14-5":{"w":"판례(전원합의체)는 무효등기의 말소등기청구권과 진정명의회복을 원인으로 한 소유권이전등기청구권이 모두 소유권에 기한 방해배제청구권(제214조)으로서 소송물이 같다고 본다.","c":"중","v":1},"변리사2016_53-13-1":{"w":"신축 건물은 신축자가 원시취득하므로 판례는 보존등기 명의인이 건물을 신축한 사람이 아니라는 점이 밝혀지면 그 보존등기의 권리추정력이 깨진다고 본다.","c":"중","v":1},"변리사2016_53-13-2":{"w":"판례는 소유권이전등기가 되어 있으면 등기명의인이 제3자뿐 아니라 전 소유자에 대해서도 적법한 등기원인으로 소유권을 취득한 것으로 추정된다고 본다.","c":"중","v":1},"변리사2016_53-13-3":{"w":"판례는 확정판결에 따라 마쳐진 등기는 그 판결이 공시송달로 이루어졌더라도 재심으로 취소되지 않는 한 적법한 것으로 추정된다고 본다.","c":"중","v":1},"변리사2016_53-13-4":{"w":"판례는 대리인을 통해 이전등기가 이루어졌다고 주장되는 경우 등기의 추정력이 대리권의 존재에도 미친다고 보므로 등기의 무효를 주장하는 전 소유자 甲이 대리권 없음을 증명해야 한다.","c":"중","v":1},"변리사2017_54-18-1":{"w":"판례는 소유권이전등기 명의자가 제3자뿐 아니라 전 소유자에 대해서도 적법한 원인으로 소유권을 취득한 것으로 추정된다고 본다.","c":"중","v":1},"변리사2017_54-18-2":{"w":"판례는 존재하지 않는 사람(허무인)으로부터 넘겨받은 등기는 원인무효이므로 그 등기명의자의 소유권 추정이 깨진다고 본다.","c":"중","v":1},"변리사2017_54-18-4":{"w":"판례는 등기가 원인 없이 말소되었더라도 물권의 효력에는 영향이 없으므로 회복등기 전에도 말소된 등기의 명의인이 적법한 권리자로 추정된다고 본다.","c":"중","v":1},"변리사2017_54-18-5":{"w":"판례는 신축 건물을 건축한 사람이 원시취득하므로 보존등기 명의자가 건물을 신축한 사람이 아니라면 그 보존등기의 추정력이 깨진다고 본다.","c":"중","v":1},"변리사2023_60-14-2":{"w":"판례는 합유지분 포기는 법률행위에 의한 물권변동이므로 등기를 해야(제186조) 포기된 지분이 나머지 합유자에게 귀속된다고 본다.","c":"중","v":1},"변리사2023_60-14-3":{"w":"판례는 물권적 합의가 인도보다 먼저 이루어진 경우 제249조의 선의·무과실은 인도받는 때를 기준으로 판단한다고 본다.","c":"중","v":1},"변리사2023_60-14-4":{"w":"제187조의 판결은 그 자체로 물권변동을 일으키는 형성판결만을 뜻한다. 소유권이전 약정을 내용으로 하는 화해조서는 이행판결과 같은 효력이어서 등기해야 소유권이 이전된다.","c":"중","v":1},"변리사2023_60-14-5":{"w":"판례(전원합의체)는 공유물분할 조정에서 현물분할 협의가 성립해도 그것은 협의분할의 성질을 가질 뿐 제187조의 판결이 아니므로 지분이전등기를 해야 분할된 부분의 소유권을 취득한다고 본다.","c":"중","v":1},"변리사2019_56-14-1":{"w":"점유권은 점유라는 사실 상태에 따라 인정되는 권리여서 혼동 규정(제191조 제3항은 점유권에 적용하지 않는다고 명시)이 적용되지 않고 소멸시효의 대상도 아니다.","c":"상","v":1},"변리사2019_56-14-2":{"w":"제162조 제2항은 채권 및 소유권 이외의 재산권만 20년 소멸시효에 걸리게 하므로 소유권은 시효로 소멸하지 않는다. 다만 타인이 취득시효로 원시취득하면 원소유자는 그 반사적 효과로 소유권을 잃는다.","c":"상","v":1},"변리사2019_56-14-3":{"w":"제191조 제1항 단서는 동일한 물건의 소유권과 다른 물권이 동일인에게 귀속해도 그 물권이 제3자의 권리의 목적인 때에는 소멸하지 않는다고 정한다.","c":"상","v":1},"변리사2019_56-14-5":{"w":"판례는 공유지분 포기를 상대방 있는 단독행위로 보아 법률행위에 의한 물권변동으로 다루므로 등기를 해야 효력이 생긴다(제186조). 다른 공유자는 포기한 공유자에게 지분이전등기를 청구할 수 있다.","c":"중","v":1},"변리사2026_63-17-1":{"w":"제191조 제1항 단서의 취지상 본인의 이익을 위해 물권을 존속시킬 필요가 있으면 혼동으로 소멸하지 않는다. 판례는 저당권자가 소유권을 취득했어도 그 저당권보다 후순위의 가압류 등이 있으면 저당권은 소멸하지 않는다고 본다.","c":"중","v":1},"변리사2026_63-17-2":{"w":"판례는 대항요건을 갖춘 임차권 뒤에 저당권이 설정된 상태에서 임차인이 소유권을 취득한 경우 제191조 제1항 단서를 준용해 임차권이 소멸하지 않는다고 본다. 경매 시 매수인에게 대항할 이익이 있기 때문이다.","c":"중","v":1},"변리사2026_63-17-3":{"w":"판례는 공유지분 포기를 법률행위에 의한 물권변동으로 보아 다른 공유자 명의로 지분이전등기를 해야 효력이 생긴다고 본다(제186조).","c":"중","v":1},"변리사2026_63-17-5":{"w":"혼동은 동일인에게 두 권리가 유효하게 귀속해야 생긴다. 판례는 근저당권자의 소유권 취득이 무효이면 혼동이 생기지 않았던 것이 되어 근저당권이 당연히 부활한다고 본다.","c":"중","v":1},"변리사2018_55-13-1":{"w":"상속은 제187조의 법률 규정에 의한 물권변동이어서 등기 없이도 효력이 있고 상속인은 상속개시 때부터 피상속인의 재산에 관한 권리의무를 승계한다(제1005조).","c":"상","v":1},"변리사2018_55-13-2":{"w":"공용징수는 제187조의 물권변동이고 공익사업을 위한 토지 등의 취득 및 보상에 관한 법률 제45조 제1항에 따라 사업시행자는 수용의 개시일에 토지의 소유권을 취득한다.","c":"상","v":1},"변리사2018_55-13-3":{"w":"판례는 자기 노력과 비용으로 건물을 지은 사람이 그 건물을 원시취득하며 건축허가 명의가 타인으로 되어 있어도 마찬가지라고 본다.","c":"중","v":1},"변리사2018_55-13-4":{"w":"판례(전원합의체)는 공유물분할 조정에서 현물분할 조정이 성립해도 제187조의 판결로 볼 수 없으므로 각 공유자는 지분이전등기를 마쳐야 분할된 부분의 소유권을 취득한다고 본다.","c":"중","v":1},"변리사2023_60-16-1":{"w":"판례는 3자간 중간생략등기 합의가 있더라도 중간자의 최초 매도인에 대한 소유권이전등기청구권이 소멸하지 않는다고 본다.","c":"중","v":1},"변리사2023_60-16-2":{"w":"판례(전원합의체)는 가등기된 소유권이전등기청구권이 양도되면 양도인과 양수인의 공동신청으로 가등기에 대한 부기등기 형식으로 가등기상 권리의 이전등기를 할 수 있다고 본다.","c":"중","v":1},"변리사2023_60-16-4":{"w":"판례는 소유권이전청구권 보전 가등기가 있다고 해서 소유권이전등기를 청구할 법률관계가 있다고 추정되지 않는다고 본다. 가등기에는 이런 추정력이 없다.","c":"중","v":1},"변리사2017_54-17-1":{"w":"이행판결은 제187조의 판결(형성판결)이 아니므로 확정되어도 등기를 해야 소유권이 이전된다(제186조).","c":"상","v":1},"변리사2017_54-17-2":{"w":"제312조 제4항의 법정갱신은 법률 규정에 의한 물권변동이므로 판례는 전세권자가 등기 없이도 전세권설정자나 목적물을 취득한 제3자에게 갱신된 권리를 주장할 수 있다고 본다.","c":"중","v":1},"변리사2017_54-17-3":{"w":"판례는 건물 완성 전에 마친 보존등기도 그 뒤 건물이 완성되면 실체관계에 부합하여 유효하다고 본다.","c":"중","v":1},"변리사2017_54-17-4":{"w":"신축건물은 제187조에 따라 등기 없이 원시취득한다. 그러나 양도는 법률행위에 의한 물권변동이어서 등기해야 하고(제186조) 판례상 미등기 무허가건물의 양수인은 사실상 처분권만 가질 뿐 소유권을 취득하지 못한다.","c":"중","v":1},"변리사2018_55-14-2":{"w":"판례는 미등기건물을 양수해 사실상 처분권을 가진 사람은 그 건물의 부지도 점유하는 것으로 본다. 건물은 그 부지를 떠나 존재할 수 없기 때문이다.","c":"중","v":1},"변리사2018_55-14-3":{"w":"가사·영업 기타 유사한 관계로 타인의 지시를 받아 물건을 사실상 지배하는 사람은 점유보조자로서 타인만이 점유자다(제195조).","c":"상","v":1},"변리사2018_55-14-4":{"w":"제194조에 따라 지상권·전세권·질권·사용대차·임대차·임치 기타의 관계로 타인에게 물건을 점유하게 한 사람은 간접으로 점유권이 있다.","c":"상","v":1},"변리사2018_55-14-5":{"w":"판례상 소유권이전등기를 마친 경우에는 그 무렵 점유를 이전받았다고 보는 것이 보통이지만 소유권보존등기는 이전을 전제로 하지 않으므로 보존등기를 마쳤다는 사실만으로 그때 점유를 이전받았다고 인정할 수 없다.","c":"중","v":1},"변리사2018_55-22-1":{"w":"판례는 제3자의 방해를 배제하는 것을 공유물의 보존행위(제265조 단서)로 보아 각 공유자가 단독으로 공유물 전부에 대한 방해제거를 청구할 수 있다고 본다.","c":"중","v":1},"변리사2018_55-22-2":{"w":"판례는 제3자가 공유물을 무단 사용해 얻은 부당이득에 대해 각 공유자가 자기 지분 비율 범위에서만 반환을 청구할 수 있다고 본다. 이는 보존행위가 아니기 때문이다.","c":"중","v":1},"변리사2018_55-22-3":{"w":"판례는 공유물분할청구소송을 공유자 전원이 당사자가 되어야 하는 고유필수적 공동소송으로 본다. 분할을 청구하는 공유자가 원고 나머지 공유자 전원이 피고가 된다.","c":"중","v":1},"변리사2018_55-22-4":{"w":"판례는 공유지분 포기를 상대방 있는 단독행위로서 법률행위에 의한 물권변동으로 보아 등기해야 효력이 생긴다고 본다(제186조).","c":"중","v":1},"변리사2019_56-13-1":{"w":"판례는 매수인으로부터 다시 매수해 인도받은 사람은 매수인의 점유사용권을 승계해 제213조 단서의 점유할 권리를 가지므로 매도인이 그에게 소유권에 기한 반환을 청구할 수 없다고 본다.","c":"중","v":1},"변리사2019_56-13-2":{"w":"판례(전원합의체)는 부동산을 인도받아 사용하던 매수인이 그 부동산을 다른 사람에게 처분하고 점유를 승계해 준 경우에도 이전등기청구권의 소멸시효가 진행하지 않는다고 본다.","c":"중","v":1},"변리사2019_56-13-3":{"w":"丙은 乙에 대한 소유권이전등기청구권을 피보전채권으로 하여 乙의 甲에 대한 소유권이전등기청구권을 대위행사할 수 있다(제404조). 등기청구권 보전을 위한 대위에는 채무자의 무자력이 필요 없다.","c":"중","v":1},"변리사2019_56-13-4":{"w":"丙은 乙로부터 점유사용권을 승계해 정당한 권원으로 점유하므로 법률상 원인 없는 이득이 아니어서 甲은 부당이득(제741조) 반환을 청구할 수 없다.","c":"중","v":1},"변리사2021_58-13-1":{"w":"선의취득(제249조)은 양도인의 무권리에 대한 신뢰를 보호하는 제도다. 대리인이 본인 소유가 아닌 물건을 처분하고 상대방이 본인 소유로 믿은 경우에도 그 신뢰가 보호되므로 선의취득이 인정될 수 있다.","c":"중","v":1},"변리사2021_58-13-2":{"w":"등록된 자동차는 등록으로 물권변동이 이루어져 제249조가 적용되지 않는다. 판례는 적법하게 등록할 수 없어 등록하지 않은 상태이고 통상 도로 밖에서만 쓰는 경우처럼 특별한 사정이 있으면 일반 동산처럼 선의취득 규정이 적용될 수 있다고 본다.","c":"중","v":1},"변리사2021_58-13-3":{"w":"판례는 채무자 아닌 사람의 동산이 강제집행 경매로 매각된 경우에도 매수인이 선의·무과실로 평온·공연하게 점유를 취득하면 제249조의 선의취득이 성립한다고 본다.","c":"중","v":1},"변리사2021_58-13-4":{"w":"판례는 점유개정은 외관상 종래의 사실상 지배에 변화가 없으므로 선의취득(제249조)의 요건인 점유취득에 해당하지 않는다고 본다.","c":"중","v":1},"변리사2024_61-14-1":{"w":"토지에서 분리된 수목은 동산이 되므로 제249조의 선의취득 대상이 될 수 있다. 명인방법으로 공시되는 것은 분리 전 수목의 집단이다.","c":"중","v":1},"변리사2024_61-14-2":{"w":"제249조의 선의취득은 동산에만 적용된다. 판례는 연립주택 입주권은 채권적 권리에 불과해 선의취득의 대상이 아니라고 본다.","c":"중","v":1},"변리사2024_61-14-4":{"w":"乙이 丙에게 매도하면서 그대로 임차해 쓰는 것은 점유개정이다. 판례는 점유개정으로는 선의취득이 인정되지 않는다고 보므로 丙은 발전기 소유권을 취득하지 못한다.","c":"중","v":1},"변리사2024_61-14-5":{"w":"제250조는 선의취득한 물건이 도품이나 유실물인 때 피해자 또는 유실자가 도난 또는 유실한 날부터 2년 내에 그 물건의 반환을 청구할 수 있다고 정한다.","c":"상","v":1},"변리사2026_63-19-5":{"w":"판례는 매매로 인한 이전등기청구권의 양도와 달리, 취득시효 완성으로 인한 소유권이전등기청구권은 채권자와 채무자 사이에 신뢰관계가 없으므로 그 양도에 소유명의인의 동의·승낙이 필요 없고 통지만으로 대항할 수 있다고 본다.","c":"중","v":1},"변리사2024_61-17-4":{"w":"제273조 제1항은 합유자가 전원의 동의 없이 합유물에 대한 지분을 처분하지 못한다고 정한다.","c":"상","v":1},"변리사2018_55-20-1":{"w":"丙이 선의취득하면 원시취득으로 丙이 완전한 소유권을 가지므로 丁은 소유자 丙으로부터 정상적으로 승계취득한다. 丁의 선의·악의는 따질 필요가 없다.","c":"중","v":1},"변리사2021_58-17-1":{"w":"판례상 점유취득시효 완성자는 등기 전에도 시효완성 당시의 소유자에게 취득시효를 주장하여 소유권이전등기를 청구할 수 있다. 시효완성 당시 소유자는 그 이행의무의 상대방이다.","c":"중","v":1},"변리사2021_58-17-2":{"w":"판례는 시효기간 중 등기명의인이 바뀌어도 시효가 중단되지 않으므로 시효완성자는 시효완성 당시의 등기명의인에게 취득시효를 주장할 수 있다고 본다.","c":"중","v":1},"변리사2021_58-17-3":{"w":"시효완성자는 등기해야 소유권을 취득하므로(제245조 제1항) 판례는 시효완성 후 소유권을 넘겨받은 제3자에게는 그 등기원인이 시효완성 전에 있었더라도 시효취득을 주장할 수 없다고 본다.","c":"중","v":1},"변리사2021_58-17-4":{"w":"판례는 시효기간 중 등기명의인이 바뀐 경우 기산점은 점유를 시작한 때로 고정되며 임의로 기산점을 정하거나 역산해 20년 이상 점유했다는 사실만 내세워 시효완성을 주장할 수 없다고 본다.","c":"중","v":1},"변리사2024_61-15-2":{"w":"판례는 건물의 부지는 건물 소유자가 점유하는 것으로 보므로 건물 소유권이 양도되면 전 소유자는 특별한 사정이 없는 한 부지의 점유를 잃는다고 본다.","c":"중","v":1},"변리사2023_60-15-1":{"w":"자주점유 여부는 점유취득 원인인 권원의 성질에 따라 객관적으로 정한다. 판례는 증여로 점유를 시작한 뒤 증여자가 무권리자임을 알게 되었다는 사정만으로 타주점유로 바뀌지 않는다고 본다.","c":"중","v":1},"변리사2026_63-18-1":{"w":"제201조 제1항은 「선의의 점유자」라고만 정할 뿐 자주점유를 요구하지 않는다. 임차인처럼 과실수취권을 포함하는 권원이 있다고 믿은 타주점유자도 과실을 취득할 수 있다.","c":"중","v":1},"변리사2026_63-18-2":{"w":"제201조 제1항에 따라 선의의 점유자는 점유물의 과실을 취득하므로 판례는 그 과실취득으로 회복자에게 손해를 입혔더라도 부당이득으로 반환할 의무가 없다고 본다.","c":"중","v":1},"변리사2026_63-18-4":{"w":"제203조 제1항 단서는 점유자가 과실을 취득한 경우 통상의 필요비는 청구하지 못한다고 정한다.","c":"상","v":1},"변리사2026_63-18-5":{"w":"판례는 제203조의 비용상환청구권은 점유자가 회복자로부터 점유물의 반환을 청구받거나 회복자에게 점유물을 반환한 때에 비로소 행사할 수 있다고 본다.","c":"중","v":1},"변리사2021_58-14-2":{"w":"제748조 제2항은 악의의 수익자가 받은 이익에 이자를 붙여 반환하고 손해가 있으면 배상하도록 정한다. 판례는 그 이자의 이행지체로 인한 지연손해금도 지급해야 한다고 본다.","c":"중","v":1},"변리사2017_54-13-1":{"w":"판례는 권리능력 없는 사단도 부동산을 자주점유해 시효취득의 주체가 될 수 있다고 본다.","c":"중","v":1},"변리사2017_54-13-2":{"w":"제247조 제1항은 소유권 취득시효에 따른 권리취득의 효력이 점유를 개시한 때에 소급한다고 정한다.","c":"상","v":1},"변리사2017_54-13-3":{"w":"점유취득시효가 완성되어도 등기해야 소유권을 취득하므로(제245조 제1항) 판례는 등기 전의 시효완성자는 소유권이 없어 소유권에 기한 방해배제청구로 담장 철거를 구할 수 없다고 본다.","c":"중","v":1},"변리사2017_54-13-4":{"w":"판례는 시효기간 완성 전에 등기명의가 바뀌었다는 사정은 점유 상태에 영향이 없으므로 취득시효의 중단사유가 아니라고 본다.","c":"중","v":1},"변리사2018_55-17-2":{"w":"판례는 시효기간 동안 소유자의 변동이 없으면 기산점을 어디에 두든 시효완성을 주장하는 시점에서 역산해 기간이 지났다는 사실만 확정되면 된다고 본다.","c":"중","v":1},"변리사2019_56-15-1":{"w":"판례는 시효기간 만료 전 등기부상 소유명의의 변경은 점유자의 점유에 영향이 없으므로 취득시효 중단사유가 될 수 없다고 본다.","c":"중","v":1},"변리사2019_56-15-2":{"w":"판례는 취득시효 중단사유인 재판상 청구에 소유권 확인·반환청구뿐 아니라 소유권 침해를 이유로 한 방해배제·손해배상·부당이득반환청구도 포함된다고 본다.","c":"중","v":1},"변리사2019_56-15-3":{"w":"판례는 시효를 주장하는 사람이 낸 소송에서 권리자가 응소하여 적극적으로 권리를 주장하고 그것이 받아들여지면 재판상 청구(제247조 제2항, 제168조 제1호)에 해당한다고 본다.","c":"중","v":1},"변리사2019_56-15-4":{"w":"시효중단은 당사자 및 그 승계인 사이에 효력이 있으므로(제169조) 판례는 중단 후의 승계인은 중단 당시 당사자의 점유기간을 이어받아 시효취득을 주장할 수 없다고 본다.","c":"중","v":1},"변리사2016_53-18-3":{"w":"A토지에 저당권이 설정될 당시 A토지와 등기된 B건물이 모두 乙 소유였고 경매로 토지 소유자가 丙으로 바뀌었으므로 제366조에 따라 乙은 B건물을 위한 법정지상권을 취득한다.","c":"중","v":1},"변리사2017_54-15-1":{"w":"판례는 전세권저당권자가 전세금반환채권에 물상대위권을 행사하면 설정자는 제315조의 손해배상채권 외의 다른 채권으로는 상계로 저당권자에게 대항할 수 없다고 본다.","c":"중","v":1},"변리사2017_54-15-2":{"w":"선순위 저당권이 있는 경우 그보다 뒤의 전세권은 매각으로 소멸한다(민사집행법 제91조 제3항). 전세권자는 제303조 제1항에 따라 자기 순위(2순위)로 전세금의 우선변제를 받는다.","c":"중","v":1},"변리사2017_54-15-3":{"w":"제304조 제1항은 타인의 토지에 있는 건물에 전세권을 설정한 때 전세권의 효력이 그 건물의 소유를 목적으로 한 지상권 또는 임차권에 미친다고 정한다.","c":"상","v":1},"변리사2017_54-15-5":{"w":"판례는 전세권 존속기간이 만료되면 전세권의 용익물권적 권능은 말소등기 없이 당연히 소멸하며 전세권저당권자는 전세금반환채권에 물상대위권을 행사할 수 있을 뿐이라고 본다.","c":"중","v":1},"변리사2017_54-21-2":{"w":"제298조의 승역지소유자 공작물 설치·수선의무 약정은 그 특별승계인도 부담하지만 승계인에게 대항하려면 그 약정을 등기해야 한다(부동산등기법 제70조).","c":"중","v":1},"변리사2018_55-16-1":{"w":"판례는 토지에 저당권을 설정할 당시 건물이 건축 중이었더라도 그 규모·종류가 외형상 예상할 수 있을 정도로 공사가 진행되었으면 제366조의 법정지상권이 성립한다고 본다.","c":"중","v":1},"변리사2018_55-16-2":{"w":"판례는 저당권 설정 당시 건물이 있었다면 그 뒤 건물을 개축·재축·신축해도 법정지상권이 성립하며 그 범위는 구건물을 기준으로 한다고 본다.","c":"중","v":1},"변리사2018_55-16-3":{"w":"판례(전원합의체)는 토지와 건물에 공동저당권을 설정한 뒤 건물을 철거하고 신축한 경우 신축건물에 토지와 동순위의 공동저당이 설정되는 등 특별한 사정이 없으면 법정지상권이 성립하지 않는다고 본다. 저당권자는 토지 전체의 담보가치를 기대했기 때문이다.","c":"중","v":1},"변리사2018_55-16-5":{"w":"판례는 토지공유자 한 사람이 다른 공유자 지분 과반수의 동의로 건물을 지은 경우에도 토지가 동일인 소유라고 볼 수 없어 경매로 소유자가 달라져도 법정지상권이 성립하지 않는다고 본다.","c":"중","v":1},"변리사2018_55-21-1":{"w":"민법은 지역권에 대가를 요건으로 정하지 않으므로(제291조) 무상의 지역권도 설정할 수 있다.","c":"중","v":1},"변리사2018_55-21-2":{"w":"판례는 지역권 취득시효(제294조)에서 요역지의 불법점유자는 통행지역권을 시효취득할 수 없다고 본다. 지역권은 요역지 소유자 등 권원 있는 사람을 위해서만 성립한다.","c":"중","v":1},"변리사2018_55-21-4":{"w":"지역권은 승역지를 점유할 권능이 없어 제301조는 제214조의 방해제거·예방청구만 준용하고 제213조의 반환청구는 준용하지 않는다.","c":"상","v":1},"변리사2018_55-21-5":{"w":"제296조는 요역지가 수인의 공유인 경우 그 1인에 의한 지역권 소멸시효의 중단 또는 정지는 다른 공유자를 위하여 효력이 있다고 정한다.","c":"상","v":1},"변리사2019_56-16-4":{"w":"제287조의 지료 2년 이상 연체는 판례상 토지양수인에 대한 연체만 따진다. 양도 전후 연체를 합산하지 않으므로 양수인에 대한 연체기간이 2년 이상이면 양수인이 소멸을 청구할 수 있다.","c":"중","v":1},"변리사2019_56-20-5":{"w":"판례는 전세권이 존속하는 동안 목적물 소유권이 이전되면 신 소유자가 전세권설정자의 지위를 승계해 전세금반환의무를 지고 구 소유자는 그 의무를 면한다고 본다.","c":"중","v":1},"변리사2021_58-18-3":{"w":"경매로 토지와 건물의 소유자가 달라져 丙은 제366조의 법정지상권을 취득했다. 이는 법률 규정에 의한 물권취득(제187조)이어서 등기 없이도 그 뒤 토지를 취득한 丁에게 주장할 수 있다. 2021. 1. 16.에는 丙이 아직 건물 소유자다.","c":"중","v":1},"변리사2021_58-20-1":{"w":"제304조 제1항은 타인의 토지에 있는 건물에 전세권을 설정한 때 전세권의 효력이 그 건물의 소유를 목적으로 한 지상권 또는 임차권에 미친다고 정한다.","c":"상","v":1},"변리사2021_58-20-2":{"w":"제305조 제1항 본문은 대지와 건물이 동일한 소유자에 속한 경우 건물에 전세권을 설정한 때 그 대지소유권의 특별승계인은 전세권설정자에 대하여 지상권을 설정한 것으로 본다고 정한다.","c":"상","v":1},"변리사2021_58-20-3":{"w":"제312조 제4항의 법정갱신은 법률 규정에 의한 물권변동이므로 판례는 전세권자가 등기 없이도 목적물을 취득한 제3자에게 갱신된 권리를 주장할 수 있다고 본다.","c":"중","v":1},"변리사2021_58-20-5":{"w":"제312조 제1항은 전세권 존속기간이 10년을 넘지 못하고 이를 넘는 약정은 10년으로 단축한다고 정하며 제3항은 갱신 기간도 갱신한 날부터 10년을 넘지 못한다고 정한다.","c":"상","v":1},"변리사2023_60-19-3":{"w":"임대차보증금은 연체 차임 등 임대차에서 생기는 임차인의 채무를 담보하므로 보증금 반환을 담보할 목적으로 전세권을 설정했어도 임대인과 임차인 사이에서는 연체 차임을 보증금에서 공제할 수 있다는 것이 판례다.","c":"중","v":1},"변리사2024_61-18-4":{"w":"판례는 지상권은 지상물의 존재를 요건으로 하지 않으므로 건물이 멸실되어도 존속기간이 남아 있으면 지상권이 소멸하지 않고 다시 건물을 지을 수 있다고 본다.","c":"중","v":1},"변리사2024_61-19-5":{"w":"제287조는 지상권자가 2년 이상 지료를 지급하지 않으면 설정자가 지상권 소멸을 청구할 수 있다고 정한다. 저당권자에 대한 통지가 필요한 것은 지상권이나 지상 건물이 저당권의 목적인 경우(제288조)이고 건물 전세권자 丙의 동의는 요건이 아니다.","c":"중","v":1},"변리사2026_63-20-1":{"w":"제281조 제2항은 설정 당시 공작물의 종류와 구조를 정하지 않은 때에는 지상권의 존속기간을 제280조 제1항 제2호의 건물 소유 목적 기간인 15년으로 한다고 정한다.","c":"상","v":1},"변리사2026_63-20-2":{"w":"제283조 제2항의 지상물매수청구권은 지상권설정자가 갱신을 거절한 경우에 인정된다. 판례는 지상권자가 갱신청구권을 행사하지 않아 그 권리가 소멸했다면 매수청구권도 행사할 수 없다고 본다.","c":"중","v":1},"변리사2026_63-20-3":{"w":"제282조는 지상권자가 타인에게 그 권리를 양도하거나 그 권리의 존속기간 내에서 그 토지를 임대할 수 있다고 정한다. 제289조에 따라 이에 반하는 약정은 효력이 없다.","c":"상","v":1},"변리사2026_63-20-4":{"w":"판례는 지료액이나 지료에 관한 약정은 등기해야 제3자에게 대항할 수 있다고 보므로(부동산등기법 제69조) 지료를 증액하지 않기로 한 특약도 등기하지 않으면 새 토지소유자에게 대항하지 못한다.","c":"중","v":1},"변리사2026_63-21-1":{"w":"판례는 전세권 존속기간이 시작되기 전에 전세권설정등기를 마쳤더라도 특별한 사정이 없는 한 그 등기는 유효한 것으로 추정된다고 본다.","c":"중","v":1},"변리사2026_63-21-2":{"w":"판례는 임대차보증금 반환채권을 담보할 목적으로 설정한 전세권설정계약도 유효하지만 임차인이 목적물을 사용·수익하는 등 임대차계약과 양립할 수 없는 범위에서는 통정허위표시로 무효라고 본다.","c":"중","v":1},"변리사2026_63-21-3":{"w":"토지 전세권이 존속기간 만료로 종료하면 전세권자는 전세금반환채권을 가지고 경매절차에서 우선변제를 받을 수 있다. 판례는 최선순위 전세권자의 채권자가 채권자대위권(제404조)에 기해 자기 이름으로 전세권에 대한 배당요구를 할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-21-5":{"w":"판례는 전세권저당권자가 전세금반환채권을 압류·추심하는 등 물상대위권을 행사하지 않는 한 전세권설정자는 전세권자에게만 전세금반환의무를 진다고 본다.","c":"중","v":1},"변리사2024_61-18-2":{"w":"제283조 제1항의 갱신청구는 형성권이 아니어서 지상권설정자가 거절하면 갱신되지 않는다. 이때 지상권자는 같은 조 제2항에 따라 지상물 매수를 청구할 수 있다.","c":"상","v":1},"변리사2024_61-18-3":{"w":"제285조 제2항은 지상권이 소멸한 때 지상권설정자가 상당한 가액을 제공하여 그 공작물이나 수목의 매수를 청구한 때에는 지상권자가 정당한 이유 없이 이를 거절하지 못한다고 정한다.","c":"상","v":1},"변리사2024_61-18-5":{"w":"무상의 지상권은 지상권자의 이익만을 위한 것이어서 언제든 포기할 수 있다. 다만 제371조 제2항은 지상권을 목적으로 저당권을 설정한 자가 저당권자의 동의 없이 지상권을 소멸하게 하는 행위를 하지 못한다고 정한다.","c":"상","v":1},"변리사2016_53-20-5":{"w":"유치권자는 직접점유뿐 아니라 점유매개자를 통한 간접점유로도 유치할 수 있다. 戊는 유치권자 甲을 위해 점유하므로 소유자 乙의 반환청구에 대해 제213조 단서의 점유할 권리를 들어 거절할 수 있다.","c":"중","v":1},"변리사2016_53-22-1":{"w":"판례는 물상보증인이 채무자의 채무만을 면책적으로 인수하고 그에 따라 근저당권 변경의 부기등기를 한 경우, 근저당권은 인수된 채무만을 담보하며 물상보증인이 다른 원인으로 부담하게 된 새 채무까지 담보하지는 않는다고 본다.","c":"중","v":1},"변리사2016_53-22-2":{"w":"판례는 근저당권자가 경매를 신청하면 그때 피담보채무가 확정되고 경매개시결정 후 경매신청이 취하되어도 확정의 효과가 번복되지 않는다고 본다.","c":"중","v":1},"변리사2016_53-22-3":{"w":"판례는 근저당권의 존속기간이나 결산기의 정함이 없으면 근저당권설정자가 근저당권자를 상대로 언제든지 해지의 의사표시를 하여 피담보채무를 확정시킬 수 있다고 본다.","c":"중","v":1},"변리사2016_53-22-5":{"w":"제357조 제2항은 근저당권에서 채무의 이자는 최고액 중에 산입한 것으로 본다고 정한다.","c":"상","v":1},"변리사2017_54-19-1":{"w":"판례는 저당권 이전의 부기등기를 마친 채권양수인은 채권양도의 대항요건(제450조)을 갖추지 못했더라도 저당권 실행 요건을 갖추었다면 경매를 신청할 수 있다고 본다. 대항요건 흠결은 채무자가 다툴 수 있는 사유일 뿐이다.","c":"중","v":1},"변리사2017_54-19-2":{"w":"판례는 저당권설정자로부터 용익권을 받은 사람이 지은 건물이라도 그 뒤 저당권설정자가 그 건물 소유권을 취득했다면 제365조를 유추적용해 토지와 함께 일괄경매를 청구할 수 있다고 본다.","c":"중","v":1},"변리사2017_54-19-3":{"w":"저당권은 피담보채권에 부종하므로 제361조에 따라 채권과 분리해 양도할 수 없다. 판례는 피담보채권이 저당권과 분리되어 양도되면 채권을 따르지 않은 저당권은 소멸한다고 본다.","c":"중","v":1},"변리사2017_54-19-4":{"w":"제364조는 저당부동산에 대해 소유권, 지상권 또는 전세권을 취득한 제3자가 저당권자에게 그 부동산으로 담보된 채권을 변제하고 저당권의 소멸을 청구할 수 있다고 정한다. 이해관계 있는 제3자이므로 채무자의 의사에 반해서도 변제할 수 있다(제469조 제2항).","c":"상","v":1},"변리사2017_54-20-2":{"w":"판례는 근저당권자가 경매를 신청하면 그 신청 시에 피담보채권이 확정되어 그 뒤 발생한 원본채권은 그 근저당권으로 담보되지 않는다고 본다.","c":"중","v":1},"변리사2017_54-20-3":{"w":"판례는 근저당권 실행 비용은 채권최고액에 포함되지 않고 최고액과 별도로 매각대금에서 우선 상환받는다고 본다.","c":"중","v":1},"변리사2017_54-20-4":{"w":"판례는 근저당권의 피담보채권이 확정되면 그 뒤 새로 생긴 원본채권은 담보되지 않지만 확정 전에 발생한 원본채권에 대해 확정 후 생기는 이자·지연손해금은 채권최고액 범위에서 계속 담보된다고 본다.","c":"중","v":1},"변리사2017_54-20-5":{"w":"판례는 후순위 저당권자가 경매를 신청한 경우 선순위 근저당권의 피담보채권은 매수인이 매각대금을 완납한 때 확정된다고 본다. 선순위 근저당권도 그때 소멸하기 때문이다.","c":"중","v":1},"변리사2019_56-18-5":{"w":"제343조는 동산질권에 제249조부터 제251조까지를 준용하므로 처분권한 없는 사람에게서 평온·공연·선의·무과실로 질권을 설정받은 채권자는 질권을 선의취득한다.","c":"상","v":1},"변리사2019_56-24-3":{"w":"질권의 피담보채권 범위에 관한 규정과 별개로, 판례·통설은 입질채권의 효력이 그 채권의 이자·지연손해금 같은 부대채권에도 미친다고 본다.","c":"중","v":1},"변리사2021_58-19-1":{"w":"대지사용권은 전유부분의 처분에 따르므로(집합건물의 소유 및 관리에 관한 법률 제20조) 판례는 전유부분에 설정된 저당권의 효력이 그 소유자가 나중에 취득한 대지권에도 종된 권리로서 미친다고 본다.","c":"중","v":1},"변리사2021_58-19-2":{"w":"판례는 저당권자가 압류하기 전에 저당목적물에 갈음하는 금전이 물상보증인에게 지급되었다면 물상보증인은 그 금액을 법률상 원인 없이 얻은 것이므로 저당권자가 부당이득반환을 청구할 수 있다고 본다.","c":"중","v":1},"변리사2021_58-19-4":{"w":"판례는 저당권자가 물상대위권을 행사하지 않아 우선변제권을 잃었다면 그 보상금으로 배당을 받은 다른 채권자는 정당한 배당을 받은 것이므로 부당이득반환을 청구할 수 없다고 본다.","c":"중","v":1},"변리사2021_58-19-5":{"w":"제364조는 저당부동산에 대해 소유권, 지상권 또는 전세권을 취득한 제3자가 저당권자에게 그 부동산으로 담보된 채권을 변제하고 저당권의 소멸을 청구할 수 있다고 정한다.","c":"상","v":1},"변리사2023_60-23-1":{"w":"채권최고액은 제3자와의 관계에서 우선변제 한도일 뿐 책임의 한도가 아니다. 판례는 채무자 겸 근저당권설정자는 확정된 채무 전액을 변제해야 근저당권 말소를 청구할 수 있다고 본다.","c":"중","v":1},"변리사2023_60-23-3":{"w":"판례는 공동근저당권자가 후순위자의 경매절차에서 일부를 배당받으면 그 금액만큼 채권최고액에서 공제되므로 우선변제받은 금액에 대해서는 다른 목적물에서 다시 우선변제권을 행사할 수 없다고 본다.","c":"중","v":1},"변리사2023_60-23-4":{"w":"제360조 단서의 지연배상 1년분 제한은 보통저당권에 관한 것이다. 근저당권은 이자를 채권최고액에 산입하므로(제357조 제2항) 판례는 1년이 지난 기간의 지연손해금도 최고액 한도에서 전액 담보된다고 본다.","c":"중","v":1},"변리사2023_60-23-5":{"w":"판례는 근저당권의 피담보채권이 확정된 뒤에 생기는 원본채권은 담보되지 않지만 확정된 원본채권에서 그 뒤 생기는 이자·지연손해금은 채권최고액 범위에서 담보된다고 본다.","c":"중","v":1},"변리사2024_61-22-1":{"w":"구분지상권(제289조의2)도 지상권이므로 제371조 제1항에 따라 지상권을 목적으로 하는 저당권을 설정할 수 있다.","c":"상","v":1},"변리사2024_61-22-3":{"w":"판례는 피담보채무 소멸로 무효가 된 저당권등기를 다른 채무의 담보로 유용하는 합의는 그 사이에 등기상 이해관계 있는 제3자가 생기지 않은 경우에만 허용된다고 본다.","c":"중","v":1},"변리사2024_61-22-4":{"w":"제359조 본문은 저당권의 효력이 저당부동산에 대한 압류가 있은 후에 저당권설정자가 그 부동산으로부터 수취한 과실 또는 수취할 수 있는 과실에 미친다고 정한다. 차임채권은 법정과실이다.","c":"상","v":1},"변리사2024_61-22-5":{"w":"부동산등기법 제77조는 일정한 금액을 목적으로 하지 않는 채권을 담보하는 저당권은 그 채권의 평가액을 기록하도록 정한다. 이는 제3자에게 우선변제 한도를 공시하는 것이므로 채권자는 제3자에 대해 등기된 평가액 한도에서만 저당권을 주장할 수 있다.","c":"중","v":1},"변리사2024_61-24-1":{"w":"가등기담보 등에 관한 법률은 소비대차나 준소비대차로 생긴 차용물 반환청구권을 담보하는 경우에 적용된다(제1조). 판례는 매매대금 채권을 담보하기 위한 가등기에는 이 법이 적용되지 않는다고 본다.","c":"중","v":1},"변리사2024_61-24-3":{"w":"판례는 가등기담보권 설정 시 가등기 이후 발생할 채권도 피담보채권에 포함하기로 한 약정은 유효하며 그 채권도 가등기담보로 담보된다고 본다.","c":"중","v":1},"변리사2024_61-24-4":{"w":"가등기담보 등에 관한 법률 제3조는 청산금의 평가액을 채무자 등에게 통지하도록 정한다. 판례는 채권자가 주관적으로 평가한 청산금 평가액을 통지하면 족하고 객관적 평가액에 못 미치더라도 통지는 유효하다고 본다.","c":"중","v":1},"변리사2024_61-24-5":{"w":"가등기담보 등에 관한 법률 제12조 제1항은 담보가등기권리자가 목적부동산의 경매를 청구할 수 있고 이 경우 경매에 관하여는 담보가등기권리를 저당권으로 본다고 정한다.","c":"상","v":1},"변리사2019_56-21-3":{"w":"丙은 2017. 10. 2. 0시에 대항력을 갖췄으나 그보다 앞선 甲의 저당권이 있다. 최선순위 저당권보다 후순위인 임차권은 경매로 소멸하므로(주택임대차보호법 제3조의5) 丙은 매수인 A에게 대항하지 못하고 주택을 인도해야 한다.","c":"중","v":1},"변리사2019_56-22-1":{"w":"가등기담보 등에 관한 법률 제3조 제1항은 청산금이 없다고 인정되는 경우에도 그 뜻을 통지하도록 하고 제4조 제2항은 통지 후 2개월의 청산기간이 지나야 본등기를 청구할 수 있다고 정한다.","c":"상","v":1},"변리사2026_63-16-3":{"w":"가등기담보 등에 관한 법률 제12조 제1항에 따라 담보가등기권리자는 권리취득에 의한 실행과 경매 중 선택할 수 있다. 판례는 경매를 선택해 그 절차가 진행 중이면 특별한 사정이 없는 한 본등기를 청구할 수 없다고 본다.","c":"중","v":1},"변리사2023_60-24-2":{"w":"가등기담보 등에 관한 법률 제4조 제3항은 청산금 지급채무와 부동산의 소유권이전등기 및 인도채무의 이행에 관하여 동시이행의 항변권(민법 제536조)을 준용한다.","c":"상","v":1},"변리사2019_56-18-1":{"w":"제343조는 유치권의 과실수취권(제323조)을 동산질권에 준용하므로 질권자는 질물의 과실을 수취해 피담보채권의 변제에 충당할 수 있다.","c":"상","v":1},"변리사2019_56-18-3":{"w":"제343조가 준용하는 제326조는 유치권(질권)의 행사가 채권의 소멸시효 진행에 영향을 미치지 않는다고 정한다. 질물 점유만으로는 시효가 중단되지 않는다.","c":"상","v":1},"변리사2019_56-18-4":{"w":"제648조는 건물 기타 공작물의 임대인이 임대차에 관한 채권으로 그 건물 등에 부속한 임차인 소유의 동산을 압류한 때 질권과 동일한 효력이 있다고 정한다.","c":"상","v":1},"변리사2024_61-20-1":{"w":"제320조 제1항은 「타인의 물건 또는 유가증권」을 점유한 자에게 유치권을 인정한다. 자기 소유 물건에는 유치권이 성립하지 않는다.","c":"상","v":1},"변리사2024_61-20-2":{"w":"판례는 권리금 반환청구권은 건물에 관하여 생긴 채권이 아니어서 그 건물에 대한 유치권의 피담보채권이 될 수 없다고 본다.","c":"중","v":1},"변리사2024_61-20-3":{"w":"유치권은 법정담보물권이지만 채권자의 이익을 위한 것이어서 판례는 당사자가 미리 유치권 발생을 배제하는 특약을 할 수 있고 그 특약은 유효하다고 본다.","c":"중","v":1},"변리사2024_61-20-4":{"w":"제320조의 견련성은 채권과 물건 사이에 있으면 되고 채권 발생 당시 점유하고 있을 필요는 없다. 판례도 채권 발생 후 점유를 취득한 경우 유치권이 성립할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-22-1":{"w":"판례는 유치권 배제 특약이 유효하면 유치권은 처음부터 생기지 않으므로 수급인의 지위를 이어받아 관리하는 파산관재인도 유치권을 행사할 수 없다고 본다.","c":"중","v":1},"변리사2023_60-22-2":{"w":"제358조 본문은 저당권의 효력이 저당부동산에 부합된 물건과 종물에 미친다고 정한다. 판례는 부합 시기가 저당권 설정 전인지 후인지를 묻지 않는다.","c":"상","v":1},"변리사2023_60-22-3":{"w":"판례는 제358조의 종물은 저당권 설정 당시 이미 있던 것이든 설정 후 종물이 된 것이든 모두 저당권의 효력이 미친다고 본다.","c":"중","v":1},"변리사2023_60-22-4":{"w":"판례는 제358조를 유추해 건물 소유를 위한 토지임차권이 건물의 종된 권리로서 그 건물에 설정된 저당권의 효력 범위에 들어간다고 본다.","c":"중","v":1},"변리사2023_60-22-5":{"w":"제359조는 저당부동산에 대한 압류가 있은 후 저당권설정자가 수취하는 과실 또는 수취할 수 있는 과실에 저당권의 효력이 미친다고 정한다. 차임채권은 법정과실이다.","c":"상","v":1},"변리사2024_61-21-1":{"w":"제343조는 동산질권에 제249조부터 제251조까지의 선의취득 규정을 준용한다. 처분권 없는 사람에게서 평온·공연·선의·무과실로 질권을 설정받으면 질권을 취득한다.","c":"상","v":1},"변리사2024_61-21-2":{"w":"제348조는 저당권으로 담보한 채권을 질권의 목적으로 한 때에는 그 저당권등기에 질권의 부기등기를 하여야 그 효력이 저당권에 미친다고 정한다.","c":"상","v":1},"변리사2024_61-21-3":{"w":"판례는 근질권이 설정된 금전채권에 제3자가 압류해 강제집행이 개시된 경우 근질권의 피담보채권은 근질권자가 그 강제집행 개시 사실을 안 때 확정된다고 본다. 근저당권의 확정 법리와 같다.","c":"중","v":1},"변리사2024_61-21-5":{"w":"물상대위에 압류를 요구하는 것은 변형물의 특정성을 유지하려는 것이므로 판례는 제3자가 이미 압류해 특정성이 유지되면 질권자·저당권자 스스로 압류하지 않아도 물상대위권을 행사할 수 있다고 본다(제342조).","c":"중","v":1},"변리사2018_55-23-2":{"w":"제320조 제1항은 그 물건이나 유가증권에 관하여 생긴 채권이 변제기에 있는 경우에 유치권을 인정한다.","c":"상","v":1},"변리사2017_54-24-1":{"w":"판례는 유치권의 요건인 점유에는 직접점유뿐 아니라 간접점유도 포함된다고 본다. 다만 채무자를 직접점유자로 하는 간접점유는 제외된다.","c":"중","v":1},"변리사2017_54-24-2":{"w":"판례는 자재공급업자의 자재대금채권은 매매대금채권에 불과해 건물 자체에 관하여 생긴 채권이 아니므로 건물에 대한 유치권을 행사할 수 없다고 본다.","c":"중","v":1},"변리사2017_54-24-4":{"w":"판례는 유치권자로부터 유치를 위해 점유를 위탁받은 사람은 유치권자의 점유매개자로서 소유자의 소유물반환청구에 대해 제213조 단서의 점유할 권리를 들어 거부할 수 있다고 본다.","c":"중","v":1},"변리사2017_54-24-5":{"w":"판례는 사회통념상 독립한 건물에 이르지 못한 정착물은 토지의 부합물이어서 수급인이 공사대금채권으로 그 정착물이나 토지에 유치권을 행사할 수 없다고 본다.","c":"중","v":1},"변리사2019_56-19-1":{"w":"유치권은 채무자의 점유를 빼앗아 변제를 간접강제하는 권리다. 판례는 채권자가 채무자를 직접점유자로 하여 간접점유하는 경우에는 유치권이 성립하지 않는다고 본다.","c":"중","v":1},"변리사2021_58-21-1":{"w":"제323조 제1항은 유치권자가 유치물의 과실을 수취하여 다른 채권보다 먼저 그 채권의 변제에 충당할 수 있다고 정한다.","c":"상","v":1},"변리사2023_60-20-4":{"w":"유치권은 변제기에 있는 채권에만 인정된다(제320조 제1항). 법원이 제203조 제3항에 따라 유익비 상환에 상당한 기간을 허락하면 변제기가 미뤄지므로 유치권이 소멸한다.","c":"중","v":1},"변리사2017_54-22-1":{"w":"판례는 가등기담보권 설정계약에서 가등기 이후 발생할 채무도 피담보채무에 포함하기로 한 약정을 유효하다고 본다.","c":"중","v":1},"변리사2017_54-22-2":{"w":"판례는 가등기가 차용금반환채무와 다른 원인의 채무를 함께 담보하다가 차용금반환채무만 남게 된 경우에는 가등기담보 등에 관한 법률이 적용된다고 본다.","c":"중","v":1},"변리사2017_54-22-3":{"w":"판례는 양도담보 목적물이 멸실해 설정자가 화재보험금청구권을 취득한 경우 양도담보권자는 담보물의 가치변형물인 그 보험금청구권에 물상대위권을 행사할 수 있다고 본다.","c":"중","v":1},"변리사2017_54-22-5":{"w":"판례는 피담보채무의 변제는 담보가등기 말소보다 먼저 이행해야 할 선이행의무이고 둘이 동시이행관계에 있지 않다고 본다.","c":"중","v":1},"변리사2019_56-24-2":{"w":"제353조 제2항은 채권의 목적물이 금전인 때 질권자가 자기 채권의 한도에서 직접 청구할 수 있다고 정한다.","c":"상","v":1},"변리사2019_56-24-4":{"w":"제348조는 저당권으로 담보한 채권을 질권의 목적으로 한 때 그 저당권등기에 질권의 부기등기를 해야 질권의 효력이 저당권에 미친다고 정한다. 저당권의 부종성 때문에 질권이 저당권에도 미치지만 등기로 공시하도록 한 것이다.","c":"상","v":1},"변리사2019_56-24-5":{"w":"판례는 제3채무자가 질권설정을 승낙한 뒤 질권설정계약이 합의해지된 경우 제452조 제1항을 유추해 질권설정자가 제3채무자에게 대항하려면 질권자가 제3채무자에게 해지 사실을 통지해야 한다고 본다.","c":"중","v":1},"변리사2021_58-23-1":{"w":"질권은 피담보채권 전부를 변제받을 때까지 목적물 전부에 효력이 미친다(제343조, 제355조가 준용하는 제321조 불가분성). 입질채권액이 피담보채권액보다 커도 질권은 입질채권 전부에 미친다.","c":"중","v":1},"변리사2021_58-23-2":{"w":"제347조는 채권증서가 있으면 그 증서를 교부해야 질권 설정의 효력이 생긴다고 정한다. 판례는 임대차계약서는 이 조문의 채권증서가 아니므로 교부하지 않아도 보증금반환채권에 대한 질권은 유효하다고 본다.","c":"중","v":1},"변리사2021_58-23-3":{"w":"제352조에 따라 질권설정자는 질권자의 동의 없이 입질채권을 소멸시키는 행위를 하지 못한다. 판례는 제3채무자가 이를 어기고 설정자와 상계합의를 해도 질권자에게 대항할 수 없으므로 질권자는 제353조에 따라 직접 변제를 청구할 수 있다고 본다.","c":"중","v":1},"변리사2021_58-23-4":{"w":"제348조는 저당권으로 담보한 채권을 질권의 목적으로 한 때 그 저당권등기에 질권의 부기등기를 해야 질권의 효력이 저당권에 미친다고 정한다. 저당권의 부종성 때문에 질권이 저당권에도 미치지만 등기로 공시하도록 한 것이다.","c":"상","v":1},"변리사2026_63-23-2":{"w":"판례는 저당권부채권에 질권을 설정하고 부기등기를 마치면 원본뿐 아니라 그 채권의 지연손해금도 등기부에 따로 기재하지 않았더라도 질권의 피담보채권 범위에 속한다고 본다.","c":"중","v":1},"변리사2026_63-23-3":{"w":"판례는 담보 없는 채권에 질권을 설정한 뒤 그 채권을 위해 저당권이 설정된 경우에도 제348조가 적용되어 저당권설정등기에 질권의 부기등기를 하지 않으면 질권의 효력이 저당권에 미치지 않는다고 본다.","c":"중","v":1},"변리사2026_63-23-4":{"w":"판례는 질권설정자가 질권자의 동의 없이도 입질채권을 양도할 수 있다고 본다. 양수인은 질권의 부담이 붙은 채권을 취득하므로 제352조가 금지하는 채권 소멸 행위에 해당하지 않는다.","c":"중","v":1},"변리사2026_63-23-5":{"w":"제349조 제1항은 질권설정을 제3채무자에게 통지하거나 그 승낙을 얻어야 대항할 수 있다고 정하며 제352조는 질권설정자가 질권자의 동의 없이 질권의 목적인 권리를 소멸하게 하는 행위를 하지 못한다고 정한다. 통지 후 설정자에게 한 변제는 질권자에게 대항하지 못한다.","c":"상","v":1},"변리사2016_53-21-3":{"w":"판례는 제352조에 반해 질권의 목적인 권리를 소멸시키는 행위는 질권자에 대한 관계에서만 무효일 뿐이므로 질권자 아닌 제3자는 그 무효를 주장할 수 없다고 본다.","c":"중","v":1},"변리사2016_53-25-1":{"w":"제467조 제1항은 채무의 성질 또는 당사자의 의사표시로 변제장소를 정하지 않은 때에는 특정물의 인도는 채권성립 당시에 그 물건이 있던 장소에서 하도록 정한다.","c":"상","v":1},"변리사2016_53-25-3":{"w":"제381조 제2항은 선택권 행사 기간이 없는 경우 채권의 기한이 도래한 후 상대방이 상당한 기간을 정해 최고해도 선택하지 않으면 선택권이 상대방에게 이전한다고 정한다. 종류채권의 지정권 이전에도 이 규정을 유추한다(통설).","c":"상","v":1},"변리사2016_53-25-5":{"w":"판례는 채무자가 가진 같은 종류의 주식 중 일부를 담보로 제공하기로 한 약정에 따른 채권을 일정 범위에서 종류로 정해진 제한종류채권으로 본다.","c":"중","v":1},"변리사2016_53-26-1":{"w":"판례는 이행불능 후 목적물 가격이 오른 경우 그 상승분은 특별한 사정으로 인한 손해여서 채무자가 이행불능 당시 그 사정을 알았거나 알 수 있었을 때에만 배상책임을 진다고 본다(제393조 제2항).","c":"중","v":1},"변리사2016_53-26-5":{"w":"판례는 손익상계가 허용되려면 손해배상책임의 원인이 된 행위로 피해자가 새로 이익을 얻었고 그 이익이 배상해야 할 손해의 범위와 상당인과관계에 있어야 한다고 본다.","c":"중","v":1},"변리사2016_53-27-5":{"w":"판례는 이행거절로 인한 계약해제를 인정하려면 채무를 이행하지 않으려는 채무자의 의사가 명백히 표시되고 그 의사표시가 위법한 것으로 평가되어야 한다고 본다.","c":"중","v":1},"변리사2016_53-29-1":{"w":"제387조 제1항 전단에 따라 확정기한이 있는 채무는 기한이 도래한 때부터 지체책임이 있다. 1월 12일이 기한이므로 그 다음 날인 1월 13일부터 지체가 된다.","c":"상","v":1},"변리사2016_53-29-2":{"w":"제517조는 지시채권 증서에 변제기한이 있는 경우에도 그 기한이 도래한 후 소지인이 증서를 제시하여 이행을 청구한 때부터 채무자가 지체책임을 진다고 정한다.","c":"상","v":1},"변리사2016_53-29-3":{"w":"채권자의 협력이 필요한 채무에서 채권자가 오지 않아 이행하지 못한 것은 채무자에게 책임 없는 사유다. 채무자가 이행을 제공하면 채무불이행 책임을 면하고(제461조) 채권자가 지체책임을 진다(제400조).","c":"중","v":1},"변리사2016_53-29-5":{"w":"판례는 확정된 지연손해금채무를 이행기의 정함이 없는 채무로 보므로 채무자는 채권자로부터 이행청구를 받은 때부터 지체책임을 진다(제387조 제2항).","c":"중","v":1},"변리사2017_54-25-5":{"w":"판례는 채무자가 잘못된 법률적 판단으로 채무가 없다고 믿고 이행을 거부한 채 소송으로 다툰 경우라도 그것만으로는 고의·과실이 없다고 할 수 없어 채무불이행 책임을 진다고 본다.","c":"중","v":1},"변리사2017_54-26-1":{"w":"판례는 계약 당시의 손해배상액 예정은 특별한 사정이 없으면 채무불이행으로 인한 손해만 예정한 것이고 그 계약과 관련된 불법행위로 인한 손해배상까지 예정한 것은 아니라고 본다.","c":"중","v":1},"변리사2017_54-26-2":{"w":"제399조는 채권자가 그 채권의 목적인 물건 또는 권리의 가액 전부를 손해배상으로 받은 때 채무자가 그 물건 또는 권리에 관하여 당연히 채권자를 대위한다고 정한다.","c":"상","v":1},"변리사2018_55-25-1":{"w":"제401조는 채권자지체 중에는 채무자가 고의 또는 중대한 과실이 없으면 불이행으로 인한 모든 책임이 없다고 정한다. 경과실에 의한 멸실은 책임이 없다.","c":"상","v":1},"변리사2018_55-27-5":{"w":"선택권 없는 甲의 과실로 X의 이행이 불능해졌으므로 급부가 Y로 특정되지 않는다(제385조 제2항). 선택권자 乙은 불능이 된 X를 선택하고 이행불능에 따른 손해배상(제390조)을 청구할 수 있다.","c":"상","v":1},"변리사2019_56-27-2":{"w":"판례는 계약 해제에 따른 원상회복의무(제548조)는 손해배상이 아니므로 이미 지급한 매매대금 등의 반환을 구하는 경우에는 과실상계가 적용되지 않는다고 본다.","c":"중","v":1},"변리사2019_56-31-2":{"w":"판례는 매매목적 부동산에 가압류가 집행되었다는 것만으로는 매도인의 소유권이전의무가 이행불능이 되지 않으므로 이를 이유로 계약을 해제할 수 없다고 본다. 가압류는 매도인이 해소할 수 있다.","c":"중","v":1},"변리사2019_56-31-4":{"w":"이행불능을 이유로 한 해제(제546조)는 최고가 필요 없다. 판례는 채무자의 의무가 이행불능이 되면 동시이행관계에 있는 상대방도 자기 채무의 이행제공 없이 계약을 해제할 수 있다고 본다.","c":"중","v":1},"변리사2019_56-31-5":{"w":"타인 소유 물건의 임대차도 유효하지만 판례는 진실한 소유자의 반환청구 등으로 임차인이 사용·수익할 수 없게 되면 임대인의 사용·수익하게 할 의무(제623조)가 이행불능이 된다고 본다.","c":"중","v":1},"변리사2021_58-25-3":{"w":"판례는 이행기의 정함이 없는 채권의 양수인이 이행의 소를 제기하고 소송 중 양도통지가 도달하면 채무자는 그 통지가 도달된 다음 날부터 이행지체책임을 진다고 본다. 소 제기 당시에는 양수인이 채무자에게 대항할 수 없었기 때문이다.","c":"중","v":1},"변리사2021_58-27-4":{"w":"판례는 매도인의 다른 채권자가 매매목적물에 강제경매를 신청해 절차가 진행 중이라는 것만으로는 매도인의 채무가 이행불능이 되지 않는다고 본다. 매도인이 채무를 변제해 경매를 막을 수 있기 때문이다.","c":"중","v":1},"변리사2021_58-27-5":{"w":"판례는 쌍무계약에서 일방의 급부뿐 아니라 상대방의 반대급부도 이행불능이 된 경우에는 대상청구를 할 수 없다고 본다. 대상청구를 하려면 자기 반대급부를 이행해야 하는데 그것이 불가능하기 때문이다.","c":"중","v":1},"변리사2024_61-25-5":{"w":"채권자취소권은 모든 채권자를 위한 책임재산 보전 제도이므로 판례는 피보전채권이 금전채권이어야 하고 특정물채권을 보전하기 위해서는 채권자취소권을 행사할 수 없다고 본다.","c":"중","v":1},"변리사2024_61-26-5":{"w":"임대인이 수선의무 이행을 위해 공사를 맡긴 수급인은 임대인의 이행보조자이므로 제391조에 따라 수급인의 과실은 임대인의 과실로 보아 임대인이 채무불이행 손해배상책임을 진다.","c":"중","v":1},"변리사2026_63-27-3":{"w":"판례는 채무불이행으로 인한 손해배상채무를 이행기의 정함이 없는 채무로 보므로 채권자가 이행을 청구한 때부터 채무자가 지체책임을 진다(제387조 제2항).","c":"중","v":1},"변리사2016_53-26-2":{"w":"제763조는 불법행위 손해배상에 제393조를 준용한다. 직접 대상이 아닌 간접적 손해는 특별한 사정으로 인한 손해여서 가해자가 그 사정을 알았거나 알 수 있었을 때에만 배상한다(제393조 제2항).","c":"중","v":1},"변리사2016_53-26-3":{"w":"판례는 위자료의 보완적 기능을 인정해 재산상 손해가 발생했으나 증명 곤란으로 손해액을 확정할 수 없어 배상받지 못하는 사정을 위자료 증액 사유로 참작할 수 있다고 본다.","c":"중","v":1},"변리사2017_54-26-4":{"w":"판례는 피해자의 부주의를 이용한 고의의 불법행위자 본인은 과실상계를 주장할 수 없지만 그 피용자의 고의 불법행위로 사용자책임(제756조)을 지는 사용자는 피해자의 과실을 들어 책임을 제한할 수 있다고 본다.","c":"중","v":1},"변리사2017_54-26-5":{"w":"판례는 해제에 따른 원상회복의무는 손해배상과 다르므로 이미 지급한 매매대금 등의 반환을 구하는 경우에는 과실상계(제396조)가 적용되지 않는다고 본다.","c":"중","v":1},"변리사2019_56-31-1":{"w":"타인의 권리도 증여나 매매의 목적이 될 수 있으므로(제569조 참조) 판례는 대상 권리가 타인에게 속한다는 사정만으로 이행불능이 되지 않는다고 본다. 사회통념상 그 권리를 취득해 이전할 수 없다고 인정되어야 불능이다.","c":"중","v":1},"변리사2021_58-27-1":{"w":"판례는 토지거래허가 전의 계약은 유동적 무효여서 채권적 효력이 없으므로 허가 전에 채무를 이행할 수 없게 되었더라도 그에 따른 손해배상책임을 지지 않는다고 본다.","c":"중","v":1},"변리사2021_58-27-2":{"w":"판례는 쌍무계약에서 일부만 이행불능이 되었더라도 나머지 이행만으로 계약 목적을 달성할 수 없으면 전부 불능으로 보아 계약 전부를 해제할 수 있다고 본다.","c":"중","v":1},"변리사2021_58-25-1":{"w":"판례는 쌍무계약의 당사자가 한 번 이행을 제공했다가 중지하면 상대방의 동시이행항변권이 다시 살아나므로 상대방에게 지연손해금을 청구하려면 자기 채무의 이행제공을 계속해야 한다고 본다.","c":"중","v":1},"변리사2021_58-25-2":{"w":"1층 골조공사 완료는 발생이 확실하나 시기가 불확실한 불확정기한이다. 제387조 제1항 후단에 따라 채무자는 기한이 도래함을 안 때부터 지체책임이 있으므로 판례상 안 날의 다음 날부터 지체가 된다.","c":"하","v":1},"변리사2021_58-25-4":{"w":"매수인이 매도인 영업소에 와서 받아가기로 한 추심채무는 채권자의 협력이 있어야 이행할 수 있다. 채권자가 오지 않아 이행하지 못한 것은 채무자에게 책임이 없으므로 지체책임을 지지 않는다.","c":"중","v":1},"변리사2016_53-25-4":{"w":"이자채권도 이미 발생해 변제기가 된 것은 독립한 금전채권이다. 판례는 그 이자의 지급을 지체하면 이자에 대한 지연손해금을 청구할 수 있다고 본다.","c":"중","v":1},"변리사2021_58-26-1":{"w":"판례는 수임인이 위임사무 처리로 받은 물건은 대체물이라도 위임인에게 인도할 그 물건 자체가 정해진 것이므로 당사자 사이에서는 특정된 물건과 같이 본다.","c":"중","v":1},"변리사2021_58-26-2":{"w":"제467조 제1항은 채무의 성질 또는 당사자의 의사표시로 변제장소를 정하지 않은 때 특정물의 인도는 채권성립 당시에 그 물건이 있던 장소에서 하도록 정한다.","c":"상","v":1},"변리사2021_58-26-3":{"w":"판례·통설은 제한종류채권에서 지정권자인 채무자가 기한 도래 후 채권자의 최고에도 이행할 물건을 지정하지 않으면 선택채권에 관한 제381조를 유추해 지정권이 채권자에게 이전한다고 본다.","c":"중","v":1},"변리사2021_58-26-5":{"w":"이자제한법 제2조 제3항에 따라 최고이자율을 넘는 이자 약정은 그 초과 부분이 무효이므로 초과 이자채권은 존재하지 않는다. 존재하지 않는 채권을 자동채권으로 한 상계는 효력이 없다.","c":"중","v":1},"변리사2023_60-28-1":{"w":"제392조는 채무자가 이행지체 중에 생긴 손해에 대해 과실이 없어도 배상책임이 있다고 정하고 이행기에 이행해도 손해를 면할 수 없는 경우만 예외로 한다.","c":"상","v":1},"변리사2023_60-28-2":{"w":"제183조는 주된 권리의 소멸시효가 완성한 때 종속된 권리에 그 효력이 미친다고 정한다. 원본채권이 시효로 소멸하면 그 종된 권리인 지분적 이자채권도 소멸한다.","c":"상","v":1},"변리사2023_60-28-3":{"w":"제397조 제2항은 금전채무불이행의 손해배상에 관하여 채권자가 손해를 증명할 필요가 없다고 정한다.","c":"상","v":1},"변리사2023_60-28-5":{"w":"판례는 무권대리인에 대한 이행 또는 손해배상청구권(제135조 제1항)의 소멸시효는 상대방이 선택권을 행사할 수 있는 때부터 진행한다고 본다.","c":"중","v":1},"변리사2026_63-26-1":{"w":"판례는 이미 변제기에 도달한 이자채권은 원본채권과 별개의 독립한 채권이므로 원본채권을 양도할 때 이자채권도 양도한다는 의사표시가 없으면 함께 양도되지 않는다고 본다.","c":"중","v":1},"변리사2026_63-26-2":{"w":"판례는 보유 주식 일정량을 담보로 제공하기로 한 약정에 따른 채권을 일정 범위의 주식 중에서 급부가 정해지는 제한종류채권으로 본다.","c":"중","v":1},"변리사2026_63-26-3":{"w":"제467조 제1항은 채무의 성질 또는 당사자의 의사표시로 변제장소를 정하지 않은 때 특정물의 인도는 채권성립 당시에 그 물건이 있던 장소에서 하도록 정한다.","c":"상","v":1},"변리사2026_63-26-4":{"w":"판례는 제한종류채권에서 당사자가 합의로 급부 목적물을 특정하거나 특정 방법 또는 지정권자를 정하면 그에 따른다고 본다. 합의가 없을 때에만 제375조 제2항의 특정 방법이 적용된다.","c":"중","v":1},"변리사2017_54-25-2":{"w":"판례는 이행보증계약상 보증금 지급의무에 지급금지가처분이 있어도 그것은 채무자가 임의로 지급하는 것을 막을 뿐 채무 자체를 소멸시키거나 지급거절 권능을 주지 않으므로 보증인은 지체책임을 면하지 못한다고 본다.","c":"중","v":1},"변리사2017_54-25-3":{"w":"제569조에 따라 타인 권리의 매매도 유효하고 매도인은 그 권리를 취득해 이전할 의무를 진다. 판례는 권리가 타인에게 속한다는 사정만으로 이행불능이 되지 않는다고 본다.","c":"중","v":1},"변리사2017_54-25-4":{"w":"판례는 부당이득반환의무를 이행기의 정함이 없는 채무로 보아 채무자가 이행청구를 받은 때(그 다음 날)부터 지체책임을 진다고 본다(제387조 제2항).","c":"중","v":1},"변리사2023_60-25-2":{"w":"제391조에 따라 이행보조자의 고의·과실은 채무자의 고의·과실로 본다. 판례는 이행보조자의 행위가 채무 이행과 객관적·외형적으로 관련되면 그것이 채권자에 대한 불법행위가 되더라도 채무자가 채무불이행 책임을 진다고 본다.","c":"중","v":1},"변리사2023_60-25-3":{"w":"판례는 대상청구권의 범위는 채무자가 이행불능으로 얻은 대상 전부이며 매매대금 범위로 제한되지 않는다고 본다.","c":"중","v":1},"변리사2023_60-25-4":{"w":"판례는 대상청구를 하는 당사자 자신의 반대급부도 전부 불능이 된 경우에는 반대급부를 이행할 수 없으므로 대상청구권을 행사할 수 없다고 본다.","c":"중","v":1},"변리사2023_60-25-5":{"w":"판례는 이행기의 정함이 없는 채권의 양수인이 소를 제기한 뒤 소송 중 양도통지가 도달하면 채무자는 그 통지가 도달한 다음 날부터 이행지체책임을 진다고 본다.","c":"중","v":1},"변리사2024_61-26-1":{"w":"판례는 제391조의 이행보조자는 채무자의 의사 관여 아래 채무 이행행위에 속하는 활동을 하는 사람이면 되고 채무자의 지시·감독을 받는 관계일 필요는 없다고 본다.","c":"중","v":1},"변리사2024_61-26-3":{"w":"판례는 매도인이 같은 부동산을 제3자에게 다시 매도하는 계약을 체결했다는 사실만으로는 먼저 체결된 매매계약이 이행불능이 되지 않는다고 본다. 제2매수인에게 이전등기를 마쳐야 불능이 된다.","c":"중","v":1},"변리사2024_61-26-4":{"w":"판례는 매매목적물이 화재로 소실되어 인도의무가 이행불능이 된 경우 채무자가 받게 되는 화재보험금은 목적물에 갈음하는 이익이므로 채권자가 대상청구권을 행사할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-27-1":{"w":"판례는 채무자가 이행을 거절하는 의사를 명백히 표시하면 이행기 전이라도 채권자가 최고 없이 계약을 해제할 수 있다고 본다(제544조 단서 참조).","c":"중","v":1},"변리사2026_63-27-2":{"w":"판례는 이행기의 정함이 없는 채권의 양수인이 소를 제기하고 소송 중 양도통지가 이루어진 경우 채무자는 그 통지가 도달한 다음 날부터 지체책임을 진다고 본다.","c":"중","v":1},"변리사2026_63-27-5":{"w":"판례는 이중매매에서 매도인이 제2매수인에게 이전등기를 마쳐주면 제1매수인에 대한 이전등기의무는 이행불능이 된다고 본다. 제2매수인의 선의·악의는 불능 판단에 영향이 없다.","c":"중","v":1},"변리사2024_61-27-3":{"w":"판례는 매도인의 이행거절로 인한 손해배상액은 이행거절 당시 부동산의 시가를 기준으로 산정한다고 본다.","c":"중","v":1},"변리사2019_56-27-1":{"w":"제394조는 다른 의사표시가 없으면 손해를 금전으로 배상하도록 정한다. 판례는 여기의 금전이 원칙적으로 우리나라 통화지만 당사자가 약정하면 외국통화로 배상할 수 있다고 본다.","c":"중","v":1},"변리사2019_56-27-3":{"w":"판례는 손해배상의 예정액을 제398조 제2항으로 감액할 때 채권자의 과실 등 제반 사정이 이미 참작되므로 그와 별도로 과실상계를 할 필요가 없다고 본다.","c":"중","v":1},"변리사2019_56-27-5":{"w":"판례는 매매대금 미지급으로 매도인이 다른 부동산 매매의 잔대금을 못 내 계약금을 몰수당한 손해는 특별한 사정으로 인한 손해로서 제393조 제2항의 예견가능성이 있어야 배상된다고 본다.","c":"중","v":1},"변리사2024_61-25-1":{"w":"제587조 후단은 매수인이 목적물의 인도를 받은 날부터 대금의 이자를 지급하도록 정한다. 판례는 대금지급이 지체되었더라도 목적물을 인도받기 전에는 이자를 지급할 필요가 없다고 본다.","c":"상","v":1},"변리사2024_61-25-3":{"w":"판례는 특정채권 보전을 위한 채권자대위권은 채무자의 무자력을 요하지 않는 대신, 그 특정물에 관하여 채무자가 제3채무자에게 가지는 권리만 대위행사할 수 있다고 본다.","c":"중","v":1},"변리사2024_61-25-4":{"w":"판례는 동·호수를 지정해 분양하는 아파트분양계약은 목적물이 특정된 특정물 매매이고 면적을 기준으로 대금을 정한 수량지정매매가 아니라고 본다.","c":"중","v":1},"변리사2017_54-28-2":{"w":"판례는 피보전채권이 사해행위 전에 성립했다면 그 뒤 채권이 양도되었더라도 양수인이 채권자취소권을 행사할 수 있다고 본다.","c":"중","v":1},"변리사2017_54-28-5":{"w":"판례는 채권자가 채무자의 채권자취소권을 대위행사하는 경우 제406조 제2항의 제척기간은 대위행사하는 채권자가 아니라 채무자를 기준으로 판단한다고 본다.","c":"중","v":1},"변리사2018_55-26-3":{"w":"판례는 채권자취소권은 책임재산 보전을 위한 것이므로 제1매수인이 특정물인 소유권이전등기청구권을 보전하기 위해 이중매매를 사해행위로 취소할 수 없다고 본다.","c":"중","v":1},"변리사2021_58-32-1":{"w":"판례는 피보전채권이 존재하지 않는다는 판결이 확정되면 그 채권으로 채권자취소권을 행사할 수 없다고 본다. 피보전채권의 존재는 채권자취소권의 요건이다.","c":"중","v":1},"변리사2021_58-32-2":{"w":"판례는 채권자가 물적 담보로 우선변제를 받을 수 있는 범위에서는 채무자의 재산처분이 채권자를 해하지 않으므로 그 범위에서는 채권자취소권을 행사할 수 없다고 본다.","c":"중","v":1},"변리사2021_58-32-3":{"w":"판례는 가압류 후 채무자가 목적물에 저당권을 설정해도 가압류채권자는 저당권자와 평등배당을 받게 되어 책임재산이 줄므로 그 저당권설정행위가 사해행위가 될 수 있다고 본다.","c":"중","v":1},"변리사2021_58-32-4":{"w":"판례는 공동저당 부동산 중 하나를 처분한 경우 피담보채권액을 각 부동산 가액 비율로 나누어 공제한다고 본다. X의 분담액은 3,000만 원×6/10=1,800만 원이므로 6,000만 원에서 이를 뺀 4,200만 원 범위에서 사해행위가 된다.","c":"중","v":1},"변리사2023_60-27-1":{"w":"제406조 제1항은 채권자가 사해행위의 취소 및 원상회복을 법원에 청구할 수 있다고 정한다. 판례도 채권자취소권은 소로써만 행사할 수 있다고 본다.","c":"상","v":1},"변리사2026_63-28-2":{"w":"판례는 재산분할청구권은 협의나 심판으로 구체적 내용이 형성되기 전에는 범위와 내용이 불명확해 채권자대위권의 목적이 될 수 없다고 본다.","c":"중","v":1},"변리사2026_63-28-4":{"w":"채권자대위권 행사는 채무자의 사무를 처리하는 것이어서 법정위임 관계와 비슷하다. 판례는 대위채권자가 제688조를 준용해 채무자에게 비용 상환을 청구할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-29-1":{"w":"판례는 사해행위 취소의 효력은 채권자와 수익자 사이에서만 생기므로 원상회복으로 채무자 명의가 회복되어도 채무자가 그 부동산을 다시 처분하면 무권리자의 처분으로서 효력이 없다고 본다.","c":"중","v":1},"변리사2026_63-29-2":{"w":"채권자취소권은 책임재산을 보전하기 위한 것이므로 판례는 채무자의 책임재산이 아닌 재산(예: 압류금지재산)에 관한 법률행위는 사해행위가 될 수 없다고 본다.","c":"중","v":1},"변리사2026_63-29-4":{"w":"판례는 사해행위취소청구와 원상회복청구를 동시에 할 필요가 없어 취소만 먼저 청구하고 원상회복은 나중에 청구할 수 있다고 본다. 다만 원상회복청구도 제406조 제2항의 기간 내에 해야 한다.","c":"중","v":1},"변리사2019_56-29-2":{"w":"판례는 대위소송의 피보전채권이 제3채무자에게 대항할 수 있는 권리일 필요는 없다고 본다. 채권자는 채무자의 권리를 행사하는 것이기 때문이다.","c":"중","v":1},"변리사2019_56-29-3":{"w":"판례는 토지거래허가 전의 매매에서 허가신청절차 협력의무 이행청구권도 피보전채권이 되어 이를 보전하기 위해 매도인의 권리를 대위행사할 수 있다고 본다.","c":"중","v":1},"변리사2019_56-29-4":{"w":"판례는 제3채무자는 채무자가 채권자에게 가지는 항변을 원용할 수 없으므로 피보전채권의 소멸시효 완성을 주장할 수 없다고 본다.","c":"중","v":1},"변리사2019_56-29-5":{"w":"판례는 피보전채권의 존재는 대위소송의 당사자적격 요건이므로 제3채무자도 그 채권의 발생원인인 법률행위가 무효라는 등 피보전채권의 존재를 다툴 수 있다고 본다.","c":"중","v":1},"변리사2016_53-34-4":{"w":"판례는 채권자취소권도 채권자대위권의 대상이 된다고 보므로 채권자는 채무자가 제3채무자의 사해행위에 대해 가지는 채권자취소권을 대위행사할 수 있다.","c":"중","v":1},"변리사2017_54-27-1":{"w":"판례(전원합의체)는 대위채권자에게 직접 지급을 명하는 판결이 확정되어도 그 판결은 피대위채권의 귀속을 바꾸지 않으므로 피대위채권이 변제 등으로 소멸하기 전이면 채무자의 다른 채권자가 이를 압류·가압류할 수 있다고 본다.","c":"중","v":1},"변리사2023_60-26-3":{"w":"판례는 조합원의 탈퇴권은 조합원 지분의 환급을 받기 위한 재산적 권리로서 일신전속적 권리가 아니므로 조합원의 채권자가 대위행사할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-28-1":{"w":"판례는 조합원의 조합 탈퇴권은 일신전속적 권리가 아니어서 조합원의 채권자가 지분 환급을 받기 위해 이를 대위행사할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-28-3":{"w":"판례는 금전채권 대위행사에서 대위채권자가 제3채무자에게 채무자가 아닌 자신에게 직접 지급하라고 청구할 수 있다고 본다. 그 뒤 상계로 사실상 우선변제를 받을 수 있다.","c":"중","v":1},"변리사2017_54-28-1":{"w":"판례는 사해행위취소 판결에 따른 원상회복의 말소등기를 소송당사자가 아닌 다른 채권자가 채무자를 대위해 마쳤더라도 그 등기는 절차상 흠이 있을 뿐 실체관계에 부합하는 등기로서 유효하다고 본다.","c":"중","v":1},"변리사2017_54-28-3":{"w":"판례는 주채무 전액에 대해 물상보증인의 담보로 채권자의 우선변제권이 확보되어 있으면 연대보증인이 유일한 재산을 처분해도 채권자를 해하지 않으므로 사해행위가 되지 않는다고 본다.","c":"중","v":1},"변리사2023_60-27-2":{"w":"판례는 채권자가 채무자 소유 부동산의 저당권으로 채권 전액의 우선변제권을 확보하고 있으면 수탁보증인의 사전구상권도 실질적으로 보전되어 있으므로 이를 피보전권리로 채무자의 처분을 취소할 수 없다고 본다.","c":"중","v":1},"변리사2023_60-27-3":{"w":"판례는 저당권이 설정된 부동산이 사해행위로 양도된 뒤 저당권 실행으로 수익자에게 배당이 된 경우, 원물반환이 불가능하므로 취소채권자가 수익자에게 그 배당금 상당액의 가액반환을 청구할 수 있다고 본다.","c":"중","v":1},"변리사2023_60-27-4":{"w":"판례는 사해행위 취소로 회복된 부동산을 채무자가 처분하는 것은 무권리자의 처분이므로 취소채권자와 취소·원상회복의 효력을 받는 다른 채권자(제407조)가 채무자를 대위해 그 명의인에게 등기 말소를 청구할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-29-5":{"w":"제406조 제1항 단서는 수익자가 채권자를 해함을 알지 못한 경우 취소를 배제한다. 판례는 수익자의 선의 여부만 따지고 선의에 과실이 있는지는 묻지 않는다고 본다.","c":"중","v":1},"변리사2024_61-28-1":{"w":"판례는 농지 매수인이 매도인을 대위해 농지취득자격증명 발급에 필요한 권리를 행사하는 등 농지취득자격증명 발급신청권도 채권자대위권의 행사 대상이 될 수 있다고 본다.","c":"중","v":1},"변리사2024_61-28-2":{"w":"채권자대위권은 채무자의 권리를 행사하는 것이어서 그 효과는 채무자에게 귀속한다. 판례는 대위소송 제기로 피대위채권의 소멸시효가 중단되는 효과도 채무자에게 생긴다고 본다.","c":"중","v":1},"변리사2024_61-28-4":{"w":"판례는 채권자취소의 범위는 원칙적으로 취소채권자의 채권액을 한도로 하고 목적물이 불가분이거나 다른 채권자의 배당요구가 명백한 경우 등 특별한 사정이 있을 때만 이를 넘을 수 있다고 본다.","c":"중","v":1},"변리사2024_61-28-5":{"w":"제116조 제1항은 의사표시의 효력이 어떤 사정을 알았는지에 의해 영향을 받는 경우 그 사실의 유무는 대리인을 표준으로 결정한다고 정한다. 판례도 수익자의 사해의사를 대리인을 기준으로 판단한다.","c":"중","v":1},"변리사2016_53-28-1":{"w":"제425조 제1항에 따라 연대채무자 한 사람이 변제로 공동면책이 되면 다른 연대채무자의 부담부분에 대해 구상할 수 있다. 판례는 자기 부담부분을 넘지 않는 일부 변제도 부담비율대로 구상할 수 있다고 보므로 900만원의 1/3씩 구상한다.","c":"상","v":1},"변리사2016_53-28-2":{"w":"제418조 제1항은 연대채무자 중 1인이 채권자에 대해 채권이 있는 경우 그 채무자가 상계한 때 채권은 모든 연대채무자의 이익을 위하여 소멸한다고 정한다.","c":"상","v":1},"변리사2016_53-28-3":{"w":"제418조 제2항은 상계할 채권이 있는 연대채무자가 상계하지 않으면 그 채무자의 부담부분에 한하여 다른 연대채무자가 상계할 수 있다고 정한다. 乙의 부담부분은 1,000만원이다.","c":"상","v":1},"변리사2016_53-28-5":{"w":"제419조는 어느 연대채무자에 대한 채무면제는 그 채무자의 부담부분에 한하여 다른 연대채무자의 이익을 위하여 효력이 있다고 정한다. 丙의 부담부분 1,000만원이 빠져 甲과 乙은 2,000만원을 연대 부담한다.","c":"상","v":1},"변리사2016_53-31-1":{"w":"판례는 채무인수가 면책적인지 중첩적인지 분명하지 않으면 채권자에게 유리한 중첩적 채무인수로 본다.","c":"중","v":1},"변리사2016_53-31-3":{"w":"판례는 중첩적 채무인수에서 인수인과 채무자가 연대채무 관계에 있는 경우 인수인이 상계하면 제418조 제1항에 따라 원채무자의 채무도 그 범위에서 소멸한다고 본다.","c":"중","v":1},"변리사2017_54-29-4":{"w":"제440조는 주채무자에 대한 시효의 중단은 보증인에 대하여 그 효력이 있다고 정한다. 연대보증인에게도 적용된다.","c":"상","v":1},"변리사2018_55-28-2":{"w":"제417조는 어느 연대채무자와 채권자 사이에 경개가 있는 때 채권은 모든 연대채무자의 이익을 위하여 소멸한다고 정한다.","c":"상","v":1},"변리사2018_55-28-3":{"w":"제427조 제1항은 상환할 자력이 없는 연대채무자의 부담부분은 구상권자와 다른 자력 있는 채무자가 부담부분 비율로 분담한다고 정한다. 乙의 몫 2,000만원을 甲과 丙이 1,000만원씩 나누므로 甲은 丙에게 2,000만원과 1,000만원을 합한 3,000만원을 구상한다.","c":"상","v":1},"변리사2018_55-28-4":{"w":"제419조에 따라 丙에 대한 면제는 丙의 부담부분 2,000만원 범위에서 다른 연대채무자에게도 효력이 있으므로 甲과 乙은 4,000만원을 연대 부담한다.","c":"상","v":1},"변리사2018_55-28-5":{"w":"제426조 제1항은 사전통지 없이 변제한 연대채무자에게 다른 연대채무자가 채권자에 대항할 사유로 그 부담부분에 한하여 대항할 수 있고 상계로 대항한 때에는 상계로 소멸할 채권이 변제한 채무자에게 이전된다고 정한다. 乙의 부담부분은 2,000만원이다.","c":"상","v":1},"변리사2018_55-29-3":{"w":"제446조는 주채무자가 면책 사실을 통지하지 않은 경우 선의로 변제한 수탁보증인이 자기 변제의 유효를 주장할 수 있다고 정한다. 판례는 보증인이 제445조의 사전통지도 하지 않았다면 이 보호를 받지 못해 주채무자에게 변제의 유효를 주장할 수 없다고 본다.","c":"중","v":1},"변리사2018_55-31-2":{"w":"판례는 채무자와 인수인 사이의 채무인수에서 채권자가 승낙을 거절하면 그 뒤 다시 승낙하더라도 면책적 채무인수의 효력이 생기지 않는다고 본다(제454조, 제456조).","c":"중","v":1},"변리사2019_56-32-1":{"w":"중첩적 채무인수는 채무자의 채무가 그대로 남아 채무자에게 불이익이 없다. 판례는 채권자와 인수인의 합의만으로 채무자의 의사에 반해서도 할 수 있다고 본다.","c":"중","v":1},"변리사2019_56-32-2":{"w":"판례는 면책적 채무인수는 인수인이 채무를 승인한 것이어서 소멸시효가 중단되고 채무인수일부터 새로 진행한다고 본다.","c":"중","v":1},"변리사2019_56-32-3":{"w":"판례는 채무자와 인수인 사이의 계약에 따른 채무인수에서 채권자가 승낙을 거절하면 채무인수는 확정적으로 효력이 없게 되어 나중에 승낙해도 효력이 생기지 않는다고 본다.","c":"중","v":1},"변리사2019_56-32-4":{"w":"제454조의 채권자 승낙은 방식이 없다. 판례는 채권자가 인수인에게 직접 인수채무의 이행을 청구하는 것도 묵시적 승낙으로 본다.","c":"중","v":1},"변리사2021_58-28-4":{"w":"판례는 중첩적 채무인수는 채무자의 채무가 소멸하지 않아 채무자에게 불리하지 않으므로 채권자와 인수인의 계약으로 채무자의 의사에 반해서도 할 수 있다고 본다.","c":"중","v":1},"변리사2021_58-30-1":{"w":"판례는 추심을 위임하면서 채권을 양도한 경우 그 원인인 위임이 해지되면 채권은 양도인에게 복귀한다고 본다. 다만 양도인이 이를 채무자에게 대항하려면 양수인이 양도인에게 채권이 복귀했다는 사실을 채무자에게 통지해야 한다.","c":"중","v":1},"변리사2021_58-30-2":{"w":"보증채무는 주채무에 부종하므로 판례는 주채권과 분리해 보증채권만 양도하기로 하는 약정은 효력이 없다고 본다.","c":"중","v":1},"변리사2021_58-30-3":{"w":"판례는 양도금지특약이 있는 채권도 압류·전부명령으로 이전될 수 있고 압류채권자의 선의·악의는 전부명령의 효력에 영향을 주지 않는다고 본다. 사적 특약으로 압류금지재산을 만들 수 없기 때문이다.","c":"중","v":1},"변리사2021_58-30-5":{"w":"판례는 확정일자 있는 양도통지와 압류·전부명령이 제3채무자에게 동시에 도달하면 양수인과 전부채권자가 서로 우선을 주장할 수 없으므로 제3채무자는 채권자를 알 수 없음을 이유로 변제공탁(제487조)을 할 수 있다고 본다.","c":"하","v":1},"변리사2026_63-30-2":{"w":"판례는 담보 목적의 채권양도 후 피담보채무가 변제되었다는 사정은 양도인과 양수인 사이의 문제일 뿐이므로 양도된 채권의 채무자는 이를 이유로 양수인의 청구를 거절할 수 없다고 본다.","c":"중","v":1},"변리사2026_63-30-3":{"w":"판례는 양도금지 특약에 대해 선의인 양수인이 채권을 유효하게 취득하면 그로부터 다시 양수한 전득자는 악의라도 유효하게 채권을 취득한다고 본다.","c":"중","v":1},"변리사2026_63-31-2":{"w":"판례는 면책적 채무인수는 인수인이 채무를 승인하는 것이므로 인수채무의 소멸시효가 중단되고 채무인수일부터 새로 진행한다고 본다.","c":"중","v":1},"변리사2019_56-28-1":{"w":"판례는 채권양도에 대한 채무자의 승낙에 조건을 붙일 수 있다고 본다. 승낙은 관념의 통지지만 조건을 붙이는 것을 막을 이유가 없기 때문이다.","c":"중","v":1},"변리사2019_56-28-2":{"w":"판례는 채무자가 이의 없이 승낙했더라도 특별한 사정이 없으면 양수인에게 채권의 성립·소멸에 영향을 미치는 사정을 알려줄 주의의무는 없다고 본다.","c":"중","v":1},"변리사2019_56-28-4":{"w":"제451조 제1항의 이의를 보류하지 않은 승낙은 양수인의 신뢰를 보호하는 제도다. 판례는 양수인이 항변사유를 알았거나 중대한 과실로 몰랐다면 채무자가 그 항변으로 대항할 수 있다고 본다.","c":"중","v":1},"변리사2019_56-28-5":{"w":"보증채무는 주채무에 수반하므로 판례는 주채권이 양도되면 보증채권도 함께 이전되고 주채권 양도에 대항요건을 갖추면 보증채권에 대해 따로 대항요건을 갖출 필요가 없다고 본다.","c":"중","v":1},"변리사2018_55-30-1":{"w":"판례는 채권양도에 대한 채무자의 승낙에 조건을 붙일 수 있다고 본다. 승낙은 채무자가 양도 사실을 인식했다는 관념의 표시지만 조건을 붙이는 것을 막을 이유가 없다.","c":"중","v":1},"변리사2018_55-30-2":{"w":"제450조의 양도통지는 양도인이 해야 한다. 판례는 양수인이 양도인의 위임을 받아 대리인으로 통지할 수 있지만 대리관계를 현명해야 하므로 현명 없이 양수인 명의로 한 통지는 특별한 사정이 없으면 효력이 없다고 본다.","c":"중","v":1},"변리사2018_55-30-3":{"w":"제451조 제2항은 양도인이 양도통지만 한 때 채무자는 통지를 받은 때까지 양도인에 대하여 생긴 사유로 양수인에게 대항할 수 있다고 정한다. 통지 후에 생긴 대여금채권으로는 상계로 대항하지 못한다.","c":"상","v":1},"변리사2018_55-30-5":{"w":"제452조 제1항은 양도인이 양도통지를 한 때 아직 양도하지 않았거나 그 양도가 무효인 경우에도 선의인 채무자는 양수인에게 대항할 수 있는 사유로 양도인에게 대항할 수 있다고 정한다. 양도가 취소된 경우도 같다.","c":"상","v":1},"변리사2016_53-30-3":{"w":"계약이 해제되면 각 당사자는 원상회복의무를 진다(제548조 제1항). 판례는 계약상 채권의 양수인은 제548조 제1항 단서의 보호받는 제3자가 아니므로 양수인이 변제받은 뒤 계약이 해제되면 채무자는 양수인에게 직접 반환을 청구할 수 있다고 본다.","c":"중","v":1},"변리사2021_58-29-2":{"w":"제409조는 불가분채권에서 각 채권자는 모든 채권자를 위하여 이행을 청구할 수 있다고 정한다. 그 청구는 모든 채권자를 위한 것이어서 채무자는 다른 채권자에게도 지체책임을 진다.","c":"상","v":1},"변리사2021_58-29-3":{"w":"판례는 공유물을 무단 점유한 제3자에 대한 부당이득반환청구권은 불가분채권이 아니라 각 공유자가 자기 지분 비율에 따라 가지는 분할채권이라고 본다.","c":"중","v":1},"변리사2021_58-29-4":{"w":"판례는 중첩적 채무인수에서 인수인이 채무자의 부탁으로 인수한 경우 원칙적으로 채무자와 인수인은 연대채무 관계에 있다고 본다. 부탁 없이 인수했다면 부진정연대 관계다.","c":"중","v":1},"변리사2021_58-29-5":{"w":"연대채무자에 대한 채권은 채무자마다 별개다. 판례는 甲의 乙에 대한 채권에 압류·추심명령이 있어도 丙에 대한 채권에는 미치지 않으므로 甲은 丙에게 이행을 청구할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-32-5":{"w":"제430조는 보증인의 부담이 주채무의 목적이나 형태보다 중한 때에는 주채무의 한도로 감축한다고 정한다.","c":"상","v":1},"변리사2019_56-26-1":{"w":"제429조 제2항은 보증인이 그 보증채무에 관한 위약금 기타 손해배상액을 예정할 수 있다고 정한다.","c":"상","v":1},"변리사2019_56-26-2":{"w":"제431조 제1항은 보증인을 세울 의무가 있는 채무자가 행위능력 및 변제자력이 있는 자를 보증인으로 세우도록 하지만 제3항은 채권자가 보증인을 지명한 경우에는 이를 적용하지 않는다고 정한다.","c":"상","v":1},"변리사2019_56-26-3":{"w":"제444조 제2항은 주채무자의 의사에 반하여 보증인이 된 자가 자기의 출재로 주채무를 소멸하게 한 때 주채무자는 현존이익의 한도에서 배상하도록 정한다.","c":"상","v":1},"변리사2019_56-26-5":{"w":"제441조 제2항은 수탁보증인의 구상권에 제425조 제2항을 준용하므로 구상권에는 면책된 날 이후의 법정이자와 피할 수 없는 비용 기타 손해배상이 포함된다.","c":"상","v":1},"변리사2026_63-30-4":{"w":"판례는 임대차보증금반환채권의 양도 통지를 받은 뒤 임대인과 임차인이 임대차계약을 갱신하기로 합의해도 양수인에게는 그 효력이 미치지 않으므로 양수인은 원래 계약의 종료를 전제로 보증금 반환을 청구할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-30-5":{"w":"보증채무는 주채무에 부종하므로 판례는 주채권과 분리해 보증채권만 양도하기로 하는 약정은 효력이 없다고 본다.","c":"중","v":1},"변리사2024_61-30-4":{"w":"판례는 선순위 근저당권부채권 양수인보다 후순위인 근저당권자는 양도된 채권 자체에 관하여 양수인과 양립할 수 없는 법률상 지위를 취득한 사람이 아니므로 제450조 제2항의 제3자에 포함되지 않는다고 본다.","c":"중","v":1},"변리사2016_53-31-2":{"w":"판례는 상대방의 승낙을 얻어 계약당사자의 지위를 포괄적으로 이전하는 계약인수에서는 종래 계약에서 이미 발생한 채권·채무도 모두 인수인에게 이전된다고 본다.","c":"중","v":1},"변리사2016_53-31-5":{"w":"판례는 채무자의 부탁 없이 채권자와의 계약으로 채무를 중첩적으로 인수한 경우 채무자와 인수인은 주관적 공동관계가 없어 부진정연대채무 관계에 있다고 본다.","c":"중","v":1},"변리사2017_54-31-2":{"w":"판례는 채권자와 보증인 사이에 보증인이 주채무를 중첩적으로 인수하기로 한 경우 채권자에 대해서는 인수인이 되지만 주채무자와의 관계에서는 종전 보증인의 지위를 그대로 유지한다고 본다.","c":"중","v":1},"변리사2023_60-31-1":{"w":"이행인수인은 채무자에 대해서만 이행 의무를 질 뿐 채권자에게 직접 채무를 부담하지 않는다. 판례는 이행인수인이 채권자에게 채무를 승인해도 채무자의 대리인 등이 아닌 한 시효중단 효력이 없다고 본다.","c":"중","v":1},"변리사2016_53-32-3":{"w":"판례는 채무 담보를 위한 대물변제예약 후 같은 채권자에게서 추가로 채무를 진 경우 특별한 사정이 없으면 그 추가 채무도 예약의 대상인 채무에 포함된다고 본다.","c":"중","v":1},"변리사2016_53-32-4":{"w":"제466조는 채무자가 채권자의 승낙을 얻어 본래 채무이행에 갈음하여 다른 급여를 한 때에 변제와 같은 효력을 인정한다. 판례는 대물변제는 요물계약이어서 다른 급부가 현실적으로 이루어져야(부동산이면 등기까지) 채무가 소멸한다고 본다.","c":"중","v":1},"변리사2016_53-32-5":{"w":"판례는 대물변제예약완결권은 형성권이므로 행사기간 약정이 없으면 권리가 발생한 때부터 10년 내에 행사해야 하고 이 기간은 제척기간이어서 지나면 완결권이 소멸한다고 본다.","c":"중","v":1},"변리사2017_54-32-1":{"w":"제498조는 지급금지명령을 받은 제3채무자가 그 후 취득한 채권으로 상계하지 못하게 할 뿐이다. 판례는 가압류 효력 발생 당시 양 채권이 상계적상에 있으면 제3채무자는 상계로 가압류채권자에게 대항할 수 있다고 본다.","c":"중","v":1},"변리사2017_54-32-2":{"w":"판례(전원합의체)는 가압류 당시 자동채권의 변제기가 도래하지 않았더라도 그 변제기가 수동채권의 변제기와 동시에 또는 먼저 도래하면 제3채무자는 상계로 가압류채권자에게 대항할 수 있다고 본다.","c":"중","v":1},"변리사2017_54-32-4":{"w":"판례(전원합의체)는 가압류 당시 자동채권의 변제기가 도래하지 않았더라도 수동채권의 변제기보다 먼저 또는 동시에 도래하면 제3채무자의 상계에 대한 기대가 보호되므로 상계로 대항할 수 있다고 본다.","c":"중","v":1},"변리사2017_54-32-5":{"w":"상계는 상계적상만으로 효력이 생기지 않고 상대방에 대한 의사표시로 해야 한다(제493조 제1항). 乙이 상계의 의사표시를 하지 않으면 甲의 채권은 그대로 남으므로 이를 들어 丙에게 대항할 수 없다.","c":"중","v":1},"변리사2019_56-25-1":{"w":"물상보증인이 채무를 변제하면 보증채무에 관한 규정에 의해 채무자에게 구상권이 있다(제341조, 제370조). 丁은 甲의 부탁으로 담보를 제공했으므로 수탁보증인에 준해 구상할 수 있다.","c":"중","v":1},"변리사2019_56-25-2":{"w":"제482조 제2항 제5호에 따라 보증인과 물상보증인 사이에서는 그 인원수에 비례하여 대위하므로 丙·丁·戊 3명이 6억원을 2억원씩 분담한다. 丁은 乙을 대위해 보증인 丙에게 2억원을 청구할 수 있다.","c":"중","v":1},"변리사2019_56-25-3":{"w":"물상보증인은 변제할 정당한 이익이 있는 자이므로 제481조에 따라 변제로 당연히 채권자를 대위하며 채권자의 승낙이 필요 없다.","c":"상","v":1},"변리사2019_56-25-4":{"w":"제482조 제2항 제1호의 부기등기는 보증인이 저당물에 권리를 취득한 제3자에게 대위하기 위한 요건이다. 판례는 물상보증인은 여기의 제3자가 아니므로 보증인 丙이 미리 부기등기를 하지 않아도 물상보증인 丁에게 채권자를 대위할 수 있다고 본다.","c":"중","v":1},"변리사2016_53-32-1":{"w":"판례는 채무변제에 갈음해 다른 채권을 양도하는 대물변제는 채권양도의 요건(대항요건 포함)을 갖추어 대체급부가 이루어져야 원래 채무가 소멸한다고 본다(제466조).","c":"중","v":1},"변리사2023_60-32-1":{"w":"변제충당은 당사자의 합의가 있으면 그에 따른다. 판례는 채무자가 원본 충당을 지정해 지급하고 채권자가 이의 없이 받아 묵시적 합의가 인정되면 제479조의 법정 순서와 달리 원본에 충당된다고 본다.","c":"중","v":1},"변리사2023_60-32-2":{"w":"판례는 이자채무만 시효가 완성된 상태에서 채무자가 충당을 지정하지 않고 일부 변제하면 특별한 사정이 없는 한 제479조 제1항에 따라 이자채무에 먼저 충당되며 이는 시효이익 포기로 볼 여지가 있다고 본다.","c":"중","v":1},"변리사2023_60-32-3":{"w":"상계금지는 상계를 못 하게 할 뿐 채권의 양도·압류를 금지하지 않는다. 판례는 상계금지채권이라도 압류금지채권이 아니면 전부명령의 대상이 될 수 있다고 본다.","c":"중","v":1},"변리사2023_60-32-5":{"w":"제495조는 소멸시효가 완성된 채권이 그 완성 전에 상계할 수 있었던 것이면 그 채권자가 상계할 수 있다고 정한다.","c":"상","v":1},"변리사2026_63-33-1":{"w":"판례는 대위변제자는 채권자의 원래 채권과 담보를 그 범위 안에서 행사하는 것이므로 대위변제자와 채무자 사이의 구상금 지연손해금 약정은 변제자대위권 행사에 적용되지 않는다고 본다.","c":"중","v":1},"변리사2026_63-33-2":{"w":"판례는 근저당권의 피담보채권이 확정되기 전에는 근저당권이 특정 채권에 부종하지 않으므로 채권 일부가 대위변제되어도 근저당권이 대위변제자에게 이전되지 않는다고 본다.","c":"중","v":1},"변리사2026_63-33-3":{"w":"제482조 제2항 제1호의 부기등기는 보증인이 저당물에 권리를 취득한 제3취득자에게 대위하기 위한 요건이다. 판례는 후순위 근저당권자는 여기의 제3자에 포함되지 않으므로 부기등기 없이도 대위할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-33-5":{"w":"제482조 제2항 제4호는 물상보증인이 수인인 경우 제3호를 준용하므로 물상보증인 1인은 각 부동산의 가액에 비례하여 다른 물상보증인에 대해 채권자를 대위한다.","c":"상","v":1},"변리사2016_53-33-1":{"w":"동시이행의 항변권(제536조)은 하나의 쌍무계약에서 생긴 대가적 채무 사이에 인정된다. 판례는 별개의 계약에서 생긴 채무 사이에는 특별한 사정이 없는 한 동시이행관계가 없다고 본다.","c":"중","v":1},"변리사2016_53-33-5":{"w":"판례는 한 번 현실의 제공으로 상대방을 수령지체에 빠지게 했어도 이행제공이 계속되지 않으면 과거의 이행제공만으로 상대방의 동시이행항변권이 소멸하지 않는다고 본다.","c":"중","v":1},"변리사2017_54-34-1":{"w":"甲은 요약자, 乙은 낙약자이다. 판례는 제3자를 위한 계약에서 요약자의 채무불이행이 있으면 낙약자는 수익자의 동의 없이 계약을 해제할 수 있다고 본다. 수익자는 계약 당사자가 아니기 때문이다.","c":"중","v":1},"변리사2017_54-34-2":{"w":"요약자와 수익자 사이의 대가관계는 제3자를 위한 계약의 내용이 아니다. 대가관계인 금전소비대차가 취소되어도 요약자와 낙약자 사이의 기본관계인 매매계약의 효력에는 영향이 없다.","c":"중","v":1},"변리사2017_54-34-3":{"w":"판례는 제3자를 위한 계약의 수익자는 계약에 따라 직접 권리를 취득하는 자일 뿐 그 계약을 기초로 새로운 법률관계를 맺은 사람이 아니므로 제110조 제3항의 제3자에 해당하지 않는다고 본다.","c":"중","v":1},"변리사2017_54-34-5":{"w":"판례는 낙약자가 수익자에게 급부한 뒤 기본관계인 계약이 해제되면 낙약자는 요약자에게 원상회복이나 부당이득반환을 구해야 하고 수익자에게는 반환을 청구할 수 없다고 본다.","c":"중","v":1},"변리사2017_54-35-3":{"w":"丁은 해제 전에 乙 명의의 등기를 믿고 가등기를 마친 사람이므로 제548조 제1항 단서의 보호받는 제3자다. 해제가 있어도 丁의 권리는 해하지 못하므로 丁은 본등기를 할 수 있다.","c":"중","v":1},"변리사2017_54-40-4":{"w":"약관의 규제에 관한 법률 제3조 제3항의 설명의무는 고객이 약관 내용을 알고 계약하게 하려는 것이다. 판례는 고객의 대리인과 계약하는 경우 그 대리인에게 약관을 설명하면 족하다고 본다.","c":"중","v":1},"변리사2019_56-34-4":{"w":"9. 17. 발송한 편지는 보통이면 9. 25.까지 도달할 수 있었으므로 제528조 제2항에 따라 청약자 甲은 연착 통지를 해야 한다. 甲이 연착 통지를 했으므로 승낙은 효력이 없고 계약은 성립하지 않는다.","c":"상","v":1},"변리사2021_58-33-1":{"w":"제541조는 제3자의 권리가 생긴 후 당사자가 이를 변경·소멸시키지 못한다고 정한다. 판례는 당사자가 미리 계약에서 제3자의 권리를 변경·소멸시킬 수 있음을 유보했다면 그 유보는 제3자에게도 효력이 있다고 본다.","c":"중","v":1},"변리사2021_58-33-3":{"w":"낙약자가 수익자에게 대항할 수 있는 것은 기본관계(요약자와 낙약자의 계약)에서 생긴 항변뿐이다(제542조). 판례는 요약자와 수익자 사이의 대가관계가 취소되어도 낙약자는 이를 이유로 수익자에게 급부를 거절할 수 없다고 본다.","c":"중","v":1},"변리사2021_58-33-4":{"w":"판례는 요약자가 낙약자의 채무불이행을 이유로 계약을 해제한 경우 수익자는 낙약자에게 자기가 입은 손해의 배상을 청구할 수 있다고 본다. 원상회복이나 계약 해제는 청구할 수 없다.","c":"중","v":1},"변리사2021_58-33-5":{"w":"판례는 기본관계인 매매계약이 취소되어도 낙약자는 요약자에게 반환을 구해야 하고 이미 급부를 받은 수익자에게 부당이득반환을 청구할 수 없다고 본다.","c":"중","v":1},"변리사2021_58-34-2":{"w":"임대차는 낙성계약(제618조)이다. 판례는 보증금 지급 약정이 있더라도 보증금 수수는 임대차계약의 성립요건이 아니라고 본다.","c":"중","v":1},"변리사2021_58-34-4":{"w":"판례는 매매계약 체결 당시 목적물과 대금이 구체적으로 확정되지 않았더라도 나중에 확정할 수 있는 방법과 기준이 정해져 있으면 계약이 성립한다고 본다.","c":"중","v":1},"변리사2021_58-36-2":{"w":"판례는 매도인이 매수인의 채무불이행을 이유로 계약을 해제한 뒤에도 매수인은 해제에 따른 손해배상책임 등을 면하기 위해 착오를 이유로 계약을 취소할 수 있다고 본다.","c":"중","v":1},"변리사2021_58-36-3":{"w":"판례는 해제 전에 해제된 계약에서 생긴 법률효과를 기초로 새로운 이해관계를 맺은 가압류채권자도 제548조 제1항 단서의 제3자에 포함된다고 본다. 甲은 丙에게 해제의 소급효를 주장할 수 없다.","c":"중","v":1},"변리사2021_58-36-4":{"w":"판례는 해제에 따른 원상회복의무는 손해배상의무가 아니므로 과실상계(제396조)가 적용되지 않는다고 본다.","c":"중","v":1},"변리사2021_58-36-5":{"w":"판례는 매수인이 중도금을 약정 기일에 지급하지 않으면 자동으로 해제된다는 약정은 유효하며 그 불이행이 있으면 해제 의사표시 없이 계약이 해제된다고 본다. 잔금 지급과 이전등기가 동시이행인 경우의 자동해제 약정과 다르다.","c":"중","v":1},"변리사2024_61-34-2":{"w":"甲과 乙 모두에게 책임 없는 지진으로 甲의 인도채무가 불능이 되었으므로 제537조에 따라 甲은 乙에게 반대급부인 매매대금을 청구하지 못한다.","c":"상","v":1},"변리사2024_61-34-3":{"w":"제537조에 따라 甲은 대금을 청구할 수 없게 되므로 이미 받은 대금은 법률상 원인 없는 이득이 된다. 乙은 부당이득(제741조)으로 반환을 청구할 수 있다.","c":"중","v":1},"변리사2024_61-34-4":{"w":"제538조 제1항 전단은 쌍무계약의 당사자 일방의 채무가 채권자의 책임 있는 사유로 이행할 수 없게 된 때 채무자가 상대방의 이행을 청구할 수 있다고 정한다.","c":"상","v":1},"변리사2024_61-34-5":{"w":"제538조 제1항 후단은 채권자의 수령지체 중에 당사자 쌍방의 책임 없는 사유로 이행할 수 없게 된 때에도 채무자가 상대방의 이행을 청구할 수 있다고 정한다.","c":"상","v":1},"변리사2026_63-35-1":{"w":"제541조는 제3자의 권리가 생긴 후에는 당사자가 이를 변경 또는 소멸시키지 못한다고 정한다.","c":"상","v":1},"변리사2026_63-35-2":{"w":"수익자는 계약 당사자가 아니므로 판례는 수익자가 계약 당사자의 의사표시 하자를 이유로 계약을 취소할 수 없다고 본다. 취소권은 계약 당사자에게 있다.","c":"중","v":1},"변리사2026_63-35-3":{"w":"판례는 수익자가 수익의 의사표시를 한 뒤라도 요약자는 낙약자의 채무불이행을 이유로 수익자의 동의 없이 계약을 해제할 수 있다고 본다. 해제는 제541조가 금지하는 임의의 변경·소멸이 아니다.","c":"중","v":1},"변리사2026_63-35-5":{"w":"판례는 낙약자가 수익자에게 급부한 뒤 계약이 해제되면 낙약자는 계약 당사자인 요약자에게 원상회복을 구해야 하고 수익자를 상대로 원상회복이나 부당이득반환을 청구할 수 없다고 본다.","c":"중","v":1},"변리사2026_63-25-4":{"w":"판례는 해제로 인한 원상회복의무의 이행지체에 따른 지연손해금률을 따로 약정했다면 그 약정이율이 법정이율보다 낮더라도 약정에 따른다고 본다.","c":"중","v":1},"변리사2018_55-33-5":{"w":"판례는 특정 계약에서 생기는 채무를 보증한 경우 보증인은 특별한 사정이 없으면 채무불이행으로 계약이 해제되었을 때의 원상회복의무에 대해서도 보증책임을 진다고 본다.","c":"중","v":1},"변리사2021_58-34-1":{"w":"판례는 계약 당사자 확정은 의사해석의 문제여서 관여한 당사자들의 의사가 일치하면 그 의사대로 당사자를 정한다고 본다. 의사가 일치하지 않으면 상대방이 합리적으로 누구를 당사자로 이해했을지를 기준으로 한다.","c":"중","v":1},"변리사2021_58-34-5":{"w":"제532조는 청약자의 의사표시나 관습에 의하여 승낙의 통지가 필요하지 않은 경우 계약은 승낙의 의사표시로 인정되는 사실이 있는 때에 성립한다고 정한다.","c":"상","v":1},"변리사2024_61-33-2":{"w":"판례는 예금계약은 예금자가 돈을 제공하고 은행 직원이 그 의사에 따라 받아 확인하면 성립하며 직원이 실제로 입금하지 않거나 횡령했더라도 계약 성립에 영향이 없다고 본다.","c":"중","v":1},"변리사2024_61-33-3":{"w":"제533조는 당사자 간에 동일한 내용의 청약이 상호교차된 경우 양 청약이 상대방에게 도달한 때 계약이 성립한다고 정한다.","c":"상","v":1},"변리사2024_61-33-4":{"w":"제534조에 따라 승낙자가 청약에 조건을 붙여 승낙하면 그 청약을 거절하고 새로 청약한 것으로 본다. 판례는 합의해제의 청약에도 이를 적용해 조건부 승낙이 있으면 원래 청약은 실효된다고 본다.","c":"중","v":1},"변리사2024_61-33-5":{"w":"판례는 임대인에게 목적물에 대한 소유권이나 임대 권한이 없어도 임대차계약은 유효하게 성립한다고 본다. 임대차는 사용·수익하게 할 채무를 지는 채권계약이기 때문이다.","c":"중","v":1},"변리사2019_56-36-1":{"w":"판례는 합의해제는 당사자가 새로운 계약으로 원래 계약을 소멸시키는 것이어서 제548조, 제551조가 적용되지 않으므로 따로 약정하지 않았다면 채무불이행에 따른 손해배상을 청구할 수 없다고 본다.","c":"중","v":1},"변리사2019_56-36-2":{"w":"제534조는 조건을 붙인 승낙을 청약의 거절과 새 청약으로 본다. 판례는 합의해제 청약에 조건을 붙여 승낙했다면 매도인의 청약은 실효된다고 본다.","c":"중","v":1},"변리사2019_56-36-4":{"w":"판례는 합의해제된 매매계약을 다시 살리는 약정도 계약자유의 원칙상 당사자 사이에서는 유효하다고 본다. 다만 그 사이에 이해관계를 맺은 제3자에게는 대항할 수 없다.","c":"중","v":1},"변리사2019_56-36-5":{"w":"판례는 합의해제·해지에는 제548조 제2항이 적용되지 않으므로 약정이 없으면 반환할 금전에 받은 날부터 이자를 붙일 의무가 없다고 본다.","c":"중","v":1},"변리사2023_60-35-1":{"w":"판례는 타인 권리 매매가 해제되어 매수인이 원상회복의무를 지는 경우, 매수인이 진정한 권리자에게 목적물을 직접 반환했다면 그 범위에서 매도인에게 반환할 의무가 없다고 본다.","c":"중","v":1},"변리사2023_60-35-3":{"w":"제547조 제1항은 당사자 일방 또는 쌍방이 수인인 경우 계약의 해지나 해제는 그 전원으로부터 또는 전원에 대하여 하도록 정한다. 매수인 지위를 공동상속한 상속인들도 전원이 해제해야 한다.","c":"상","v":1},"변리사2023_60-35-4":{"w":"판례는 조합계약은 단체적 성격이 있어 일반 계약처럼 해제·해지로 소급해 원상회복시킬 수 없고 조합원은 탈퇴(제716조, 제717조)나 해산청구(제720조)로 해결해야 한다고 본다.","c":"중","v":1},"변리사2023_60-35-5":{"w":"판례는 합의해제·해지는 새로운 계약이므로 해제에 관한 제551조가 적용되지 않아 특별한 약정이 없으면 채무불이행 손해배상을 청구할 수 없다고 본다.","c":"중","v":1},"변리사2016_53-36-1":{"w":"판례는 계약이 채무불이행으로 해제된 뒤에도 해제로 인한 손해배상책임을 면하기 위해 착오를 이유로 계약을 취소할 수 있다고 본다.","c":"중","v":1},"변리사2016_53-36-3":{"w":"이행불능을 이유로 해제하는 경우 최고가 필요 없다(제546조). 판례는 상대방의 잔대금지급의무가 동시이행관계에 있더라도 매수인은 그 이행제공 없이 해제할 수 있다고 본다.","c":"중","v":1},"변리사2016_53-36-4":{"w":"판례는 제3자를 위한 계약의 수익자는 계약 당사자가 아니므로 낙약자의 채무불이행을 이유로 계약을 해제할 수 없다고 본다. 손해배상은 청구할 수 있다.","c":"중","v":1},"변리사2016_53-36-5":{"w":"제556조 제1항 제1호는 수증자가 증여자 또는 그 배우자나 직계혈족에 대한 범죄행위가 있는 때 증여자가 증여를 해제할 수 있다고 정하고 제558조는 그 해제가 이미 이행한 부분에는 영향을 미치지 않는다고 정한다.","c":"상","v":1},"변리사2016_53-33-2":{"w":"판례는 쌍무계약의 일방 채무가 이행불능으로 손해배상채무로 바뀌어도 본래 채무와 동일성을 유지하므로 동시이행관계가 존속한다고 본다.","c":"중","v":1},"변리사2016_53-33-4":{"w":"판례는 매수인이 선이행할 중도금을 지급하지 않은 채 잔대금지급일이 지나면 중도금과 그 지연손해금, 잔대금지급채무가 모두 매도인의 소유권이전등기의무와 동시이행관계에 놓인다고 본다.","c":"중","v":1},"변리사2019_56-35-5":{"w":"판례는 매수인이 부가가치세를 부담하기로 한 경우 부가가치세도 매매대금의 일부이므로 특별한 사정이 없으면 이를 포함한 매매대금 전부와 소유권이전등기의무가 동시이행관계에 있다고 본다.","c":"중","v":1},"변리사2021_58-35-1":{"w":"판례는 매수인이 부가가치세를 부담하기로 약정했다면 부가가치세를 포함한 매매대금 전부와 소유권이전등기의무가 동시이행관계에 있다고 본다.","c":"중","v":1},"변리사2021_58-35-2":{"w":"판례는 도급인의 지체상금채권과 수급인의 공사대금채권은 대가관계에 있는 채무가 아니므로 특별한 사정이 없으면 동시이행관계가 아니라고 본다.","c":"중","v":1},"변리사2021_58-35-3":{"w":"판례는 구분소유적 공유관계가 전부 해소되어 공유지분권자 상호 간에 지분이전등기의무가 생기면 그 의무들은 서로 동시이행관계에 있다고 본다.","c":"중","v":1},"변리사2021_58-35-5":{"w":"판례는 동시이행관계에 있는 채무 중 하나가 이행불능이 되어 생긴 손해배상채무도 본래 채무와 동일성이 있어 다른 채무와 동시이행관계에 있다고 본다.","c":"중","v":1},"변리사2023_60-34-1":{"w":"판례·통설은 제3자를 위한 계약에서 요약자도 계약 당사자로서 제3자의 권리와 별도로 낙약자에게 제3자에게 급부하라고 요구할 권리를 가진다고 본다.","c":"중","v":1},"변리사2023_60-34-2":{"w":"제541조는 제3자의 권리가 생긴 후에는 당사자가 이를 변경 또는 소멸시키지 못한다고 정한다.","c":"상","v":1},"변리사2023_60-34-4":{"w":"판례는 채무자와 인수인 사이의 중첩적 채무인수를 제3자를 위한 계약으로 보면서도 채권자의 수익 의사표시는 계약의 성립요건이나 효력발생요건이 아니라 채권자가 인수인에게 권리를 취득하기 위한 요건이라고 본다.","c":"중","v":1},"변리사2023_60-34-5":{"w":"판례는 기본관계인 계약이 무효이면 낙약자는 요약자에게 부당이득반환을 구해야 하고 제3자를 상대로 그가 받은 급부의 반환을 청구할 수 없다고 본다.","c":"중","v":1},"변리사2019_56-33-1":{"w":"판례는 계약금 일부만 지급된 경우 해약금의 기준은 실제 지급된 금액이 아니라 약정 계약금이라고 본다. 따라서 수령자가 해제하려면 약정 계약금의 배액을 상환해야 한다.","c":"중","v":1},"변리사2019_56-33-2":{"w":"제565조의 해제는 당사자 일방이 이행에 착수할 때까지 할 수 있다. 판례는 이행기 전이라도 이행기 전 착수를 하지 않기로 하는 특약 등 특별한 사정이 없으면 이행에 착수할 수 있고 착수하면 해제권을 행사할 수 없다고 본다.","c":"중","v":1},"변리사2019_56-33-3":{"w":"제565조는 「당사자 간에 다른 약정이 없는 한」이라고 정해 임의규정이다. 해제권을 배제하는 약정을 하면 계약금에 기한 해제를 할 수 없다.","c":"중","v":1},"변리사2019_56-33-5":{"w":"판례는 토지거래허가를 받은 것은 계약의 효력을 완성시키는 것일 뿐 채무 이행의 일부가 아니므로 제565조의 이행 착수가 아니라고 본다.","c":"중","v":1},"변리사2016_53-35-1":{"w":"제565조 제1항은 「당사자 간에 다른 약정이 없는 한」 해약금 해제를 인정하므로 임의규정이다. 해약권을 배제하는 약정은 유효하다.","c":"중","v":1},"변리사2016_53-37-2":{"w":"판례는 도급계약의 지체상금 약정을 손해배상액의 예정으로 보므로 부당히 과다하면 법원이 제398조 제2항에 따라 감액할 수 있다.","c":"중","v":1},"변리사2016_53-37-3":{"w":"판례는 제작물공급계약에서 제작물이 대체물이면 매매에 관한 규정을, 특정 주문자의 수요를 만족시키기 위한 부대체물이면 도급에 관한 규정을 적용한다고 본다.","c":"중","v":1},"변리사2016_53-37-4":{"w":"판례는 도급인이 하도급 공사대금채무를 인수한 경우 인수인은 원래 채무자(수급인)가 가진 항변으로 채권자에게 대항할 수 있으므로(제458조) 수급인의 하자보수청구권 등에 기한 동시이행 항변으로 하수급인에게 대항할 수 있다고 본다.","c":"중","v":1},"변리사2017_54-33-5":{"w":"건물 소유 목적의 토지임대차가 기간 만료로 끝나면 임차인은 제643조, 제283조에 따라 건물 매수를 청구할 수 있다. 판례는 미등기 건물도 그 대상이 될 수 있다고 본다.","c":"중","v":1},"변리사2017_54-36-5":{"w":"조합재산은 조합원의 합유다(제704조). 판례는 조합재산인 부동산을 합유등기하지 않고 조합원 1인 명의로 등기했다면 조합체가 그 조합원에게 명의신탁한 것으로 본다.","c":"중","v":1},"변리사2018_55-39-2":{"w":"제591조 제1항은 부동산 환매기간이 5년을 넘지 못하고 제3항은 기간을 정하지 않으면 5년으로 한다고 정한다. 제2항은 환매기간을 정한 때에는 다시 연장하지 못한다고 정한다.","c":"상","v":1},"변리사2018_55-39-3":{"w":"환매특약은 매매계약에 붙은 종된 계약이다. 판례·통설은 환매특약이 실효되어도 주된 매매계약의 효력에는 영향이 없다고 본다.","c":"중","v":1},"변리사2018_55-39-4":{"w":"제590조 제3항은 목적물의 과실과 대금의 이자는 특별한 약정이 없으면 상계한 것으로 본다고 정한다.","c":"상","v":1},"변리사2018_55-39-5":{"w":"매매등기와 동시에 환매권 보류를 등기하면 제3자에게 효력이 있다(제592조). 판례는 그 뒤 저당권을 취득한 제3자의 권리는 매도인이 적법하게 환매권을 행사해 소유권을 회복하면 소멸한다고 본다.","c":"중","v":1},"변리사2019_56-37-4":{"w":"제644조의 전차인 매수청구권은 임대인의 동의를 얻은 적법한 전대차에서만 인정된다. 무단전대의 전차인 丙은 임대인 甲에게 건물매수를 청구할 수 없다.","c":"중","v":1},"변리사2024_61-35-2":{"w":"제555조는 서면에 의하지 않은 증여를 각 당사자가 해제할 수 있게 한다. 판례는 증여계약 성립 후 계약이 존속하는 동안 서면을 작성하면 그때부터 서면에 의한 증여가 되어 임의로 해제할 수 없다고 본다.","c":"중","v":1},"변리사2024_61-35-4":{"w":"판례는 제555조의 서면에 의하지 않은 증여의 해제는 일종의 특수한 철회여서 형성권의 제척기간(제146조 등)이 적용되지 않는다고 본다.","c":"중","v":1},"변리사2024_61-37-4":{"w":"제689조 제1항은 위임계약을 각 당사자가 언제든지 해지할 수 있다고 정한다. 부득이한 사유 없이 상대방에게 불리한 시기에 해지하면 손해를 배상해야 한다(같은 조 제2항).","c":"상","v":1},"변리사2026_63-37-4":{"w":"판례는 무단전대라도 임대인이 임대차계약을 해지하지 않아 임대차가 존속하는 동안에는 임대인이 차임을 받을 수 있어 손해가 없으므로 전차인에게 불법점유를 이유로 한 차임 상당 손해배상이나 부당이득반환을 청구할 수 없다고 본다.","c":"중","v":1},"변리사2016_53-37-1":{"w":"판례는 수급인이 자기 노력과 재료의 전부 또는 주요 부분을 들여 건물을 완성하면 도급인에게 소유권을 귀속시키기로 하는 특약 등이 없는 한 수급인이 그 건물 소유권을 원시취득한다고 본다.","c":"중","v":1},"변리사2026_63-38-2":{"w":"판례는 수급인이 자기 노력과 재료로 건물을 신축하면 특별한 사정이 없는 한 수급인이 그 건물의 소유권을 원시취득한다고 본다.","c":"중","v":1},"변리사2026_63-38-3":{"w":"제666조의 저당권설정청구권은 공사대금채권을 담보하기 위한 것이다. 판례는 공사대금채권이 양도되면 이 청구권도 수반해 양수인에게 이전된다고 본다.","c":"중","v":1},"변리사2026_63-38-4":{"w":"판례는 도급인의 지체상금채권과 수급인의 공사대금채권은 서로 대가관계에 있는 채무가 아니어서 특별한 사정이 없으면 동시이행관계가 아니라고 본다.","c":"중","v":1},"변리사2026_63-38-5":{"w":"제667조 제1항 단서는 하자가 중요하지 않은 경우 그 보수에 과다한 비용을 요할 때에는 하자보수를 청구할 수 없다고 정한다. 이때 도급인은 손해배상을 청구할 수 있다.","c":"상","v":1},"변리사2018_55-38-1":{"w":"제579조 제2항은 변제기에 도달하지 않은 채권의 매도인이 채무자의 자력을 담보한 때에는 변제기의 자력을 담보한 것으로 추정한다고 정한다.","c":"상","v":1},"변리사2018_55-38-3":{"w":"제576조 제1항은 매매목적 부동산의 저당권 행사로 매수인이 소유권을 취득할 수 없거나 잃은 때 매수인이 계약을 해제할 수 있다고 정하며 매수인의 선의·악의를 묻지 않는다.","c":"상","v":1},"변리사2018_55-38-4":{"w":"제571조 제1항은 매도인이 계약 당시 매매목적 권리가 자기에게 속하지 않음을 알지 못한 경우 그 권리를 취득해 매수인에게 이전할 수 없는 때 매도인이 손해를 배상하고 계약을 해제할 수 있다고 정한다.","c":"상","v":1},"변리사2018_55-38-5":{"w":"판례는 가압류 목적 부동산을 매수한 사람이 가압류에 기한 강제집행으로 소유권을 잃은 경우 제576조를 유추적용하므로 매수인이 가압류를 알았더라도 손해배상을 청구할 수 있다고 본다.","c":"중","v":1},"변리사2021_58-40-2":{"w":"판례는 타인 권리 매매에서 매도인이 권리를 이전할 수 없게 되면 선의의 매수인에게 제570조에 따라 이행이익을 배상해야 하고 그 액수는 이행불능 당시의 목적물 시가를 기준으로 한다고 본다.","c":"중","v":1},"변리사2021_58-40-3":{"w":"판례는 매매계약 내용의 중요부분에 착오가 있으면 매도인의 하자담보책임이 성립하는지와 관계없이 매수인이 제109조로 계약을 취소할 수 있다고 본다. 두 제도는 요건과 효과가 달라 경합한다.","c":"중","v":1},"변리사2021_58-40-4":{"w":"판례는 하자담보책임은 무과실책임이지만 공평의 원칙상 하자의 발생·확대에 매수인의 잘못이 있으면 법원이 이를 직권으로 참작해 손해배상의 범위를 정해야 한다고 본다.","c":"중","v":1},"변리사2021_58-40-5":{"w":"제576조 제1항은 저당권 행사로 매수인이 소유권을 취득할 수 없거나 잃은 때 계약을 해제할 수 있다고 정하며 매수인의 선의를 요구하지 않는다.","c":"상","v":1},"변리사2023_60-36-1":{"w":"판례는 예약완결권을 소장 송달로 행사하는 경우 소장 부본이 제척기간 내에 상대방에게 송달되어야 기간 내에 행사한 것이 된다고 본다. 소 제기만으로는 부족하다.","c":"중","v":1},"변리사2023_60-36-2":{"w":"판례는 예약완결권의 행사기간을 약정했다면 그 기간이 매매예약 성립 시부터 10년을 넘더라도 약정대로 그 기간 내에 행사하면 된다고 본다.","c":"중","v":1},"변리사2023_60-36-3":{"w":"판례는 예약완결권 행사 전에 목적물이 멸실해 이전이 불가능해지면 완결의 의사표시를 해도 매매의 효력이 생기지 않는다고 본다. 원시적 불능 상태의 매매를 성립시킬 수 없기 때문이다.","c":"중","v":1},"변리사2023_60-36-4":{"w":"판례는 매도인이 제565조 제1항으로 해제하려면 해제 의사표시 외에 계약금 배액을 현실로 상환하거나 적어도 이행제공을 해야 하고 상대방이 수령을 거절하면 공탁까지 할 필요는 없다고 본다.","c":"중","v":1},"변리사2019_56-39-2":{"w":"제716조 제2항은 조합의 존속기간을 정한 때에도 조합원은 부득이한 사유가 있으면 탈퇴할 수 있다고 정한다.","c":"상","v":1},"변리사2021_58-39-2":{"w":"조합은 2인 이상이 서로 출자해 공동사업을 경영하기로 하는 계약이다(제703조). 판례는 일부 조합원만 이익분배를 받는 관계는 공동사업으로 볼 수 없어 조합이 아니라고 본다.","c":"중","v":1},"변리사2024_61-37-1":{"w":"제681조는 수임인이 위임의 본지에 따라 선량한 관리자의 주의로 위임사무를 처리하도록 정하며 보수 약정 여부(제686조)로 구별하지 않는다.","c":"상","v":1},"변리사2024_61-37-2":{"w":"판례는 제684조 제1항에 따라 수임인이 위임인에게 인도할 금전의 범위는 특별한 사정이 없으면 위임 종료 시를 기준으로 정한다고 본다.","c":"중","v":1},"변리사2024_61-37-3":{"w":"제690조는 위임 종료 사유로 당사자 한쪽의 사망·파산과 수임인의 성년후견개시 심판을 정한다. 위임인의 성년후견개시 심판은 종료 사유가 아니다.","c":"상","v":1},"변리사2018_55-34-1":{"w":"판례는 임대차보증금반환채권은 건물에 관하여 생긴 채권이 아니므로 이를 피담보채권으로 하여 임차건물에 유치권을 주장할 수 없다고 본다.","c":"중","v":1},"변리사2018_55-34-3":{"w":"판례는 임대차 존속 중에는 연체차임이 임대인의 별도 의사표시 없이 보증금에서 당연히 공제되지 않는다고 본다. 보증금에서 당연히 공제되는 것은 목적물 반환 시점이다.","c":"중","v":1},"변리사2018_55-34-4":{"w":"보증금은 목적물 반환 시까지 임대차에서 생기는 임차인의 모든 채무를 담보한다. 판례는 보증금반환채권에 전부명령이 있어도 반환 시까지 생긴 연체차임 등을 공제한 잔액에 대해서만 전부명령이 효력을 가진다고 본다.","c":"중","v":1},"변리사2018_55-34-5":{"w":"판례는 차임채권에 추심명령이 송달되었더라도 임대차가 끝나 목적물이 반환될 때 추심되지 않은 잔존 차임채권 상당액은 보증금에서 당연히 공제된다고 본다.","c":"중","v":1},"변리사2016_53-38-2":{"w":"판례는 조합이 해산했더라도 처리할 잔무가 없고 잔여재산 분배만 남았다면 따로 청산절차를 거칠 필요 없이 각 조합원이 자기 몫의 분배를 청구할 수 있다고 본다.","c":"중","v":1},"변리사2016_53-38-3":{"w":"제706조 제1항은 조합계약으로 업무집행자를 정하지 않은 경우 조합원 3분의 2 이상의 찬성으로 선임하도록 정한다. 제708조는 업무집행자인 조합원을 다른 조합원의 일치가 아니면 해임하지 못한다고 정한다.","c":"상","v":1},"변리사2016_53-38-4":{"w":"판례는 조합의 대표조합원이 대표자격을 밝히고 어음에 서명하면 유효하며 어음행위의 본인인 조합원 전원을 구체적으로 표시할 필요는 없다고 본다.","c":"중","v":1},"변리사2016_53-38-5":{"w":"판례는 동업자 중 1인에게 업무집행을 맡긴 경우 다른 동업자는 그를 지휘·감독할 지위에 있으므로 업무집행 과정의 불법행위에 대해 제756조의 사용자책임을 진다고 본다.","c":"중","v":1},"변리사2023_60-38-5":{"w":"판례는 조합원이 다른 조합원 전원의 동의를 얻어 지분을 양도하면 양도양수 약정만으로 조합원 지위의 변동이 바로 효력을 가진다고 본다.","c":"중","v":1},"변리사2024_61-35-3":{"w":"판례는 재단법인 설립을 위한 서면 출연행위도 착오 취소 요건(제109조)을 갖추면 취소할 수 있다고 본다. 서면 증여의 해제 제한(제555조)과는 별개 문제다.","c":"중","v":1},"변리사2024_61-35-5":{"w":"제560조는 정기의 급여를 목적으로 한 증여는 증여자 또는 수증자의 사망으로 효력을 잃는다고 정한다.","c":"상","v":1},"변리사2016_53-39-2":{"w":"사무관리는 의무 없이 타인의 사무를 관리하는 것이다(제734조). 판례는 계약상 의무를 이행하는 과정에서 제3자의 사무를 처리한 경우에는 의무 없이 한 것이 아니므로 그 제3자와의 사이에 사무관리가 성립하지 않는다고 본다.","c":"중","v":1},"변리사2016_53-40-1":{"w":"판례는 어업권 임대차를 금지한 규정을 위반한 임대차가 무효이더라도 임차인이 어장을 점유·사용해 얻은 이익은 법률상 원인 없는 이득이므로 어업권자가 부당이득으로 반환을 청구할 수 있다고 본다.","c":"중","v":1},"변리사2016_53-40-3":{"w":"판례는 과반수 지분의 공유자라도 다른 공유자의 허락 없이 공유토지 전부를 배타적으로 점유·사용하면 그 공유자의 지분 비율에 해당하는 부분만큼 부당이득을 얻은 것이므로 반환해야 한다고 본다.","c":"중","v":1},"변리사2016_53-40-4":{"w":"판례는 확정판결은 재심으로 취소되지 않는 한 효력이 있으므로 그 확정판결에 따른 강제집행으로 받은 금전은 뒤에 반대 내용의 판결이 확정되어도 법률상 원인 없는 이득이 아니라고 본다.","c":"중","v":1},"변리사2016_53-40-5":{"w":"취득시효로 인한 소유권취득은 점유를 개시한 때에 소급하므로(제247조 제1항) 판례는 시효기간 중 점유자가 얻은 이익을 소유명의자가 부당이득으로 반환청구할 수 없다고 본다.","c":"중","v":1},"변리사2017_54-37-4":{"w":"제740조는 관리자가 사무관리를 하면서 과실 없이 손해를 받은 때 본인의 현존이익의 한도에서 그 손해의 보상을 청구할 수 있다고 정한다.","c":"상","v":1},"변리사2018_55-35-1":{"w":"부당이득은 실질적 이득이 있어야 성립한다. 판례는 임대차 종료 후 임차인이 목적물을 계속 점유했더라도 본래 용도대로 사용·수익하지 않았다면 차임 상당 부당이득반환의무가 없다고 본다.","c":"중","v":1},"변리사2018_55-35-2":{"w":"판례는 권원 없이 타인 토지에 건물을 소유하는 사람은 그 건물을 실제로 사용·수익하지 않더라도 건물 소유 자체로 부지를 점유·사용하는 것이어서 토지 차임 상당의 부당이득을 반환해야 한다고 본다.","c":"중","v":1},"변리사2018_55-35-3":{"w":"판례는 임대차 종료 후 임차인이 임차건물을 계속 점유했더라도 임차인 사정으로 본래 목적대로 사용·수익하지 않아 실질적 이득이 없으면 차임 상당 부당이득반환의무가 없다고 본다.","c":"중","v":1},"변리사2018_55-35-5":{"w":"판례는 미등기 건물을 원시취득한 乙은 그 건물을 매도했더라도 이전등기를 넘기지 않은 이상 여전히 법률상 소유자로서 부지를 점유하는 것이므로 토지소유자에게 차임 상당 부당이득반환의무를 진다고 본다.","c":"중","v":1},"변리사2023_60-39-1":{"w":"쌍방 책임 없는 사유로 일방의 채무가 불능이 되면 그 채무자는 상대방의 이행을 청구하지 못한다(제537조). 상대방이 이미 이행한 급부는 법률상 원인을 잃으므로 부당이득으로 반환을 청구할 수 있다.","c":"중","v":1},"변리사2023_60-39-2":{"w":"판례는 배당요구가 필요한 채권자가 배당요구 종기까지 배당요구를 하지 않아 배당에서 제외되었다면 다른 채권자가 받은 배당은 법률상 원인이 있으므로 부당이득반환을 청구할 수 없다고 본다.","c":"중","v":1},"변리사2023_60-39-4":{"w":"판례는 임대차 종료 후 임차인이 건물을 계속 점유하더라도 본래 목적에 따라 사용·수익하지 않아 실질적 이득이 없으면 차임 상당 부당이득반환의무가 없다고 본다.","c":"중","v":1},"변리사2023_60-39-5":{"w":"판례는 원인관계 없이 착오송금으로 수취인이 예금채권을 취득하면 수취인은 법률상 원인 없이 이득을 얻은 것이므로 송금의뢰인이 수취인에게 부당이득반환청구권을 가진다고 본다. 은행에는 청구할 수 없다.","c":"중","v":1},"변리사2026_63-39-1":{"w":"판례는 권원 없이 타인 토지 위에 건물을 소유하는 사람은 그 건물을 실제로 사용·수익하지 않더라도 건물 소유 자체로 부지를 점유하므로 차임 상당 부당이득을 반환해야 한다고 본다.","c":"중","v":1},"변리사2026_63-39-2":{"w":"판례는 물상대위권을 행사하지 않아 우선변제권을 잃은 저당권자는 보상금에서 배당을 받은 다른 채권자에게 부당이득반환을 청구할 수 없다고 본다. 그 채권자는 정당한 배당을 받은 것이다.","c":"중","v":1},"변리사2026_63-39-4":{"w":"판례는 법률상 원인 없이 제3자에 대한 채권을 취득한 경우 이득은 그 채권 자체이므로 이득자가 아직 추심하지 못했다면 손실자는 채권 가액의 금전 반환이 아니라 그 채권의 반환(양도)을 청구해야 한다고 본다.","c":"중","v":1},"변리사2026_63-39-5":{"w":"판례는 횡령한 금전으로 채무를 변제받은 채권자가 그 사실에 대해 악의 또는 중대한 과실이 없으면 채권자의 금전취득은 피해자에 대한 관계에서 법률상 원인이 있어 부당이득이 되지 않는다고 본다.","c":"중","v":1},"변리사2017_54-37-2":{"w":"제738조는 사무관리에 제685조를 준용하므로 관리자가 본인에게 인도할 금전을 자기를 위해 소비한 때에는 소비한 날 이후의 이자를 지급하고 그 외의 손해가 있으면 배상해야 한다.","c":"상","v":1},"변리사2017_54-37-3":{"w":"제735조는 관리자가 타인의 생명, 신체, 명예 또는 재산에 대한 급박한 위해를 면하게 하기 위해 사무를 관리한 때 고의나 중대한 과실이 없으면 그로 인한 손해를 배상할 책임이 없다고 정한다.","c":"상","v":1},"변리사2017_54-37-5":{"w":"판례는 사무관리의 요건인 타인을 위한 의사는 관리자 자신의 이익을 위한 의사와 병존할 수 있다고 본다.","c":"중","v":1},"변리사2024_61-38-5":{"w":"제735조에 따라 타인의 신체에 대한 급박한 위해를 면하게 하기 위한 긴급사무관리에서는 관리자에게 고의나 중대한 과실이 없으면 손해배상책임이 없다.","c":"상","v":1},"변리사2017_54-38-1":{"w":"과실상계(제763조, 제396조)로 丙의 과실 30%를 빼면 배상액은 5천만원의 70%인 3천5백만원이다. 공동불법행위자 甲과 乙은 이를 연대해 배상한다(제760조 제1항).","c":"중","v":1},"변리사2017_54-38-3":{"w":"판례는 공동불법행위자 사이의 구상권은 일반 채권으로 10년의 소멸시효(제162조 제1항)에 걸리고 그 기산점은 구상권자가 현실로 피해자에게 배상한 때라고 본다.","c":"중","v":1},"변리사2017_54-38-4":{"w":"판례는 공동불법행위자 중 1인이 자기 부담부분을 넘어 배상한 경우에만 다른 공동불법행위자에게 구상할 수 있다고 본다. 甲의 부담부분은 3천5백만원의 70%인 2천4백5십만원이므로 1천만원 배상으로는 구상할 수 없다.","c":"중","v":1},"변리사2017_54-38-5":{"w":"판례는 공동불법행위자 1인의 보증인이 피해자에게 배상하면 제447조를 유추해 다른 공동불법행위자에게 그의 부담부분에 한해 구상할 수 있다고 본다.","c":"중","v":1},"변리사2018_55-36-1":{"w":"판례는 피용자의 손해배상채무와 사용자책임에 따른 손해배상채무는 부진정연대채무여서 피용자의 채무가 시효로 소멸해도 사용자의 채무는 소멸하지 않는다고 본다.","c":"중","v":1},"변리사2018_55-36-2":{"w":"도급인은 원칙적으로 수급인의 불법행위에 책임이 없다(제757조). 판례는 도급인이 수급인에게 구체적 행위를 지휘하는 노무도급에서는 사용관계를 인정해 도급인이 제756조의 사용자책임을 질 수 있다고 본다.","c":"중","v":1},"변리사2018_55-36-3":{"w":"판례는 지입회사는 지입차량의 운행을 객관적으로 지휘·감독해야 할 지위에 있으므로 지입차주가 고용한 운전자의 과실로 생긴 손해에 대해 사용자책임을 진다고 본다.","c":"중","v":1},"변리사2019_56-40-2":{"w":"판례는 제760조 제1항의 공동불법행위는 행위자 사이에 의사의 공통이나 행위공동의 인식이 필요 없고 각 행위가 객관적으로 관련·공동되어 있으면 성립한다고 본다.","c":"중","v":1},"변리사2019_56-40-3":{"w":"판례는 공동불법행위자의 책임을 부진정연대채무로 보며 한 사람의 변제는 채권을 만족시키는 사유이므로 변제한 금액 범위에서 다른 공동불법행위자도 함께 면책된다고 본다.","c":"중","v":1},"변리사2019_56-40-4":{"w":"제760조 제2항의 가해자불명 공동불법행위는 인과관계를 추정하는 규정이다. 판례는 개별 행위자가 자기 행위와 손해 사이에 인과관계가 없음을 증명하면 책임을 면한다고 본다.","c":"중","v":1},"변리사2021_58-37-1":{"w":"乙과 丙의 과실이 경합해 甲이 다쳤으므로 제760조 제1항의 공동불법행위가 성립하고 판례는 공동불법행위자의 책임을 부진정연대채무로 본다.","c":"중","v":1},"변리사2021_58-37-2":{"w":"판례는 호의동승에 따른 감액은 피해자 측 사정에 따른 것이어서 공동불법행위자 전원에 대한 관계에서 전체적으로 평가해야 하므로 운전자 乙에 대한 책임 제한이 상대 차량 운전자 丙에게도 인정된다고 본다.","c":"중","v":1},"변리사2021_58-37-3":{"w":"판례는 동승자가 운전자의 난폭운전 등으로 사고 위험을 인식할 수 있었다면 안전운전을 촉구할 주의의무가 있고 이를 게을리하면 과실상계 사유가 된다고 본다.","c":"중","v":1},"변리사2021_58-37-4":{"w":"30% 제한으로 乙·丙의 배상액은 700만원이고 丙의 부담부분은 과실비율 8에 따라 560만원이다. 丙이 600만원을 변제했으므로 부담부분을 넘은 40만원을 乙에게 구상할 수 있다.","c":"중","v":1},"변리사2023_60-40-2":{"w":"판례는 위법행위 시점과 손해 발생 시점에 간격이 있으면 불법행위로 인한 손해배상책임은 손해가 현실적으로 발생한 때 성립한다고 본다.","c":"중","v":1},"변리사2023_60-40-3":{"w":"판례는 대여자가 고의·과실로 이자제한법상 최고이자율을 넘는 이자를 받아 채무자에게 손해를 입혔다면 특별한 사정이 없는 한 불법행위(제750조)가 성립한다고 본다.","c":"중","v":1},"변리사2023_60-40-5":{"w":"판례는 불법행위로 인한 손해배상채무는 이행청구가 없어도 불법행위 성립과 동시에 지체가 되어 그때부터 지연손해금이 발생한다고 본다.","c":"중","v":1},"변리사2026_63-40-3":{"w":"판례는 도급인이 수급인에게 특정한 행위를 지휘하는 노무도급의 경우 도급인과 수급인 사이에 사용관계를 인정해 도급인에게 제756조의 사용자책임을 인정할 수 있다고 본다.","c":"중","v":1},"변리사2019_56-40-1":{"w":"제760조 제1항은 수인이 공동의 불법행위로 타인에게 손해를 가한 때 연대하여 그 손해를 배상할 책임이 있다고 정한다.","c":"상","v":1},"변리사2023_60-40-4":{"w":"판례는 제756조의 사용관계는 실제로 지휘·감독하는지가 아니라 객관적으로 지휘·감독을 해야 할 관계에 있는지로 판단한다고 본다.","c":"중","v":1},"변리사2024_61-39-3":{"w":"제758조 제1항 단서는 점유자가 손해 방지에 필요한 주의를 게을리하지 않은 때 소유자가 손해를 배상할 책임이 있다고 정한다. 소유자의 책임은 무과실책임이다.","c":"상","v":1},"변리사2018_55-36-4":{"w":"판례는 피용자와 제3자의 공동불법행위에서 사용자가 피용자의 부담부분을 넘어 배상하면 사용자는 피용자와 같은 지위에서 제3자에게 그 부담부분 범위에서 구상할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-40-2":{"w":"판례는 제756조의 사용관계 존재 여부는 실제 지휘·감독 여부가 아니라 객관적·규범적으로 지휘·감독해야 할 관계에 있는지에 따라 정한다고 본다.","c":"중","v":1},"변리사2026_63-40-4":{"w":"판례는 피용자와 제3자의 공동불법행위에서 사용자가 피용자의 부담부분을 넘어 배상하면 그 초과 부분에 대해 제3자에게 구상권을 행사할 수 있다고 본다.","c":"중","v":1},"변리사2026_63-40-5":{"w":"판례(전원합의체)는 금액이 다른 부진정연대채무에서 다액채무자가 일부 변제하면 그 변제액은 다액채무자가 단독으로 부담하는 부분부터 먼저 소멸시킨다고 본다(외측설).","c":"중","v":1}};
